// Definitions for the new 2027 units, including a precise return link.
const G=(term,definition,lesson,unit,section,aliases='',contextualAliases=[])=>({term,category:'CFA 2027 · Vertiefung',definition,lesson,aliases:aliases?aliases.split('|'):[],cfa:{unit,section},...(contextualAliases.length?{contextualAliases}: {})});
module.exports=[
 G('Hedgefonds','Fonds mit einer konkret vereinbarten Strategie, häufig mit flexibleren Long-/Short-, Derivate- oder Leverage-Möglichkeiten. Der Name bezeichnet weder eine einzelne Risikoklasse noch eine Gewinn- oder Absicherungsgarantie. Vehikel, tatsächliche Positionen, Finanzierung, Kosten und Rückgaberechte sind gemeinsam zu prüfen.','alternatives-09','hedge-funds','map','Hedge Fund|Hedgefondsstrategien'),
 G('Long/Short','Kombination von positiv gehaltenen Positionen und negativen Positionen in anderen Basiswerten. Beim Short schadet eine positive Basiswertrendite. Gleiche Long- und Short-Marktwerte neutralisieren zwar den Netto-Marktwert, bei verschiedenen Betas aber nicht automatisch das Marktrisiko.','alternatives-09','hedge-funds','long-short'),
 G('Hedgefonds-Marktneutralität','Auf eine ausdrücklich bezeichnete Risikomessung und einen Markt bezogene Neutralität. Beta-Neutralität gegen einen linearen Aktienmarktfaktor ist etwas anderes als gleich große Long-/Short-Marktwerte. Einzelwert-, Kredit-, Volatilitäts-, Liquiditäts- und Finanzierungsrisiken können bestehen bleiben.','alternatives-09','hedge-funds','beta','', [{label:'Market Neutral',units:['hedge-funds']},{label:'Marktneutralität',units:['hedge-funds']},{label:'marktneutral',units:['hedge-funds']}]),
 G('Bruttoexposure','Summe der absoluten Long- und Short-Marktwerte, häufig relativ zum Anfangs-NAV. Bei 150 Long und 100 Short zu NAV 100 sind das 250 Prozent. Die Größe zeigt Positionsumfang und eine mögliche Kostenbasis, misst aber weder Nettoausrichtung noch sämtliche Risiken vollständig.','alternatives-09','hedge-funds','exposures','Gross Exposure'),
 G('Nettoexposure','Long-Marktwert abzüglich des als positive Größe erfassten Short-Marktwerts, auf eine benannte Kapitalbasis bezogen. Es beschreibt eine Marktwertausrichtung. Verschiedene Betas oder weitere Faktoren können trotz Nettoexposure null erhebliches Risiko erzeugen.','alternatives-09','hedge-funds','exposures','Net Exposure'),
 G('Hedgefonds-Beta','Empfindlichkeit des Fonds gegen einen bestimmten Markt- oder Risikofaktor. In einem einfachen Long-/Short-Modell werden die Betas der Basiswerte mit ihren signierten NAV-Gewichten verbunden. Ein geschätztes historisches Beta ist modell- und periodenabhängig und kann nichtlineare oder andere Risiken auslassen.','alternatives-09','hedge-funds','beta','', [{label:'Beta',units:['hedge-funds']}]),
 G('Hedgefonds-Alpha','Geschätzter Renditeanteil jenseits der in einer benannten Faktorregression erklärten Risikoprämien. Ein positiver Wert kann von Modellwahl, Daten, Kosten und Zufall abhängen und beweist keine dauerhafte Managerfähigkeit. Weder eine einfache Benchmarkdifferenz noch ein im Rechner angenommener Sondereffekt ist automatisch nachgewiesenes Alpha.','alternatives-09','hedge-funds','factors','', [{label:'Alpha',units:['hedge-funds']}]),
 G('Prime Broker','Dienstleister mit vertraglich bestimmten Aufgaben wie Wertpapierleihe, Finanzierung, Verwahrung oder Handelsunterstützung. Die Bündelung kann operativ hilfreich sein, aber Gegenpartei- und Liquiditätsabhängigkeiten schaffen. Leistungen und Sicherheitenregeln sind keine Garantie für Anlagegewinne.','alternatives-09','hedge-funds','short-funding'),
 G('Short Borrow','Leihe des für einen Leerverkauf benötigten Wertpapiers. Verfügbarkeit, Gebühr, mögliche Rückrufe und erforderliche Sicherheiten beeinflussen Haltedauer und Ergebnis. Verkaufserlöse sind nicht automatisch frei verfügbares Eigenkapital.','alternatives-09','hedge-funds','short-sale','Wertpapierleihe für Short'),
 G('Short Squeeze','Starker Kursanstieg, der Short-Verkäufer zu teuren Rückkäufen drängen kann; solche Käufe können den Druck weiter erhöhen. Leih-Rückrufe und Sicherheitenanforderungen können die Situation verschärfen. Ein Short-Verlust ist nicht auf den anfänglichen Verkaufserlös begrenzt.','alternatives-09','hedge-funds','short-squeeze'),
 G('Dividendenkompensation','Im bezeichneten Wertpapierleihefall vom Short zu tragender Ausgleich einer Ausschüttung. Wird mit reinen Kursrenditen gerechnet, ist er ein zusätzlicher Cashposten. Ist er bereits in derselben Gesamtertragsbasis negativ gewichtet enthalten, darf er nicht nochmals als Kosten abgezogen werden.','alternatives-09','hedge-funds','short-sale','', [{label:'Dividend Compensation',units:['hedge-funds']}]),
 G('Short-Sicherheiten','Nach dem konkreten Broker- oder Leihvertrag gebundene Werte zur Sicherung der Short-Verpflichtung. Gebundenes Cash ist ein Vermögenswert, aber nicht automatisch frei auszahlbar. Ein zusätzlicher Kredit, eine Short-Schuld und das Eigenkapital müssen in einer vollständigen Bilanz getrennt abgestimmt werden.','alternatives-09','hedge-funds','short-funding','Short Collateral'),
 G('Merger Arbitrage','Ereignisstrategie, die auf den Abschluss einer angekündigten Übernahme oder einer vergleichbaren Transaktion setzt. Der Abstand zum Angebotspreis steht möglichen Abschlussgewinnen, Scheiternverlusten, Zeit und Kosten gegenüber. Trotz des Namens ist das gewöhnlich keine risikolose Arbitrage.','alternatives-09','hedge-funds','event-driven','Übernahmearbitrage'),
 G('Deal Spread','Abstand zwischen dem aktuellen Preis eines Übernahmeziels und der im Erfolgsfall erwarteten Gegenleistung. Der Spread ist kein sicherer Gewinn: Scheitern, geänderte Bedingungen, Wartezeit und Finanzierung beeinflussen den tatsächlichen Ertrag. Aktienangebote benötigen zusätzlich die Analyse ihrer Tausch- und Hedgeverhältnisse.','alternatives-09','hedge-funds','deal-math'),
 G('Deal-Break-Risiko','Risiko, dass eine erwartete Transaktion scheitert oder wesentlich anders abgeschlossen wird. Der dann erreichbare Zielunternehmenswert kann deutlich unter dem Einstiegskurs liegen. Eine Abschlusswahrscheinlichkeit muss mit beiden Endzuständen, Kosten und Zeitpunkt verbunden werden.','alternatives-09','hedge-funds','deal-math'),
 G('Relative Value','Strategien, die Unterschiede zwischen ökonomisch zusammenhängenden Positionen ausnutzen sollen. Ähnliche Instrumente können unterschiedliche Rechte, Kreditrisiken oder Liquidität besitzen. Spreads können sich weiter ausweiten, und eine Position kann vor einer möglichen Konvergenz an Finanzierung oder Margin scheitern.','alternatives-09','hedge-funds','relative-value','Relative-Value-Strategie'),
 G('Convertible Arbitrage','Strategie mit Wandelanleihen und häufig einem Aktienhedge. Ein Delta-Hedge kann die lokale erste Aktienkursempfindlichkeit reduzieren, lässt aber unter anderem Volatilität, Krümmung, Emittentenbonität, Leihe und Finanzierung übrig. Gleicher lokaler Deltaeffekt ist keine globale Risikolosigkeit.','alternatives-09','hedge-funds','convertible','Wandelanleihenarbitrage'),
 G('Fixed-Income Arbitrage','Sammelbegriff für relative Positionen in Zins- und Kreditinstrumenten. Kurve, Spread, Basis, Liquidität und Finanzierung können unterschiedlich wirken; kleine erwartete Spreads werden teilweise mit hohem Bruttoengagement umgesetzt. Der Name allein belegt keine sichere Arbitrage.','alternatives-09','hedge-funds','fixed-income'),
 G('Global Macro','Strategien auf Basis breiter wirtschaftlicher Entwicklungen, etwa Zinsen, Währungen, Politik oder Konjunktur. Positionen können diskretionär oder systematisch und über verschiedene Instrumente umgesetzt werden. Prognosefehler, Hebel und täglicher Cashbedarf bleiben wesentliche Risiken.','alternatives-09','hedge-funds','macro'),
 G('Managed Futures','Professionell verwaltete Strategien mit Futures und gegebenenfalls weiteren Derivaten, häufig aber nicht zwingend systematische Trendfolge. Ein Trendsignal kennt die Zukunft nicht. Richtungswechsel, Handelskosten, Margin und der tatsächliche Sicherheitenpfad beeinflussen das Anlegerergebnis.','alternatives-09','hedge-funds','managed-futures'),
 G('Whipsaw','Verlustmuster, bei dem eine Strategie nach einem Signal einsteigt und die Kursrichtung kurz darauf wieder umkehrt. Wiederholte Wechsel können in Trendfolgestrategien kleine Verluste und Kosten anhäufen. Ein früherer Trend garantiert keine gewinnbringende Fortsetzung.','alternatives-09','hedge-funds','managed-futures'),
 G('Volatilitätsstrategie','Strategie, deren Ergebnis besonders auf Ausmaß, Preis oder Verlauf von Schwankungen reagiert, häufig über Optionen. Long- und Short-Volatilität haben unterschiedliche Prämien- und Tail-Profile. Niedrige gewöhnliche Streuung oder häufige kleine Gewinne beweisen keine geringe Extremverlustgefahr.','alternatives-09','hedge-funds','volatility','Volatility Strategy'),
 G('Straddle','Kombination aus Call und Put mit gleichem Strike und Verfall. Ein Long-Straddle profitiert im einfachen Verfallsbild von ausreichend großer Bewegung in beide Richtungen, muss aber die gezahlten Prämien verdienen. Der Short-Straddle erhält Prämie und trägt die entgegengesetzten Pflichten; Zeitwert, Volatilität und Finanzierung wirken vor Verfall zusätzlich.','alternatives-09','hedge-funds','volatility'),
 G('Hedgefonds-Dachfonds','Fonds, der Anteile an anderen Hedgefonds hält. Er kann Zugang, Auswahl und laufende Prüfung bündeln, fügt aber eine eigene Kosten- und Anspruchsebene hinzu. Gemeinsame Faktoren, Positionen, Broker oder Rückgabebeschränkungen der Zielfonds können trotz vieler Namen bestehen bleiben.','alternatives-09','hedge-funds','fund-of-funds','Fund of Hedge Funds|Fund of Funds'),
 G('Master-Feeder','Struktur, in der ein oder mehrere Feeder Anlegerkapital in einem gemeinsamen Master bündeln. Verschiedene Zugangswege können organisatorische oder anlegerspezifische Zwecke erfüllen. Zwei Feeder im selben Master erzeugen allein noch keine unabhängigen Anlageerträge oder Risikotreiber.','alternatives-09','hedge-funds','master-feeder','Master Feeder'),
 G('Managed Account','Gesondert verwaltetes Anlegerkonto mit konkret vereinbartem Mandat. Eigentum, Berichte, Restriktionen und Kontrolle können direkter ausgestaltet werden als bei einem gepoolten Fonds. Individuelle Umsetzung kann eigene Größen-, Kosten-, Verwahrungs- und Gegenparteianforderungen haben.','alternatives-09','hedge-funds','managed-account','Separately Managed Account'),
 G('Liquid Alternatives','Liquider ausgestaltete Produkte mit alternativen Strategiemerkmalen unter ihrem jeweiligen Regel- und Vertragsrahmen. Ähnliche Strategienamen gewährleisten keine gleichen Instrumente, Hebel, Kosten oder Renditen wie private Hedgefonds. Weder täglicher Zugang noch eine universelle Überlegenheit wird allein aus dem Namen abgeleitet.','alternatives-09','hedge-funds','liquid-alts','Liquid Alts'),
 G('Hedgefonds-Gate','Vertragliche Begrenzung bestimmter Rückgaben an einem Stichtag oder in einer Periode. NAV-Basis, Anwendungsbereich, Zuteilung und spätere Behandlung offener Anträge sind konkret festzulegen. Ein Gate ist weder zusätzlicher Ertrag noch eine Garantie, dass selbst der begrenzte Betrag bei weiteren Beschränkungen sofort bezahlt wird.','alternatives-09','hedge-funds','redemption','', [{label:'Gate',units:['hedge-funds']}]),
 G('Hedgefonds-Side-Pocket','Gesondert geführter Teil eines Fonds, häufig für schwer bewertbare oder illiquide Positionen. Beteiligung, Bewertung, Gebühren und Rückgabe können besonderen Regeln folgen. Separater Ausweis bedeutet weder einen tatsächlich abgeschlossenen Verkauf noch garantiert sofort verfügbares Geld.','alternatives-09','hedge-funds','redemption','', [{label:'Side Pocket',units:['hedge-funds']}]),
 G('Crowding','Konzentration vieler Anleger auf ähnliche Positionen, Signale oder Finanzierungswege. Gleichzeitige Ausstiege können Preise, Marktliquidität und Sicherheitenbedarf gemeinsam verschlechtern. Viele Fondsnamen beseitigen solche gemeinsamen wirtschaftlichen Risiken nicht.','alternatives-09','hedge-funds','stress','Crowded Trades'),
 G('Naturressourcen','Anlagen mit Bezug zu Land, Wald, Agrarproduktion oder Rohstoffen. Die Ertragsquelle hängt vom konkreten Anspruch ab: Pacht, Bewirtschaftung, Holzernte, Warenpreis oder Derivat. Ein Kategoriename garantiert weder laufendes Einkommen noch unabhängiges Risiko oder perfekten Inflationsschutz.','alternatives-07','resources','map','Natural Resources'),
 G('Unbewirtschaftetes Land','Grundstück ohne im Fall bezeichnete laufende Bewirtschaftungs- oder Pachteinnahmen. Ein positiver Bruttoertrag hängt dann vor allem am später erzielbaren Preis. Halte-, Entwicklungs- und Finanzierungskosten können trotzdem vorher Geld benötigen.','alternatives-07','resources','land','Raw Land'),
 G('Farmland','Für landwirtschaftliche Nutzung gehaltene Fläche. Ein Anleger kann feste oder variable Pacht erhalten oder den Betrieb selbst tragen. Boden, Wasser, Ernte, Preise, Kosten und Verträge bestimmen je nach Zugang unterschiedliche Zahlungen und Risiken.','alternatives-07','resources','farm-access','Agrarland'),
 G('Timberland','Forstfläche mit Land- und gegebenenfalls stehenden Bestandsrechten. Erträge können aus Holzernte, biologischem Wachstum und Wertänderung entstehen. Erntekosten, Preis, Schaden und verbleibender Landwert müssen ohne doppelte Bestandszählung verbunden werden.','alternatives-07','resources','biology','Forstfläche'),
 G('Feste Agrarpacht','Vertraglicher Pachtbetrag für eine bezeichnete Flächennutzung. Direkte Ernte- und Marktpreisänderungen liegen zunächst stärker beim Betreiber, können aber Bonität und spätere Pachttragfähigkeit beeinflussen. Der Eigentümer trägt weiterhin seine tatsächlichen Kosten und Vertragsrisiken.','alternatives-07','resources','farm-access'),
 G('Ertragsabhängige Pacht','Pacht auf Basis einer konkret definierten Größe, etwa Erlös oder Ergebnis. Quote, Kostenverteilung und Abrechnung müssen offengelegt werden. Gleiche Prozentsätze auf Umsatz und auf Überschuss sind keine gleichen Ansprüche.','alternatives-07','resources','farm-leases'),
 G('Biologisches Wachstum','Zunahme des natürlichen Bestands, etwa an verkaufbarem Holzvolumen oder Qualität. Es ist eine physische Größe und keine garantierte Finanzrendite. Preise, Erntekosten, Wartezeit, Pflege und Schäden können den wirtschaftlichen Ertrag anders verändern.','alternatives-07','resources','biology','Biological Growth'),
 G('Nettoerntezahlung','Verkaufserlös der tatsächlich vermarkteten Menge abzüglich ausdrücklich bezeichneten Ernte- und Vermarktungskosten. Laufende Besitzkosten, Finanzierung und der verbleibende Landanspruch sind gegebenenfalls separat zu berücksichtigen.','alternatives-07','resources','biology','Net Harvest Proceeds'),
 G('Ernteflexibilität','Möglichkeit, den Erntetermin in bestimmten Grenzen zu wählen. Bei Wald kann späteres Wachstum eine Verschiebung erlauben, die aber Preis-, Schaden-, Pflege-, Rechts- und Liquiditätsrisiken trägt. Mehr spätere Menge garantiert keinen höheren heutigen Wert.','alternatives-07','resources','harvest','Harvest Timing'),
 G('Forstrotation','Zyklus aus Aufforstung, Wachstum und Ernte. Bei einer wiederholten Strategie entstehen erneut Pflanz- und Pflegekosten. Ein Wert aller künftigen Nutzungen darf nicht zusätzlich ein zweites Mal als derselbe unbereinigte Landanspruch angesetzt werden.','alternatives-07','resources','rotation','Forest Rotation'),
 G('Land Expectation Value','Wert eines Landanspruchs aus einem ausdrücklich angenommenen wiederholten Aufforstungs-/Ernteplan. Die geometrische Herleitung benötigt identische unbegrenzt wiederholte Zyklen und einen passenden positiven Diskontsatz. Zusätzliche Kosten, Risiken oder endliche Rechte verändern den Ansatz.','alternatives-07','resources','rotation','LEV'),
 G('Stehender Holzbestand','Noch nicht geerntetes verkaufbares Holz beziehungsweise die dazugehörigen wirtschaftlichen Rechte. Ist dieser Bestand bereits im Preis einer gesamten Forstfläche enthalten, darf derselbe Anspruch beim Verkauf nicht zusätzlich als ebenfalls erhaltene Erntezahlung gezählt werden.','alternatives-07','resources','land-terminal','Standing Timber'),
 G('Rohstoff','Physisches Gut bestimmter Qualität und Lieferbarkeit, etwa Energie, Metall oder Agrargut. Preis und Nutzwert hängen von Angebot, Nachfrage, Beständen und konkreten Spezifikationen ab. Die Ware allein verspricht keinen Anleihekupon und keine feste Rückzahlung.','alternatives-08','resources','commodity-features','Commodity|Commodities'),
 G('Hard Commodities','Grobe gebräuchliche Bezeichnung für etwa geförderte Metalle oder extrahierte Energiegüter. Sie ersetzt keine konkrete Prüfung von Produktionsvorlauf, Lagerung, Qualität, Lieferort und Nachfrage.','alternatives-08','resources','sectors'),
 G('Soft Commodities','Grobe gebräuchliche Bezeichnung für angebaute oder gezüchtete Rohstoffe, etwa Agrargüter. Biologische Vorlaufzeiten, Wetter, Verderb, Wasser und Verarbeitung können sich je Produkt deutlich unterscheiden.','alternatives-08','resources','sectors'),
 G('Physischer Rohstoffnutzen','Vorteil unmittelbar verfügbarer Ware, etwa die Vermeidung eines Produktionsstillstands. Als Convenience Yield kann er eine Carry-Relation erklären. Er ist keine automatisch an jeden Future- oder Fondsinhaber ausgezahlte Dividende.','alternatives-08','resources','storage','',[{label:'Convenience Yield',units:['resources']},{label:'Besitznutzen',units:['resources']}]),
 G('Rohstoffbasis','Hier ausdrücklich passender Spotpreis minus Preis des bezeichneten Futures. Andere Texte können das Vorzeichen umkehren. Güte, Ort und Liefer-/Abrechnungstermin müssen passen; eine beliebige ähnliche Spotnotierung genügt nicht.','alternatives-08','resources','basis','',[{label:'Basis',units:['resources']}]),
 G('Rohstoff-Contango','Höherer betrachteter Terminpreis gegenüber passendem Spot beziehungsweise steigender betrachteter Abschnitt zwischen naher und ferner Fälligkeit. Welche Preise verglichen werden, ist anzugeben. Keine Garantie eines späteren Spotanstiegs oder positiven Long-Ertrags.','alternatives-08','resources','curve','',[{label:'Contango',units:['resources']}]),
 G('Rohstoff-Backwardation','Niedrigerer betrachteter Terminpreis gegenüber passendem Spot beziehungsweise fallender betrachteter Fälligkeitsabschnitt. Die spätere tatsächliche Preisbewegung bleibt unsicher. Der Begriff allein garantiert einem Long-Anleger keinen Gewinn.','alternatives-08','resources','curve','',[{label:'Backwardation',units:['resources']}]),
 G('Normal Backwardation','In Renditetheorien verwendete Relation eines Futures zum erwarteten späteren Spot. Diese Erwartung ist vom heute beobachteten Spot zu unterscheiden und kann falsch liegen. Eine erwartete Risikoprämie ist keine sichere positive Auszahlung in jedem Zustand.','alternatives-08','resources','curve'),
 G('Rohstoff-Rollwirkung','Renditewirkung einer Strategie, die auslaufende Kontrakte durch spätere ersetzt. Einstiegspreis, anschließende Konvergenz, gewählte Mengen und Abrechnung sind konkret zu verfolgen. Eine Differenz alter und neuer Quotes ist nicht allein eine sofortige volle Kaufpreis- oder Verlustzahlung beim neuen fairen Einstieg.','alternatives-08','resources','roll','',[{label:'Roll Yield',units:['resources']},{label:'Rollrendite',units:['resources']}]),
 G('Rohstoff-Variation-Margin','Tatsächlich abgerechnete Preisgewinne oder -verluste des gehaltenen Futures. Menge mal Preisänderung und passender Multiplikator ergeben den Kontobetrag. Nach vollständiger Abrechnung darf dieselbe Preiswirkung nicht nochmals als zusätzlicher nicht abgerechneter Kontraktwert angesetzt werden.','alternatives-08','resources','futures-cash','',[{label:'Variation Margin',units:['resources']}]),
 G('Vollunterlegte Futuresposition','Position mit anfänglich liquiden Sicherheiten in Höhe des ganzen bezeichneten positiven Entry-Nominalwerts. Das ist im Labor eine eigene Vermögenskonvention, keine universelle Börsen-Mindestmargin. Beim späteren Rebalancing bestimmt vorhandenes Cash die neu tragbare Referenzmenge.','alternatives-08','resources','futures-cash','Fully Collateralized Futures'),
 G('Rohstoff-Excess-Return','Definierte Futures-/Indexrendite vor einer zusätzlich bezeichneten Sicherheitenzinskomponente. Roll-, Mengen- und Abrechnungsmethodik müssen bekannt sein. Nicht automatisch identisch mit einem allgemeinen Alpha oder einer Rendite über jede beliebige Benchmark.','alternatives-08','resources','collateral','',[{label:'Excess Return',units:['resources']}]),
 G('Rohstoff-Gesamtrendite','Vollständige Rendite der bezeichneten Rohstoffstrategie einschließlich ihrer ausdrücklich erfassten Preis-/Rollwirkung, tatsächlicher Sicherheitenzinsen und Kosten. Vergleichbare Nenner, Perioden und Zahlungsregeln sind erforderlich.','alternatives-08','resources','collateral','',[{label:'Total Return',units:['resources']},{label:'Gesamtrendite',units:['resources']}]),
 G('Sicherheitenzins','Tatsächliche Verzinsung des nach den geltenden Regeln vorhandenen freien oder gebundenen Sicherheitenvermögens. Frühe Preisgewinne und -verluste können die spätere Zinsbasis verändern. Nicht jeder Marginbestand ist frei verfügbar oder identisch verzinst.','alternatives-08','resources','daily','Collateral Return'),
 G('Spotpreisreferenz','Reine Veränderung einer bezeichneten Kassapreisreihe. Ohne Ergänzung um Lagerung, Versicherung, Finanzierung und Ausführungskosten ist sie keine vollständige behauptete physische Nettostrategie.','alternatives-08','resources','return-basis','Spot Price Return'),
 G('Rohstoffindex','Nach einer Methodik ausgewählter und gewichteter Rohstoffkorb beziehungsweise Kontraktindex. Fälligkeiten, Rollfenster, Rebalancing sowie Excess-/Total-Return-Konvention können die Rendite verändern. Ähnliche Namen garantieren keine gleiche wirtschaftliche Exposition.','alternatives-08','resources','indices','Commodity Index'),
 G('Rollfenster','Zeitraum, in dem eine Strategie gehaltene nahe Kontrakte durch spätere Fälligkeiten ersetzt. Die tatsächlich verwendeten Kurse, Mengen und Handelskosten beeinflussen das Ergebnis. Eine Referenz muss nach derselben Rollregel verglichen werden.','alternatives-08','resources','indices','Roll Window'),
 G('Ressourcen-Liquiditätsrisiko','Risiko, fällige Betriebsausgaben, Erneuerung oder Margin nicht rechtzeitig durch freie Mittel decken zu können. Ein später erwarteter Preisgewinn oder geglätteter NAV garantiert keine heutige Zahlung. Handelbarkeit und verfügbare Kasse sind unterschiedliche Aspekte.','alternatives-08','resources','liquidity'),
 G('Objekt-NOI','Operativer Objektüberschuss aus Mieten und anderen Objekterträgen nach laufenden Objektkosten, aber vor Kreditzins, Tilgung, Abschreibung und Capex. Laufende Grundsteuern können zu Objektkosten gehören; Anleger-Ertragsteuern sind davon zu unterscheiden. Ein periodisierter NOI kann wegen Mietforderungen außerdem von erhaltenem Cash abweichen.','alternatives-06','real-assets','noi','',[{label:'NOI',units:['real-assets']},{label:'Net Operating Income',units:['real-assets']}]),
 G('Immobilien-Cap-Rate','Verhältnis eines genau bezeichneten jährlichen NOI zum heutigen Objektpreis. Current-/Trailing-Cap verwendet aktuellen beziehungsweise vergangenen, Forward-Cap erwarteten nächsten NOI. Fünf Prozent NOI-Cap sind nach notwendigem Capex nicht automatisch fünf Prozent frei verfügbare Cashrendite.','alternatives-06','real-assets','cap-rate','',[{label:'Cap Rate',units:['real-assets']},{label:'Capitalization Rate',units:['real-assets']},{label:'Kapitalisierungssatz',units:['real-assets']}]),
 G('Forward-Cap-Rate','Erwarteter NOI der nächsten Jahresperiode geteilt durch den Preis am betrachteten Stichtag. Bei einem Verkauf am Ende von Jahr fünf kann der Zähler daher NOI des sechsten Jahres sein. Der Verkäufer erhält nicht zusätzlich zu diesem Verkauf bereits diese nächste Miete als zweite Zahlung.','alternatives-06','real-assets','periods','Forward-Cap|Forward-NOI-Cap'),
 G('Current-Cap-Rate','Aktueller Jahres-NOI relativ zum heutigen Preis. Bei unverändertem Preis und wachsendem NOI liegt die auf nächstes Jahr bezogene Forward-Cap höher. Ein Cap-Vergleich braucht dieselbe Perioden- und Kostenbasis.','alternatives-06','real-assets','periods','Current-Cap|Trailing-Cap'),
 G('Effektiver Bruttoobjektertrag','Mögliche volle Miete nach ausdrücklich angesetzten Leerstands- und Ausfallabzügen plus weiteren laufenden Objekterträgen. Operative Objektkosten sind davon für NOI noch abzuziehen. Die konkrete Behandlung von Incentives und Forderungen muss offengelegt werden.','alternatives-06','real-assets','noi','Effective Gross Income|EGI'),
 G('Mietfreie Zeit','Vertragliche Nutzungsperiode ohne die bezeichnete Mietzahlung. Die späteren tatsächlich vereinbarten Zahlungen bestimmen den Cashflow; eine rechnerisch gleichmäßige Durchschnittsmiete darf nicht als in jedem Jahr erhaltenes Geld eingesetzt werden.','alternatives-06','real-assets','leases','Rent-free Period'),
 G('Mieterbonität','Fähigkeit und Bereitschaft des Mieters, seine Vertragszahlungen zu erfüllen. Lange Laufzeit und hohe genannte Miete gewährleisten keine tatsächliche Zahlung. Gemeinsame Großmieter können mehrere Objekte wirtschaftlich konzentrieren.','alternatives-06','real-assets','tenant-credit','Tenant Credit'),
 G('Core-Immobilie','Übliche Marktbezeichnung für ein eher etabliertes, stabiler vermietetes Objektprofil. Sie ist keine einheitliche Garantie geringen Risikos. Standort, Zustand, Mietverträge, Finanzierung und Kaufpreis bleiben einzeln zu prüfen.','alternatives-06','real-assets','strategies','',[{label:'Core',units:['real-assets']}]),
 G('Core Plus','Übliche Immobilienstrategie mit zusätzlichen Verbesserungs-, Objekt- oder Finanzierungsrisiken gegenüber einem einfachen Core-Profil. Grenzen der Marktbezeichnungen sind nicht überall identisch; maßgeblich sind die tatsächlichen Maßnahmen und Zahlungen.','alternatives-06','real-assets','strategies'),
 G('Value-add','Strategie, die Wert durch wesentliche Veränderungen wie Umbau, höhere Belegung oder Neuvermietung erreichen soll. Mehr erwarteter NOI muss gegen zusätzliche Investition, Zeit, Finanzierung und Ausführungsrisiko gerechnet werden.','alternatives-06','real-assets','strategies','Value Add'),
 G('Opportunistische Immobilienstrategie','Immobilienansatz mit häufig höherem Entwicklungs-, Umwandlungs-, Finanzierungs- oder Problemobjektrisiko. Hohe Zielrendite ist weder sichere Auszahlung noch Beweis positiven Kapitalwerts nach Kosten.','alternatives-06','real-assets','strategies'),
 G('Immobilien-Cashkonversion','Anteil des NOI, der nach den ausdrücklich bezeichneten weiteren Ausgaben als verfügbarer Cashflow bleibt. Bei wiederkehrendem Capex von zehn Prozent des zahlungswirksamen NOI beträgt diese Quote im einfachen Fall 90 Prozent. Andere Forderungs-, Reserve- und Steuerpositionen können weitere Überleitungen erfordern.','alternatives-06','real-assets','growth-return'),
 G('Exit-Cap','Kapitalisierungssatz für den im Verkaufszeitpunkt angesetzten zukünftigen Objektertrag. Im Labor ist es eine Forward-Quote auf NOI des ersten Käuferjahrs. Ein höherer Exit-Cap senkt bei unverändertem NOI den Verkaufspreis und damit DCF und Kaufpreis-IRR.','alternatives-06','real-assets','exit','Exit-Cap-Rate|Verkaufs-Cap'),
 G('Verkaufsbarwertanteil','Anteil des diskontierten Nettoverkaufs am gesamten DCF. Er beschreibt die Abhängigkeit der Bewertung von der Schlussannahme, nicht die Wahrscheinlichkeit eines erfolgreichen Exits oder den sicheren späteren Erlös.','alternatives-06','real-assets','terminal-risk'),
 G('Real Estate Investment Trust','Nach den jeweiligen Regeln organisiertes Immobilien- oder Immobilienfinanzierungsvehikel. Equity REITs und Mortgage REITs haben unterschiedliche typische Anspruchs- und Risikoprofile. Börsliche Handelbarkeit, Steuerstatus und Ausschüttungspflichten müssen konkret geprüft werden; keine weltweit gleiche Quote wird unterstellt.','alternatives-06','real-assets','reit','REIT|REITs'),
 G('NAV je Aktie','Geschätzter Nettovermögenswert der zutreffenden Anteilsebene geteilt durch deren Aktienzahl. Bewertete Objekte und weitere Vermögenswerte werden um Schulden und weitere Verpflichtungen bereinigt. Der Börsenkurs kann davon abweichen; der NAV ist keine sichere sofortige Liquidationszahlung.','alternatives-06','real-assets','nav','NAVPS|NAV per Share'),
 G('Funds from Operations','Im REIT-Kontext eine aus dem Ergebnis übergeleitete Kennzahl mit Anpassungen für bestimmte Immobilienabschreibungen und Veräußerungs- oder weitere definierte Effekte. Die genaue Nareit-Abgrenzung ist zu beachten. Nicht identisch mit Dividende, Geldflussrechnung oder der gleichnamigen Kreditkennzahl.','alternatives-06','real-assets','ffo','FFO'),
 G('Adjusted Funds from Operations','Weitere bereinigte REIT-Kennzahl, etwa mit offengelegten Anpassungen für wiederkehrendes Capex oder noch nicht erhaltene Mietbestandteile. Die konkrete AFFO-Definition und Überleitung muss geprüft werden; sie ist nicht universell und keine Garantie einer Ausschüttung.','alternatives-06','real-assets','ffo','AFFO'),
 G('FFO/AFFO','Zwei verwandte, aber nicht identische Immobilienkennzahlen. FFO überleitet das Ergebnis nach seiner Definition; AFFO kann weitere, vom Anbieter offenzulegende Cash- oder Erhaltungsanpassungen vornehmen. Eine Doppelzählung desselben Capex oder ein Vergleich unterschiedlicher Definitionen wäre irreführend.','alternatives-06','real-assets','ffo'),
 G('Funktionale Obsoleszenz','Verlust wirtschaftlicher Nutzbarkeit durch ungeeignete Technik, Gestaltung oder andere veränderte Anforderungen. Ein physisch bestehendes Asset kann dadurch weniger Miete erzielen, Leerstand haben oder weitere Investition benötigen.','alternatives-06','real-assets','property-limits','Functional Obsolescence'),
 G('Infrastruktur','Kapitalintensive, oft langlebige Anlagen für wirtschaftliche oder soziale Leistungen wie Verkehr, Netze, Wasser oder öffentliche Einrichtungen. Anlegererträge folgen konkreten Eigentums-, Kredit- oder Vertragsrechten. Gesellschaftlicher Nutzen garantiert keine private Rentabilität.','alternatives-07','real-assets','infrastructure','Infrastructure'),
 G('Greenfield','Projekt mit noch wesentlicher Entwicklung, Genehmigung, Bau oder Inbetriebnahme vor etabliertem Betrieb. Frühere Auszahlungen und später erst mögliche Einnahmen erzeugen insbesondere Fertigstellungs-, Termin- und Kostenrisiken.','alternatives-07','real-assets','stages','Greenfield-Projekt|Greenfield-Projekte'),
 G('Brownfield','Bereits bestehende beziehungsweise betriebene Infrastruktur mit beobachtbaren Leistungen und Kosten. Der laufende Betrieb beseitigt Erhaltung, regulatorische Änderungen, technische Erneuerung oder Refinanzierungsrisiko nicht.','alternatives-07','real-assets','stages','Brownfield-Projekt|Brownfield-Projekte'),
 G('Nutzerentgelt','Vergütung auf Basis tatsächlich bezahlter Nutzung, etwa Verkehrsmenge mal Tarif. Mengenrückgänge können bei hohen Fixkosten den Überschuss überproportional belasten. Preisregeln, Kosten und mögliche Mindestzusagen müssen konkret bestimmt werden.','alternatives-07','real-assets','user-pay','User-pay|User Pay'),
 G('Verfügbarkeitszahlung','Vertragliche Vergütung für eine nach definierten Standards verfügbare Leistung oder Anlage. Sie kann direktes Nutzermengenrisiko verlagern, bleibt aber von Leistungskriterien, Abzügen, Vertrag und Zahlungsfähigkeit des Verpflichteten abhängig.','alternatives-07','real-assets','availability','Availability Payment'),
 G('Konzession','Vertraglich beziehungsweise rechtlich begrenztes Nutzungs-, Betriebs- oder Einnahmerecht. Dauer, Verlängerung, Restrechte und Rückgabe bestimmen die berechtigten Zahlungen. Ein endliches Recht darf ohne zusätzliche Grundlage nicht wie unbeschränktes ewiges Eigentum bewertet werden.','alternatives-07','real-assets','concession','Concession'),
 G('Build–Operate–Transfer','Struktur aus Errichtung, Betrieb und späterer Übertragung. Bei ausdrücklich entschädigungslosem Ende aller privaten Rechte kann der private Schlusswert null sein; mögliche Rückgabeaufwendungen kommen gesondert hinzu. Die konkrete Vertragslage bleibt maßgeblich.','alternatives-07','real-assets','concession','Build-Operate-Transfer|BOT'),
 G('Rückgabepflicht','Verpflichtung, ein Projekt bei Vertragsende in einem bestimmten Zustand zu übergeben. Notwendige Erneuerungen und weitere Kosten müssen zu ihrem tatsächlichen Termin in den Cashflow eingehen, auch wenn kein zusätzlicher Verkaufserlös besteht.','alternatives-07','real-assets','handback','Handback'),
 G('Public–Private Partnership','Vertragliche Zusammenarbeit öffentlicher und privater Beteiligter an einer Leistung oder einem Projekt. Bau-, Betriebs-, Mengen-, Finanzierungs- und politische Risiken hängen von konkreten Verträgen ab. Die Bezeichnung ist keine allgemeine Staatsgarantie für Kredit oder Eigenkapitalgewinn.','alternatives-07','real-assets','project-structure','Public-Private Partnership|PPP'),
 G('Projekt-CFADS','Nach der konkreten Kreditdefinition für Schuldendienst verfügbares Projektcash. Verpflichtende vorgelagerte Betriebsausgaben, Investitionen oder gebundene Reservebeiträge können es vermindern. Im eigenen Fall werden 24 vor Reserve durch sechs Pflichtreserve auf 18 verfügbares Cash reduziert.','alternatives-07','real-assets','infrastructure-debt','',[{label:'CFADS',units:['real-assets']},{label:'Cash Flow Available for Debt Service',units:['real-assets']}]),
 G('Anerkannte Kapitalbasis','Für eine konkret definierte Vergütungsregel zugelassener Kapitalbetrag. Er kann vom tatsächlich investierten Betrag abweichen. Eine erlaubte Rendite auf diese Basis ist deshalb kein automatisch identischer Ertrag des gesamten Anlegerkapitals.','alternatives-07','real-assets','regulated','Approved Capital Base'),
 G('Abnahmevertrag','Vereinbarung über Kauf oder Vergütung künftiger Projektleistung, etwa Energie. Sie kann bestimmte Preis- oder Mengenrisiken verlagern, benötigt aber einen zahlungsfähigen Abnehmer und durchsetzbare Bedingungen. Langfristigkeit allein beseitigt Gegenparteirisiko nicht.','alternatives-07','real-assets','currency-policy','Offtake Agreement'),
 G('Private Equity','Eigenkapitalanlage außerhalb gewöhnlicher öffentlicher Börsenanteile, etwa Venture, Growth oder Buyout. Der Anspruch trägt den wirtschaftlichen Rest nach vorrangigen Verpflichtungen. Hohe Kontrolle, Wachstum oder Illiquidität garantieren weder hohen Nettoertrag noch einen erfolgreichen Exit.','alternatives-04','private-capital','claims'),
 G('Private Credit','Privat vereinbarte oder gehaltene Kreditfinanzierung, häufig direkt oder über spezialisierte Fonds. Rang, Sicherheit, Verzinsung, Covenants und Rückzahlung sind einzeln zu bestimmen. Ein hoher vertraglicher Kupon ist keine Garantie tatsächlicher Zahlung oder hoher realisierter Rendite.','alternatives-05','private-capital','debt-map','Private Debt'),
 G('Venture-Finanzierung','Beteiligungskapital für junge Unternehmen mit oft unsicherem Produkt, Markt oder Finanzierungsbedarf. Mehrere Finanzierungsrunden können Informationsgewinn und begrenzten Ersteinsatz ermöglichen, bringen aber Anschlussfinanzierungs- und Verwässerungsrisiko.','alternatives-04','private-capital','venture','',[{label:'Venture Capital',units:['private-capital']}]),
 G('Wachstumsbeteiligung','Eigenkapital zur Expansion einer bereits besser belegten Geschäftsbasis. Neues Kapital, Kauf bestehender Anteile und Kontrolle sind getrennte Merkmale. Umsatzwachstum ist nur dann ein Wertargument, wenn Rentabilität, Kapitalbedarf, Preis und spätere Cashflows zusammenpassen.','alternatives-04','private-capital','growth','',[{label:'Growth Equity',units:['private-capital']}]),
 G('Buyout','Erwerb einer maßgeblichen Beteiligung, häufig mit Kontrollabsicht über einen reiferen Betrieb. Operative Veränderungen, Kaufpreis, Finanzierung und Exit bestimmen den Ertrag gemeinsam. Bei einem fremdfinanzierten Buyout entsteht nicht jeder Eigenkapitalgewinn aus operativer Verbesserung.','alternatives-04','private-capital','buyouts'),
 G('Management Buyout','Unternehmens- oder Beteiligungskauf unter Beteiligung des bisherigen Managementteams. Beschreibt eine Rolle der handelnden Personen und keine automatische Garantie von Preisqualität, Finanzierungstragfähigkeit oder Rendite.','alternatives-04','private-capital','buyouts','MBO'),
 G('Management Buy-in','Unternehmenskauf mit Einführung eines neuen Managementteams. Ein Wechsel kann eine neue operative Richtung ermöglichen, muss aber nach Erfahrung, Ausführung, Anreizen und Finanzierungsrisiko beurteilt werden.','alternatives-04','private-capital','buyouts','MBI'),
 G('Cash Burn','Nettoverbrauch verfügbarer Geldmittel in einem bezeichneten Zeitraum. Für eine Runway-Rechnung sind freie Kasse, konstante oder veränderliche Abflüsse und realistisch verfügbare neue Finanzierung getrennt zu prüfen. Ein Buchverlust muss nicht exakt dem Cash Burn entsprechen.','alternatives-04','private-capital','venture'),
 G('Runway','Rechnerische Zeit, bis verfügbare freie Mittel bei angenommener Verbrauchsrate aufgebraucht sind. Sechs freie WE und 0,5 WE konstanter monatlicher Nettoabfluss ergeben zwölf Monate. Ein veränderter Verbrauch oder verzögerter Finanzierungsabschluss kann die tatsächliche Reichweite ändern.','alternatives-04','private-capital','venture'),
 G('Stufenfinanzierung','Bereitstellung von Kapital in mehreren Runden oder nach definierten Entwicklungsschritten. Kann den frühen Einsatz begrenzen und neue Information nutzen. Eine spätere Runde ist jedoch nicht automatisch gesichert; ihr Preis und ihre Rechte können alte Eigentümer verwässern.','alternatives-04','private-capital','venture','Staged Financing'),
 G('Primärfinanzierung','Ausgabe neuer Ansprüche gegen eine Zahlung an das Unternehmen. Bei einer reinen gleichberechtigten Eigenkapital-Bareinzahlung ohne Kosten entspricht Post-Money dem Pre-Money-Wert plus neuem Cash. Ein Verkauf bestehender Anteile an einen anderen Eigentümer ist ein anderer Geldfluss.','alternatives-04','private-capital','primary-secondary','Primary Financing'),
 G('Sekundärbeteiligung','Erwerb bereits bestehender Anteile von einem bisherigen Eigentümer. Der Kaufpreis geht in einer reinen Sekundärtransaktion an den Verkäufer und ist kein neues Betriebscash. Zusätzliche primäre Ausgabe oder Finanzierung kann getrennt daneben stattfinden.','alternatives-04','private-capital','primary-secondary'),
 G('Verwässerungsfaktor','Verhältnis, mit dem eine alte Quote unter bezeichneten gleichartigen Anteilrechten nach einer neuen Ausgabe multipliziert wird. Bei einer reinen Primärrunde ohne weitere Änderungen ist es Pre-Money geteilt durch Post-Money; Optionspools und Vorzugsrechte können zusätzliche Regeln verlangen.','alternatives-04','private-capital','dilution'),
 G('Nicht teilnehmender Vorzugsanspruch','Hier eigener Aktienvertrag: Wahl zwischen bis zur verfügbaren Masse begrenzter bevorzugter Zahlung und Umwandlung in eine gewöhnliche Quote. Nach Inanspruchnahme des Vorzugs erfolgt keine zusätzliche Teilnahme am Rest. Die zwei Alternativen werden nicht addiert.','alternatives-04','private-capital','preferences'),
 G('Cash Sweep','Vertragliche Verwendung definierter verfügbarer Mittel zur Schuldentilgung. Im eigenen Buyout-Plan geht Cash zuerst an Zins, dann bis zur ausstehenden Schuld an Tilgung und erst danach an Dividenden. Eine Tilgung kann die tatsächliche Restschuld nicht unterschreiten.','alternatives-04','private-capital','cash-debt'),
 G('Buyout-Cashquote','Eigene Modellannahme zur Umwandlung des jährlichen EBITDA in für Schuldendienst verfügbares Cash nach bereits berücksichtigten Steuern, Investitionen und weiteren operativen Zahlungen, aber vor Kreditzins. Keine allgemeine Free-Cashflow-Definition und keine Garantie konstanter Konversion.','alternatives-04','private-capital','calculator'),
 G('Zinsstützung','Im eigenen Szenario tatsächlich geleistetes zusätzliches Eigenkapital, wenn operatives Geld den laufenden Kreditzins nicht deckt. Beiträge müssen in Liquiditätsbedarf, Gesamtmultiplikator und datierte IRR eingehen. Die Annahme ist keine allgemeine gesetzliche Nachschusspflicht.','alternatives-04','private-capital','support'),
 G('Direct Lending','Direkte privat verhandelte Kreditvergabe an einen Schuldner statt bloßer Kauf eines gewöhnlichen börslichen Standardinstruments. Kreditgeber müssen Betriebscash, Rang, Sicherheit, Covenants, Rückzahlung und Refinanzierung prüfen; die Direktbeziehung garantiert keinen Erfolg.','alternatives-05','private-capital','direct-lending'),
 G('Mezzanine-Finanzierung','Nachrangige Finanzierung zwischen bezeichneten höheren Kreditansprüchen und gewöhnlichem Eigenkapital. Kann PIK, Warrants oder andere Beteiligungsrechte besitzen. Höherer Kupon ist keine Kompensation mit sicherem Ergebnis und macht Mezzanine nicht automatisch vorrangig.','alternatives-05','private-capital','mezzanine','',[{label:'Mezzanine',units:['private-capital']}]),
 G('Unitranche','Gebündelte Finanzierung mit wirtschaftlich unterschiedlichen Finanzierungs- oder Risikoanteilen. Eine vom Schuldner betrachtete gemeinsame Struktur kann zusätzliche Verteilungsregeln unter Kreditgebern enthalten. Ein Mischzins macht die einzelnen Risiken nicht identisch.','alternatives-05','private-capital','mezzanine'),
 G('Venture Debt','Kreditfinanzierung eines jungen Wachstumsunternehmens. Schuldendienst kann von Kasse, künftiger Kapitalrunde oder späteren Cashflows abhängen; mögliche Warrants sind separate bedingte Rechte. Produktpotenzial beseitigt keine fällige Zins- oder Rückzahlungsverpflichtung.','alternatives-05','private-capital','venture-debt'),
 G('Venture-Warrant','Zusätzlich zu einer Venture-Finanzierung vereinbartes Recht auf einen bestimmten Aktienerwerb. Innerer Wert, Ausübungspreis, Anteildefinition und spätere Verwässerung sind getrennt zu prüfen. Das Recht ist keine garantiert ausgezahlte Zinszahlung.','alternatives-05','private-capital','venture-debt','',[{label:'Warrant',units:['private-capital']}]),
 G('PIK-Forderung','Durch kapitalisierte Zinsen vergrößerter Kreditanspruch. Bei 100 Beginn und zehn Prozent jährlicher PIK stehen nach zwei Jahren 121 aus. Der vertragliche Betrag kann trotz seines Wachstums wirtschaftlich schlechter einbringlich werden.','alternatives-05','private-capital','pik','',[{label:'PIK',units:['private-capital']},{label:'Payment-in-Kind',units:['private-capital']}]),
 G('Distressed Debt','Kreditanspruch im Zusammenhang mit erheblichen wirtschaftlichen, finanziellen oder vertraglichen Problemen des Schuldners. Für einen Käufer zählen Preis, tatsächliche Netto-Recovery, Rang, Kosten und Zeit; ein Abschlag zum Nennwert ist kein sicherer Gewinn.','alternatives-05','private-capital','distressed'),
 G('Vintage Year','Jahrgangseinordnung eines privaten Fonds nach einer ausdrücklich angegebenen Start- oder Investitionskonvention. Sie hilft, Einstiegsumfeld und Alter zu vergleichen. Über mehrere Vintages zu verteilen beseitigt keine gemeinsamen Branchen-, Markt- oder Liquiditätsrisiken.','alternatives-04','private-capital','vintage','Vintage'),
 G('Denominator Effect','Anstieg einer relativen Portfolioquote durch einen fallenden Gesamtnenner, etwa wenn liquide Marktwerte sinken und private NAVs zunächst unverändert gemeldet werden. Die höhere private Quote erfordert dann keinen privaten Wertgewinn.','alternatives-04','private-capital','liquidity'),
 G('Exitmultiple','Zur Bewertung eines späteren Verkaufs verwendetes Verhältnis, etwa EV zu Jahres-EBITDA. Eine höhere Annahme kann den Eigenkapitalrückfluss erhöhen, ohne bessere operative Entwicklung. Kaufmultiple, Ergebnisbasis und Kapitalstruktur sind konsistent abzugrenzen.','alternatives-04','private-capital','multiple-risk','Exit Multiple'),
 G('Secondary Buyout','Verkauf einer Beteiligung beziehungsweise eines Unternehmens von einem Finanzinvestor an einen anderen. Der Eigentümerwechsel kann Liquidität für den Verkäufer schaffen, ist aber allein kein zusätzlicher operativer Gewinn im Unternehmen.','alternatives-04','private-capital','exits'),
 G('Rekapitalisierungsdividende','Ausschüttung im Zusammenhang mit geänderter Kapitalstruktur, etwa finanziert durch neue Schuld. Unter sonst unverändertem Unternehmenswert vermindert die höhere Schuld den verbleibenden Eigenkapitalwert. Frühes Cash ist daher nicht automatisch zusätzlicher Gesamtwert.','alternatives-04','private-capital','exits','Recapitalization Dividend'),
 G('Distributed to Paid-In','DPI: tatsächlich erhaltene kumulierte Ausschüttungen geteilt durch die unter einer angegebenen Methode geleisteten Beiträge. Zeigt realisierten Rückfluss je eingezahlter Einheit, nicht jährliche Rendite. Gebührenkapital und wiederabrufbare Zahlungen müssen konsistent behandelt werden.','alternatives-02','alternative-fees','multiples','DPI'),
 G('Residual Value to Paid-In','RVPI: verbliebener Nettoanteilwert am Stichtag geteilt durch die konsistent definierten geleisteten Beiträge. Dieser Teil ist noch bewertet und nicht bereits ausgeschüttet. Eine Restwertkorrektur verändert RVPI und TVPI, aber keine früher erhaltene Ausschüttung.','alternatives-02','alternative-fees','multiples','RVPI'),
 G('Total Value to Paid-In','TVPI: Ausschüttungen plus verbleibender Nettoanteilwert, geteilt durch die bezeichneten geleisteten Beiträge. Entspricht bei gleicher Basis DPI plus RVPI. Enthält keine Zahlungszeitpunkte und darf bei mehreren Cashflows nicht allein aus dem Fondsalter annualisiert werden.','alternatives-02','alternative-fees','multiples','TVPI'),
 G('Multiple on Invested Capital','MOIC: Verhältnis aus Rückflüssen und Restwert zur definierten investierten Kapitalbasis. Asset-Gross-MOIC und LP-Net-TVPI können andere Kosten und Nenner enthalten. Ein Multiple beschreibt Wert relativ zu Kapital, nicht automatisch eine jährliche Verzinsung.','alternatives-02','alternative-fees','multiples','MOIC'),
 G('LP-IRR','Interner Zinsfuß der tatsächlich datierten Anlegerzahlungen einschließlich eines einmalig angesetzten Schlusswerts. Beiträge sind aus LP-Sicht negativ, Ausschüttungen positiv. Die Rate berücksichtigt Größe und Zeit, beweist aber weder Risikobereinigung noch tatsächlich verfügbare Wiederanlage zum selben Satz.','alternatives-02','alternative-fees','irr','LP IRR',[{label:'IRR',units:['alternative-fees']},{label:'Money-Weighted Return',units:['alternative-fees']},{label:'MWR',units:['alternative-fees']}]),
 G('Fonds-J-Kurve','Möglicher Verlauf anfänglich belasteter und später steigender kumulierter Fondsperformance, etwa durch frühe Kosten und spätere Veräußerungen. Weder die Form noch eine spätere Erholung ist garantiert. Vom gleichnamigen Außenhandelseffekt zu unterscheiden.','alternatives-02','alternative-fees','life-cycle','Fund J-Curve',[{label:'J-Kurve',units:['alternative-fees']}]),
 G('Anfangs-NAV','Nettoinventarwert des bezeichneten Anteils am Beginn einer Messperiode. Als Managementbasis liefert er einen anderen Betrag als ein Brutto-End-NAV. Externe Geldbewegungen und bereits einbezogene Kosten müssen gesondert abgegrenzt werden.','alternatives-02','alternative-fees','management','Beginning NAV'),
 G('Brutto-End-NAV','Wert am Periodenende vor den ausdrücklich bezeichneten noch abzuziehenden Vertragsgebühren. Brutto ist nur mit bekanntem Kostenumfang eindeutig. Eine Gebühr auf diesen Wert ist nicht dieselbe Regel wie eine Gebühr auf den erst nach Gebühren ermittelten Netto-Endwert.','alternatives-02','alternative-fees','end-base','Gross End NAV'),
 G('Management-Komponente','Nach Satz, Basis und Zeitanteil berechneter Managementbetrag. Beim Summenvertrag wird er neben Erfolg bezahlt; beim ausdrücklich definierten Entweder/oder-Vertrag ist er eine Alternative, von der nur die größere Komponente tatsächlich als Gesamtgebühr bezahlt wird.','alternatives-02','alternative-fees','management','Management Component'),
 G('Gebührenreihenfolge','Vertragliche Abfolge, in der Beträge oder Bemessungsgrundlagen berechnet werden. Erfolg nach Management belastet einen kleineren Gewinn als Erfolg vor Management, wenn der Managementbetrag positiv ist. Die Reihenfolge ist von der späteren Summe-/Maximum-Zahlungsregel zu unterscheiden.','alternatives-02','alternative-fees','ordering','Fee Ordering'),
 G('Entweder/oder-Gebühr','Hier ausdrücklich definierter Vertrag, der die größere von Management- und Erfolgs-Komponente bezahlt. Beide Komponenten brauchen eigene genaue Berechnungsregeln. Sie werden nicht zusätzlich addiert; Erfolg vor und nach hypothetischem Management wären unterschiedliche Verträge.','alternatives-02','alternative-fees','either-or','Either-or Fee'),
 G('Harte Hürde','Erfolgsklausel, bei der im bezeichneten Vertrag nur der Gewinn oberhalb einer bestimmten Rendite- oder Zahlungsstufe belastet wird. Ein zusätzlicher Höchststand kann die maßgebliche Basis weiter anheben. Nicht gleich garantiertem Nettomindestzins.','alternatives-02','alternative-fees','hurdles','Hard Hurdle'),
 G('Weiche Hürde','Erfolgszugangsschwelle, nach deren Überschreiten die Klausel auch Gewinn unterhalb der Schwelle belasten kann. Exakte Gleichheit, Basis, Höchststand und mögliche Catch-up-Stufen sind festzulegen. Die eigene strikte Jahresklausel kann einen Sprung des Nettoergebnisses erzeugen.','alternatives-02','alternative-fees','soft-cliff','Soft Hurdle'),
 G('Anteilshöchststand','Für die Erfolgsvergütung maßgeblicher früherer Wert desselben Anteils. Im eigenen HWM-Vertrag gilt der höchste nach Gebühren erreichte NAV bei unverändertem Anteilbestand. Reine Verlustaufholung erzeugt dort keinen neuen vergütbaren Erfolg. Neue Beiträge erfordern zusätzliche Anpassungsregeln.','alternatives-02','alternative-fees','high-water','',[{label:'High-Water Mark',units:['alternative-fees']},{label:'HWM',units:['alternative-fees']}]),
 G('Catch-up','Verteilungsstufe nach einer LP-Vorzugsstufe, in der der GP vorübergehend überproportional am verfügbaren Gewinn teilnimmt, bis ein Zielanteil erreicht ist. Bei vollständigem Catch-up mit 20 % Zielcarry und acht LP-Vorzug sind zwei GP-WE erforderlich, aber nur soweit genügend Geld vorhanden ist.','alternatives-02','alternative-fees','catch-up','Full Catch-up'),
 G('Preferred Return','Vertragliche Vorzugsrendite oder bevorzugte Gewinnstufe vor bestimmten nachrangigen Verteilungen. Kapitalbasis, Zeit, Aufzinsung und Catch-up sind konkret zu bestimmen. Der Vorzug ordnet verfügbares Geld; ohne zusätzliche Garantie erzeugt er bei Verlusten keinen fehlenden Cashflow.','alternatives-02','alternative-fees','catch-up','',[{label:'Vorzugsrendite',units:['alternative-fees']}]),
 G('Whole-fund-Waterfall','Vertragliche Ausschüttungsfolge, die den Erfolg bestimmter Anlagen auf der bezeichneten Gesamtfondsebene zusammenführt, bevor Carry bezahlt wird. Welche Beiträge, Kosten und Vorzugsbeträge zuvor zurückzuführen sind, ist ausdrücklich zu regeln. Nicht mit jeder einzelnen Deal-Verteilung gleichzusetzen.','alternatives-02','alternative-fees','whole-fund','Whole-fund'),
 G('Deal-by-deal-Carry','Erfolgszuteilung auf der Ebene einzelner Transaktionen. Frühe Gewinner können Carry auslösen, bevor spätere Verlierer feststehen. Ein finaler Clawback kann Beträge korrigieren, stellt aber den ursprünglichen Zahlungszeitpunkt nicht automatisch wieder her.','alternatives-02','alternative-fees','whole-fund','deal-by-deal'),
 G('Carry-Rückforderung','Anspruch auf Rückzahlung nach der konkret vereinbarten finalen oder zwischenzeitlichen Carry-Abrechnung. Fälliger Betrag, gebuchter Anspruch und eingezogenes Cash sind zu unterscheiden. Durchsetzbarkeit, Fristen, Sicherheiten und Zahlungsfähigkeit beeinflussen den realen LP-Rückfluss.','alternatives-02','alternative-fees','clawback','',[{label:'Clawback',units:['alternative-fees']}]),
 G('Founder Share Class','Anteilsklasse mit besonderen Konditionen für bestimmte frühe Kapitalgeber, etwa niedrigeren Gebühren. Zusätzliche Bindungen und Rechte können sich ebenfalls unterscheiden. Höhere Nettorendite derselben Bruttoanlage belegt dann nicht bessere Asset-Auswahl.','alternatives-02','alternative-fees','classes','Gründerklasse|Founder Class'),
 G('Fee Offset','Vertragliche Anrechnung definierter Vergütungen auf eine andere Gebühr. Beispiel: 75 % von acht anrechenbaren WE senken einen Managementanspruch von 20 auf 14. Derselbe Offset darf in der Gesamtkostenrechnung nicht doppelt als Entlastung erfasst werden.','alternatives-02','alternative-fees','other-costs','Gebührenanrechnung'),
 G('Public Market Equivalent','Cashflowbezogener Vergleich eines privaten Fonds mit einem gewählten öffentlichen Marktindex. Die KS-PME skaliert Beiträge und Ausschüttungen auf dasselbe Schlussdatum und bildet ein relatives Wertverhältnis. Es ist keine annualisierte Rate und ohne weitere Risikomodellierung kein Alpha.','alternatives-02','alternative-fees','pme','PME|KS-PME|Kaplan-Schoar-PME'),
 G('Survivorship Bias','Verzerrung durch eine Auswahl, in der ausgeschiedene beziehungsweise gescheiterte Fonds fehlen. Die übrig gebliebenen Historien können den damals verfügbaren Durchschnitt zu günstig darstellen. Vollständige Stichprobe und zeitgerechte Aufnahme sind zu prüfen.','alternatives-03','alternative-fees','bias-tail','Überlebendenverzerrung'),
 G('Backfill Bias','Mögliche Verzerrung, wenn ein später gemeldeter Fonds nachträglich ausgewählte frühere Ergebnisse in eine Datenbank einbringt. Gute Startphasen können rückwirkend die Historie verbessern. Vom bloßen Fehlen später geschlossener Fonds zu unterscheiden.','alternatives-03','alternative-fees','bias-tail'),
 G('Bewertungsglättung','Verzögerte oder gedämpfte Übernahme wirtschaftlicher Wertänderungen in gemeldete Bewertungen und Renditen. Kann ausgewiesene Volatilität und gleichzeitige Korrelation verkleinern, ohne den wirtschaftlichen Verlust oder Liquiditätsbedarf zu beseitigen.','alternatives-03','alternative-fees','smoothing','Return Smoothing'),
 G('Stale Pricing','Bewertung mit Preisen oder Schätzungen, die neue wirtschaftliche Information noch nicht vollständig widerspiegeln. Niedrige gemessene Schwankungen oder verzögerte Korrelationen können dadurch Messartefakte sein. Ein alter Preis ist kein garantierter heutiger Verkaufserlös.','alternatives-03','alternative-fees','smoothing'),
 G('Commitment','Vertragliche Kapitalzusage eines Anlegers. Sie ist weder automatisch vollständig eingezahlt noch gleich dem aktuellen Beteiligungswert. Abrufrechte, Fristen, Kosten außerhalb der Zusage und mögliche Wiederherstellungen müssen aus der konkreten Vereinbarung bestimmt werden.','alternatives-01','alternative-structures','commitment','Kapitalzusage|Commitments'),
 G('Capital Call','Anforderung eines nach Vertrag fälligen Kapitalbeitrags. Abrufkapazität, tatsächliche Anforderung und erfolgte Zahlung sind verschiedene Größen. Der Anleger braucht verfügbare Mittel zum genannten Termin; ein hoher NAV ersetzt diese Liquidität nicht automatisch.','alternatives-01','alternative-structures','cash-call','Kapitalabruf|Kapitalabrufe'),
 G('Unfunded Commitment','Nach der konkreten Kapitalrechnung noch abrufbare Zusage. Im einfachen Fall ursprüngliche Zusage minus angerechnete Beiträge; Wiederabrufrechte und weitere Vertragsanpassungen können den Betrag verändern. Frühere Ausschüttungen dürfen nicht pauschal gegengerechnet werden.','alternatives-01','alternative-structures','recall','Uncalled Commitment|Restzusage'),
 G('Recallable Distribution','Tatsächlich ausgezahlter Betrag, der nach den vereinbarten Bedingungen nochmals angefordert werden darf. Ein heutiger Zufluss kann deshalb mit einer späteren Beitragspflicht zusammenfallen. Maßgeblich sind Zweck, Frist, Obergrenzen und die noch unverbrauchte Wiederabrufkapazität.','alternatives-01','alternative-structures','recall','rückrufbare Ausschüttung|rückrufbare Ausschüttungen'),
 G('Kapital-Recycling','Erneute Verwendung von Rückflüssen nach den vertraglichen Fondsregeln. Dies kann eine Wiederanlage innerhalb des Fonds oder eine Ausschüttung mit späterem Wiederabruf betreffen; die Zahlungswege und Obergrenzen sind nicht automatisch identisch.','alternatives-01','alternative-structures','recall','Recycling',[{label:'Recycling',units:['alternative-structures']}]),
 G('Net Asset Value','Bewertetes Nettovermögen eines Fonds beziehungsweise daraus abgeleiteter Anteilswert nach passender Zuordnung der Anlagen, Verbindlichkeiten und Kosten. Ein NAV ist kein garantierter sofortiger Verkaufserlös und kein zusätzliches Anlegercash. Bewertungsstichtag und Methodik sind wesentlich.','alternatives-01','alternative-structures','nav','NAV|Nettoinventarwert'),
 G('Management Fee','Verwaltungsvergütung mit ausdrücklich zu bestimmendem Satz, Zeitraum und Bemessungsbasis. Basis kann etwa Kapitalzusage, definierter investierter Betrag oder NAV sein. Derselbe Satz kann deshalb unterschiedliche Geldbeträge und relative Belastungen erzeugen; weitere Kosten und Erfolgsvergütung kommen gegebenenfalls hinzu.','alternatives-01','alternative-structures','fee-base','Managementgebühr|Verwaltungsgebühr'),
 G('Carried Interest','Vertraglicher Anteil des Managers an einer definierten Erfolgsbasis eines Fonds. Kapitalrückzahlung, Gebühren, Hürden und Verteilungsreihenfolge bestimmen den Betrag. Kein garantierter Anlegerkupon und nicht gleich Finanzierungskosten beziehungsweise Cost of Carry eines Derivats.','alternatives-01','alternative-structures','performance-fee','',[{label:'Carry',units:['alternative-structures']}]),
 G('Co-Investment','Teilnahme an einer konkreten Transaktion neben einem führenden Investor oder Fonds. Bietet eigene Auswahl und möglicherweise andere Gebührenbedingungen, verlangt aber eigene Prüfung von Anlage, Kosten, Rechten und Konflikten. Eine bereits im Fonds enthaltene Position kann dadurch stärker konzentriert werden.','alternatives-01','alternative-structures','co-investment','Co-Investments'),
 G('Look-through-Analyse','Analyse der tatsächlichen Anlagen, Risiken, Finanzierung und Kosten hinter einem oder mehreren Vehikeln. Sie kann gemeinsame Schuldner oder Unternehmenspositionen sichtbar machen. Wirtschaftliche Zuordnung bedeutet nicht automatisch dieselben direkten Rechts- oder Kontrollbefugnisse.','alternatives-01','alternative-structures','risk-drivers','Look-through'),
 G('Blind Pool','Fonds, bei dem zum Zeitpunkt einer Anlegerzusage noch nicht alle späteren Einzelanlagen feststehen. Managerprozess, Mandat, Team und Kontrollen der Folgeauswahl sind deshalb wichtige Prüfgegenstände. Eine bekannte Anfangsposition beschreibt nicht automatisch die künftige Gesamtanlage.','alternatives-01','alternative-structures','fund-selection'),
 G('Side Letter','Zusätzliche individuelle Vereinbarung zur Fondsbeteiligung, etwa über Information, Gebühren oder Co-Investment-Zugang. Ihre Wirkung, Zulässigkeit und Offenlegung sind konkret zu prüfen. Die Existenz solcher Rechte beweist weder universelle Gleichbehandlung noch eine garantierte besondere Anlagerendite.','alternatives-01','alternative-structures','documents','Side Letters'),
 G('Limited Partnership Agreement','Maßgeblicher Partnerschaftsvertrag einer entsprechenden Fondsstruktur. Regelt etwa Mandat, Laufzeit, Abrufe, Verteilung, Gebühren und Zustimmungsrechte. Industrieempfehlungen werden nicht allein durch Veröffentlichung automatisch Teil dieses Vertrags.','alternatives-01','alternative-structures','documents','LPA'),
 G('Fonds-General-Partner','Leitungs- und Organisationsrolle einer Fonds-Partnerschaft. Im klassischen LP-Grundmodell mit grundsätzlich nicht auf die Einlage begrenzter Partnerschaftshaftung. Die Rolle kann durch einen eigenen haftungsbeschränkten Rechtsträger ausgeübt werden; sie ist nicht automatisch dieselbe Managementgesellschaft oder eine persönlich haftende natürliche Person. Recht und Vertrag sind konkret zu prüfen.','alternatives-01','alternative-structures','parties','Fund General Partner',[{label:'General Partner',units:['alternative-structures']},{label:'GP',units:['alternative-structures']}]),
 G('Fonds-Limited-Partner','Anlegerrolle in der bezeichneten Fonds-Partnerschaft mit vertraglichen Beitrags-, Zahlungs- und sonstigen Rechten und Pflichten. Eine Beteiligung am Vehikel vermittelt nicht automatisch direkte Steuerung jedes Zielunternehmens. Limited bedeutet keine Kapitalgarantie oder beliebige Befreiung von wirksamen Abrufen.','alternatives-01','alternative-structures','ownership','Fund Limited Partner',[{label:'Limited Partner',units:['alternative-structures']},{label:'LP',units:['alternative-structures']},{label:'LPs',units:['alternative-structures']}]),
 G('Limited Partner Advisory Committee','Anlegerbeirat mit den im Vertrag festgelegten Beratungs- oder Zustimmungsaufgaben, etwa bei bestimmten Konflikten. Kein automatisch allzuständiges Kontrollorgan und keine Garantie fairer Preise. Auch Beiratsmitglieder können eigene Interessen besitzen.','alternatives-01','alternative-structures','governance','LPAC|LP Advisory Committee'),
 G('Fonds-Hurdle','Vertragliche Rendite- oder Zahlungsstufe zur Bestimmung einer Fonds-Erfolgsvergütung. Hard oder Soft Hurdle, Kapitalbasis, Aufzinsung und Catch-up beeinflussen den tatsächlichen Wasserfall. Keine sichere Mindestrendite bei Anlageverlusten und von einer Projektdiskontierungsrate zu unterscheiden.','alternatives-01','alternative-structures','hurdles','Fund Hurdle',[{label:'Hurdle',units:['alternative-structures']},{label:'Hurdle Rate',units:['alternative-structures']}]),
 G('High-Water Mark','Vertraglich definierter bereits vergüteter Höchststand, über den eine maßgebliche neue Erfolgsbasis steigen muss, bevor erneute Erfolgsvergütung anfällt. Kann doppelte Gebühren auf bloßes Aufholen verhindern. Ein-/Auszahlungen, Anteilsklassen und genaue Basis sind zusätzlich zu berücksichtigen.','alternatives-01','alternative-structures','hurdles','HWM'),
 G('Fonds-Clawback','Vertragliche Rückforderung überhöhter früherer Manager-Erfolgszuteilungen nach späterem Gesamtabgleich. Anspruch, Fristen, Sicherheiten und Einbringlichkeit bestimmen seine Wirkung. Er ist keine allgemeine Versicherung gegen jeden Anlegerverlust.','alternatives-01','alternative-structures','hurdles','Fund Clawback',[{label:'Clawback',units:['alternative-structures']}]),
 G('Gebührenbasis','Vertraglich definierte Bezugsgröße zur Berechnung einer Vergütung, etwa Zusage, bestimmtes investiertes Kapital oder NAV. Sie wird zusammen mit Satz, Zeitanteil und Reihenfolge geprüft. Ein unveränderter Satz garantiert bei anderer Basis keinen gleichen Geldbetrag.','alternatives-01','alternative-structures','fee-base','Fee Base'),
 G('Lock-up','Vertragliche Bindung, die bestimmte Rückgaben oder Übertragungen während eines bezeichneten Zeitraums begrenzt. Ausnahmen, Anfangspunkt und betroffene Anteilsklasse müssen geprüft werden. Keine allgemeine Garantie der Kapitalerhaltung.','alternatives-01','alternative-structures','open-ended','Lock-ups'),
 G('Gate','Vertragliche Betrags- oder Mengenbegrenzung von Rücknahmen in einem bestimmten Fenster. Kann Anlegerauszahlungen verzögern; Zuteilung, Vortrag und spätere Bedienung hängen von den konkreten Regeln ab. Nicht dasselbe wie eine vollständige Aussetzung oder ein Side Pocket.','alternatives-01','alternative-structures','open-ended','Gates'),
 G('Side Pocket','Gesonderte Zuordnung bestimmter schwer veräußerbarer Fondspositionen mit eigenen Beteiligungs- oder Rückflussregeln. Sie kann Liquiditätsrechte gegenüber dem übrigen Anteil verändern. Sie bedeutet weder automatisch Wertlosigkeit noch sofortige Verkaufbarkeit.','alternatives-01','alternative-structures','open-ended','Side Pockets'),
 G('Kapitalabrufdeckung','Vergleich tatsächlich verfügbarer Anlegerliquidität mit einer bestimmten fälligen Kapitalanforderung. Bei positivem Abruf kann Cash geteilt durch Anforderung als Quote dienen. Ein gedeckter einzelner Abruf beweist nicht die Deckung aller künftigen Verpflichtungen.','alternatives-01','alternative-structures','cash-timing','Capital Call Coverage'),
 G('Sekundärpreisabschlag','Abstand eines ausgehandelten Anteilsverkaufspreises unter einem bezeichneten gemeldeten NAV. Vergleichsstichtag, Gebühren, tatsächlicher Zahlungstermin und Übernahme von Restpflichten sind gesondert zu prüfen. Der Abschlag ist kein Beweis eines sicheren sofortigen Geldzugangs.','alternatives-01','alternative-structures','secondary','Secondary Discount'),
 G('Binomialmodell','Finanzmodell, in dem der Basiswert pro Schritt genau zwei mögliche Folgezustände besitzt. Im Einperiodenfall können Aktie und sichere Geldposition jeden zweizuständigen Zahlungsanspruch nachbilden, sofern die Handels- und Finanzierungsannahmen gelten. Die Kursäste sind Modellvorgaben, keine vollständige Beschreibung realer Kurse.','derivatives-07','binomial','market','Binomial Model'),
 G('Risikoneutrale Bewertung','Darstellung des Replikationspreises als sicher abgezinster Mittelwert unter passenden Preisgewichten. Diese Gewichte folgen aus heutigen Bausteinpreisen und den modellierten Zuständen. Sie sind keine tatsächlichen Prognosewahrscheinlichkeiten und setzen keine allgemeine Risikoneutralität der Anleger voraus.','derivatives-07','binomial','neutral-price','Risk-Neutral Valuation'),
 G('Replikationsdelta','Aktienzahl je nachzubauendem Anspruch im bezeichneten Zustandsmodell. Im Einperiodenbaum gleich Differenz der Anspruchszahlungen geteilt durch Differenz der Aktienendkurse. Es ist ein Mengenverhältnis und keine Wahrscheinlichkeit; Vorzeichen und Kontraktgröße bestimmen die nötige Aktienposition.','derivatives-07','binomial','delta','Replication Delta',[{label:'Delta',units:['binomial']},{label:'Hedgeverhältnis',units:['binomial']}]),
 G('Geldbaustein','Sichere Geldposition als Bestandteil einer Replikation. Ein positiver heutiger Betrag ist eine Anlage, ein negativer ein Kredit. Der spätere Betrag entsteht mit dem passenden Periodenfaktor; heutiger Krediterlös und spätere Rückzahlung dürfen nicht gleichgesetzt werden.','derivatives-07','binomial','bond','Cash Component',[{label:'Geldposition',units:['binomial']}]),
 G('Brutto-Kursfaktor','Multiplikator vom heutigen Aktienkurs zum bezeichneten Folgekurs. Ein Faktor 1,20 entspricht zwanzig Prozent Nettokursgewinn, ein Faktor 0,80 zwanzig Prozent Verlust. Die Faktoren müssen derselben Modellperiode wie die Finanzierung zugeordnet sein.','derivatives-07','binomial','market','Gross Stock Return Factor'),
 G('Sicherer Periodenfaktor','Positiver Multiplikator einer sicheren Geldposition über die gesamte betrachtete Periode. Gleich eins plus effektiver Periodenrendite. Bei negativer Nettorendite liegt er unter eins, bleibt aber positiv. Eine annualisierte Zinsangabe muss erst passend auf die Periode umgerechnet werden.','derivatives-07','binomial','periods','Risk-Free Gross Period Factor',[{label:'Periodenfaktor',units:['binomial']}]),
 G('Zustandspreis','Heutiger Preis einer Zahlung von einer Geldeinheit ausschließlich in einem bestimmten späteren Zustand. Im Binomialmodell gleich risikoneutralem Zustandsgewicht geteilt durch sicheren Periodenfaktor. Die Summe aller solchen Preise ist der Barwert einer sicheren Endeinheit, nicht allgemein eins.','derivatives-07','binomial','state-prices','State Price|Zustandspreise'),
 G('Vollständiger Modellmarkt','Zustandsmodell, dessen zugelassene handelbare Instrumente jeden betrachteten Zahlungsanspruch exakt nachbilden können. Im nicht entarteten Zweizustandsmodell genügen Aktie und sichere Anlage. Vollständigkeit hängt von Zustandsraum und Instrumenten ab und bedeutet keine allgemeine Absicherbarkeit aller realen Risiken.','derivatives-07','binomial','replication','Complete Model Market'),
 G('Unvollständiger Modellmarkt','Zustandsmodell, in dem nicht jeder Zahlungsanspruch mit den verfügbaren Instrumenten erreichbar ist. Beispielsweise können drei unabhängige Endzahlungen mehr Bedingungen stellen, als Aktie und Geldposition erfüllen können. Ohne weitere Instrumente oder Annahmen folgt dann nicht für jeden Anspruch ein eindeutiger Preis.','derivatives-07','binomial','incomplete','Incomplete Model Market'),
 G('Tatsächliches Zustandsgewicht','Tatsächliche oder subjektiv geschätzte Wahrscheinlichkeit eines wirtschaftlichen Zustands. Sie wird für Prognosen und erwartete Renditen verwendet. Bei festgehaltenen Marktpreisen ersetzt sie nicht das risikoneutrale Preisgewicht der Replikationsbewertung.','derivatives-07','binomial','physical','Physical State Probability'),
 G('Risikoneutrale Bewertungsverteilung','Hilfsverteilung über Modellzustände, unter der abgezinste handelbare Preise zu denselben heutigen Bausteinpreisen passen. Im vollständigen Zweizustandsmarkt ist sie unter den Voraussetzungen eindeutig. Sie ist von der tatsächlichen Verteilung und von Anlegerpräferenzen zu unterscheiden.','derivatives-07','binomial','neutral-derive','Risk-Neutral Pricing Distribution',[{label:'Bewertungsverteilung',units:['binomial']}]),
 G('Risikoloses Hedgepaket','Zusammengesetzte Position mit derselben Endzahlung in jedem zugelassenen Zustand. Im Callbaum kann eine passende Aktienzahl minus Call die Unsicherheit aufheben. Der einzelne Call bleibt riskant; die Sicherheit des Pakets hängt von der vollständigen Deckung und den Modellannahmen ab.','derivatives-07','binomial','hedged','Riskless Hedged Portfolio'),
 G('Einperiodenreplikation','Nachbildung eines Anspruchs über einen einzigen Modellschritt durch feste Aktien- und Geldpositionen. Beide alternativen Endzahlungen werden einzeln abgeglichen. Daraus folgen Hedgequote, Finanzierung und heutiger Preis ohne tatsächliche Eintrittswahrscheinlichkeiten.','derivatives-07','binomial','replication','One-Period Replication',[{label:'Replikation',units:['binomial']}]),
 G('Digitale Zustandszahlung','Bedingter Anspruch mit einer fest definierten Geldzahlung nur im bezeichneten Zustand und null in anderen Zuständen. Eine einzelne Endeinheit hat als heutigen Preis den passenden Zustandspreis. Ihre exakte Nachbildung hängt vom zugelassenen Zustandsraum ab.','derivatives-07','binomial','digital','Digital State Claim'),
 G('Zweipunktdeckung','Exakte Übereinstimmung eines Nachbaus mit dem Anspruch an den zwei bezeichneten Endkursen. Eine affine Aktien-Geld-Gerade kann dort eine geknickte Optionsfunktion treffen, ohne dazwischen oder außerhalb übereinzustimmen. Zusätzliche mögliche Zustände verändern deshalb das Hedgeproblem.','derivatives-07','binomial','incomplete','Two-State Payoff Matching'),
 G('Randarbitrage','Arbitrage am Rand einer Modellbedingung: Ein Geschäft kostet anfangs null, verliert in keinem Zustand und gewinnt in mindestens einem tatsächlich möglichen Zustand. Im vollen Zweizustandsmodell tritt dies etwa auf, wenn der sichere Faktor genau dem oberen Aktienfaktor entspricht.','derivatives-07','binomial','boundary','Boundary Arbitrage'),
 G('Rückwärtsinduktion','Lösen eines mehrstufigen Entscheidungs- oder Bewertungsbaums vom Ende zurück zum Anfang. Bei Optionen werden zunächst Endzahlungen bestimmt und danach an jedem vorherigen Knoten passende Folgewertmittel abgezinst; erlaubte frühere Ausübung muss dort zusätzlich verglichen werden.','derivatives-07','binomial','multi-period','Backward Induction'),
 G('Selbstfinanzierender Hedge','Absicherungsstrategie, deren Umschichtungen aus dem bereits vorhandenen Portfoliowert finanziert werden. Sie benötigt keine unerklärten neuen Mittelzuflüsse. Das bedeutet weder null Anfangskapital noch automatisch geringe Zwischenliquidität oder vollständige reale Absicherung.','derivatives-07','binomial','multi-period','Self-Financing Hedge'),
 G('Dynamischer Baumhedge','Nachbau, dessen Aktien- und Geldpositionen nach jeder realisierten Baumbewegung neu an die nächsten möglichen Anspruchswerte angepasst werden. Ein einziges anfängliches Delta reicht im Mehrperiodenmodell meist nicht. Modellfehler, Sprünge und Handelskosten können in der Praxis Restverluste erzeugen.','derivatives-07','binomial','multi-period','Dynamic Tree Hedge'),
 G('Options-Fortführungswert','Wert des Weiterhaltens einer Option am bezeichneten Entscheidungsknoten. Im Baum folgt er aus den passend gewichteten und abgezinsten Folgewerten. Bei amerikanischen Rechten wird er mit dem sofortigen Ausübungswert verglichen; der höhere Wert bestimmt die optimale Knotenentscheidung.','derivatives-07','binomial','american','Option Continuation Value',[{label:'Fortführungswert',units:['binomial']}]),
 G('Put-Call-Parität','Preisbeziehung zwischen passenden europäischen Call- und Putrechten, dem reinen Aktienerhalt am Endtermin und der sicheren Strikezahlung. Sie folgt aus gleichen Leistungen in jedem Endzustand. Ohne Ausschüttung gilt Call plus Strikebarwert gleich Put plus Aktie. Allein bestimmt sie keine zwei einzelnen Optionspreise.','derivatives-06','parity','spot','Put-Call Parity',[{label:'Parität',units:['parity']}]),
 G('Put-Call-Forward-Parität','Ausdruck derselben europäischen Preisbeziehung über die aktuelle faire Forwardquote. Call minus Put entspricht dem diskontierten Abstand der fairen Lieferquote vom gemeinsamen Strike. Die Quote ist ein späterer Lieferbetrag, der Optionspreisabstand dagegen ein heutiger Geldwert.','derivatives-06','parity','forward','Put-Call Forward Parity'),
 G('Paritäts-Endpaket','Zusammenstellung von Rechten und Geldleistungen, deren gesamte Endzahlung mit einem anderen Paket in jedem passenden Zustand übereinstimmt. Klassischer Vergleich: Call plus sichere Strikezahlung gegen Put plus Endaktie. Gleicher Erwartungswert allein genügt nicht.','derivatives-06','parity','terminal','Parity Payoff Package'),
 G('Synthetischer Aktienerhalt','Nachbildung einer Endaktie durch passenden Callkauf, Putverkauf und sichere Strikebereitstellung. Die Optionsdifferenz allein lässt die Strikefinanzierung offen und ist ein Forwardanspruch. Bei laufendem Aktienertrag muss auch dieser vom reinen Endaktienanspruch getrennt werden.','derivatives-06','parity','synthetic-share','Synthetic Stock',[{label:'synthetische Aktie',units:['parity']}]),
 G('Synthetischer Forward','Passende Kombination aus Long Call und Short Put mit gleichem Strike und Endtermin. Liefert am Ende Aktienkurs minus Strike, einschließlich negativer Leistungen bei niedrigem Kurs. Ihr heutiger Preis ist nicht automatisch null, denn der Strike muss nicht der aktuellen fairen Forwardquote entsprechen.','derivatives-06','parity','synthetic-forward','Synthetic Forward'),
 G('Strikebarwert','Heutiger Preis der sicheren späteren Zahlung des Ausübungspreises. Er entspricht Strike mal passendem Enddiskontfaktor und ist nicht der unverschobene Strike. Bei negativem Zins kann er über dem späteren Nennbetrag liegen.','derivatives-06','parity','claims','Present Value of Strike'),
 G('Options-Conversion','Long Aktie plus Long Put und Short Call mit passenden europäischen Endrechten. Erzeugt ohne Zwischenaktienertrag eine feste Strikezahlung; mit Ausschüttungen müssen deren Cashs zusätzlich abgegrenzt werden. Für eine Arbitragebeurteilung gehören die passende Finanzierung und sämtliche Kosten zum Paket.','derivatives-06','parity','conversion','',[{label:'Conversion',units:['parity']}]),
 G('Options-Reversal','Gegenrichtung zur Conversion: Short Aktie, Short Put und Long Call. Mit sicherer Strikebereitstellung kann die spätere Aktienrücklieferpflicht ausgeglichen werden. Bei Aktienleihe sind Dividendenersatz, Leihkosten und Verfügbarkeit der Erlöse zusätzlich zu berücksichtigen.','derivatives-06','parity','reversal','Reverse Conversion',[{label:'Reversal',units:['parity']}]),
 G('Fiduciary Call','Long Call plus genügend sichere Geldanlage für die Strikezahlung am gemeinsamen Endtermin. Ohne laufenden Aktienertrag entspricht sein Endpaket einer Aktie mit passendem Protective Put. Die Enduntergrenze beweist keinen kostenlosen Schutz und keinen garantierten Gewinn nach Anschaffungskosten.','derivatives-06','parity','protection','Treuhänderisch finanzierter Call'),
 G('Cashgesicherter Put','Verkaufter Put zusammen mit tatsächlich ausreichender sicherer Strikebereitstellung. Seine Endleistung entspricht unter passenden Bedingungen einem Covered Call. Ein bloßer kleiner Marginbetrag ist keine vollständige Cashsicherung; die Aktienunterseite bleibt wirtschaftlich relevant.','derivatives-06','parity','covered','Cash-Secured Put'),
 G('Reiner Endaktienerhalt','Anspruch auf die Aktie am bezeichneten Endtermin ohne zusätzlich behaltene Zwischenzahlungen. Bei bekannten replizierbaren Gelddividenden beträgt sein heutiger vorab bezahlter Wert Spot minus Dividendenbarwert. Bei stetiger Ertragsrendite gilt eine andere ausdrücklich modellierte Ertragskonvention.','derivatives-06','parity','income','',[{label:'Endaktienerhalt',units:['parity']}]),
 G('Dividendenersatzzahlung','Leistung, mit der ein Aktienleerverkäufer den Verleiher für die ausgeschüttete Dividende entschädigt. Sie gehört bei passender Aktienleihe zum vollständigen Zahlungsweg. Das Weglassen kann einen scheinbaren Gewinn einer synthetischen Position erzeugen, der wirtschaftlich nicht besteht.','derivatives-06','parity','dividend-ledger','Dividend Compensation'),
 G('Paritäts-Quoteband','Bereich von ausführbaren Call-, Put- und Aktienquoten, in dem nach den richtigen Geld-Brief-Seiten keine der beiden betrachteten Paritätsrichtungen positiven Anfangszufluss liefert. Weitere Kosten und unterschiedliche Finanzierung können diesen Bereich verändern. Ein Mittelpreisabstand allein ist keine solche Handelsrechnung.','derivatives-06','parity','bid-ask','Parity Bid-Ask Band'),
 G('Paritätsrest','Differenz der heutigen Preise zweier eigentlich endleistungsgleicher Pakete. Im idealen europäischen Vergleich verschwindet sie bei konsistenten Preisen. Ein Rest ist vor tatsächlicher Umsetzung nach Quoteseiten, Finanzierung, Ertrag und Kosten zu prüfen; Rest null ersetzt keine Einzelpreisgrenzen.','derivatives-06','parity','difference','Parity Residual|Paketdifferenz'),
 G('Einheitliche Finanzierung','Idealisierte Annahme, dass die betreffenden sicheren Anlagen und Kreditaufnahmen mit denselben passenden Faktoren umgesetzt werden können. Unterschiedliche Kredit-, Anlage- und Shorterlösbedingungen verändern die gerichteten Arbitragecashs. Die Zeit- und Geldrichtung jeder Position muss erhalten bleiben.','derivatives-06','parity','funding-costs','Common Funding Assumption'),
 G('Europäischer Box-Spread','Kombination zweier ansonsten passender europäischer Call-Put-Paare verschiedener Strikes. Die Aktienendteile kürzen sich, sodass der feste Strikeabstand übrig bleibt. Der heutige Preis entspricht im idealen Fall dessen Zahlungsbarwert; frühe Ausübung und Erfüllungsfriktionen sind zusätzliche Bedingungen.','derivatives-06','parity','box','European Box Spread|Box-Spread'),
 G('Optionsimplizite Forwardquote','Aus Strike, europäischem Call-Put-Preisabstand und passendem Diskontfaktor abgeleitete Lieferquote. Sie bringt den heutigen Optionspreisabstand zunächst auf den Endtermin. Sie ist weder ein heutiger Vertragsmarktwert noch eine garantierte tatsächliche Spotprognose.','derivatives-06','parity','forward-case','Option-Implied Forward'),
 G('Paritäts-Rechtezahl','Tatsächlich abgestimmte Anzahl von Aktienrechten auf sämtlichen entsprechenden Seiten eines Replikationspakets. Gleiche Kontraktzahlen können bei verschiedenen Multiplikatoren unterschiedliche Rechtezahlen bedeuten. Eine Abweichung lässt zusätzliche bedingte Pflichten offen.','derivatives-06','parity','quantity','',[{label:'Kontraktmultiplikator',units:['parity']}]),
 G('Paritäts-Anfangszufluss','Nettozufluss aller gleichzeitig angesetzten Replikationspositionen heute. Bei exakt ausgeglichenen späteren Cashs und umsetzbaren Annahmen kann er den theoretischen Preisvorteil ausdrücken. Seine spätere Anlage wird nicht noch einmal als zweiter unabhängiger Anfangsgewinn addiert.','derivatives-06','parity','conversion','Parity Initial Cash Surplus'),
 G('Synthetische Strikezahlung','Feste Endleistung aus passender Aktie beziehungsweise reinem Endaktienanspruch plus Put minus Call. Ihr heutiger Preis ist der Strikebarwert. Zwischenaktienerträge, Sicherheiten und Finanzierung werden nicht allein durch die konstante Endzahl beseitigt.','derivatives-06','parity','synthetic-bond','Synthetic Strike Bond'),
 G('Optionszeitwert','Heutiger Preis eines Optionsrechts minus dessen heutigen Spot-Ausübungswert. Er enthält neben verbleibender Wahl auch Finanzierung und Ertragswirkungen. Bei sofort ausübbaren amerikanischen Rechten ist er unter reibungsfreien Annahmen nicht negativ; bei europäischen Rechten kann er negativ sein. Kein gleichmäßiger täglicher Kontoabzug.','derivatives-06','option-values','time-value','Time Value of an Option|Extrinsischer Optionswert',[{label:'Zeitwert',units:['option-values']}]),
 G('Spot-Ausübungswert','Positive aktuelle Spot-Strike-Differenz beim Call beziehungsweise Strike-Spot-Differenz beim Put, sonst null. Er beschreibt die hypothetische Sofortleistung je Recht. Europäische Rechte können vor Ablauf dennoch nicht sofort ausgeübt werden. Frühere Prämie und Gewinn gehören nicht zu dieser Größe.','derivatives-06','option-values','exercise','Spot Intrinsic Value',[{label:'Ausübungswert',units:['option-values']}]),
 G('Spot-Moneyness','Lage des heutigen Aktienkurses zum Strike. Call ist bei Spot über Strike im Geld, Put bei Spot unter Strike; Gleichheit bedeutet am Geld. Prämie, Positionsrichtung und früherer Kaufpreis verändern diese Vertragslage nicht.','derivatives-06','option-values','moneyness','',[{label:'Moneyness',units:['option-values']}]),
 G('Forward-Moneyness','Verhältnis der heutigen Forwardquote zum Strike eines passenden Endrechts. Unterscheidet sich bei nicht neutralem Carry von Spot-Moneyness. Eine Aussage am Geld muss deshalb ihre Bezugsgröße nennen.','derivatives-06','option-values','moneyness','Forward Moneyness'),
 G('Europäische Optionsuntergrenze','Aus passenden handelbaren Zahlungswegen abgeleiteter Mindestpreis eines europäischen Rechts. Im stetigen Ertragsmodell ist die Callgrenze der positive Teil aus Prepaid-Aktienerhalt minus Strikebarwert; die Putgrenze verwendet die umgekehrte Differenz. Keine vollständige Bestimmung eines einzelnen Modellpreises.','derivatives-06','option-values','call-bounds','European Option Lower Bound'),
 G('Europäische Putobergrenze','Heutiger Preis der höchsten möglichen späteren Putzahlung. Bei nicht negativem Aktienkurs und festem Strike entspricht sie dem passenden Strikebarwert. Bei negativem Zins kann diese heutige Grenze über dem Strike liegen.','derivatives-06','option-values','put-bounds','European Put Upper Bound'),
 G('Negativer Optionszeitwert','Optionspreis unter dem hypothetischen aktuellen Spot-Ausübungswert. Bei europäischen Rechten kann das mit korrekten diskontierten Grenzen vereinbar sein, etwa für einen tief im Geld liegenden Put bei positivem Zins. Die frühe Ausübung muss vertraglich fehlen; ein negativer Zeitwert ist kein negativer Gesamtpreis.','derivatives-06','option-values','negative-time','Negative Option Time Value'),
 G('Frühausübungswert','Ökonomischer Nutzen des zusätzlichen amerikanischen Ausübungsfensters gegenüber einem sonst gleichen europäischen Endrecht. Dieser Zusatz kann null sein. Eine sofortige Ausübung kann handelbaren Restwert aufgeben; Finanzierung und tatsächliche Ausschüttungstermine beeinflussen die Entscheidung.','derivatives-06','option-values','american','Early Exercise Premium'),
 G('Dynamische Optionsreplikation','Nachbildung eines bedingten Anspruchs durch im Zeitverlauf angepasste Aktien- und Finanzierungspositionen. Eine exakte Theorie benötigt passende Prozess-, Handels- und Finanzierungsannahmen. Ein unveränderter lokaler Delta-Hedge ist keine allgemeine globale Replikation.','derivatives-06','option-values','replication-limits','Dynamic Option Replication'),
 G('Konvexer Optionspayoff','Endleistung mit nach oben gekrümmter beziehungsweise geknickter Form. Call und Put begrenzen die ungünstige Ausübung bei null. Eine passende mittelwerterhaltende Streuungsvergrößerung unter gleichen Bewertungsbedingungen kann deshalb beide Rechte verteuern, ohne den Aktienmittelwert zu erhöhen.','derivatives-06','option-values','convexity','Convex Option Payoff'),
 G('Mittelwerterhaltende Streuung','Verteilungsänderung, die mehr Variabilität bei gleichem Mittelwert im passenden konvexen Vergleich erzeugt. Eine beliebige größere Varianzzahl allein beweist nicht jede solche Ordnung. Der Vergleich erklärt die gemeinsame Volatilitätswirkung auf Call und Put unter entsprechenden Modellannahmen.','derivatives-06','option-values','convexity','Mean-Preserving Spread'),
 G('Stetige Ausschüttungsrendite','Modellparameter für laufenden proportionalen Ertrag aus dem Aktienbesitz. Verringert den heutigen vorab bezahlten Endaktienerhalt gegenüber dem Spot. Kein genauer Ersatz für einen Kalender diskreter Gelddividenden und kein direkter Dividendenanspruch des Optionskäufers.','derivatives-06','option-values','dividends','Continuous Dividend Yield'),
 G('Risikoneutrale Ausübungswahrscheinlichkeit','Ausübungswahrscheinlichkeit unter einer zur Replikationsbewertung passenden Modellverteilung. Sie ist weder automatisch die tatsächliche Prognosewahrscheinlichkeit noch das Delta. Im einfachen geschlossenen europäischen Modell verwenden diese Größen unterschiedliche standardisierte Modellgrößen.','derivatives-06','option-values','model','Risk-Neutral Exercise Probability'),
 G('Optionsmodellgrenze','Beschränkung einer Optionsbewertung durch ihre Rechts-, Ertrags-, Prozess- und Handelsannahmen. Europäische kontinuierliche Modelle lösen keine beliebige amerikanische Entscheidung bei diskreten Dividenden. Abweichung von einem Modellwert allein beweist keine ausführbare Arbitrage.','derivatives-06','option-values','model','Option Model Limitation'),
 G('Delta','Lokale Ableitung des Optionspreises nach dem Basiswertkurs bei festgehaltenen übrigen Parametern. Entspricht im passenden Replikationsmodell der Aktienquote je Recht. Es ist keine allgemein gleiche tatsächliche oder risikoneutrale Ausübungswahrscheinlichkeit und bleibt bei Kursbewegungen nicht zwingend konstant.','derivatives-09','option-values','greeks','Option Delta'),
 G('Vega','Lokale Preisableitung nach der als Dezimalzahl angegebenen Volatilität. Im standardmäßigen europäischen Call-/Putmodell bei positiver Restzeit positiv. Eine Angabe je 1,00 Volatilität wird für einen Prozentpunkt mit 0,01 multipliziert. Einheit und Modellannahmen müssen genannt werden.','derivatives-09','option-values','greeks','Option Vega'),
 G('Theta','Lokale Preisableitung nach vergehender Kalenderzeit bei festgehaltenen übrigen Parametern. Bei vielen Longoptionen negativ, aber nicht bei allen europäischen Rechten. Eine Jahresquote wird nur mit einer ausdrücklich festgelegten Tageskonvention in eine Tagesquote übersetzt. Keine garantierte tatsächliche Tagespreisänderung.','derivatives-09','option-values','decay','Option Theta'),
 G('Implizite Volatilität','Volatilitätseingabe, die in einem ausdrücklich genannten Preismodell die ausgewählte Marktquote reproduziert. Abhängig von Strike, Laufzeit, Rechts- und Ertragsannahmen; nicht automatisch unverzerrte Prognose tatsächlicher zukünftiger Schwankung. Ein Preis außerhalb korrekter Grenzen lässt sich nicht durch beliebige zulässige Volatilität reparieren.','derivatives-09','option-values','implied','Implied Volatility'),
 G('Volatilitätsstruktur','Zusammenhang der impliziten Volatilitäten mit Strikes beziehungsweise Moneyness und Laufzeiten. Smile und Skew zeigen unterschiedliche inverse Modellpreiseingaben. Eine einheitliche konstante Modellvolatilität erklärt deshalb nicht automatisch alle beobachteten Optionspreise.','derivatives-09','option-values','implied','Volatility Surface|Volatility Smile|Volatility Skew'),
 G('Delta-Hedge','Basiswertposition, die die erste lokale Spotableitung einer Optionsposition ausgleicht. Beseitigt nicht automatisch Gamma, Vega, Sprung-, Finanzierungs- oder Transaktionsrisiken. Bei neuen Kursen kann ein anderes Hedgeverhältnis erforderlich werden.','derivatives-09','option-values','replication-limits','Delta Hedging'),
 G('Par-Swaprate','Gemeinsamer neuer Festzins, der die passend bewerteten variablen und festen Swapzahlungen ausgleicht. Bei identischen Perioden und Plänen ist er ein normalisierter Barwertdurchschnitt der passenden Forwardprojektionen. Er ist eine Jahresquote, kein Geldmarktwert und keine garantierte spätere Referenzrate.','derivatives-05','swaps','par-rate','Par Swap Rate',[{label:'Swaprate',units:['swaps']},{label:'Swapzins',units:['swaps']}]),
 G('Swap-Altvertragswert','Heutiger Geldwert der noch relevanten alten Swaprechte und -pflichten. Bei passendem konstantem Nominal entspricht der Pay-fixed-Wert der passenden neuen Vergleichsrate minus altem Festzins, multipliziert mit Nominal und verbleibender fester Rentenbarwertbasis. Bekannte Coupons und der tatsächliche Zahlungsplan müssen darin enthalten sein.','derivatives-05','swaps','value','',[{label:'Swapmarktwert',units:['swaps']},{label:'Mark-to-Market',units:['swaps']},{label:'Marktwert',units:['swaps']}]),
 G('Pay-fixed-Zinsswap','Swaprichtung, die festen Zins zahlt und die bezeichnete variable Referenz erhält. Eine höhere passende variable Rate begünstigt diese Seite bei sonst gleichen Bedingungen. Ihre Zahlungsstruktur kann eine gleichartige variable Kreditreferenz ausgleichen; Spread, Floor und Abweichungen bleiben gesondert.','derivatives-05','swaps','direction','',[{label:'Pay-fixed',units:['swaps']},{label:'Festzinszahler',units:['swaps']}]),
 G('Receive-fixed-Zinsswap','Gegenrichtung, die festen Zins erhält und variable Referenz zahlt. Kann den Ertrag einer genau passenden variablen Anlage stabilisieren. Sie ist nicht dieselbe wirtschaftliche Richtung wie ein Pay-fixed-Hedge eines variablen Kredits.','derivatives-05','swaps','lender','',[{label:'Receive-fixed',units:['swaps']},{label:'Festzinsempfänger',units:['swaps']}]),
 G('Swap-Nominal','Vertragliche Zinsberechnungsbasis. Im beschriebenen einfachen Zinsswap in einer Währung wird sie nicht automatisch als Darlehenskapital bereitgestellt oder getilgt. Ein variierender Nominalpfad verändert die Periodengewichte; andere Swaptypen können ausdrücklich zusätzliche Kapitalzahlungen vorsehen.','derivatives-05','swaps','contract','',[{label:'Nominal',units:['swaps']},{label:'Nominalbetrag',units:['swaps']}]),
 G('Swap-Rentenbarwertfaktor','Summe der vollständigen festen Zinsperiodenbrüche mal ihren passenden heutigen Zahlungsdiskontfaktoren. Bündelt den Barwert einer Einheit jährlicher fester Rate auf dem tatsächlichen Zahlungsplan. Er ist vom finanzierten Annuitätendarlehen gleichen Sprachstamms zu unterscheiden.','derivatives-05','swaps','annuity','Swap Annuity',[{label:'Annuity',units:['swaps']},{label:'Rentenbarwertfaktor',units:['swaps']}]),
 G('Swap-Barwertgewicht','Im gleichen Periodenmodell positiver Anteil aus Jahresbruch mal Zahlungsfaktor geteilt durch die Summe aller solchen Größen. Diese Gewichte summieren sich zu eins und machen den gemeinsamen Parzins zum gewichteten Forwardmittel. Abweichende fixe und variable Kalender verlangen andere vollständige Beinsummen.','derivatives-05','swaps','weights','',[{label:'Barwertgewicht',units:['swaps']},{label:'Barwertgewichte',units:['swaps']}]),
 G('Bekannter Swapcoupon','Bereits nach der vertraglichen Referenzregel festgestellter, aber noch nicht bezahlter Zinsbetrag. Wird mit der heutigen Restzahlungsfrist diskontiert. Sein vollständiger vertraglicher Zinsperiodenbruch wird nicht bloß wegen kürzerer verbleibender Zeit verkleinert.','derivatives-05','swaps','known-fixing'),
 G('Swap-Fixing','Vertraglicher Vorgang der Referenzbestimmung für eine Swapzinszahlung. Klassische Termraten können vorab feststehen; zusammengesetzte Overnight-Referenzen werden während der Periode beobachtet. Fixingdatum, Zinsperiode und Zahlungsdatum sind deshalb gesondert anzugeben.','derivatives-05','swaps','dates','',[{label:'Fixing',units:['swaps']}]),
 G('Swap-Abrechnungssprung','Änderung des verbleibenden Marktwerts durch tatsächliche Erfüllung einer fälligen Zahlung. Direkt vor Settlement enthält der Anspruch den fälligen Coupon, danach steht dieser als Cash und nur der Restwert verbleibt. Der isolierte Bildschirmwertsprung ist nicht automatisch ein zusätzlicher wirtschaftlicher Verlust.','derivatives-05','swaps','settlement'),
 G('Off-Market-Swap','Swap mit einer von der heutigen fairen gemeinsamen Quote abweichenden Festkondition. Seine reine Zahlungsreihe kann bereits bei Unterschrift positiven oder negativen Wert haben. Ein fairer Gesamtaustausch muss diesen Unterschied durch passende zusätzliche Gegenleistung berücksichtigen.','derivatives-05','swaps','off-market','Off Market Swap'),
 G('Swap-Erwerbswert','Heutiger Wertausgleich für den Erwerb eines bestehenden vorteilhaften Swapanspruchs. Er muss bei einer neu gerechneten Gesamtfinanzierung berücksichtigt werden. Eine alte niedrige Festquote ist bei fairem Erwerb kein kostenloser neuer Marktpreis.','derivatives-05','swaps','off-market'),
 G('Festzinsquote-PV01','Hier der zusätzliche heutige feste Zahlungsbarwert bei einem Basispunkt mehr vertraglichem Festzins unter unverändertem Markt. Er entspricht Nominal mal fester Rentenbarwertbasis mal einem Zehntausendstel. Diese Vertragsquoten-Sensitivität ist nicht automatisch die vollständige parallele Marktkurven-DV01.','derivatives-05','swaps','curve-risk','',[{label:'PV01',units:['swaps']}]),
 G('Mehrkurven-Swapbewertung','Bewertung mit getrennten passenden Referenzprojektionen und Zahlungsdiskontierung. Die Gleichsetzung der Beinsbarwerte bleibt maßgeblich, die Ein-Kurven-Teleskopabkürzung benötigt jedoch zusätzliche gemeinsame Faktorbeziehungen. Referenztenor, Besicherung und Kalender müssen konsistent sein.','derivatives-05','swaps','multi-curve','',[{label:'Mehrkurvenstruktur',units:['swaps']}]),
 G('Swap-Referenzfloor','Vertragliche Untergrenze einer verwendeten Zinsreferenz. Liegt eine solche Begrenzung nur im Kredit und nicht im gegenläufigen Swap, stimmen die Zahlungsfunktionen bei negativen Raten nicht mehr überein. Ein Floor des All-in-Zinses ist nochmals von einem Floor nur der Referenz zu unterscheiden.','derivatives-05','swaps','mismatch','',[{label:'Referenzfloor',units:['swaps']}]),
 G('Amortisierender Swap','Swap mit vorab festgelegtem sinkendem Nominalpfad. Die jährlichen Geldbeiträge werden mit ihrem jeweiligen Restbetrag gewichtet; ein einziger konstanter Nominal darf nicht aus allen Perioden herausgekürzt werden. Passender Tilgungsverlauf kann ein entsprechendes amortisierendes Darlehen absichern.','derivatives-05','swaps','telescope','Amortizing Swap'),
 G('Währungsswap','Swap mit Zahlungen in unterschiedlichen Währungen und je nach Vertrag zusätzlichen Kapitalaustauschen. Jedes Bein wird in seiner eigenen Währung passend bewertet und anschließend eindeutig in die Vergleichswährung übersetzt. Ursprüngliche Austauschbeträge, heutiger Spot, Referenzbasis und Sicherheiten sind getrennte Vertrags- und Bewertungsgrößen.','derivatives-05','swaps','currency','Currency Swap|Cross-currency Swap'),
 G('Swap-Festzinsdifferenz zur Staatsanleihe','Hier die aktuelle Par-Swaprate minus passend verglichener Staatsanleihenrendite. Kann positiv oder negativ sein und reflektiert neben Kredit- und Liquiditätsmerkmalen auch Funding, Repo, Anleiheangebot und Bilanzkosten. Ist weder automatisch ein persönlicher Kreditaufschlag noch ein Beweis kostenloser Arbitrage.','derivatives-05','swaps','swap-spread','',[{label:'Swapspread',units:['swaps']}]),
 G('Swap-Forwardserie','Lesart eines einfachen Swaps als Reihe passender künftiger Zinsdifferenzansprüche. Der gemeinsame Swapfestzins muss das Gesamtpaket fair machen, während einzeln faire Forwards ihre jeweiligen eigenen Periodenraten benutzen. Referenz, Nominal, Periodenbruch und tatsächliche Zahlungszeit müssen übereinstimmen.','derivatives-05','swaps','forward-strip'),
 G('Futures-Abrechnungsquote','Aktuell verwendete Preisbedingung für genau den bezeichneten Future und Erfüllungstermin. Ihre Änderung gegenüber der vorigen Abrechnung bestimmt im linearen Cash-Lehrfall den neuen Ausgleich. Sie ist weder der heutige Gesamtvertragswert noch der Saldo des Margin-Kontos.','derivatives-04','futures','map','',[{label:'Futuresquote',units:['futures']},{label:'Futurespreis',units:['futures']}]),
 G('Futures-Restvertragswert','Noch offener Marktwertanspruch des betrachteten Futures zu einem genau bezeichneten Zeitpunkt. Direkt nach vollständigem tatsächlichem Barausgleich ist er im erklärten Standardmodell null. Bereits bezahlte Ergebnisse und weitere Risiken bleiben bestehen.','derivatives-04','futures','reset','',[{label:'Vertragswert',units:['futures']},{label:'Restvertragswert',units:['futures']}]),
 G('Realisierte Futuresvariation','Laufender tatsächlicher Barausgleich einer Futurespreisänderung unter der ausdrücklich angegebenen Cashkonvention. Bei fester linearer Longposition ergibt er sich aus neuer minus voriger Abrechnungsquote mal Einheitenmenge. Eine Sicherheitsauffüllung ist davon gesondert zu verfolgen.','derivatives-04','futures','ledger','',[{label:'Variation Margin',units:['futures']},{label:'Futuresvariation',units:['futures']}]),
 G('Futures-Marginkonto','Zugeordnetes Konto für gestellte Sicherheitsmittel und nach den jeweiligen Regeln verbuchte Ausgleiche, Einzahlungen und Entnahmen. Ein hoher Saldo ist nicht automatisch ein hoher Gewinn, weil er eigene Einzahlungen enthalten kann. Entnahmeregeln und Verzinsung müssen separat geprüft werden.','derivatives-04','futures','margin','Futures-Margin-Konto',[{label:'Margin-Konto',units:['futures']},{label:'Margin-Kontoauszug',units:['futures']}]),
 G('Futures-Auffüllbetrag','Zusätzliche Mittelübertragung auf das Margin-Konto nach einer Schwellenunterschreitung gemäß der angegebenen Regel. Im eigenen Lehrfall wird auf Initial Margin aufgefüllt. Die Übertragung bindet freie Kasse; sie ist nicht nochmals derselbe bereits erfasste Kursverlust.','derivatives-04','futures','margin','',[{label:'Nachschuss',units:['futures']}]),
 G('Futures-Sicherheitspuffer','Anfänglich nach dem jeweiligen Regelwerk zu stellende Mittel für potenzielle künftige Exposition. Der Betrag ist keine vollständige Basiswertzahlung, keine Optionsprämie und keine maximale Verlustgrenze. Seine Bindung kann zusätzliche Finanzierungskosten verursachen.','derivatives-04','futures','initial','',[{label:'Initial Margin',units:['futures']}]),
 G('Futures-Maintenance-Schwelle','Im bezeichneten Kontomodell Mindestkontostand, dessen Unterschreitung die festgelegte Auffüllung auslöst. Die Schwelle ist vom Auffüllziel zu unterscheiden. Beide Beträge und mögliche untertägige Anforderungen sind vertraglich beziehungsweise durch Broker- und Clearingregeln bestimmt.','derivatives-04','futures','margin','',[{label:'Maintenance Margin',units:['futures']}]),
 G('Teleskopierende Summe','Summe aufeinanderfolgender Differenzen, in der sich innere Werte paarweise aufheben. Bei unveränderter Futuresmenge liefert die ungewichtete Summe der Preisbewegungen die letzte minus erste Quote. Abweichende Mengen, Gebühren und Zeitwertfaktoren müssen zusätzlich berücksichtigt werden.','derivatives-04','futures','telescope'),
 G('Finanzierter Futures-Endwert','Auf einen gemeinsamen Endtermin gebrachte Summe sämtlicher tatsächlicher Futureszahlungen. Positive Zwischenzahlungen werden passend angelegt und negative finanziert. Unterschiedliche Anlage- und Kreditsätze oder eingeschränkte Verfügbarkeit erfordern eine entsprechend genauere Cashrechnung.','derivatives-04','futures','funding'),
 G('Futures-Punktmultiplikator','Geldbetrag je vollem Preisquotenpunkt und Kontrakt im festgelegten Produkt. Zusammen mit Preisquoteänderung und Kontraktzahl bestimmt er den linearen Ausgleich. Ein Punkt, ein Tick und ein Basispunkt der Referenzrate sind nicht notwendig dieselbe Größe.','derivatives-04','futures','tick','',[{label:'Punktmultiplikator',units:['futures']}]),
 G('Inverse Zinsquote','Preisquotierung als hundert minus der in Prozent ausgedrückten Referenzrate. Eine steigende Rate senkt damit die Preisquote; der Short der Preisquote profitiert von dieser Bewegung. Die Rate selbst muss nach der jeweiligen Referenzperiodenregel berechnet werden.','derivatives-04','futures','rate-quote'),
 G('Convexity Bias','Modell- und zahlungsregelabhängiger Unterschied zwischen passenden fairen Futures- und Forward-/Swap-Zinskonditionen. Laufende Futureszahlungen und nichtlineare zeitwertbereinigte Vergleichsansprüche gehören zu seiner Erklärung. Der Betrag ist kein universeller fester Spread und nicht einfach der Abstand zweier zu unterschiedlichen Zeitpunkten gezeigter Zahlungen.','derivatives-04','futures','convexity','Futures-FRA-Convexity|Konvexitätsbias'),
 G('Zustandsabhängiger Diskontfaktor','Faktor, der eine Zahlung innerhalb des bezeichneten Zustands auf einen früheren Termin übersetzt. Im Zwei-Zustände-Lehrmodell ist der zweite Periodenzins erst beim ersten späteren Termin bekannt; deshalb unterscheidet sich der Faktor je Zustand. Alle Ansprüche müssen mit denselben konsistenten Faktoren bewertet werden.','derivatives-04','futures','state-discount'),
 G('Risikoneutrales Zustandsgewicht','Im angegebenen Modell verwendetes Bewertungsgewicht für einen Zustand. Gemeinsam mit den Diskontfaktoren erzeugt es konsistente heutige Preise. Es ist weder eine garantierte reale Ereignishäufigkeit noch eine beliebige zusätzliche Annahme bei unabhängig festgehaltenen widersprüchlichen Marktpreisen.','derivatives-04','futures','state-model','',[{label:'Bewertungsgewicht',units:['futures']},{label:'Bewertungsgewichte',units:['futures']}]),
 G('Settled-to-market','Vertragsgestaltung, bei der die bezeichnete laufende Zahlung den aktuellen Marktwertanspruch erfüllt statt nur Sicherheiten dafür zu stellen. Nach vollständiger Erfüllung wird der Restanspruch für den bezeichneten Zyklus zurückgesetzt. Bisherige Ergebnisse und zukünftiges Exposure bleiben wirtschaftlich relevant.','derivatives-04','futures','clearing','STM'),
 G('Collateralised-to-market','Gestaltung mit laufender Sicherheitenstellung für einen weiter zu verfolgenden Derivatanspruch. Derivatwert und Sicherheiten- beziehungsweise Rückgewähranspruch sind entsprechend getrennt abzustimmen. Zentrales Clearing oder ein laufender Transfer allein beweist keine Erfüllung des Derivatanspruchs.','derivatives-04','futures','clearing','CTM|Collateralized-to-market'),
 G('Discounted Contingent Variation Margin','Besondere, unter anderem für bestimmte physisch erfüllte LME-Kontrakte verwendete Variation-Margin-Gestaltung. Ein positiver Marktwert kann zur Sicherheitenabdeckung nutzbar sein, ohne vor dem Schlussdatum frei als realisierter Gewinn ausgezahlt zu werden. Die konkrete Marktregel ist für die Fundingrechnung entscheidend.','derivatives-04','futures','clearing','DCVM'),
 G('Realised Variation Margin','Bezeichnung für tatsächlich realisierte laufende Gewinne und Verluste unter der jeweiligen Abrechnungsregel. Sie wird etwa im LME-Kontext von Discounted Contingent Variation Margin unterschieden. Ob und wann Mittel frei verfügbar sind, muss für Produkt und Kundenbeziehung geprüft werden.','derivatives-04','futures','clearing','RVM|Realized Variation Margin'),
 G('Zusammengesetzte SOFR-Rate','Aus den tatsächlich beobachteten Overnight-SOFR-Abschnitten und ihren Tagen zusammengesetzte, anschließend annualisierte Referenzrate. Im erklärten Dreimonats-Futuresfall wird sie nachschüssig über die Referenzperiode bestimmt. Sie ist keine schon zu Periodenbeginn vollständig bekannte klassische Termrate.','derivatives-04','futures','sofr','',[{label:'SOFR',units:['futures']},{label:'SOFR-Rate',units:['futures']}]),
 G('Futures-Schlussreferenz','Vertraglich genau definierter Schlussindex beziehungsweise lieferbarer Referenzwert für die Enderfüllung. Konvergenz bezieht sich auf diese übereinstimmende Einheit, Qualität, Orts- und Zeitdefinition, nicht auf jeden ähnlichen Kassapreis. Lieferoptionen und Marktfriktionen verlangen zusätzliche Prüfung.','derivatives-04','futures','convergence','',[{label:'Schlussreferenz',units:['futures']}]),
 G('Forward Rate Agreement','Verbindlicher Vertrag über den Ausgleich einer Zinsdifferenz für eine künftig beginnende definierte Periode auf einen Nominalbetrag. Nominal, Referenz, Festzins, Tagzählung und Zahlungsregel stehen fest. Das FRA selbst stellt kein Darlehenskapital bereit. Der hier erklärte Lehrfall wird zu Periodenbeginn um den passenden Zeitwert bereinigt bar erfüllt.','derivatives-03','forward-value','fra-contract','FRA'),
 G('Pay-fixed-FRA','FRA-Seite, die wirtschaftlich den festen Zins zahlt und den später bestimmten Referenzzins erhält. Ihr Ausgleich steigt bei höherer Referenz relativ zum Festzins. Sie kann eine passende zukünftige variable Zinslast stabilisieren; Kreditspread, Mengen-, Termin- und Finanzierungsabweichungen bleiben separat zu prüfen.','derivatives-03','forward-value','fra-contract','',[{label:'Pay-fixed',units:['forward-value']},{label:'Pay-fixed/Receive-floating',units:['forward-value']}]),
 G('Receive-fixed-FRA','Gegenrichtung zum Pay-fixed-FRA: fester Zins wird erhalten und Referenzzins bezahlt. Kann den geringeren Ertrag einer passenden künftigen variablen Einlage bei fallenden Zinsen ausgleichen. Die tatsächliche Anlage des frühen Ausgleichs gehört zur vollständigen Endrechnung.','derivatives-03','forward-value','lender','',[{label:'Receive-fixed',units:['forward-value']},{label:'Receive-fixed/Pay-floating',units:['forward-value']}]),
 G('FRA-Startzahlung','Im hier festgelegten vorschüssigen Lehrvertrag tatsächlich am Beginn der späteren Zinsperiode bezahlter Betrag. Die Endzinsdifferenz wird mit dem passenden positiven Periodenfaktor auf diesen früheren Termin übersetzt. Der abgezinste Betrag und sein späteres Endwertäquivalent sind keine zwei unabhängigen Gewinne.','derivatives-03','forward-value','fra-settlement','FRA-Ausgleich|Vorschüssiger FRA-Ausgleich'),
 G('FRA-Endwertäquivalent','Zinsdifferenz des FRA ausgedrückt am Ende der Referenzperiode. Bei vorschüssiger Erfüllung ist dieser Betrag keine zusätzliche Endzahlung; er beschreibt, was die frühere Zahlung bei passender Anlage oder Finanzierung zum Periodenende bewirkt.','derivatives-03','forward-value','fra-case','',[{label:'Endwertäquivalent',units:['forward-value']}]),
 G('FRA-Reset','Vertraglich definierter Zeitpunkt beziehungsweise Vorgang, bei dem die relevante Zinsreferenz für den betrachteten FRA feststeht. Im vereinfachten Lehrfall fallen Beobachtung und früher Ausgleich auf den Periodenbeginn. Reale Vorlauf-, Beobachtungs- und Abwicklungsregeln müssen gesondert geprüft werden.','derivatives-03','forward-value','fra-contract','',[{label:'Reset',units:['forward-value']}]),
 G('FRA-Nominal','Nichtnegative Berechnungsbasis für die FRA-Zinsdifferenz. Im beschriebenen bar erfüllten FRA wird sie nicht als Kapital zwischen den Parteien ausgetauscht. Eine wirkliche Kreditaufnahme oder Einlage ist ein gesonderter Vertrag und besitzt ihre eigenen Kapitalströme.','derivatives-03','forward-value','fra-contract','',[{label:'Nominalbetrag',units:['forward-value']},{label:'Nominal',units:['forward-value']}]),
 G('FRA-Forwardrate','Heute aus zwei passenden Kurvenfaktoren implizierte Zinskondition für die später beginnende FRA-Periode. Der Faktorquotient wird zuerst in eine Periodenrendite und anschließend in die verlangte Jahresquote übersetzt. Sie ist keine garantiert eintretende spätere Referenzbeobachtung.','derivatives-03','forward-value','forward-derive','',[{label:'Forwardrate',units:['forward-value']},{label:'Forwardzins',units:['forward-value']}]),
 G('FRA-Vertragswert','Heutiger Wert des bestehenden Zinsdifferenzanspruchs unter den jeweils angegebenen Kurven- und Vertragsbedingungen. Im passenden Ein-Kurven-Lehrfall entsteht er aus zwei Nullkuponansprüchen. Er darf nicht mit der Nominalbasis, dem alten Zinssatz oder einem späteren Szenario-Cashfluss gleichgesetzt werden.','derivatives-03','forward-value','fra-value'),
 G('Zinsperiodenbruch','Vertraglicher Jahresanteil der betrachteten Zinsperiode. Kann etwa aus tatsächlichen Zinstagen geteilt durch eine festgelegte Basis berechnet werden. Drei Kalendermonate sind deshalb nicht automatisch exakt ein Vierteljahr; Fixingvorlauf und Banktagsregeln sind nochmals andere Terminfragen.','derivatives-03','forward-value','day-count','Periodenbruch|Accrual Fraction'),
 G('Forward-Wachstumsfaktor','Quotient zweier passender heutiger Diskontfaktoren für Beginn und Ende einer späteren Anlageperiode. Er ist ein dimensionsloser Faktor und noch keine annualisierte Zinsquote. Erst die gewählte Verzinsungs- und Zeitkonvention bestimmt die zugehörige Rate.','derivatives-03','forward-value','forward-derive'),
 G('Wiederanlage-Breakeven','Heute festgelegte oder implizierte Wiederanlagerate, bei der ein kurzer Anlageweg mit anschließender späterer Anlage denselben Endbetrag wie der passende direkte längere Weg erzeugt. Der Preisgleichstand ist von einer Prognose des später tatsächlich verfügbaren Zinssatzes zu unterscheiden.','derivatives-03','forward-value','forward-case'),
 G('Altvertragswert','Heutiger Vorteil oder Nachteil eines bereits bestehenden Vertrags mit unveränderter alter Kondition gegenüber einem gleichartigen aktuellen Vergleich. Für den einfachen Long-Lieferforward wird der spätere Preisunterschied passend diskontiert und mit der Menge skaliert. Ein positiver Wert ist keine automatisch schon erhaltene Barzahlung.','derivatives-03','forward-value','replication','',[{label:'Vertragswert',units:['forward-value']}]),
 G('Off-Market-Forward','Forward mit bewusst von der aktuellen fairen neuen Kondition abweichendem Lieferpreis. Kann bereits bei Abschluss einen positiven Wert für eine Seite und negativen für die andere besitzen. Ein fairer Gesamtaustausch benötigt dann eine geeignete Gegenleistung; fehlender Cashfluss allein beweist keinen Nullwert.','derivatives-03','forward-value','off-market','Off-Market'),
 G('Forward-Glattstellung','Herstellung einer gegenläufigen passenden Forwardposition zur Beseitigung des verbleibenden Basiswertexposures. Kann einen späteren Nettobetrag fixieren, ohne den alten Vertrag rechtlich aufzuheben oder den Betrag heute bar auszuzahlen. Identische Menge, Referenz und Termine sind entscheidend.','derivatives-03','forward-value','closeout','',[{label:'Glattstellung',units:['forward-value']}]),
 G('Mark-to-Market','Neubewertung eines Instruments zu aktuell vergleichbaren Marktbedingungen. Bei einem bestehenden Forward bleibt die alte Vertragskondition fest; bewertet wird deren heutiger Vor- oder Nachteil. Der resultierende Marktwert ist von tatsächlicher Zahlung, Sicherheiten und vollständigem Kreditausfallverlust zu unterscheiden.','derivatives-03','forward-value','value-case','MTM|Marktwertbewertung'),
 G('Nullkuponreplikation','Hier im ausdrücklich passenden Ein-Kurven-Modell eine Kombination aus Anspruch auf Nominal am Periodenbeginn und Gegenpflicht aus Nominal mal festem Periodenfaktor am Ende. Der Wert der Kombination beim Reset entspricht dem definierten frühen FRA-Ausgleich; eine danach geschlossene Endpflicht wird nicht nochmals gezählt.','derivatives-03','forward-value','fra-replication'),
 G('Finanzierung des FRA-Ausgleichs','Tatsächlicher Anlage- oder Finanzierungspfad der frühen FRA-Zahlung. Nur bei passenden Bedingungen erzeugt ihre Verwendung genau das für die einfache Zinsfixierung benötigte Endwertäquivalent. Ein später günstiger Kredit ersetzt keine rechtzeitige Finanzierung eines frühen Abflusses.','derivatives-03','forward-value','funding'),
 G('Verbleibender Ertrag','Für eine heutige Neubewertung noch ausstehender und dem betrachteten Besitzpfad zustehender Ertrag. Bereits vor dem Bewertungsdatum gezahlte Beträge werden nicht erneut aus dem aktuellen Spotpreis abgezogen. Bei einem Übergangstag bestimmt die wirtschaftliche Ertragsberechtigung die Zuordnung.','derivatives-03','forward-value','income-case'),
 G('Kreditzusage','Gesonderte vertragliche Vereinbarung über Kapitalbereitstellung unter den festgelegten Bedingungen. Von einer Zinsabsicherung zu unterscheiden: Ein gewöhnlicher FRA vereinbart einen Zinsausgleich auf eine Rechenbasis und stellt selbst kein tatsächliches Darlehenskapital bereit. Umfang und Bedingungen einer wirklichen Zusage sind separat zu prüfen.','derivatives-03','forward-value','fra-contract'),
 G('Arbitrage','Vollständig ausführbare Kombination von Geschäften ohne positiven eigenen Anfangsaufwand und ohne spätere negative Nettopflicht, die mindestens einen positiven Vorteil bietet. Im idealen Carryfall verbleibt in jedem Endzustand derselbe sichere Überschuss. Alle Finanzierungs-, Rückgabe-, Kosten- und Zwischenzahlungspflichten gehören zum Nachweis. Eine günstige Prognose allein genügt nicht.','derivatives-02','carry','arbitrage','Arbitragefreiheit|No-Arbitrage|No-Arbitrage-Prinzip'),
 G('Terminvertragsreplikation','Nachbildung des vollständigen Forward-Zahlungsprofils durch andere ausführbare Geschäfte. Im ertragsfreien Grundfall erzeugen kreditfinanzierter Spotkauf und sichere Endschuld dieselbe wirtschaftliche Endwirkung wie ein Long-Forward. Bei Erträgen und Kosten muss deren gesamte zeitliche Wirkung ergänzt werden.','derivatives-02','carry','replication','',[{label:'Replikation',units:['carry']}]),
 G('Gesetz des einheitlichen Preises','Unter identischen erreichbaren Handelsbedingungen haben Portfolios mit identischen Zahlungen in allen relevanten Zuständen und zu allen relevanten Zeitpunkten denselben heutigen Preis. Sonst könnte der günstigere Anspruch gekauft und der teurere verkauft werden. Gleichheit bloßer Erwartungswerte reicht nicht.','derivatives-02','carry','one-price','Law of One Price'),
 G('Cash-and-Carry','Vollständiger Pfad aus Kauf des lieferfähigen Basiswerts, Finanzierung und gleichzeitigem Terminverkauf. Unter den idealen Annahmen fixiert ein angebotener Lieferpreis oberhalb der vollständigen Endkosten einen Überschuss. Erträge, Lagerung, Kosten und rechtzeitige Liquidität sind einzubeziehen.','derivatives-02','carry','cash-carry','Cash and Carry'),
 G('Reverse Cash-and-Carry','Umgekehrter Replikationspfad: den Basiswert leihen und verkaufen, Erlös anlegen und die Rückgabe über einen Long-Forward festlegen. Ein positiver Modellabstand ist nur bei tatsächlich verfügbarer Leihe, passender Ertragskompensation und vollständiger Erfüllung ein Arbitragenachweis.','derivatives-02','carry','reverse','Reverse Cash and Carry'),
 G('Cost of Carry','Gesamte Kosten und Vorteile des Besitzes bis zur Lieferung, insbesondere Finanzierung und Haltekosten abzüglich berücksichtigter Erträge oder Besitzvorteile. Im handelbaren Finanzasset-Modell werden damit Replikationspreise begründet; bei Verbrauchsgütern können nicht handelbarer Nutzen und fehlende Umkehrbarkeit nur bedingte Beziehungen oder Grenzen erlauben.','derivatives-02','carry','storage','Haltekosten|Netto-Carry'),
 G('Prepaid Forward Price','Heute sofort bezahlter Preis für den Erhalt einer Einheit zu einem späteren Termin. Bei bekannter stetiger proportionaler Ertragsrate und vollständiger Wiederanlage entspricht er dem heutigen Kaufpreis eines bis dahin auf eine Einheit wachsenden Teilbestands. Der gewöhnliche Forward-Lieferpreis wird dagegen erst am Termin bezahlt.','derivatives-02','carry','yield','Prepaid-Replikationspreis|Prepaid-Preis|Prepaid Forward'),
 G('Forwardpreis','Heute vereinbarte oder aktuell angebotene Kondition für Lieferung zu einem bestimmten späteren Termin, je definierter Einheit. Ein marktgerechter neuer Preis ist unter passenden Annahmen durch Replikation beschränkt. Er ist weder der heutige Vertragsmarktwert noch zwingend die reale Erwartung des späteren Spotpreises.','derivatives-02','carry','notation','Forward Price|Lieferpreis'),
 G('Finanzierungscarry','Wirkung der Finanzierung des heutigen Besitzes bis zur Lieferung. Ohne Erträge und Kosten ist der faire Lieferpreis der auf den Termin aufgezinste Spotpreis. Der tatsächlich verfügbare Zinssatz und die Verzinsungskonvention müssen angegeben werden.','derivatives-02','carry','base'),
 G('Bekannter Geldertrag','Im Replikationsmodell sicherer betragsmäßig und zeitlich festgelegter Zufluss während der Halteperiode. Sein heutiger Barwert reduziert den zu finanzierenden Nettokaufpreis. Eine nur geschätzte Dividende erfüllt diese Sicherheit nicht automatisch.','derivatives-02','carry','income'),
 G('Proportionale Ertragsrate','Ertrag als kontinuierlicher Anteil des jeweils gehaltenen Werts im ausdrücklich bezeichneten Modell. Bei bekannter konstanter Rate und vollständiger Wiederanlage wächst die Stückzahl deterministisch. Das ist ein anderer Zahlungsansatz als ein fester Geldbetrag auf den heutigen Spotpreis.','derivatives-02','carry','yield','Proportional Income Yield'),
 G('Convenience Yield','Wirtschaftlicher Nutzen verfügbaren physischen Bestands, etwa vermiedener Produktionsunterbrechungen. Gewöhnlich kein separat handelbarer sicherer Coupon. Er senkt im üblichen Rohstoff-Ratenmodell den Forwardpreis relativ zu Finanzierung und Lagerkosten; eine implizierte Rate allein beweist keine risikolose Gegenstrategie.','derivatives-02','carry','convenience','Besitznutzen'),
 G('Contango','Hier ein Terminpreis oberhalb des gleichzeitig betrachteten Spotpreises; bei konstant positivem Netto-Carry zugleich steigende Laufzeitkurve. Die Terminstruktur zeigt heutige Preise verschiedener Liefertermine und garantiert keinen späteren Spotanstieg. Bei komplexen Kurven muss genau bezeichnet werden, welche Fälligkeiten verglichen werden.','derivatives-02','carry','curve'),
 G('Backwardation','Hier ein Terminpreis unter dem gleichzeitig betrachteten Spotpreis; im konstanten negativen Netto-Carry-Modell fällt die Laufzeitkurve. Hohe Erträge, Besitznutzen oder negative Finanzierung können einen Abschlag erklären. Der Ausdruck belegt allein weder Fehlbewertung noch einen sicheren späteren Gewinn.','derivatives-02','carry','curve'),
 G('Carry-Konvergenz','Annäherung eines aktuellen neuen Terminpreises an den gleichzeitig geltenden Spotpreis bei verschwindender Restlaufzeit für denselben sofort lieferbaren Anspruch. Der alte feste Kaufpreis eines schon bestehenden Vertrags wird dadurch nicht angepasst.','derivatives-02','carry','convergence','',[{label:'Konvergenz',units:['carry']}]),
 G('Erwarteter künftiger Spotpreis','Mit ausdrücklich bezeichneten realen oder subjektiven Wahrscheinlichkeiten gewichteter Mittelwert möglicher späterer Spotpreise. Eine Schätzung mit möglichen Verlustzuständen und keine sichere Zahlung. Sie kann vom durch Replikation bestimmten Forwardpreis abweichen.','derivatives-02','carry','expectation','Expected Future Spot Price'),
 G('Reale Wahrscheinlichkeiten','Gewichte für die tatsächlichen oder subjektiv geschätzten Häufigkeiten möglicher Zustände. Mit ihnen berechnete Erwartungen sind von aus Marktpreisen abgeleiteten Bewertungsgewichten zu unterscheiden. Ein positiver realer Erwartungswert schließt Verluste nicht aus.','derivatives-02','carry','expectation','Physical Probabilities'),
 G('Bewertungswahrscheinlichkeiten','Aus aktuellen handelbaren Preisen gewonnene Gewichte zur konsistenten Bewertung in einem geeigneten Modell. Im vollständigen Zwei-Zustands-Fall reproduzieren sie den sicheren Finanzierungsweg. Sie sind nicht automatisch Prognosen tatsächlicher Häufigkeiten; die Carrydarstellung dazu ist eine optionale Vertiefung.','derivatives-02','carry','pricing-measure','Pricing Weights'),
 G('Carry-Arbitrageband','Bereich ohne Gewinn in den konkret untersuchten ausführbaren Cash-and-Carry- und Reversepfaden. Geld-/Briefpreise, unterschiedliche Kredit- und Anlagezinssätze sowie zusätzliche Kosten erzeugen unterschiedliche Schwellen. Die jeweilige Forwardseite muss mit dem passenden Pfad verglichen werden.','derivatives-02','carry','bands','No-Arbitrage Band'),
 G('Stückreplikation','Aufbau einer später festgelegten Stückzahl durch passenden heutigen Teilbestand und vollständige Wiederanlage proportionaler Erträge. Im konstanten stetigen Modell wächst der reduzierte Anfangsbestand bis zur Lieferung auf eine Einheit. Reinvestierte Erträge sind kein zusätzlicher freier Cashzufluss.','derivatives-02','carry','yield'),
 G('Hedge','Gegenposition zur Veränderung eines bestehenden oder konkret erwarteten wirtschaftlichen Risikos. Ob eine Absicherung gelingt, wird am gemeinsamen Grundgeschäft, Derivat, den Kosten und Zahlungszeitpunkten beurteilt. Ein isolierter Derivateverlust kann einen günstiger gewordenen Einkauf oder höheren Verkaufserlös ausgleichen.','derivatives-12','derivative-uses','exposure','Hedging|Absicherung|absichern'),
 G('Spekulation','Bewusst eingegangenes Markt- oder anderes Risiko ohne die für den bezeichneten Zweck passende Gegenposition, mit dem Ziel eines günstigen Ergebnisses. Kann zu einem zulässigen Mandat gehören, wird aber durch den Namen Hedge nicht automatisch zur Absicherung.','derivatives-12','derivative-uses','exposure','Speculation'),
 G('Preisentdeckung','Informationsprozess, in dem Handel zu beobachtbaren Preisen für definierte Verträge führt. Solche Preise können Entscheidungen unterstützen, sind aber weder eine sichere Vorhersage noch eine garantierte spätere Quote für einen abweichenden lokalen Bedarf.','derivatives-12','derivative-uses','price-discovery','Price Discovery'),
 G('Risikoallokation','Zuordnung von Risiken zu Parteien oder Positionen. Derivate können bestimmte Risiken übertragen und mit anderen Zahlungsbedarfen verbinden; das übertragene Risiko verschwindet dadurch nicht automatisch aus dem System.','derivatives-12','derivative-uses','allocation','Risk Allocation'),
 G('Long-Hedge','Im einfachen Beschaffungsfall eine gekaufte Futures- oder Forwardposition gegen einen künftig teurer werdenden Einkauf. Die positive Wirkung bei steigender Referenz soll den höheren physischen Aufwand ausgleichen; Menge, Basis und Termine müssen passen.','derivatives-12','derivative-uses','long-hedge','Long Hedge|Einkaufssicherung'),
 G('Short-Hedge','Im einfachen Absatzfall eine verkaufte Futures- oder Forwardposition gegen einen künftig niedrigeren Verkaufspreis. Die positive Wirkung bei fallender Referenz ergänzt den gesunkenen physischen Erlös. Ein Verlust bei steigenden Preisen kann mit erfolgreicher Erlösstabilisierung zusammenfallen.','derivatives-12','derivative-uses','short-hedge','Short Hedge|Verkaufssicherung'),
 G('Futuresbasis','Hier definierte Differenz lokaler Kassapreis minus Futurespreis in konsistenten WE je Einheit. Sie kann positiv oder negativ sein und sich durch Ort, Qualität, Termin oder lokale Marktbedingungen verändern. Eine passende Hedge-Menge fixiert diese Differenz nicht automatisch.','derivatives-12','derivative-uses','basis','Cash-Futures-Basis',[{label:'Basis',units:['derivative-uses']}]),
 G('Hedge-Basisrisiko','Risiko, dass sich die tatsächliche Beziehung zwischen Grundgeschäft und Hedge-Referenz anders entwickelt als erwartet. Bei der Definition Kassa minus Future erhöht eine stärkere Endbasis den effektiven Einkaufspreis und zugleich den effektiven Verkaufspreis: dieselbe Änderung belastet Käufer und begünstigt Verkäufer.','derivatives-12','derivative-uses','basis-case','',[{label:'Basisrisiko',units:['derivative-uses']},{label:'Basis Risk',units:['derivative-uses']}]),
 G('Stärkere Basis','Höhere beziehungsweise weniger negative Differenz unter der hier ausdrücklich verwendeten Konvention Kassapreis minus Futurespreis. Der Effekt auf einen passend gesicherten Einheitspreis ist positiv; als Käuferaufwand ist dies ungünstig, als Verkäufererlös günstig.','derivatives-12','derivative-uses','basis-case','Basisverstärkung|Strengthening Basis'),
 G('Schwächere Basis','Niedrigere beziehungsweise stärker negative Differenz unter der hier verwendeten Konvention Kassapreis minus Futurespreis. Ein passend gesicherter effektiver Einheitspreis sinkt; dies begünstigt den Käufer und belastet den Verkäufer.','derivatives-12','derivative-uses','basis-case','Basisabschwächung|Weakening Basis'),
 G('Hedgequote','Umfang der Hedge-Gegenposition relativ zum bezeichneten Grundexposure. Im einfachen Einheitenfall sind das Futures-Einheiten je tatsächlicher physischer Einheit. Bei physischer Menge null ist diese Verhältniszahl nicht definiert. Gleiche Nominale garantieren keine gleiche Sensitivität.','derivatives-12','derivative-uses','quantity','Hedge Ratio'),
 G('Unterabsicherung','Ein Hedge, dessen relevante Gegenwirkung kleiner als das zum Ziel passend ermittelte Grundexposure ist. Im einfachen gleichartigen Einheitenfall bleibt bei kleinerer Hedge-Menge eine positive Restmenge und damit ein Teil der ursprünglichen Preisabhängigkeit.','derivatives-12','derivative-uses','quantity','Underhedging|Unterdeckung des Hedges'),
 G('Übersicherung','Ein Hedge, dessen Gegenwirkung das zum Ziel passende Grundexposure übersteigt. Im einfachen Einheitenfall wird physische Menge minus Hedge-Menge negativ: Die Restpreisabhängigkeit dreht sich um. Ein nominal größerer Hedge ist deshalb nicht automatisch besser.','derivatives-12','derivative-uses','quantity','Overhedging|Überabsicherung'),
 G('Hedge-Restmenge','Im einfachen gleichartigen Einheitenmodell tatsächliche physische Menge minus abgesicherte Futures-Einheiten. Bei festgehaltener Basis entspricht sie der Steigung des Netto-Einkaufsaufwands gegenüber dem Auflösungsfuture. Sie ist keine vollständige Kennzahl aller verbleibenden Risiken.','derivatives-12','derivative-uses','quantity','',[{label:'Restmenge',units:['derivative-uses']}]),
 G('Cross-Hedge','Absicherung mit einem verwandten, aber nicht identischen Referenzkontrakt. Eine historische Korrelation kann hilfreich sein; unterschiedliche Schwankungshöhen, lokale Preise, Terminlagen und Stressverhalten können trotzdem ein erhebliches Restexposure erzeugen.','derivatives-12','derivative-uses','cross-hedge','Cross Hedging|Cross-Hedging'),
 G('Varianzminimaler Hedge','Gegenposition, die in einem angegebenen Modell die Varianz einer gemeinsamen Wert- oder Preisänderung minimiert. Im linearen Einperiodenmodell mit freien Mengen hängt die passende Quote von Korrelation und dem Verhältnis der Preisänderungsvolatilitäten ab. Kosten und andere Risikoziele können eine andere Wahl begründen.','derivatives-12','derivative-uses','minimum-variance','Minimum-Variance Hedge|Minimum Variance Hedge'),
 G('Wirtschaftlicher Nettobedarf','Unter passenden Annahmen verbleibende Zahlung oder Exposition nach Gegenüberstellung eigener Grundgeschäftszuflüsse und -ausgaben. Diese wirtschaftliche Betrachtung ist von rechtlich wirksamem Close-out-Netting verschiedener Derivateansprüche zu unterscheiden.','derivatives-12','derivative-uses','net-exposure'),
 G('Mengenrisiko im Hedge','Gefahr, dass die tatsächliche Grundgeschäftsmenge von der bei Vertragsabschluss abgesicherten Menge abweicht. Bei geringerem oder entfallenem Bedarf kann eine frühere Absicherung zu einer ungebundenen Gegenposition werden.','derivatives-12','derivative-uses','forecast','Quantity Risk'),
 G('Cashsaldo','Vorzeichenbehaftete Summe der tatsächlich betrachteten Geldzahlungen: Eingang positiv, Ausgang negativ. Im Hedge-Rechner ist der Cashsaldo beim Käufer der Gegenbetrag seines positiv bezeichneten Nettoaufwands; beim Verkäufer entspricht er dem Nettoerlös.','derivatives-12','derivative-uses','calculator','Cash Balance'),
 G('Netto-Beschaffungsaufwand','Gesamter Aufwand aus tatsächlichem Einkauf abzüglich passendem Derivategewinn beziehungsweise zuzüglich Derivateverlust und ausdrücklich angesetzten Kosten. Er ist von der Bruttokassazahlung und einem Unternehmensgewinn nach Herstellung und anderen Kosten zu unterscheiden.','derivatives-12','derivative-uses','long-hedge','Nettoaufwand'),
 G('Hedge-Ergebnis','Isolierter Gewinn oder Verlust der betrachteten Gegenposition unter einer klaren Zeit- und Kostenkonvention. Seine Bedeutung ergibt sich erst zusammen mit der Veränderung des Grundgeschäfts und des vorher festgelegten Ziels. Ein positiver Hedgegewinn allein beweist keine gute Gesamtentscheidung.','derivatives-12','derivative-uses','exposure','Hedgesaldo'),
 G('Leverage','Verstärkung einer wirtschaftlichen Sensitivität relativ zur gewählten Kapital- oder Cashbasis, beispielsweise durch Fremdfinanzierung oder Derivate. Nominal, anfängliche Sicherheit, mögliche Verluste und tatsächliches Risikokapital sind verschiedene Bezugsgrößen. Eine kleine Anfangszahlung begrenzt keinen allgemeinen späteren Verlust.','derivatives-12','derivative-uses','leverage','Hebel|Verschuldungshebel'),
 G('Derivate-Overlay','Zusätzliche Derivateposition zur gezielten Veränderung eines bereits bestehenden oder geplanten Portfolioexposures. Referenz, Umfang und Mandat müssen passen; nach einer Änderung des Grundportfolios kann ein ursprünglich zweckmäßiger Overlay selbst ein unerwünschtes Zusatzrisiko erzeugen.','derivatives-12','derivative-uses','investor-market','',[{label:'Overlay',units:['derivative-uses']}]),
 G('Beta-Overlay','Indexderivateposition zur Veränderung der geschätzten Marktsensitivität eines Portfolios gegenüber einer bestimmten Referenz. Ein Short-Overlay kann ein positives Beta reduzieren, ohne es vollständig auf null zu setzen. Die Betabeziehung ist eine Modellannahme und muss überwacht werden.','derivatives-12','derivative-uses','investor-market','Index-Overlay'),
 G('Zielbeta','Explizit gewünschte Portfoliosensitivität gegenüber dem bezeichneten Referenzmarkt nach einer Anpassung. Ein noch positives Zielbeta trägt weiterhin einen Teil der Marktbewegung; Nominalgleichheit allein beweist keine passende Anpassung.','derivatives-12','derivative-uses','investor-market','Target Beta'),
 G('Cash Equitization','Vorübergehende Herstellung eines zum Mandat passenden Markt-, meist Indexexposures durch Derivate, während vorhandenes Cash noch nicht in den Kassakorb umgesetzt ist. Anfangs- und Nachschussanforderungen bleiben zu finanzieren. Die Strategie trägt das hergestellte Marktrisiko und garantiert keine positive Cashrendite.','derivatives-12','derivative-uses','investor-cash','Cash-Overlay'),
 G('Futures-Roll','Schließen oder Auslaufenlassen einer näheren Futuresposition und Aufbau einer passenden späteren Laufzeit, um das gewünschte Exposure fortzuführen. Preise, Basis, handelbare Größe und Kosten können sich dabei ändern. Es handelt sich nicht um eine automatische kostenfreie Verlängerung.','derivatives-12','derivative-uses','efficiency','Kontraktroll'),
 G('Physische CDS-Erfüllung','Abwicklung einer wirksam ausgelösten Kreditderivateleistung durch Lieferung einer nach Vertrag zulässigen Schuldverschreibung gegen den vereinbarten Nominalbetrag. Die abgelieferte Anleihe verbleibt nicht zusätzlich beim Sicherungskäufer; ihr aufgegebener Restwert ist vom Bruttocashzufluss zu unterscheiden.','derivatives-11','derivative-contracts','cds-case'),
 G('Total Return Swap','Swap über die vertraglich definierte Gesamtrendite eines Referenzvermögens gegen eine andere Zahlungsseite, häufig Finanzierung. Kursänderungen und vereinbarte Ausschüttungen werden einmalig erfasst; negative Gesamtrendite kann eine Zahlungspflicht erzeugen. Die Referenz kann Kredit-, Marktpreis- und Zinsrisiken enthalten; dies ist keine reine CDS-Ereignisleistung und kein automatischer Erwerb rechtlicher Eigentümerrechte.','derivatives-05','swaps','total-return','TRS|Total-Return-Swap'),
 G('Call-Option','Gekauftes Recht, den bezeichneten Basiswert nach den Ausübungsbedingungen zum Strike zu erwerben. Am Ende ist der Einheitenanspruch bei nicht negativer Aktie der positive Teil von Endkurs minus Strike. Der Käufergewinn zieht die gezahlte Prämie ab; der Verkäufer trägt die entgegengesetzte Pflicht.','derivatives-06','derivative-contracts','call','Call|Kaufoption'),
 G('Put-Option','Gekauftes Recht, den bezeichneten Basiswert nach den Ausübungsbedingungen zum Strike zu verkaufen. Am Ende ist der Einheitenanspruch der positive Teil von Strike minus Endkurs. Ein Long Put kann trotz positiver Auszahlung insgesamt verlieren, wenn die frühere Prämie höher war.','derivatives-06','derivative-contracts','put','Put|Verkaufsoption'),
 G('Optionsprämie','Preis für das Optionsrecht. Im hier verwendeten Modell bezahlt Long die Prämie zu Beginn und Short erhält sie. Sie ist keine rückzahlbare Margin; beim Käufergewinn wird sie vom Endanspruch abgezogen, beim Verkäufergewinn gegen seine Endpflicht gerechnet.','derivatives-06','derivative-contracts','options-rights','Optionsprämien|Option Premium'),
 G('Strike','Vertraglicher Ausübungspreis der Option je korrekt bestimmter Einheit. Er legt den Kauf- oder Verkaufspreis bei Ausübung fest. Die Gewinnschwelle nach Prämie liegt bei positivem Optionspreis im Allgemeinen an einem anderen Kurs.','derivatives-06','derivative-contracts','break-even','Ausübungspreis|Exercise Price|Strike Price'),
 G('Swap','Vertraglicher Austausch einer Folge nach bestimmten Regeln berechneter Leistungen. Der einfache gleichwährungsige Zinsswap tauscht feste gegen variable Zinsen auf ein Bezugsnominal, ohne dieses Nominal auszuzahlen. Andere Formen können beispielsweise Währungen, Kapitalbeträge oder Aktienrenditen tauschen.','derivatives-05','derivative-contracts','swap','Swaps'),
 G('Credit Default Swap','Kreditderivat mit Prämienpflicht des Sicherungskäufers und vertraglicher Schutzleistung bei einem definierten Kreditereignis der Referenz. Referenzschuldner und zur Zahlung verpflichteter Sicherungsverkäufer sind unterschiedliche Risikoadressen. Vereinfachte Verlustleistung: Nominal mal eins minus Recovery.','derivatives-11','derivative-contracts','cds','CDS|Credit Default Swaps'),
 G('Long Call','Gekaufte Kaufoption. Der positive Kaufvorteil am Ende gehört dem Käufer; im einfachen Gewinnvergleich wird die Anfangsprämie abgezogen. Sein Verlust ist ohne weitere Kosten auf diese Prämie begrenzt, sein Gewinn bei unbegrenzt möglichem Aktienkurs nach oben nicht.','derivatives-06','derivative-contracts','call'),
 G('Short Call','Verkaufte Kaufoption. Der Stillhalter erhält die Prämie und muss eine wirksame Ausübung erfüllen. Ohne Deckung oder zusätzliche Absicherung ist der Gewinn auf die Prämie begrenzt, der Verlust bei unbegrenzt möglichem Aktienkurs nach oben theoretisch unbegrenzt.','derivatives-06','derivative-contracts','short-risk'),
 G('Long Put','Gekaufte Verkaufsoption. Ihr Endanspruch wächst unterhalb des Strike bei fallendem Kurs. Ohne Kosten oder Finanzierung beträgt der schlechteste Gewinn minus Prämie; bei nicht negativer Aktie beträgt der höchste Gewinn Strike minus Prämie.','derivatives-06','derivative-contracts','put'),
 G('Short Put','Verkaufte Verkaufsoption mit möglicher Kaufpflicht zum Strike. Der Verkäufergewinn ist auf die Prämie begrenzt. Bei nicht negativer Aktie liegt sein schlechtester Gewinn im einfachen Modell bei Prämie minus Strike, erreicht bei Aktienkurs null.','derivatives-06','derivative-contracts','short-risk'),
 G('Stillhalter','Verkäufer eines Optionsrechts. Er erhält dessen Preis und trägt die zugehörige Pflicht bei wirksamer Ausübung beziehungsweise Zuteilung. Seine Position ist kein zweites frei wählbares Recht, die eigene ungünstige Endleistung abzulehnen.','derivatives-06','derivative-contracts','options-rights','Option Writer|Writer'),
 G('Assignment','Zuteilung einer aus einer wirksamen Optionsausübung folgenden Erfüllungspflicht an einen Verkäufer nach den jeweiligen Regeln. Nicht dasselbe wie Kauf der Option, Verkauf der Position oder Ausübung durch den Käufer.','derivatives-06','derivative-contracts','exercise','',[{label:'Zuteilung',units:['derivative-contracts']}]),
 G('Europäische Option','Option, deren vertragliches Ausübungsrecht auf den bezeichneten Endtermin beschränkt ist. Europäisch ist keine geografische Vorgabe. Eine mögliche vorherige Veräußerung der Position ist von der vorher nicht zugelassenen Ausübung zu trennen.','derivatives-06','derivative-contracts','exercise','European Option|European Exercise'),
 G('Amerikanische Option','Option, die während des festgelegten Zeitfensters bis zum Endtermin ausgeübt werden kann. Das zusätzliche Recht bedeutet keine Pflicht zur sofortigen Ausübung bei positivem inneren Wert; Restrecht, Zahlungszeitpunkt und weitere Bedingungen sind zu vergleichen.','derivatives-06','derivative-contracts','exercise','American Option|American Exercise'),
 G('Moneyness','Verhältnis von Basiswertkurs und Strike. Beim Call bedeutet Kurs über Strike im Geld und Kurs darunter aus dem Geld; beim Put ist die Richtung umgekehrt. Am Geld liegt der Kurs ungefähr am Strike. Die historische Prämie ist darin nicht enthalten: Positiver Ausübungswert garantiert keinen positiven Gesamtgewinn.','derivatives-06','derivative-contracts','moneyness'),
 G('Im-Geld-Zustand','Zustand mit positivem sofortigen Ausübungsvorteil: Beim Call liegt der Basiswertkurs über dem Strike, beim Put darunter. Ein entsprechender Käufergewinn nach Prämie kann trotzdem negativ sein.','derivatives-06','derivative-contracts','moneyness','In the Money|In-the-Money|ITM',[{label:'Im Geld',units:['derivative-contracts']}]),
 G('Am-Geld-Zustand','Zustand mit Basiswertkurs ungefähr am Strike, im idealen Vergleich exakt gleich. Am Endtermin ist dann der einfache Call-/Put-Ausübungswert null. Vor Ablauf kann trotzdem ein positiver Marktwert des verbleibenden Rechts bestehen.','derivatives-06','derivative-contracts','moneyness','At the Money|At-the-Money|ATM',[{label:'Am Geld',units:['derivative-contracts']}]),
 G('Aus-dem-Geld-Zustand','Zustand ohne positiven sofortigen Ausübungsvorteil: Beim Call liegt der Kurs unter dem Strike, beim Put darüber. Vor Ablauf bedeutet dies nicht zwingend Marktwert null; günstige spätere Zustände können noch möglich sein.','derivatives-06','derivative-contracts','moneyness','Out of the Money|Out-of-the-Money|OTM',[{label:'Aus dem Geld',units:['derivative-contracts']}]),
 G('Optionsauszahlung','Wirtschaftlicher Endanspruch des bezeichneten Optionsrechts vor Einbezug seiner historischen Prämie. Long Call erhält den positiven Kaufvorteil, Long Put den positiven Verkaufsvorteil. Die Short-Seite besitzt den negativen Gegenbetrag. Ein physischer Bruttokaufpreis ist eine andere Größe.','derivatives-06','derivative-contracts','four-positions','Expiration Payoff',[{label:'Endauszahlung',units:['derivative-contracts']}]),
 G('Ausübungswert','Wirtschaftlicher Vorteil aus der sofortigen Nutzung des Kauf- oder Verkaufsrechts unter den bezeichneten Bedingungen. Beim einfachen Long-Recht wird ein ungünstiger Unterschied auf null begrenzt. Vor Ablauf ist dieser Betrag nicht allgemein der vollständige Marktpreis der Option.','derivatives-06','derivative-contracts','exercise','Exercise Value'),
 G('Optionsgewinn','Ergebnis der bezeichneten Optionsposition nach Einbezug ihres Anfangspreises. Die einfache Endrechnung zieht beim Käufer die Prämie vom Endanspruch ab; beim Verkäufer wird der Endverpflichtung die erhaltene Prämie gegenübergestellt. Finanzierung und Kosten benötigen zusätzliche Annahmen.','derivatives-06','derivative-contracts','four-positions','Option Profit'),
 G('Options-Gewinnschwelle','Aktienendkurs mit Gewinn null nach der ausdrücklich bezeichneten Kostenkonvention. Bei positiver Prämie und ohne Finanzierung: Call-Strike plus Prämie beziehungsweise Put-Strike minus Prämie. Die rechnerische Put-Schwelle muss in der angenommenen Kursdomäne liegen.','derivatives-06','derivative-contracts','break-even','',[{label:'Gewinnschwelle',units:['derivative-contracts']},{label:'Break-even',units:['derivative-contracts']},{label:'Break-even-Kurs',units:['derivative-contracts']}]),
 G('Netto-Anfangskosten','Bezahlte Anfangsausgaben abzüglich empfangener Anfangsbeträge der gemeinsam betrachteten Position. Im Optionsrechner sind positive Kosten bezahlt, negative erhalten. Das Vorzeichen ist damit entgegengesetzt zur Anfangszahlung, die einen tatsächlichen Eingang positiv zählt.','derivatives-06','derivative-contracts','calculator','Anfangskosten'),
 G('Finanzierter Optionsgewinn','Auf einen gemeinsamen Endtermin bezogene Differenz zwischen Optionsendanspruch und entsprechend aufgezinstem Anfangspreis. Die Zahl hängt von Laufzeit, Zinskonvention und tatsächlichen Finanzierungsbedingungen ab. Der einfache Optionsrechner verwendet diese Erweiterung ausdrücklich nicht.','derivatives-06','derivative-contracts','financing'),
 G('Prämienrendite','Gewinn einer gekauften Option relativ zu ihrer bezahlten Anfangsprämie unter einer klar genannten Zeit- und Kostenkonvention. Ein auf die Prämie begrenzter Geldverlust kann hundert Prozent dieser Anlage ausmachen. Für Verkäufer ersetzt die vereinnahmte Prämie keine Definition der gesamten Kapitalbindung.','derivatives-06','derivative-contracts','short-risk'),
 G('Protective Put','Eine gehaltene Aktie plus ein passender gekaufter Put. Bei gemeinsamer Menge, Referenz und Endfälligkeit liefert der Put einen Endwertfloor beim Strike und erhält die Aktienoberseite. Der Gesamtgewinn berücksichtigt Aktienerwerbspreis und zusätzliche Put-Prämie.','derivatives-10','derivative-contracts','protective-put','Married Put'),
 G('Covered Call','Eine gehaltene Aktie plus ein Call, der auf diese Aktie verkauft wurde. Die Aktie deckt die mögliche Lieferpflicht, die Prämie puffert einen kleinen Teil des Kursverlusts, und der Call begrenzt die weitere Oberseite. Covered bedeutet keine Absicherung gegen den Aktienkursverfall.','derivatives-10','derivative-contracts','covered-call','Buy-Write'),
 G('Festzinszahler','Seite des einfachen Zinsswaps, die die feste Zinsleistung bezahlt und die vereinbarte variable Seite erhält. Ein höherer bekannter variabler Satz verbessert den einzelnen Nettozahlungssaldo; der Marktwert der gesamten Restlaufzeit verlangt eine gesonderte Bewertung.','derivatives-05','derivative-contracts','swap','Fixed-Rate Payer|Pay Fixed'),
 G('Festzinsempfänger','Seite des einfachen Zinsswaps, die feste Zinsen erhält und die vereinbarte variable Seite bezahlt. Bei identischen Bedingungen ist ihr einzelner Nettozahlungssaldo der Gegenbetrag des Festzinszahlers.','derivatives-05','derivative-contracts','swap','Fixed-Rate Receiver|Receive Fixed'),
 G('Swaprate','Im einfachen Fixed-for-Floating-Swap vereinbarte feste Rate für die Zahlungsreihe. Sie ist vom aktuellen Marktwert des alten Swaps und von einzelnen fairen Forwardraten verschiedener Perioden zu unterscheiden.','derivatives-05','derivative-contracts','swap','Swapsatz|Swap Rate'),
 G('Swap-Leg','Eine der nach Vertragsregel bestimmten Zahlungsseiten eines Swaps. Bei passender gleichwährungsiger Zinsperiode können feste und variable Bruttobeträge zum vorgesehenen Nettozahlungssaldo verrechnet werden; die Zinsdefinition bleibt gesondert festzuhalten.','derivatives-05','derivative-contracts','swap','Swap Leg'),
 G('Sicherungskäufer','Käufer der im Kreditderivat vereinbarten Schutzleistung. Er schuldet die vereinbarten Prämien und erhält bei wirksamer Ereignisauslösung den definierten Anspruch. Ein vorhandener Anspruch garantiert ohne weitere Annahmen keine vollständige Leistung einer ausfallenden Gegenpartei.','derivatives-11','derivative-contracts','cds','Protection Buyer'),
 G('Sicherungsverkäufer','Partei, die im Kreditderivat die vereinbarte Schutzleistung schuldet und die Prämien erhält. Sie ist vom Referenzschuldner zu unterscheiden; deren Zahlungsfähigkeit kann gerade im selben Stresszustand problematisch werden.','derivatives-11','derivative-contracts','cds','Protection Seller|Sicherungsgeber'),
 G('Referenzschuldner','Kreditadresse, auf deren definiertes Kreditereignis sich ein Kreditderivat bezieht. Nicht automatisch identisch mit dem Sicherungsverkäufer, einer CCP oder der Gegenpartei des CDS-Käufers.','derivatives-11','derivative-contracts','cds','Reference Entity'),
 G('Kreditereignis','Nach dem jeweiligen Kreditderivatevertrag definierter Zustand, der bei wirksamer Feststellung eine bestimmte Schutzleistung auslösen kann. Ein beliebiger Kursrückgang oder ein Ratingwechsel ist nicht ohne die entsprechende Vereinbarung automatisch ein solches Ereignis.','derivatives-11','derivative-contracts','cds','Credit Event|Referenzausfall'),
 G('Upfrontzahlung','Zu Beginn eines Vertrags geleisteter Betrag, beispielsweise zusätzlich zu einem standardisierten laufenden CDS-Coupon. Er ist von späteren periodischen Prämien und von Sicherheitsleistungen zu unterscheiden. Die einfachen CDS-Rechenfälle dieses Kapitels setzen ausdrücklich keinen Upfront voraus.','derivatives-11','derivative-contracts','cds','Upfront|Upfront Payment'),
 G('Fixing','Nach dem vertraglich festgelegten Verfahren bestimmter Referenzwert zu einem definierten Zeitpunkt oder Beobachtungsfenster. Der für eine Abrechnung maßgebliche Wert muss nicht dem gerade auf einem anderen Bildschirm sichtbaren Kassakurs entsprechen.','derivatives-01','derivative-markets','cash-settlement'),
 G('Intraday','Innerhalb eines Handelstags. Eine untertägige Margin- oder Zahlungsanforderung kann vor der regulären Tagesendabrechnung fällig werden; die eigene Tagestabelle bildet solche zusätzlichen Termine nicht ab.','derivatives-01','derivative-markets','margins'),
 G('Funding','Bereitstellung tatsächlich verfügbarer Finanzierungsmittel zu den benötigten Zeitpunkten, etwa aus eigenen Mitteln oder vertraglich zugänglichen externen Quellen. Erwarteter künftiger Gewinn ist keine heutige Kasse; Finanzierung kann Kosten und Bedingungen besitzen.','derivatives-01','derivative-markets','liquidity'),
 G('Derivate-Gegenparteiausfall','Nach den einschlägigen Vertrags- und Rechtsregeln zu behandelnde Nichterfüllung beziehungsweise ein definiertes Ausfallereignis einer verpflichteten Derivatepartei. Aktueller Marktwert, Verwertung von Sicherheiten und endgültiger Verlust sind getrennt zu bestimmen.','derivatives-01','derivative-markets','risks','',[{label:'Default',units:['derivative-markets']}]),
 G('Derivat','Vertrag, dessen Wert von vereinbarten Referenzgrößen und eigenen Zahlungs- oder Ausübungsregeln abhängt. Preisexposure bedeutet nicht automatisch Eigentum am Basiswert; Nullstartwert bedeutet weder null Menge noch fehlende Zukunftspflichten.','derivatives-01','derivative-markets','definition','Derivative'),
 G('Basiswert','Vermögenswert, Satz, Index, Kurs oder andere vertraglich bestimmte Referenz eines Derivats. Qualität, Notierung, Beobachtungszeit und Zahlungsregel müssen zum beabsichtigten Exposure passen.','derivatives-01','derivative-markets','underlyings','Underlying'),
 G('Forward-Vertrag','Beiderseitig verpflichtender Vertrag über eine spätere Leistung nach heute vereinbarten Bedingungen. Beim einfachen Kauf-Forward bindet sich Long an Menge und Lieferpreis; der feste Preis ist vom aktuellen Vertragsmarktwert zu trennen.','derivatives-01','derivative-markets','long-short','',[{label:'Forward',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Forward Contract',units:['derivative-markets','derivative-contracts','derivative-uses']}]),
 G('Futureskontrakt','Standardisierter Terminkontrakt nach dem jeweiligen Börsen- und Clearingregelwerk mit laufender Abrechnung von Wertänderungen. Menge, Referenz und Termine können vom individuellen Bedarf abweichen; Margin ist kein voller Basiswertkaufpreis.','derivatives-01','derivative-markets','exchange','Futures Contract',[{label:'Future',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Futures',units:['derivative-markets','derivative-contracts','derivative-uses']}]),
 G('Derivate-Long-Position','Käuferseite des bezeichneten Vertrags oder gekauften Rechts. Beim Kauf-Forward profitiert sie im einfachen Endfall vom höheren Basiswertpreis; ein Long Put besitzt dagegen ein Verkaufsrecht. Long ist deshalb keine universelle Aussage über dieselbe Preisrichtung aller Instrumente.','derivatives-01','derivative-markets','long-short','',[{label:'Long',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Long-Position',units:['derivative-markets','derivative-contracts','derivative-uses']}]),
 G('Derivate-Short-Position','Verkäuferseite des bezeichneten Vertrags oder geschriebenen Rechts. Ihre Pflichten folgen dem Instrument; beim einfachen erfüllten Forward besitzt sie den Gegenbetrag zur Long-Seite. Sie kann nicht allein wegen eines ungünstigen Markts folgenlos auf Erfüllung verzichten.','derivatives-01','derivative-markets','long-short','',[{label:'Short',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Short-Position',units:['derivative-markets','derivative-contracts','derivative-uses']}]),
 G('Forward Commitment','Beiderseitige zukünftige Verpflichtung nach den vereinbarten Vertragsregeln. Der Begriff beschreibt die Bindung, nicht eine sichere künftige Kursprognose und nicht den heute für den Vertrag gezahlten Wert.','derivatives-01','derivative-markets','rights','Forward Commitments'),
 G('Contingent Claim','Vertraglicher Anspruch mit vereinbarter Bedingung oder Ausübungsregel, beispielsweise das gekaufte Recht einer Option. Ein nicht ausgeübtes Recht kann trotzdem durch Prämie und Kosten ein negatives Gesamtergebnis hinterlassen.','derivatives-01','derivative-markets','rights','Bedingter Anspruch'),
 G('Forward-Lieferpreis','Im bestehenden Forward fest vereinbarter Preis je Einheit für den Endtermin. Dieser Preis bleibt vom aktuellen Neugeschäftspreis und vom heutigen Marktwert des alten Vertrags getrennt.','derivatives-01','derivative-markets','price-value','',[{label:'Lieferpreis',units:['derivative-markets']}]),
 G('Derivatemarktwert','Heutige Bewertung der noch offenen vertraglichen Ansprüche und Pflichten unter den bezeichneten Markt- und Bewertungsbedingungen. Er kann vorzeichenbehaftet sein und ist weder Nominalbetrag noch bereits eingegangener Cash.','derivatives-01','derivative-markets','price-value','',[{label:'Mark-to-market',units:['derivative-markets']},{label:'Vertragsmarktwert',units:['derivative-markets']}]),
 G('Derivate-Nominalbetrag','Vertragliche Bezugsgröße zur Skalierung von Zahlungen oder Preisexposure. Im eigenen Kauf-Forward ist sie Menge mal fester Lieferpreis. Bei anderen Instrumenten kann Kapital tatsächlich getauscht werden oder nur Berechnungsbasis sein; das Nominal ist kein allgemeiner aktueller Verlustbetrag.','derivatives-01','derivative-markets','notional','',[{label:'Nominalbetrag',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Notional',units:['derivative-markets','derivative-contracts','derivative-uses']},{label:'Notional Amount',units:['derivative-markets','derivative-contracts','derivative-uses']}]),
 G('Aktuelle Wiederbeschaffungsexposition','Im einfachen unbesicherten Einzelvertragsfall der positive Teil des heutigen Vertragsmarktwerts aus der betrachteten Sicht. Netting, Sicherheiten und Kosten können den Zugriff verändern; die Größe ist weder Expected Loss noch eine sichere Obergrenze künftiger Exposition.','derivatives-01','derivative-markets','notional','Current Exposure'),
 G('Mögliche künftige Exposition','Nach einer ausdrücklich angegebenen Szenario- oder Verteilungsmethode geschätzter späterer positiver Wiederbeschaffungsbedarf. Marktänderungen während einer Schließung können ihn gegenüber dem heutigen Wert erhöhen. Modellhorizont und Sicherheitsniveau sind keine Garantie gegen jeden Zustand.','derivatives-01','derivative-markets','gap','Potential Future Exposure|PFE'),
 G('Over the Counter','Handelsvereinbarung außerhalb einer organisierten Börse. OTC-Geschäfte können elektronische Anfragen und standardisierte Dokumentation nutzen und können je nach Produkt und Regeln bilateral verbleiben oder zentral gecleart werden.','derivatives-01','derivative-markets','otc','OTC'),
 G('Exchange-Traded Derivative','Derivatekontrakt nach organisierten Börsenregeln mit vorgegebenen gemeinsamen Spezifikationen. Standardisierung erleichtert Vergleichbarkeit, garantiert aber weder einen exakten individuellen Hedge noch jederzeitige Liquidität.','derivatives-01','derivative-markets','exchange','ETD|Exchange-Traded Derivatives'),
 G('Clearing','Ermittlung und Organisation der gegenseitigen Verpflichtungen aus Geschäften nach den jeweiligen Regeln. Zentrales Clearing mit einer CCP ist eine besondere Ausgestaltung; Handelsplatz, Kontoführung und tatsächliche Enderfüllung sind getrennte Funktionen.','derivatives-01','derivative-markets','clearing-axis'),
 G('Central Counterparty','Zentrale Gegenpartei, die übernommene Verpflichtungen zwischen direkten Teilnehmern nach ihrem Regelwerk organisiert. Sicherheiten und Ausfallverfahren mindern bestimmte bilaterale Risiken; sie beseitigen nicht jedes Markt-, Liquiditäts- oder Infrastrukturrisiko.','derivatives-01','derivative-markets','ccp','CCP|Zentrale Gegenpartei'),
 G('Novation','Rechtlicher Mechanismus, durch den bestehende Verpflichtungen nach den Voraussetzungen durch neue Vertragsbeziehungen ersetzt werden können, etwa im Clearing. Ein wirtschaftlich gegenläufiges Geschäft mit einer dritten Partei bewirkt das nicht automatisch.','derivatives-01','derivative-markets','clearing-axis'),
 G('Clearingmitglied','Teilnehmer mit direkter Mitgliedsbeziehung zur jeweiligen Clearingstruktur. Kunden können über ein Mitglied Zugang erhalten, besitzen aber zusätzlich ihre eigenen Kunden- und Vermittlerverhältnisse. Mitgliedspflichten sind nicht automatisch mit Kundenrechten identisch.','derivatives-01','derivative-markets','participants','Clearing Member'),
 G('Client Clearing','Zugang eines Kunden zu einer Clearingstruktur über die nach den Bedingungen beteiligten Vermittler und Mitglieder. Kontentrennung, Marginweiterleitung und mögliche Positionsübertragung müssen entlang der tatsächlichen Vertragskette geprüft werden.','derivatives-01','derivative-markets','participants','Kundenclearing'),
 G('Derivate-Margin','Sicherheiten- oder laufende Ausgleichsanforderungen nach dem betrachteten Derivatevertrag und Marktsystem. Bezugsgröße, Termin und Rechtswirkung müssen benannt werden; Margin ist kein allgemeines Synonym für den vollen Kaufpreis oder den maximalen Verlust.','derivatives-01','derivative-markets','margins','',[{label:'Margin',units:['derivative-markets']},{label:'Margins',units:['derivative-markets']}]),
 G('Derivate-Initial-Margin','Nach der jeweiligen Risikomethode gestellter Puffer für mögliche zusätzliche Veränderungen während der Abwicklung eines Ausfalls. Er ist endlich und keine Verlustgarantie. Die hier gemeinte Geld- oder Sicherheitenanforderung unterscheidet sich vom Repo-Sicherheiten-zu-Cash-Verhältnis gleichen Namens.','derivatives-01','derivative-markets','margins','',[{label:'Initial Margin',units:['derivative-markets','derivative-uses']}]),
 G('Derivate-Variation-Margin','Auf aktuelle Bewertungsänderungen reagierende Anforderung beziehungsweise Zahlung nach dem jeweiligen System. Sie kann je nach Regelwerk Sicherheiten stellen oder laufende Gewinne und Verluste ausgleichen. Ein heutiger Transfer verhindert keine spätere Marktbewegung.','derivatives-01','derivative-markets','margins','',[{label:'Variation Margin',units:['derivative-markets','derivative-uses']}]),
 G('Maintenance Margin','Im eigenen Futureskontofall die untere Kontoschwelle, deren Unterschreitung eine Auffüllung auf den angegebenen Initialbetrag verlangt. Schwelle, Auffüllziel und Zeitpunkte sind Fall- oder Vertragsbedingungen und keine überall gleichen Werte.','derivatives-01','derivative-markets','margins'),
 G('Derivate-Nachschuss','Zusätzlich fällige Sicherheits- oder Ausgleichsleistung nach den geltenden Bedingungen. Ein später positives Gesamtgeschäft finanziert eine heute fällige Zahlung nicht rückwirkend. Marktverlust und Nachschussbetrag können wegen Kontoschwellen verschieden sein.','derivatives-01','derivative-markets','daily-ledger','',[{label:'Margin Call',units:['derivative-markets']},{label:'Nachschuss',units:['derivative-markets']}]),
 G('Netting','Zusammenfassung gegenseitiger Verpflichtungen innerhalb der tatsächlich zulässigen rechtlichen und vertraglichen Grenzen. Payment Netting betrifft bezeichnete Zahlungen; Close-out Netting einen nach einem Ereignis bestimmten Restanspruch. Andere Gegenparteien können nicht beliebig miteinander verrechnet werden.','derivatives-01','derivative-markets','netting'),
 G('Close-out Netting','Nach einem festgelegten Ereignis vorgesehene Beendigung beziehungsweise Bewertung erfasster gegenseitiger Geschäfte und Zusammenfassung zu einem Nettoanspruch. Umfang, Methode und Durchsetzbarkeit sind konkret zu prüfen; gegenläufige Marktwerte allein reichen nicht.','derivatives-01','derivative-markets','netting'),
 G('Payment Netting','Verrechnung bestimmter fälliger Zahlungen nach den vereinbarten Regeln. Sie ist von einer Beendigung und Bewertung aller erfassten Verträge beim Close-out zu unterscheiden.','derivatives-01','derivative-markets','netting','Zahlungsnetting'),
 G('Netting Set','Menge von Geschäften, deren Verpflichtungen unter den betrachteten Bedingungen wirksam gemeinsam verrechnet werden dürfen. Gegenpartei, Dokumente, Produkte und Rechtsrahmen begrenzen den Satz; ein bloß gemeinsamer Bildschirm oder Händlername genügt nicht.','derivatives-01','derivative-markets','netting','Netting Sets|Netting-Satz'),
 G('Cash Settlement','Vertraglich bestimmter Barausgleich statt Lieferung des Basiswerts. Ein Differenzbetrag kann denselben idealisierten Endwert wie Lieferung erzeugen, besitzt aber andere Brutto- und Liquiditätsanforderungen. Fixing und Termin folgen dem Vertrag.','derivatives-01','derivative-markets','cash-settlement','Barausgleich'),
 G('Physische Erfüllung','Erfüllung durch Lieferung der vereinbarten Vermögenswerte gegen die jeweilige Gegenleistung. Beim eigenen Aktienforward werden Aktienansprüche und Bruttokaufpreis getrennt übertragen; der Marktwert der Aktien ist kein zusätzlicher Cashgewinn.','derivatives-01','derivative-markets','delivery','Physical Settlement'),
 G('Derivate-Settlement','Vertragliche Erfüllung der bestimmten Derivatepflichten durch die vorgesehenen Geld- oder Vermögensübertragungen. Handelsabschluss, Bewertung, Bestimmung des Betrags und tatsächlicher Zahlungstag können auseinanderfallen.','derivatives-01','derivative-markets','lifecycle','',[{label:'Settlement',units:['derivative-markets','derivative-contracts']}]),
 G('Kontraktgröße','Nach dem jeweiligen Vertrag festgelegte Menge oder Multiplikator je gehandeltem Kontrakt. Ganzzahlige Standardkontrakte können einen individuellen Bedarf unter- oder überdecken; eine passende Menge beseitigt nicht automatisch Basis-, Termin- oder Kreditrisiken.','derivatives-01','derivative-markets','market-choice','Contract Size|Kontraktmultiplikator|Contract Multiplier'),
 G('Derivate-Haircut','Im angegebenen Sicherheitenvergleich vereinbarter Abschlag vom Sicherheitenmarktwert zur verwendbaren Anrechnung. Er ist von Verlustquote, Vertragsgewinn und einer sicher garantierten späteren Verwertung zu unterscheiden.','derivatives-01','derivative-markets','collateral','',[{label:'Haircut',units:['derivative-markets']}]),
 G('Segregation','Trennung von Positionen, Konten oder Sicherheiten nach den einschlägigen Regeln. Sie kann den Zugriff und mögliche Übertragungen beeinflussen; eine pauschale vollständige Insolvenz- oder Verlustfreiheit folgt aus dem Wort nicht.','derivatives-01','derivative-markets','collateral','Kontentrennung'),
 G('Close-out-Periode','Zeitspanne für die nach einem Ereignis notwendige Beendigung, Absicherung oder Ersetzung offener Positionen nach der verwendeten Definition. Markt- und Sicherheitenwerte können sich währenddessen ändern; heutige Vollbesicherung deckt das nicht automatisch.','derivatives-01','derivative-markets','gap','Close-out Period'),
 G('Default Fund','Nach den jeweiligen Regeln zur Bewältigung von Teilnehmerausfällen vorgesehene zusätzliche Ressource einer Clearingstruktur. Eigentum, Reihenfolge, Verfügbarkeit und weitere Beitragspflichten sind konkret zu lesen; der eigene Lehr-Wasserfall ist keine allgemeine Marktregel.','derivatives-01','derivative-markets','ccp-resources','Ausfallfonds'),
 G('Hypothek','Im Lernkontext eine auf Immobilien bezogene Kreditsicherung beziehungsweise die damit verbundene Finanzierung. Der konkrete Rechtsbegriff und seine Durchsetzung hängen von Recht und Vertrag ab. Kreditforderung, Objektwert und Verwertungserlös sind keine identischen Größen.','bonds-14','mbs','loan','Mortgage|Wohnhypothek'),
 G('Debt-to-Income','Verhältnis der nach der verwendeten Definition einbezogenen periodischen Schuldzahlungen zum auf derselben Periodenbasis abgegrenzten Einkommen. Im eigenen Wohnkreditfall werden Monatsverpflichtungen und monatliches Bruttoeinkommen verglichen; keine allgemeine Kreditgrenze ist damit vorgegeben.','bonds-14','mbs','ltv','DTI|Einkommensbelastungsquote'),
 G('Servicing Advance','Nach den jeweiligen Regeln vorfinanzierter Betrag eines Kreditverwalters, der eine Lücke zwischen Einzug und Anlegerzahlung überbrücken kann. Verfügbarkeit, Erstattungsrang und Grenzen sind konkret zu prüfen; eine Vorfinanzierung ist keine automatische unbegrenzte Kreditverlustgarantie.','bonds-14','mbs','pass-through','Servicing Advances'),
 G('Prepayment Premium','Vertraglich bestimmter Zusatzbetrag bei bestimmter zulässiger vorzeitiger Rückzahlung. Er kann als Rückzahlungsbeschränkung oder Ausgleich wirken; Betrag, Zeitfenster, Ausnahmen und Rechtsrahmen sind einzeln zu lesen.','bonds-14','mbs','call-protection','Prepayment Penalty|Vorfälligkeitsentgelt'),
 G('ARM-Zinscap','Vertragliche obere Grenze der Zinsanpassung oder des gesamten Zinsniveaus einer Adjustable-Rate Mortgage. Periodischer Cap und Laufzeitgrenze können gleichzeitig wirken; der anwendbare Gesamtbereich muss vor Einsetzen von Index und Marge bestimmt werden.','bonds-14','mbs','arm','',[{label:'Cap',units:['mbs']},{label:'Caps',units:['mbs']}]),
 G('ARM-Zinsfloor','Vertraglicher Mindestzins oder eine untere Anpassungsgrenze einer Adjustable-Rate Mortgage. Welche Grenze beim Reset tatsächlich wirkt, folgt aus allen einschlägigen periodischen und laufzeitweiten Bedingungen.','bonds-14','mbs','arm','',[{label:'Floor',units:['mbs']},{label:'Floors',units:['mbs']}]),
 G('Mortgage-Backed Security','Wertpapier, dessen Zahlungen an Hypothekenkredite oder darauf bezogene Ansprüche und die vereinbarte Verteilung anknüpfen. Kreditmerkmale, Poolverhalten, Gebühren, Garantie und Struktur bestimmen gemeinsam Cashflows und Risiken.','bonds-14','mbs','map','MBS|Mortgage-Backed Securities|Hypothekenwertpapier'),
 G('Residential Mortgage-Backed Security','MBS mit wohnhypothekarischen Forderungen beziehungsweise darauf bezogenen Ansprüchen. Pass-through und CMO können unterschiedliche Zeitprofile erzeugen; Agency-Garantie und private Kredittranchierung sind konkret zu prüfen.','bonds-14','mbs','segments','RMBS|Residential Mortgage-Backed Securities'),
 G('Commercial Mortgage-Backed Security','MBS mit gewerblichen Immobilienkrediten. Operativer Objektcashflow, Konzentration, Sicherheitenwert, Rückzahlungsbeschränkungen und mögliche Ballonrefinanzierung sind wichtige Analysegrößen.','bonds-14','mbs','commercial','CMBS|Commercial Mortgage-Backed Securities'),
 G('Mortgage Pass-through','Wertpapier mit anteiliger Weiterleitung der vertraglich zugeordneten Hypothekenpoolzahlungen. Anlegercash umfasst typischerweise Nettozins nach definierten Entgelten sowie planmäßige und zusätzliche Kapitalrückzahlungen; Versatz und Garantien sind separat zu lesen.','bonds-14','mbs','pass-through','Pass-through|Mortgage Pass-through Securities'),
 G('Collateralized Mortgage Obligation','Struktur, die Hypotheken- oder MBS-Cashflows nach festgelegten Regeln auf mehrere Klassen verteilt. Zeitpriorität ist von Kreditverlustpriorität zu unterscheiden; die Struktur erzeugt keinen zusätzlichen Poolcash.','bonds-14','mbs','cmo','CMO|Collateralized Mortgage Obligations'),
 G('Prepayment','Kapitalrückzahlung vor dem ursprünglichen planmäßigen Termin. Sie verändert die verbleibende Zinsbasis und tatsächliche Kapitaldauer; Refinanzierung ist ein möglicher, aber nicht der einzige Anlass.','bonds-14','mbs','prepayment','Vorzeitige Tilgung'),
 G('Contraction Risk','Risiko schnellerer Kapitalrückgabe als erwartet, beispielsweise bei verstärkter Refinanzierung nach fallenden Zinsen. Attraktive alte Zinsen können früher enden und Wiederanlage zu schlechteren Bedingungen nötig werden.','bonds-14','mbs','prepayment','Contraction|Verkürzungsrisiko'),
 G('Extension Risk','Risiko langsamerer Kapitalrückgabe als erwartet, etwa wenn höhere Marktzinsen vorzeitige Refinanzierung unattraktiver machen. Kapital bleibt dann länger gebunden und steht später für neue Anlage bereit.','bonds-14','mbs','prepayment','Extension|Verlängerungsrisiko'),
 G('Conditional Prepayment Rate','Annualisierte zusätzliche Rückzahlungsquote relativ zum jeweils noch bestehenden Kapital. Aus einer konstanten monatlichen SMM entsteht sie über zwölf multiplizierte Überlebensfaktoren, nicht durch bloße Monatsaddition.','bonds-14','mbs','cpr-smm','CPR|Constant Prepayment Rate'),
 G('Single Monthly Mortality','Monatliche zusätzliche Rückzahlungsquote des nach planmäßiger Tilgung verbleibenden Kapitals. Trotz der Bezeichnung ist hier keine Personensterblichkeit gemeint. Zeitbasis und Kapitalbasis sind für die Umrechnung zur CPR wesentlich.','bonds-14','mbs','cpr-smm','SMM'),
 G('PSA-Skala','Konventionelle altersabhängige Prepayment-Vergleichsskala. Bei 100 PSA steigt annualisierte CPR von 0,2 Prozent im ersten Kreditmonat um 0,2 Prozentpunkte je Monat auf sechs Prozent ab Monat dreißig. Andere PSA-Niveaus skalieren diese Kurve; sie sind keine sicheren Prognosen.','bonds-14','mbs','psa','PSA|PSA-Standard'),
 G('Seasoning','Reifung eines Kreditpools mit dem Alter seit Entstehung der Kredite. Ein neu ausgegebenes Wertpapier kann bereits ältere Kredite enthalten; Wertpapieremission setzt deren Alter nicht auf null.','bonds-14','mbs','drivers','Kreditreifung'),
 G('Burnout','Veränderung der Reaktion des verbleibenden Pools, weil besonders refinanzierungsbereite oder fähige Schuldner schon ausgeschieden sein können. Ein erneut gleicher Zinsanreiz muss deshalb nicht dieselbe CPR wie früher erzeugen.','bonds-14','mbs','drivers'),
 G('Adjustable-Rate Mortgage','Hypothekenkredit mit nach Vertrag anpassbarem Zins, etwa Index plus Marge mit periodischen oder laufzeitweiten Grenzen. Zins-, Raten- und Kapitaländerungen müssen anhand der tatsächlichen Regeln getrennt gelesen werden.','bonds-14','mbs','arm','ARM'),
 G('Negative Amortisation','Zunahme der Schuld, wenn eine Zahlung den aufgelaufenen Zins nicht deckt und der unbezahlte Anteil dem Kapital zugeschlagen wird. Das gilt nur bei entsprechender Vereinbarung und ist keine reguläre Kapitaltilgung.','bonds-14','mbs','arm','Negative Amortization'),
 G('Interest-only-Kredit','Kreditform, bei der während des bezeichneten Zeitraums nur Zins und keine reguläre Kapitaltilgung bezahlt wird. Das verbleibende Kapital wird später fällig; ein IO-Wertpapierstrip ist ein anderer Begriff.','bonds-14','mbs','balloon','Interest-only'),
 G('Hypotheken-Ballon','Größerer verbleibender Kapitalbetrag, der am vertraglichen Endtermin zusätzlich fällig wird, beispielsweise nach einer Interest-only-Phase oder bei längerer rechnerischer Amortisationsbasis. Laufende Zinsdeckung finanziert ihn nicht automatisch.','bonds-14','mbs','balloon','Ballonfälligkeit',[{label:'Ballon',units:['mbs']},{label:'Balloon Payment',units:['mbs']}]),
 G('Weighted-Average Coupon','Mit aktuellen Kapitalbeträgen gewichteter durchschnittlicher Vertragskupon eines Pools nach einheitlicher Zinskonvention. Der Wert bestimmt weder allein Nettoanlegerzins noch einen vollständigen Zahlungsplan.','bonds-14','mbs','pool-weights','WAC|Weighted Average Coupon'),
 G('Weighted-Average Maturity','Kapitalgewichteter Durchschnitt der vertraglichen Restlaufzeiten der Poolkredite nach der angegebenen Berichtskonvention. Kein Synonym für tatsächliche Kapital-WAL oder Duration.','bonds-14','mbs','pool-weights','WAM|Weighted Average Maturity'),
 G('Hypotheken-WAL','Mit tatsächlichen Kapitalrückzahlungen gewichtete Zeit im betrachteten Hypothekenszenario. Das eigene verlustfreie Modell teilt die zeitgewichtete Kapitalzahlung durch vollständig zurückgezahltes Anfangskapital; Kupons und Diskontgewichte gehören nicht in diese Größe.','bonds-14','mbs','wal','',[{label:'WAL',units:['mbs']}]),
 G('Servicing Fee','Entgelt für die vereinbarten Kreditverwaltungsleistungen. Im eigenen Modell wird es monatlich auf Anfangskapital berechnet und vom Bruttozins abgezogen; reale Gebühren- und Vorfinanzierungsregeln können anders sein.','bonds-14','mbs','pass-through','Servicing-Entgelt'),
 G('Agency MBS','MBS mit der jeweiligen institutionellen Agency- oder unternehmensbezogenen Absicherung. Garant und Umfang müssen konkret gelesen werden; nicht jede solche Garantie ist eine unmittelbare US-Staatsgarantie. Marktpreis und Prepayment sind eigenständige Risiken.','bonds-14','mbs','guarantees','Agency'),
 G('Non-agency MBS','Hypothekenwertpapier ohne die im jeweiligen Vergleich gemeinte Agency-Garantie. Private Kreditverbesserung kann Ansprüche schützen, muss aber nach Betrag, Rang, Gegenpartei und Bedingungen geprüft werden.','bonds-14','mbs','guarantees','Non-agency'),
 G('Zeittranchierung','Verteilung vorhandener Kapitalrückflüsse auf Klassen mit unterschiedlichen zeitlichen Regeln. Sie verändert Rückzahlungsprofile und verteilt Prepayment-Risiko; daraus allein folgt keine bestimmte Kreditverlustpriorität.','bonds-14','mbs','cmo','Time Tranching'),
 G('Sequential Pay','Kapitalverteilung, bei der eine festgelegte frühere Klasse zunächst bis zur vollständigen Tilgung Kapital erhält. Spätere Klassen können trotzdem laufenden Zins erhalten; Kapitalzeit und Kreditverlustregel bleiben getrennt.','bonds-14','mbs','sequential','Sequential-Pay'),
 G('Planned Amortization Class','Klasse mit einem auf Annahmen beruhenden geplanten Kapitalpfad, dessen Timing durch andere Klassen gepuffert wird. Fehlender Poolcash oder erschöpfter Support kann den Plan stören; ursprüngliche PSA-Spannen sind keine bedingungslose Garantie.','bonds-14','mbs','pac','PAC'),
 G('Support-Klasse','Companion-Klasse, die gemäß Struktur zusätzliche Schwankungen der Kapitalrückzahlung absorbiert, um einen PAC-Pfad zu stabilisieren. Ihr verbleibender Bestand und die Vorgeschichte begrenzen die weitere Schutzwirkung.','bonds-14','mbs','pac','Support|Companion|Companion Class'),
 G('Busted PAC','PAC, dessen beabsichtigte zeitliche Stabilisierung nicht mehr wie geplant funktioniert. Die Aussage betrifft zunächst den Kapitalpfad; rechtlicher Ausfall und Kreditverlust benötigen eigene Prüfung.','bonds-14','mbs','path-dependence'),
 G('Targeted Amortization Class','Klasse mit einem auf einer gewählten Prepayment-Annahme beruhenden Zielpfad. Die tatsächliche Absicherung ist anhand der Struktur zu lesen und nicht automatisch mit einer PAC-Schutzspanne gleichzusetzen.','bonds-14','mbs','other-classes','TAC'),
 G('Accrual-Klasse','Klasse, bei der laufender Zins nach vereinbarten Regeln aufgeschoben und dem Anspruch zugeschlagen wird. Fehlender heutiger Zinscash bedeutet keinen automatischen Zinsverzicht; spätere Bedienung und Rang sind wichtig.','bonds-14','mbs','other-classes','Z-Klasse'),
 G('Interest-only Strip','Wertpapieranspruch auf die zugeordneten Zinscashflows eines Pools ohne zusätzlichen vollen Kapitalanspruch. Schnelleres Prepayment kann künftige Zinsen abschneiden. Nicht mit einem Interest-only-Kreditvertrag verwechseln.','bonds-14','mbs','strips','IO-Strip|IO'),
 G('Principal-only Strip','Wertpapieranspruch auf die zugeordneten Kapitalrückzahlungen ohne den separaten Zinsanspruch. Bei festem positivem Diskontsatz ist dieselbe frühere Kapitalrückgabe mehr wert; reale Zinsszenarien können weitere Effekte enthalten.','bonds-14','mbs','strips','PO-Strip|PO'),
 G('Net Operating Income','Operativer Immobilienüberschuss nach der im Fall gewählten Definition. Hier Objektumsatz nach laufenden Betriebskosten, vor Zins, Ertragsteuer und Abschreibung. Notwendige Investitionen oder Reserven können den verfügbaren Schuldendienstcash weiter reduzieren.','bonds-14','mbs','noi-dscr','NOI'),
 G('CMBS-DSCR','Deckung des auf derselben Periodenbasis definierten Immobilienkreditdienstes durch den dafür angesetzten Objektüberschuss. Die eigene laufende IO-Quote schließt den späteren Ballon ausdrücklich aus und beweist deshalb keine vollständige Endrefinanzierung.','bonds-14','mbs','noi-dscr','',[{label:'DSCR',units:['mbs']}]),
 G('Kapitalisierungssatz','Satz zur vereinfachten direkten Kapitalisierung eines nachhaltig angesetzten Objektüberschusses. Ein höherer Satz senkt bei gleichem NOI den Modellwert. Er ist nicht automatisch der Kreditzins oder eine exakte vollständige DCF-Bewertung.','bonds-14','mbs','noi-dscr','Cap Rate|Capitalization Rate'),
 G('Refinanzierungslücke','Ungedeckter Unterschied zwischen fälliger alter Schuld und tatsächlich verfügbarer neuer Finanzierung beziehungsweise anderen gesicherten Mitteln. Objektwert und laufende Tragfähigkeit können die neue Finanzierung gleichzeitig begrenzen.','bonds-14','mbs','refinancing','Refinancing Gap'),
 G('Prepayment Lockout','Vertragliche Einschränkung vorzeitiger Kapitalrückzahlung während eines definierten Zeitraums. Sie beseitigt weder Mieter- und Objektverluste noch eine spätere Refinanzierungslücke.','bonds-14','mbs','call-protection','Lockout'),
 G('Yield Maintenance','Vertraglich definierter Ausgleich bei bestimmter zulässiger früher Rückzahlung, der an die verbleibende Ertragsposition des Kreditgebers anknüpfen kann. Tatsächliche Formel, Referenzsatz, Termine und Mindestbetrag sind einzeln zu prüfen.','bonds-14','mbs','call-protection'),
 G('Defeasance','Im hier gemeinten Immobilienkreditkontext Ersatz der Objektsicherheit durch vertraglich zulässige Ersatzsicherheiten zur Bedienung des weiter bestehenden Kredits. Kein automatisches Recht und keine bloße sofortige Kapitalrückzahlung.','bonds-14','mbs','call-protection'),
 G('Asset-Backed Security','Wertpapier, dessen Zahlungen an einen bezeichneten Pool von Vermögenswerten und die vereinbarten Strukturregeln anknüpfen. Im engeren Vergleich hier stehen nicht hypothekarische Forderungen im Vordergrund. Pooltyp, Anspruch, Schutz und Verteilung sind gesondert zu prüfen; eine automatische bilanzielle Ausbuchung folgt nicht aus dem Namen.','bonds-13','abs','map','ABS|Asset-Backed Securities'),
 G('Covered Bond','Schuldverpflichtung eines Emittenten, typischerweise eines Kreditinstituts, mit besonderen Rückgriffsrechten auf einen abgegrenzten Deckungspool. Emittentenpflicht, Poolrechte und möglicher verbleibender Restanspruch bilden den Schutz; sie bedeuten keine doppelte Auszahlung oder allgemeine Verlustfreiheit.','bonds-13','abs','comparison','Covered Bonds|Gedeckte Anleihe|Gedeckte Schuldverschreibung'),
 G('Deckungspool','Für bestimmte besicherte Ansprüche abgegrenzte geeignete Vermögenswerte eines Programms. Zusammensetzung, Austausch, anrechenbarer Wert und Zugriff folgen dessen Regeln. Nominalwert, sofort verfügbarer Nettoerlös und tatsächliches Ausfallrisiko müssen nicht übereinstimmen.','bonds-13','abs','cover-pool','Cover Pool|Deckungsaktiva'),
 G('Dual Recourse','Rückgriff auf den verpflichteten Emittenten und den besonders zugeordneten Deckungspool. Beide Wege dienen derselben Forderung. Ein möglicher Anspruch gegen die sonstige Emittentenmasse betrifft nur den ungedeckten Rest; bereits bezahlte Beträge werden nicht nochmals verlangt.','bonds-13','abs','dual-recourse','Doppelter Rückgriff|Double Recourse'),
 G('Asset Encumbrance','Bindung von Vermögenswerten zugunsten bestimmter besicherter oder vorrangiger Ansprüche. Dieselben Werte sind dadurch nicht zugleich voll frei für andere Gläubiger verfügbar. Für die Restmasse sind tatsächliche Rechte und Rangfolgen maßgeblich.','bonds-13','abs','cover-risks','Vermögensbindung'),
 G('Hard Bullet','Vertragsstruktur mit Kapitalfälligkeit zum vereinbarten Endtermin ohne den jeweils verglichenen eingebauten Verlängerungsmechanismus. Sie kann hohen Liquiditätsbedarf am Termin erzeugen. Konkrete Nichtzahlungsfolgen richten sich nach Vertrag und Recht.','bonds-13','abs','maturity'),
 G('Soft Bullet','Fälligkeitsstruktur mit geplantem und verlängertem Enddatum; unter festgelegten Bedingungen kann sich die Kapitalfälligkeit verschieben. Die zusätzliche Zeit kann Verkaufsdruck mindern, bedeutet für Anleger aber möglicherweise späteren Kapitalzugang. Frist und Auslöser sind nicht weltweit einheitlich.','bonds-13','abs','maturity'),
 G('Conditional Pass-through','Struktur mit vertraglich bestimmten Bedingungen für eine Verlängerung beziehungsweise Weitergabe von Cashflows aus Deckungsaktiva. Sie kann sofortigen Verwertungsdruck mindern und zugleich die Rückzahlungsdauer verändern. Sie ist nicht identisch mit jeder gewöhnlichen Hypotheken-Pass-through-Struktur.','bonds-13','abs','maturity','CPT Covered Bond|Conditional Pass-Through Covered Bond'),
 G('Credit Enhancement','Mechanismus, der bestimmte Ansprüche durch zusätzliche oder anders zugeordnete Deckung beziehungsweise Verlusttragung schützt. Beispiele sind Nachrang, Übersicherung, nutzbare Reserven, Margen und Garantien. Quelle, Umfang, Rang und Zeitpunkt bestimmen den tatsächlichen Nutzen; Gesamtrisiko verschwindet nicht automatisch.','bonds-13','abs','enhancement','Kreditverbesserung|Kreditschutzmechanismus'),
 G('Verbriefungsübersicherung','Überschuss des abgegrenzten anrechenbaren Aktivawerts über die dazu gehörigen Wertpapieransprüche. Aktivadeckungsfaktor, Überschuss auf Schuld und Überschuss auf Aktiva sind verschiedene Quoten. Eine bereits enthaltene Reserve darf nicht nochmals als zusätzliche Ressource addiert werden.','bonds-13','abs','oc','Overcollateralization|Overcollateralisation',[{label:'Übersicherung',units:['abs']}]),
 G('Verbriefungs-Subordination','Rangregel, nach der benannte untere Anspruchsschichten Verluste vor höheren Klassen tragen oder später bezahlt werden. Sie ordnet vorhandene Ressourcen und Verlustlagen neu; sie erzeugt kein zusätzliches Poolvermögen. Schutz einer Klasse und Schutz aller Notes haben verschiedene Basen.','bonds-13','abs','subordination','ABS Subordination',[{label:'Subordination',units:['abs']}]),
 G('Attachment Point','Poolverlustschwelle, oberhalb der eine bestimmte Tranche im festen terminalen Modell erstmals Kapitalverlust trägt. Sie verwendet die ursprüngliche Poolbasis. Die anschließende Trancheverlustquote bezieht sich dagegen auf das eigene kleinere Tranchekapital; Schwelle und Eintrittswahrscheinlichkeit sind verschiedene Größen.','bonds-13','abs','attachment','Attachment-Schwelle'),
 G('Detachment Point','Poolverlustschwelle, bei der eine bestimmte Tranche im festen terminalen Modell vollständig aufgezehrt ist. Differenz aus Detachment und Attachment ist die Tranchebreite auf derselben Poolbasis; der Kapitalverlust der Tranche bleibt auf ihr Kapital begrenzt.','bonds-13','abs','attachment','Detachment-Schwelle'),
 G('Finanzierte Verbriefungsreserve','Tatsächlich vorhandenes, nach den Dokumenten für bestimmte Fehlbeträge nutzbares Guthaben. Finanzierung und Erstattungsrang gehören zur Analyse. Ist das Cash bereits im gesamten Aktivawert enthalten, darf es nicht nochmals als unabhängige zusätzliche Deckung addiert werden.','bonds-13','abs','reserve','Funded Securitization Reserve',[{label:'Cashreserve',units:['abs']},{label:'Reservekonto',units:['abs']}]),
 G('Excess Spread','Nach der jeweiligen Definition verbleibende Poolfinanzierungs- oder Zinserträge nach bestimmten Kosten und gegebenenfalls Kreditverlusten. Vor- und Nachverlustmarge werden im Kapitel getrennt. Künftiger erwarteter Spread ist keine schon finanzierte Cashreserve; tatsächlich nutzbare Beträge und Einbehalte bestimmen den Schutz.','bonds-13','abs','spread'),
 G('Cash Trapping','Vertraglicher Einbehalt vorhandener Mittel in der Struktur statt Freigabe an nachrangige oder Residualempfänger. Kann künftige Deckung stärken, erzeugt aber kein neues Geld. Auslöser, Verwendung und spätere Freigabe richten sich nach den Dokumenten.','bonds-13','abs','triggers'),
 G('Verbriefungstrigger','Definierte Bedingung, deren Eintritt eine bestimmte Maßnahme auslöst, etwa Einbehalt, Tilgung oder Begrenzung der Wiederanlage. Messgröße, Zeitpunkt, Schwelle und Folge werden gemeinsam gelesen. Ein Schutztestbruch ist nicht automatisch eine fällige Nichtzahlung oder ein Event of Default.','bonds-13','abs','triggers','Securitization Trigger',[{label:'Trigger',units:['abs']}]),
 G('Revolving-Periode','Phase, in der bestimmte Kapitalrückflüsse nach den Regeln der Struktur für neue geeignete Forderungen verwendet werden können. Pooltilgung ist dadurch nicht automatisch Investortilgung. Qualität, Verfügbarkeit und zulässige Wiederanlage bestimmen den Erhalt des Pools.','bonds-13','abs','revolving','Revolving Period|Revolving-Phase|Lockout Period'),
 G('Early Amortization','Vertraglich ausgelöster früherer Beginn oder beschleunigter Verlauf der Kapitalrückzahlung, etwa zulasten weiterer Wiederanlage. Kann Anleger schützen und zugleich den Originator zur Suche nach anderer Finanzierung zwingen. Es ist keine automatische Garantie gegen endgültigen Poolverlust.','bonds-13','abs','triggers','Vorzeitige Amortisation'),
 G('Seller’s Interest','Vom Verkäufer gehaltener Anteil etwa an einem Revolving-Forderungspool. Eine rein proportionale Beteiligung trägt nur ihren anteiligen Kreditverlust und ist nicht allein wegen des Inhabers First Loss. Größen-, Dilution- und Kreditfunktionen werden nach den konkreten Regeln unterschieden.','bonds-13','abs','seller-interest',"Seller's Interest|Transferor’s Interest|Transferor's Interest"),
 G('Monthly Payment Rate','Hier ausdrücklich monatliche Kapitalrückzahlung geteilt durch ausstehendes Poolkapital zu Monatsbeginn. Ohne Wiederanlage und bei konstanter Quote entsteht geometrischer Bestandsabbau. Zinsanteil, Investoranteil, Phase und Konvention müssen vor einer Laufzeitfolgerung feststehen.','bonds-13','abs','amortization','MPR'),
 G('Forderungsverwässerung','Verringerung eines Rechnungsanspruchs etwa durch berechtigte Gutschriften, Rücksendungen, Preisnachlässe oder Einreden. Der Kunde kann den verbleibenden Betrag vollständig erfüllen, ohne einen Kreditausfall zu verursachen. Wer die ursprüngliche Deckungsminderung trägt, folgt den Vertragsregeln.','bonds-13','abs','dilution','Dilution'),
 G('Restwertrisiko','Risiko, dass der tatsächlich erzielte künftige Wert eines Gegenstands vom für eine Rechnung erwarteten Restwert abweicht. Bei Leasing kann so trotz vollständig gezahlter Raten weniger Gesamtcash entstehen. Schätzung, tatsächlicher Erlös und Garantiedeckung sind zu unterscheiden.','bonds-13','abs','leases','Residual Value Risk'),
 G('Asset-Backed Commercial Paper','Kurzfristiges Papier einer mit bestimmten Aktiva finanzierten Struktur. Bei länger laufenden Aktiva können Fälligkeit und Cashzufluss auseinanderfallen. Anschlussfinanzierung, tatsächlich abrufbare Liquiditätshilfe und endgültiger Kreditschutz sind getrennt zu prüfen.','bonds-13','abs','abcp','ABCP'),
 G('Collateralized Debt Obligation','Oberbegriff für eine Struktur, die Cashflows und Risiken eines Schuldportfolios nach den vereinbarten Anspruchsschichten verteilt. Pooltyp, Rang, Gebühren, Phasen und Tests bestimmen die Wirkung. Die eigenen Kapitelrechnungen behandeln eine Cashflow-Struktur mit tatsächlichen Aktiva.','bonds-13','abs','cdo','CDO|Collateralised Debt Obligation'),
 G('Collateralized Loan Obligation','Auf Kreditforderungen ausgerichtete Form strukturierter Schuldansprüche. In einer verwalteten Cashflow-Struktur beeinflussen Poolzahlungen, Managerentscheidungen, Gebühren, Rang, Wiederanlage und Deckungstests die Anlegerzahlungen. Variabelzins oder hoher Rang beseitigen nicht alle Risiken.','bonds-13','abs','clo','CLO|Collateralised Loan Obligation'),
 G('Collateralized Bond Obligation','Auf Anleihen als Poolaktiva ausgerichtete Form strukturierter Schuldansprüche. Die Bezeichnung grenzt vor allem den Pooltyp ab und garantiert weder einen bestimmten Verlustschutz noch eine bestimmte Rendite.','bonds-13','abs','cdo','CBO|Collateralised Bond Obligation'),
 G('CLO-Zinsdeckungsfaktor','Nach den konkreten Testregeln verfügbare Zinserträge relativ zu den am geprüften Rang und darüber enthaltenen Note-Zinsen. Kostenabzüge, Zuordnungen und Messzeitpunkt müssen feststehen. Eine Sicherheitsgrenze kann verletzt sein, obwohl die aktuellen Zinsen noch vollständig bezahlt werden.','bonds-13','abs','interest','CLO Interest Coverage',[{label:'IC',units:['abs']},{label:'Interest Coverage',units:['abs']}]),
 G('CLO-Deckungstest','Vertraglicher Vergleich anrechenbarer Aktiva mit dem ausstehenden Kapital der berücksichtigten Note-Ränge. Der Zähler kann Abschläge enthalten und ist nicht zwingend Marktwert oder Bruttonominal. Tilgungsquelle und zeitliche Abgrenzung bestimmen, wie sich die Quote verändert.','bonds-13','abs','oc-test','OC Test|Overcollateralization Test',[{label:'OC',units:['abs']},{label:'OC-Test',units:['abs']}]),
 G('Anrechenbarer CLO-Poolwert','Nach den jeweiligen Testregeln berücksichtigtes Aktivakapital einschließlich definierter Anpassungen und Ausschlüsse. Es darf nicht ohne Prüfung mit unbereinigtem Nominal, Marktpreis oder verfügbarem Cash gleichgesetzt werden. Im eigenen Tilgungsfall ist separates Zinscash ausdrücklich nicht enthalten.','bonds-13','abs','oc-test','Adjusted Collateral'),
 G('Cash Diversion','Vertraglich bestimmte Umlenkung vorhandener Mittel, beispielsweise von einer sonst möglichen Residualzahlung zur Senior-Kapitaltilgung nach einem Schutztestbruch. Sie verändert den Empfänger und gegebenenfalls die Deckungsquote; fehlende Mittel werden nicht erzeugt.','bonds-13','abs','diversion'),
 G('Reinvestment Period','Vertraglich abgegrenzte Phase für Wiederanlage bestimmter Rückflüsse in zulässige Aktiva. Qualitäts-, Konzentrations-, Laufzeit- und Deckungsregeln können Entscheidungen begrenzen. Ende der Phase, erwartete Kapitaldauer und rechtliche Endfälligkeit sind verschiedene Zeitangaben.','bonds-13','abs','reinvestment','Wiederanlagephase'),
 G('CLO-Mezzanine','Im jeweils betrachteten CLO zwischen benannten höheren und niedrigeren Ansprüchen liegende Klasse. Ihr Schutz und ihre Zahlung hängen vom tatsächlichen Rang und Wasserfall ab. Ein Test durch diese Klasse zählt auch die darüber liegenden relevanten Ansprüche mit.','bonds-13','abs','oc-test','CLO Mezzanine',[{label:'Mezzanine',units:['abs']}]),
 G('Verbriefungsresidual','Nach den bezeichneten vorrangigen Verpflichtungen verbleibender wirtschaftlicher Anspruch einer Struktur. Cashzahlung, ursprünglicher Kapitalüberschuss und Erwartungsverlust sind verschiedene Größen. Der Begriff bezeichnet hier keinen statistischen Schätzfehler.','bonds-13','abs','clo','Securitization Residual',[{label:'Residual',units:['abs']},{label:'Residualposition',units:['abs']}]),
 G('Ausfallabhängigkeit','Zusammenhang zwischen den Ausfällen verschiedener Schuldner. Bei gleichen Einzel-Ausfallwahrscheinlichkeiten kann andere Abhängigkeit die gemeinsame Verlustverteilung und die Verluste einzelner Tranchen verändern, ohne den erwarteten Poolverlust zu ändern. Nicht jede Schicht muss im Erwartungswert gleichgerichtet reagieren.','bonds-13','abs','dependence','Default Dependence',[{label:'Ausfallkorrelation',units:['abs']}]),
 G('Verbriefung','Finanzierungsstruktur, in der Ansprüche auf einen bezeichneten Forderungspool zur Grundlage von Wertpapieren werden. Anlegercash, Poolrechte und vertragliche Verteilung sind zu trennen. Risikotransfer, bilanzielle Ausbuchung und Kapitalentlastung folgen nicht automatisch allein aus dem Namen.','bonds-13','securitization','claim','Securitization'),
 G('Forderungspool','Abgegrenzte Gruppe von Darlehens- oder anderen Zahlungsforderungen mit bestimmten Schuldnern, Vertragsbedingungen und verbleibenden Risiken. Sein Nominal ist kein sofort verfügbares Cash; viele Konten beseitigen gemeinsame Stressfaktoren nicht.','bonds-13','securitization','pool','Receivables Pool',[{label:'Pool',units:['securitization','abs']}]),
 G('Originator','Partei, die die ursprünglichen Forderungen begründet. Sie kann zusätzlich Verkäufer, Servicer oder Investor sein, doch diese Aufgaben und ihre Pflichten werden gesondert geprüft. Origination allein ist keine unbegrenzte Garantie späterer Wertpapierzahlungen.','bonds-13','securitization','originator','Kreditoriginator'),
 G('Verbriefungszweckgesellschaft','Gesonderter Rechtsträger, der im traditionellen Grundfall den abgegrenzten Pool erwirbt und darauf bezogene Titel ausgibt. Die eigene Rechtspersönlichkeit beweist weder Schutz vor jedem Poolverlust noch automatisch bilanzielle Ausbuchung oder fehlende Konzernkonsolidierung.','bonds-13','securitization','spe','SPE|SPV|Special Purpose Entity|Special Purpose Vehicle|Zweckgesellschaft'),
 G('Servicer','Vertraglich beauftragte Partei zur laufenden Verwaltung, zum Einzug und zur Bearbeitung der zugrunde liegenden Forderungen. Einzug, Kreditrisikoübernahme und etwaige Vorschusspflicht sind verschiedene Aufgaben. Daten, Konten, Ersatz und Grenzen der Pflichten werden konkret gelesen.','bonds-13','securitization','servicer','Servicing|Kreditservicer'),
 G('Verbriefungs-Trustee','Treuhand- oder Verwaltungsfunktion mit den tatsächlich vereinbarten Kontroll-, Konten-, Sicherheiten- und Gläubigeraufgaben der Struktur. Die Funktion ist kein unbegrenztes Versprechen, jeden wirtschaftlichen Poolverlust auszugleichen.','bonds-13','securitization','trustee','Securitization Trustee',[{label:'Trustee',units:['securitization']},{label:'Treuhänder',units:['securitization']}]),
 G('Arranger','Partei, die eine Transaktion strukturiert oder ihre Umsetzung koordiniert. Konkrete Pflichten, Vergütung und etwaige Übernahmeverpflichtung folgen der Vereinbarung; die Strukturierungsrolle allein ist keine dauerhafte Garantie sämtlicher Anlegerzahlungen.','bonds-13','securitization','arranger'),
 G('Verbriefungs-Underwriter','Für die Emission übernommene Platzierungs- oder Übernahmefunktion mit ihrem tatsächlichen Umfang und Zeitraum. Feste Übernahme und reine Bemühenspflicht unterscheiden sich; aus einer erfolgreichen Platzierung folgt keine unbegrenzte spätere Kreditgarantie.','bonds-13','securitization','arranger','Securitization Underwriter',[{label:'Underwriter',units:['securitization']}]),
 G('Tranche','Abgegrenzte Klasse von Ansprüchen innerhalb einer Finanzierung mit bestimmten Zahlungs-, Rang- und Risikoregeln. Verschiedene Tranchen desselben Pools können andere Verlustquoten und Zahlungszeitpunkte besitzen. Die Regeln verteilen vorhandene Ressourcen, ohne allein neue Poolerträge zu erzeugen.','bonds-13','securitization','losses','Tranchen'),
 G('Seniortranche','Im gegebenen Anspruchskreis vorrangige Tranche gegenüber benannten nachrangigen Klassen. Der konkrete Schutz hängt von Reihenfolge, Umfang der vorgelagerten Verlustlagen und verfügbaren Mitteln ab. Seniorität ist keine vollständige Garantie gegen jeden Verlust oder jedes Timingproblem.','bonds-13','securitization','losses','Senior Tranche',[{label:'Senior',units:['securitization','abs']}]),
 G('Juniortranche','Gegenüber benannten früheren Klassen nachrangiger Anspruch. Im eigenen Zwei-Tranchen-Fall trägt er die erste Kapitalverlustlage und erhält laufend nur den verbleibenden Rest nach den angegebenen Stufen. Das eigene Nominal, nicht das ganze Poolnominal, ist der Nenner seiner Verlustquote.','bonds-13','securitization','losses','Junior Tranche',[{label:'Junior',units:['securitization','abs']}]),
 G('True Sale','Als endgültiger Forderungsverkauf ausgestaltete und rechtlich zu prüfende Übertragung. Wirksamkeit, Zugriff und mögliche verbleibende Verpflichtungen hängen vom tatsächlichen Rahmen ab. Die Bezeichnung beweist nicht für sich vollständige bilanzielle Ausbuchung oder ökonomischen Risikotransfer.','bonds-13','securitization','remoteness'),
 G('Insolvenzferne','Gestaltungsziel zur Abschirmung einer Struktur gegen bestimmte Insolvenz- und Zugriffskanäle. Wirksame Übertragung, getrennte Massen und begrenzte Tätigkeit können dazu beitragen. Insolvenzferne beseitigt nicht die wirtschaftlichen Risiken der gehaltenen Aktiva.','bonds-13','securitization','remoteness','Bankruptcy Remoteness'),
 G('Verbriefungswasserfall','Konkret festgelegte Reihenfolge der Verteilung verfügbarer Mittel einer Verbriefung. Im eigenen Zahlungsfall zuerst Gebühr, dann Seniorzins, fälliges Senior-Kapital und Juniorrest. Jede Stufe kann nur den nach früheren Zahlungen verbleibenden Betrag verwenden; andere Verträge können andere Regeln besitzen.','bonds-13','securitization','waterfall','Securitization Waterfall',[{label:'Waterfall',units:['securitization']},{label:'Zahlungswasserfall',units:['securitization']}]),
 G('Verbriefungsrückbehalt','Beim Verkäufer verbleibender Anspruch oder Risikoanteil nach der Transaktion. Ein gehaltener Junioranspruch ist keine heutige externe Cashzahlung und kann in bestimmten Stresslagen einen großen Teil der Poolverluste beim Verkäufer belassen. Marktwert und Nominal sind gesondert zu prüfen.','bonds-13','securitization','retention','Retained Interest',[{label:'Rückbehalt',units:['securitization']}]),
 G('First-Loss-Position','Anspruch oder Schutzlage, die unter der festgelegten Struktur die erste bezeichnete Verlustschicht absorbiert. Größe, Auslöser und Beteiligungsanteil bestimmen die Belastung. Ein beim Verkäufer verbleibender First Loss kann trotz hoher externer Finanzierung eine erhebliche Exposition bewahren.','bonds-13','securitization','retained-loss','First Loss|First-Loss|Erstverlustposition'),
 G('Verlusttranchierung','Verteilung eines gegebenen Kredit- oder Kapitalverlusts auf unterschiedliche Anspruchsränge. Im eigenen terminalen Fall wird zuerst Junior bis zu seinem Nominal belastet, dann Senior. Die Geldverluste müssen sich zum gegebenen Gesamtverlust addieren; Prozentquoten benötigen passende Gewichte.','bonds-13','securitization','losses','Credit Tranching|Tranchierung'),
 G('Poolausbuchung','Bilanzielle Entfernung einer Forderungsposition, wenn die jeweiligen Rechnungslegungsvoraussetzungen erfüllt sind. Rechtliche Übertragung, verbliebene Risiken und Chancen, gegebenenfalls Kontrolle und die Berichtsebene sind gesondert zu beurteilen. Ein juristisch eigener Rechtsträger entscheidet den Bilanzbefund nicht allein.','bonds-13','securitization','accounting','Pool Derecognition',[{label:'Ausbuchung',units:['securitization']},{label:'Derecognition',units:['securitization']}]),
 G('Verbriefungs-Emissionscash','Beim Vehikel tatsächlich aus der Ausgabe von Titeln eingegangene Mittel. Sie werden mit Kaufpreis, eigenen Kosten, Reserve und weiteren Verwendungen abgestimmt. Derselbe an den Verkäufer weitergeleitete Betrag ist keine zweite unabhängige externe Finanzierungsquelle.','bonds-13','securitization','sources','Securitization Issuance Cash',[{label:'Emissionscash',units:['securitization']}]),
 G('Poolgegenwert','Für die Übertragung vereinbarte Gegenleistung in der jeweils benannten Preisrechnung. Sie kann aus Cash und anderen Ansprüchen bestehen. Nicht ausgezahlte Rückbehaltspositionen werden getrennt von heute verfügbarem Cash und von ihrem tatsächlichen späteren Rückfluss beurteilt.','bonds-13','securitization','retention','Pool Consideration'),
 G('Verbriefungssammelkonto','Das im konkreten Ablauf für eingegangene Poolzahlungen verwendete Konto. Die Weiterverteilung verändert nicht die Anzahl vorhandener Ressourcen. Eigentum, Zugriff, Kontentrennung und tatsächlicher Eingangstermin bestimmen, welche Mittel für die betrachtete Zahlung verfügbar sind.','bonds-13','securitization','collections','Collection Account',[{label:'Sammelkonto',units:['securitization']}]),
 G('Liquiditätsvorschuss','Vertraglich möglicher vorübergehender Mittelzufluss zur Überbrückung einer Zahlungslücke. Auslöser, Grenzen, Erstattungsrang und Finanzierung sind zu prüfen. Eine solche Liquiditätshilfe ist weder automatisch eine endgültige Verlustübernahme noch allein aus der Rolle des Servicers abzuleiten.','bonds-13','securitization','timing','Liquidity Advance|Servicer Advance'),
 G('Vermischungsrisiko','Risiko aus der Vermischung von Poolgeldern mit anderen Mitteln eines Dienstleisters, etwa vor Weiterleitung. Verzögerter Zugriff oder zusätzliche Ansprüche können relevant werden; die Folgen hängen von Kontentrennung, Vertrag und Recht ab. Es ist von einem unmittelbaren Kreditausfall des ursprünglichen Schuldners zu unterscheiden.','bonds-13','securitization','servicer','Commingling Risk'),
 G('Ersatzservicer','Nach den konkreten Regeln zur Übernahme der Forderungsverwaltung vorgesehene Partei. Benennung allein beweist keine einsatzbereite Übernahme: Datenzugriff, Systeme, Vergütung, Aktivierung und Finanzierung müssen tatsächlich funktionieren. Ein Ersatz verhindert nicht automatisch Kreditausfälle des Pools.','bonds-13','securitization','servicer','Backup Servicer'),
 G('Originate-to-Distribute','Geschäftsmodell, bei dem Forderungen mit dem Ziel ihrer späteren Weiterplatzierung begründet werden. Es kann Kreditvergabe und Kapitalgeber verbinden, erzeugt aber Informations-, Anreiz- und Zwischenfinanzierungsfragen. Platzierung ist keine automatisch gesicherte zukünftige Mittelquelle.','bonds-13','securitization','capacity'),
 G('EBIT','Earnings Before Interest and Taxes: Ergebnis vor Zinsaufwand und Ertragsteuer unter der jeweiligen Rechnungsabgrenzung. Enthält im Neravo-Fall die planmäßige Abschreibung. EBIT ist keine freie Kasse; Working Capital, Cashsteuer, Investitionen und Zahlungstermine verlangen eine weitere Überleitung.','corporate-07','corporate-credit','earnings'),
 G('EBITDA','Earnings Before Interest, Taxes, Depreciation and Amortization: Ergebnis vor Zinsen, Steuern und planmäßiger Abschreibung. Im einfachen Neravo-Fall EBIT plus Abschreibung; zusätzliche Adjustierungen benötigen eigene Begründung. Weder Cashsteuer noch Working Capital, Capex oder Tilgung sind damit vollständig abgedeckt.','equity-10','corporate-credit','earnings'),
 G('Kredit-FFO','Funds from Operations in der ausdrücklich abgegrenzten Kreditanalyse: nicht zahlungswirksame Ergebniseffekte werden zum Nettogewinn passend übergeleitet, vor Änderung des operativen Working Capital. Im Neravo-Fall Nettogewinn plus Abschreibung, nach Cashzins und Cashsteuer. Nicht identisch mit der Immobilien-/REIT-Ergebniskennzahl gleichen Namens.','bonds-10','corporate-credit','ffo','Credit FFO',[{label:'FFO',units:['corporate-credit']},{label:'Funds from Operations',units:['corporate-credit']}]),
 G('EBITDA-Zinsdeckung','EBITDA geteilt durch die konsistent abgegrenzte positive Zinsgröße desselben Zeitraums. Sie zeigt Ergebnisdeckung vor Abschreibung, enthält aber keine vollständige Prüfung von Cashsteuer, Working Capital, Investitionen oder Kapitaltilgung. Ein hoher Wert garantiert keine rechtzeitige Rückzahlung.','bonds-10','corporate-credit','coverage','EBITDA Interest Coverage'),
 G('EBIT-Zinsdeckung','EBIT geteilt durch die zur Ergebnisabgrenzung passende positive Zinsgröße. Bei gleichem Zins liegt sie um Abschreibung geteilt durch Zins unter EBITDA-Deckung. Historische Abschreibung ist nicht zwangsläufig identisch mit aktuellem Erhaltungs-Capex.','bonds-10','corporate-credit','coverage','EBIT Interest Coverage'),
 G('Brutto-Leverage','Im Kapitel verzinsliche Bruttoschuld geteilt durch positives Jahres-EBITDA auf konsistenter Basis. Ein Vielfaches setzt Schuld und Ergebnis ins Verhältnis; es ist weder eine automatische Ratingnote noch ohne weitere Cashannahmen eine Rückzahlungsdauer.','bonds-10','corporate-credit','leverage','Gross Debt to EBITDA|Debt-to-EBITDA'),
 G('Analytische Netto-Leverage','Im Kapitel nach zulässigem verfügbarem Cash verbleibende Nettoschuld geteilt durch positives EBITDA. Cashzugänglichkeit, Vertrag, Erfassungskreis und Periode bestimmen die Aussage. Ein negativer EBITDA-Nenner wird nicht als günstige Verschuldung interpretiert.','bonds-10','corporate-credit','leverage','Net Debt to EBITDA',[{label:'Netto-Leverage',units:['corporate-credit']}]),
 G('Kredit-FCF','Hier operativer Cashflow nach Cashzins, Cashsteuer und operativer Working-Capital-Veränderung minus ausgezahltem Gesamt-Capex; vor Tilgung, neuer Finanzierung und Ausschüttung. Diese ausdrücklich gewählte Größe ist nicht automatisch FCFF oder FCFE.','bonds-10','corporate-credit','fcf','Free Operating Cash Flow',[{label:'FCF',units:['corporate-credit']}]),
 G('FFO-Schuldquote','Für dieselbe Periode und Abgrenzung berechneter Kredit-FFO geteilt durch die bezeichnete Schuld. Im Neravo-Fall Jahres-FFO nach Zins und Cashsteuer geteilt durch Anfangsschuld. Die Quote erfasst dort weder Working-Capital-Bindung noch Capex und garantiert keine Tilgung.','bonds-10','corporate-credit','cash-case','FFO to Debt'),
 G('Cashkonversion','Überleitung einer Ergebnisgröße in tatsächliche Zahlungsmittel unter benannter Abgrenzung. Forderungen, Vorräte, Lieferantenverbindlichkeiten, Steuern und Investitionen können hohe Ergebniszahlen mit schwachen Cashzuflüssen verbinden. Eine Freisetzung aus Bestandsabbau ist nicht automatisch wiederholbarer Ertrag.','bonds-10','corporate-credit','cfo','Cash Conversion'),
 G('Erhaltungs-Capex','Investitionen zur Sicherung der vorhandenen operativen Leistungsfähigkeit unter einer konkreten Planung. Höhe und notwendiger Zeitpunkt sind Schätzfragen; historische Abschreibung ist kein automatisch gleich großer Cashersatz. Aufschub kann kurzfristig Liquidität erhöhen und künftige Leistung schwächen.','bonds-10','corporate-credit','fcf','',[{label:'Maintenance Capex',units:['corporate-credit']}]),
 G('Wachstums-Capex','Investitionen für zusätzliche Kapazität oder neue Geschäftsmöglichkeiten. Zahlungszeit, spätere Erträge und Umsetzungsrisiko werden getrennt prognostiziert. Die Trennung von Erhaltungsinvestitionen ist nicht immer eindeutig; beide können tatsächlich Cash binden.','bonds-10','corporate-credit','fcf','',[{label:'Growth Capex',units:['corporate-credit']}]),
 G('Freie Endbetriebskasse','Am Ende des betrachteten Plans benötigte ungesperrte Liquiditätsreserve. Ein Plan, der gerade alle bisherigen Zahlungen deckt, kann diese Reserve trotzdem unterschreiten. Die Zielkasse ist eine ausdrückliche Planannahme, keine universelle gesetzliche Mindesthöhe.','bonds-10','corporate-credit','liquidity','Minimum Operating Cash'),
 G('Pro-forma-EBITDA','Auf eine bezeichnete hypothetische oder angepasste Situation übergeleitetes EBITDA, etwa nach einer Transaktion. Realisierte operative Beiträge, behauptete Synergien und Einmalkosten sind transparent zu unterscheiden. Die Bereinigung schafft nicht selbst Cash und muss zur verwendeten Schuld passen.','bonds-10','corporate-credit','adjustments','Adjusted Pro Forma EBITDA'),
 G('Finanzpolitik','Entscheidungsregeln und tatsächliches Verhalten eines Unternehmens zu Verschuldung, Investitionen, Übernahmen, Ausschüttungen und Liquiditätsreserven. Sie beeinflussen künftige Gläubigerschutzpuffer; ein kommuniziertes Ziel ist noch keine vertragliche Garantie.','bonds-10','corporate-credit','governance','Financial Policy'),
 G('Struktureller Nachrang','Wirtschaftliche Beschränkung eines Anspruchs durch getrennte Rechtsträger und Vermögensmassen. Besitzt eine Holding nur Tochteraktien, erreicht sie im einfachen Fall erst den nach eigenen Tochterverpflichtungen verbleibenden Rest; ein Senior-Titel bei der Holding überspringt diese Tochteransprüche nicht.','bonds-10','corporate-credit','structural','',[{label:'Structural Subordination',units:['corporate-credit']}]),
 G('Vertraglicher Nachrang','Durch eine einschlägige Vereinbarung festgelegte nachgeordnete Anspruchsstellung gegenüber bezeichneten anderen Forderungen. Schuldnerkreis, Auslöser und Zahlungsregeln sind zu lesen. Er ist von einem nur durch die Konzernstruktur entstehenden strukturellen Nachrang zu unterscheiden.','bonds-10','corporate-credit','seniority','',[{label:'Contractual Subordination',units:['corporate-credit']}]),
 G('Ungesicherte Restforderung','Nach unzureichender Sicherheitenverwertung verbleibender Teil eines Anspruchs, der unter den konkret zugelassenen Regeln zusätzlich an einer unbesicherten Masse teilnehmen kann. Die Teilnahme wird nicht universell unterstellt und erzeugt keine zweite Sicherheit.','bonds-10','corporate-credit','waterfall','',[{label:'Deficiency Claim',units:['corporate-credit']}]),
 G('Verteilungsmasse','Für die betrachteten Ansprüche nach den ausdrücklich relevanten Eigentums-, Kosten- und Prioritätsregeln verfügbare Vermögensmasse. Verpfändete Werte, freie Werte und Tochter-/Holdingwerte werden nicht mehrfach gezählt. Reale Verfahren benötigen eine eigenständige Rechts- und Werthaltigkeitsprüfung.','bonds-10','corporate-credit','waterfall','Distribution Pool'),
 G('Senior-Unsecured-Referenzebene','Für Vergleichbarkeit verwendete Bezugsebene einer allgemeinen Emittentenbonität. Eine Zuordnung zu Senior Unsecured macht das Emittentenrating nicht identisch mit jeder konkreten unbesicherten Verpflichtung; deren eigene Merkmale bleiben relevant.','bonds-10','corporate-credit','ratings','Senior Unsecured Reference Level'),
 G('Kredit-Schuldendienstdeckung','Cashbasis zur Deckung desselben Zins- und Tilgungsdienstes nach ausdrücklich konsistenten Abzügen. Im Neravo-Beispiel CFO nach Zins plus dieser Zins minus notwendigem Capex, geteilt durch Zins plus Tilgung. Projekt-, Vertrags- und Agenturdefinitionen können abweichen.','bonds-10','corporate-credit','cashcoverage','Corporate Debt Service Coverage',[{label:'DSCR',units:['corporate-credit']}]),
 G('Zahlungsfähigkeit','Fähigkeit des betrachteten Schuldners, eine Verpflichtung mit tatsächlich verfügbaren Ressourcen zum benötigten Zeitpunkt und in der passenden Währung zu bedienen. Große Wirtschaftsleistung oder Vermögenswerte allein sind keine sofortige Kasse.','bonds-11','sovereign-credit','ability','Ability to Pay'),
 G('Zahlungsbereitschaft','Entscheidung, verfügbare Mittel tatsächlich für einen bestimmten Anspruch einzusetzen. Sie ist von Zahlungsfähigkeit zu unterscheiden und wird über konkrete institutionelle, vertragliche und politische Evidenz beurteilt.','bonds-11','sovereign-credit','willingness','Willingness to Pay'),
 G('Schuldentragfähigkeit','Beurteilung, ob ein Schuld- und Zahlungsplan unter realistischen Einnahmen, Ausgaben, Finanzierung und Anpassungen aufrechterhalten werden kann. Eine mechanische Schuldenquotenprojektion ist dafür nur ein Teilbeleg; politische Umsetzbarkeit und kurzfristige Liquidität bleiben gesondert zu prüfen.','bonds-11','sovereign-credit','fiscal-capacity','Debt Sustainability'),
 G('Finanzierbarkeit','Fähigkeit, einen konkreten Mittelbedarf rechtzeitig durch verfügbare Einnahmen, Aktiva oder tatsächlich zugängliche Finanzierung zu decken. Ein günstiger langfristiger Schuldenpfad garantiert nicht automatisch jeden kurzfristigen Marktzugang.','bonds-11','sovereign-credit','liquidity','Financeability'),
 G('Schuldenperimeter','Institutioneller Erfassungskreis einer Schuldenzahl, beispielsweise Zentralstaat, Gesamtstaat oder ein weiter definierter öffentlicher Sektor. Unterschiedliche Kreise und die Behandlung interner Forderungen können unterschiedliche Bestände ergeben, ohne dass dies alles neue Kreditaufnahme wäre.','bonds-11','sovereign-credit','perimeter','Debt Perimeter'),
 G('Konsolidierte Staatsschuld','Schuld des ausdrücklich zusammen betrachteten öffentlichen Kreises nach Entfernung der gegenseitigen Binnenforderungen. Die Konsolidierung ändert die gemeinsame Darstellung, beseitigt aber nicht automatisch einen bestehenden einzelnen Vertrag.','bonds-11','sovereign-credit','perimeter','Consolidated Government Debt',[{label:'Konsolidierung',units:['sovereign-credit']}]),
 G('Zins-Einnahmen-Quote','Jährlicher Zinsdienst geteilt durch die passend abgegrenzten öffentlichen Einnahmen. Sie misst eine andere Belastung als Schuld/BIP und benötigt konsistente Perioden und Vorzeichen. Gleiche Zinsbeträge können unterschiedlich große Teile der verfügbaren Einnahmebasis binden.','bonds-11','sovereign-credit','revenue','Interest-to-Revenue Ratio'),
 G('FX-Bestandsänderung','Änderung eines in Heimatwährung ausgedrückten Schuldwerts durch neue Währungsumrechnung bei unverändertem FX-Nominal. Sie ist von neuer Kreditaufnahme und von tatsächlich umgerechneten Cashzahlungen zu trennen.','bonds-11','sovereign-credit','currency','Währungsbewertungseffekt'),
 G('Fremdwährungsschuld','Verpflichtung mit Zahlungen in einer anderen als der gewählten Heimatwährung. Ein Auslandsinvestor kann auch Heimatschuld halten; Vertragswährung und Residenz des Gläubigers sind verschiedene Dimensionen.','bonds-11','sovereign-credit','currency','Foreign-Currency Debt'),
 G('Auslandsschuld','Im üblichen residenzbasierten externen Schuldbegriff bestehende Schuldverpflichtungen Gebietsansässiger gegenüber Gebietsfremden. Die Währung allein bestimmt diesen Auslandsbezug nicht. Sie ist weder gleichbedeutend mit sämtlicher Staatsverschuldung noch mit jeder inländischen Fremdwährungsschuld.','bonds-11','sovereign-credit','external-accounts','Externe Schuld|External Debt'),
 G('Währungsmismatch','Nicht passende Währungsstruktur von Verpflichtungen und verfügbaren Zahlungsquellen beziehungsweise Aktiva. Kursänderung, Konvertierbarkeit, Mengen und Zeitpunkte können dadurch relevant werden. Ein bloßer Heimatbetrag ist keine bereits verfügbare fremde Zahlungswährung.','bonds-11','sovereign-credit','currency','Currency Mismatch'),
 G('Bestandszins','Auf den betrachteten bestehenden Schuldenbestand entfallender Zins unter seinen Verträgen und Zeitpunkten. Er ist nicht automatisch identisch mit dem heutigen Satz für neue Anleihen. Ersatzfinanzierung oder tatsächlicher Reset können den zukünftigen Bestandsdienst verändern.','bonds-11','sovereign-credit','interest-reset','Effective Interest on Outstanding Debt'),
 G('Quotenstabilisierender Primärsaldo','Unter ausdrücklich gesetzten Zins-, Wachstums-, Bewertungs- und Belastungsannahmen berechneter Primärsaldo, bei dem die Anfangsschuldenquote unverändert bleibt. Sein Geldbetrag hängt vom Nenner und von weiteren Bestandswirkungen ab; die Zielrechnung beweist keine politische Umsetzbarkeit.','bonds-11','sovereign-credit','stress','Debt-Stabilizing Primary Balance'),
 G('Fälligkeitsleiter','Zeitliche Aufteilung der tatsächlich fälligen Kapital- und gegebenenfalls Zinszahlungen. Sie zeigt Konzentrationen des Cashbedarfs, die eine einzelne Endschuldenquote nicht enthält. Alte und bereits zugesagte neue Finanzierung werden mit ihren tatsächlichen Zeitpunkten gelesen.','bonds-11','sovereign-credit','liquidity','Maturity Ladder'),
 G('Cashfinanzierungsbedarf','Vor neuer Finanzierung bestimmter Zahlungsbedarf nach einer benannten Abgrenzung. Im eigenen Modell Tilgung plus Zins minus Primärüberschuss plus zusätzliche noch nicht erfasste Belastung. Ein negativer Rohbetrag ist ein Überschuss und wird von positiver neuer Pari-Schuldaufnahme getrennt.','bonds-11','sovereign-credit','gross-needs','Cash Financing Need'),
 G('Zusätzlicher Schuldabbau','Im eigenen Modell Verwendung eines nach planmäßiger Tilgung verbleibenden Cashüberschusses für weitere Schuldtilgung. Der Betrag wird nicht als negative neue Anleihe bezeichnet. Übersteigt der Überschuss den ganzen Restbestand, wäre eine zusätzliche Aktiv- beziehungsweise Kassenrechnung nötig.','bonds-11','sovereign-credit','gross-needs','Additional Debt Repayment'),
 G('Verfügbare Devisenliquidität','Zum betrachteten Zahlungstermin tatsächlich zugängliche Mittel in der benötigten Fremdwährung nach den relevanten Eigentums-, Belastungs- und Verwendungsgrenzen. Ein nationaler Bruttoreservebestand ist nicht automatisch derselbe Betrag wie die freie FX-Kasse eines einzelnen Staatsorgans.','bonds-11','sovereign-credit','fx-reserves','Available FX Liquidity'),
 G('Reservewährung','Währung, die international unter anderem als Reserve- und Finanzierungsanlage verwendet wird. Breite Nutzung und tiefe Märkte können Nachfrage und Flexibilität stützen, garantieren aber keine unbegrenzte Finanzierung zu jedem Zeitpunkt oder Satz.','bonds-11','sovereign-credit','reserve-currency','Reserve Currency'),
 G('Bedingte Staatsbelastung','Im gegebenen Risikoszenario erst bei bestimmten Ereignissen entstehender öffentlicher Zahlungsbedarf. Eine ausdrückliche Garantie und eine bloße erwartete Unterstützung haben unterschiedliche Grundlagen. Bereits in Bestand oder Haushalt erfasste Kosten dürfen nicht nochmals als neue Belastung gezählt werden; Rechnungslegungsregeln sind gesondert zu prüfen.','bonds-11','sovereign-credit','contingent','Public Contingent Liability'),
 G('Erwartete Staatsunterstützung','Erwartung einer möglichen öffentlichen Hilfe ohne denselben konkret nachgewiesenen Garantieanspruch. Aufgabe, Anreize, bisheriges Verhalten und finanzielle Kapazität können die Einschätzung beeinflussen; Erwartung und garantierte Zahlung werden nicht gleichgesetzt.','bonds-11','sovereign-credit','support','Expected Public Support',[{label:'Implizite Staatsunterstützung',units:['sovereign-credit']},{label:'erwartete Unterstützung',units:['sovereign-credit']}]),
 G('Transferabhängigkeit','Abhängigkeit der Zahlungsfähigkeit von Zuflüssen einer anderen öffentlichen Ebene. Höhe, Regelbindung, Bedingungen und tatsächlicher Zahlungszeitpunkt können die Verfügbarkeit verändern, auch wenn eigene Einnahmen gleich bleiben.','bonds-11','sovereign-credit','transfers','Transfer Dependence'),
 G('Projekt-DSCR','Deckung des im Fall definierten Zins- und Kapitaldienstes durch den nach den ausdrücklich erforderlichen vorherigen Abzügen verfügbaren Projektcashflow. Im eigenen Versorgerfall sind Betrieb und notwendige Erhaltung vorher abgezogen. Eine Jahresquote ersetzt keine Prüfung einzelner Zahlungstermine oder Garantieansprüche.','bonds-11','sovereign-credit','project','Project Debt-Service Coverage',[{label:'DSCR',units:['sovereign-credit']}]),
 G('CFADS','Cash Flow Available for Debt Service: nach den festgelegten vorgelagerten Auszahlungen für den benannten Schuldendienst verfügbarer Cashflow. Welche Betriebs-, Erhaltungs-, Steuer- oder weiteren Zahlungen abgezogen werden, folgt der verwendeten Definition; Bruttoumsatz ist nicht automatisch frei verfügbarer Cashflow.','bonds-11','sovereign-credit','project','Cash Flow Available for Debt Service'),
 G('Leistungsbilanz','Gesamtwirtschaftlicher Saldo von Waren- und Dienstleistungshandel, Primäreinkommen und laufenden Transfers beziehungsweise Sekundäreinkommen. Sie betrifft die Volkswirtschaft und ist kein identisches einzelnes Staatskonto. Private Ersparnis und Investition können neben dem öffentlichen Haushalt ihre Entwicklung beeinflussen.','bonds-11','sovereign-credit','external-accounts','Current Account'),
 G('Schuldendienst-Exportquote','Abgegrenzter externer oder staatlicher Schuldendienst geteilt durch passende Exporterlöse über denselben Zeitraum. Sektor und Zähler müssen benannt werden. Der Quotient beweist keinen direkten staatlichen Zugriff auf alle privaten Exporterlöse und ist keine Ausfallwahrscheinlichkeit.','bonds-11','sovereign-credit','external-ratios','Debt-Service-to-Exports Ratio'),
 G('Staats-Banken-Rückkopplung','Möglicher gemeinsamer Risikokanal zwischen öffentlicher Bonität und Bankenbilanzen, etwa über konzentrierte Staatsanleihebestände und anschließende Unterstützungsbelastung. Der tatsächliche Bestand, Finanzierung und Reaktion müssen belegt werden; derselbe Anspruch wird nicht mehrfach unbereinigt addiert.','bonds-11','sovereign-credit','bank-state','Sovereign-Bank Nexus'),
 G('Zins-Wachstums-Beitrag','Mechanischer Beitrag des passenden Zins-Wachstums-Verhältnisses auf die alte Schuldenquote. In der einfachen nominalen Einperiodenrechnung beträgt er Zins minus Wachstum, geteilt durch eins plus Wachstum, mal Anfangsquote. Primärsaldo und weitere Bestandsänderungen sind zusätzliche Beiträge.','bonds-11','sovereign-credit','snowball','Debt Snowball Effect'),
 G('Primärsaldoquote','Primärsaldo geteilt durch einen ausdrücklich benannten BIP-Nenner. Ein Anteil des End-BIP entspricht bei Wachstum nicht demselben Geldbetrag wie derselbe Prozentsatz des Anfangs-BIP. Die Quotenumrechnung muss zur Budgetgleichung passen.','bonds-11','sovereign-credit','debt-identity','Primary-Balance-to-GDP Ratio'),
 G('Copula','Mathematische Funktion, die vorgegebene einzelne Randverteilungen über eine Abhängigkeitsstruktur zu einer gemeinsamen Verteilung verbindet. Eine Korrelation allein legt diese gesamte Struktur nicht fest. Das eigene Kreditbeispiel konstruiert eine konkrete gemeinsame Bernoulli-Mischung und behauptet keine universelle reale Abhängigkeitsstruktur.','bonds-10','credit-risk','dependence'),
 G('Marginale PD','Ausfallwahrscheinlichkeit eines einzelnen Schuldners für sich betrachtet, unabhängig davon, wie seine Ereignisse mit denen anderer Schuldner zusammenhängen. Gleiche einzelne PDs erlauben sehr unterschiedliche gemeinsame Verlustverteilungen.','bonds-10','credit-risk','dependence','Rand-PD|Marginal Default Probability'),
 G('Rating Outlook','Zusätzliche Einschätzung einer Ratingagentur zu einer möglichen künftigen Ratingentwicklung nach deren eigener Methodik und Zeitsicht. Sie ist keine bereits vollzogene neue Note und garantiert weder einen Änderungstermin noch eine universelle exakte Änderungswahrscheinlichkeit.','bonds-11','credit-risk','rating-process', '',[{label:'Outlook',units:['credit-risk']}]),
 G('Credit Watch','Agenturspezifische Bezeichnung für eine besondere Überprüfung oder Beobachtung eines Kreditratings. Anlass, Richtung, Zeithorizont und Bedeutung werden in der konkreten Mitteilung gelesen. Sie ist nicht automatisch eine bereits vollzogene Herabstufung.','bonds-11','credit-risk','rating-process','Rating Watch',[{label:'Watch',units:['credit-risk']}]),
 G('Credit Spread','Nach einer angegebenen Referenz- und Bewertungsregel gemessener Aufschlag. Er kann sich durch Ausfallerwartung, Verlustschwere, Risikovergütung, Liquidität und weitere Marktbedingungen verändern. Er ist daher keine allgemeine exakte physische PD mal LGD. Benchmark, Laufzeit, Quote und Optionsbehandlung gehören zum Vergleich.','bonds-11','credit-risk','spread','Kreditspread|Kreditspreads',[{label:'Spread',units:['credit-risk']},{label:'Spreads',units:['credit-risk']}]),
 G('Bonität','Eingeschätzte Fähigkeit und Bereitschaft eines Schuldners, die betrachteten Verpflichtungen vollständig und rechtzeitig zu bedienen. Zahlungsquellen, Fälligkeiten, Umfeld und Anspruchsstruktur sind relevant. Eine Ratingnote ist eine methodische Verdichtung, keine Garantie dieser künftigen Fähigkeit.','bonds-11','credit-risk','ratings','Creditworthiness'),
 G('Ausfallindikator','Zufallsvariable mit eins bei Eintritt des definierten Ausfalls und null sonst. Ihr Erwartungswert ist die zugehörige PD. Erst die Verbindung mit Exposition und Verlustquote ergibt einen Geldverlust; gemeinsame Indikatoren erlauben eine präzise Definition der Ausfallkorrelation.','bonds-10','credit-risk','identity','Default Indicator'),
 G('Kreditrisiko','Risiko wirtschaftlicher Verluste durch nicht vollständige oder nicht rechtzeitige Zahlung eines Schuldners. Ereignis, Verpflichtung und Horizont müssen feststehen. Ausfallverlust und Marktwertverlust bei einer bloßen Spreadänderung sind verschiedene Messgegenstände.','bonds-10','credit-risk','default','Credit Risk'),
 G('Probability of Default','Wahrscheinlichkeit eines definierten Ausfallereignisses innerhalb eines angegebenen Horizonts unter einem benannten Informationsstand und Wahrscheinlichkeitsmaß. Eine Einjahres-PD ist weder der Verlustanteil im Ausfall noch automatisch die kumulative Mehrjahres-PD. Physische Prognose und risikoneutrales Bewertungsgewicht können verschieden sein.','bonds-10','credit-risk','pd','PD|Ausfallwahrscheinlichkeit'),
 G('Loss Given Default','Verlustschwere unter der Bedingung eines definierten Ausfalls. Als Quote gibt sie den verlorenen Anteil der passenden EAD an; als Geldbetrag muss sie ausdrücklich so bezeichnet werden und darf nicht noch einmal mit EAD multipliziert werden. Recovery, Kosten, Zeitpunkt und Forderungsbasis müssen konsistent sein.','bonds-10','credit-risk','lgd','LGD|Verlustquote|LGD-Quote|Verlustquote bei Ausfall'),
 G('Exposure at Default','Relevante exponierte Forderung zum Zeitpunkt eines definierten Ausfalls. Sie ist nicht automatisch das zugesagte Limit oder der heutige Marktwert; weitere Ziehungen, Tilgungen und aufgelaufene Ansprüche können sie verändern. Bei zufälliger Exposition wird die bedingte gemeinsame Verlustrechnung verwendet.','bonds-10','credit-risk','ead','EAD'),
 G('Expected Loss','Erwarteter Ausfallverlust für einen benannten Horizont: PD mal bedingte mittlere Verlustschwere in Geld. Bei fester EAD und passender bedingter LGD-Quote ergibt sich EAD mal PD mal LGD. Er ist ein Mittelwert, weder Obergrenze noch Verlustquantil und nicht automatisch die gesamte Marktvergütung für Kreditrisiko.','bonds-10','credit-risk','identity','EL|erwarteter Verlust|erwarteter Kreditverlust'),
 G('Ausfall-Recovery','Auf die ausdrücklich genannte Forderung bezogener wirtschaftlicher Rückgewinnungsanteil im Ausfall. Bruttoerlös, Nettoerlös und diskontierter Nettoerlös sind verschiedene Konventionen. Eins minus Recovery ist nur bei gleicher Basis und Kosten-/Zeitwertbehandlung die zugehörige LGD-Quote.','bonds-10','credit-risk','recovery-time','Netto-Recovery',[{label:'Recovery',units:['credit-risk']},{label:'Recovery Rate',units:['credit-risk']}]),
 G('Kumulative PD','Wahrscheinlichkeit eines erstmaligen definierten Ausfalls bis zu einem angegebenen Zukunftszeitpunkt. Sie folgt aus eins minus der Überlebenswahrscheinlichkeit. Bedingte jährliche Ausfallraten werden über die jeweils zuvor überlebende Gruppe verknüpft.','bonds-10','credit-risk','term-pd','Cumulative Default Probability|kumulative Ausfallwahrscheinlichkeit'),
 G('Überlebenswahrscheinlichkeit','Wahrscheinlichkeit, dass bis zum angegebenen Horizont noch kein definierter Ausfall eingetreten ist. Bei passend auf Überleben bedingten Jahresraten ist sie das Produkt der jährlichen Überlebensanteile.','bonds-10','credit-risk','term-pd','Survival Probability'),
 G('Bedingte Jahres-PD','Wahrscheinlichkeit des Ausfalls innerhalb eines bestimmten Jahres unter der Bedingung, bis zu dessen Beginn überlebt zu haben. Die heute unbedingte Erst-Ausfallwahrscheinlichkeit dieses Jahres multipliziert diese Rate zusätzlich mit der vorherigen Überlebenswahrscheinlichkeit.','bonds-10','credit-risk','pd-case','Conditional Default Probability'),
 G('Konzentrationsrisiko','Anfälligkeit durch hohe Exposition gegenüber einzelnen Schuldnern oder gemeinsamen Risikotreibern. Mehr Namen können unabhängige Einzelrisiken verteilen, beseitigen aber gemeinsame Abhängigkeiten nicht. Der erwartete Gesamtverlust kann bei festem Gesamtexposure gleich bleiben, obwohl sich Streuung und Verlustquantile stark ändern.','bonds-10','credit-risk','concentration','Concentration Risk'),
 G('Ausfallkorrelation','Korrelation der Ausfallindikatoren verschiedener Schuldner für denselben Horizont. Sie ist von der Korrelation ihrer Aktienrenditen oder einer latenten Modellgröße zu unterscheiden. Im eigenen transparenten Mischungsmodell entspricht sie bei mehreren Schuldnern und nicht entarteter PD dem Mischungsgewicht des gemeinsamen Ereignisses.','bonds-10','credit-risk','dependence','Default Correlation'),
 G('Kreditrating','Methodisch verdichtete Einschätzung relativer Kreditqualität eines Emittenten oder einer Verpflichtung. Agentur, Skala und Gegenstand gehören dazu. Es ist weder eine exakte universelle PD, eine Rückzahlungsgarantie noch eine Kaufempfehlung und deckt nicht automatisch Zins- oder Liquiditätsrisiko ab.','bonds-11','credit-risk','ratings','Credit Rating|Kreditratings',[{label:'Rating',units:['credit-risk']},{label:'Ratings',units:['credit-risk']}]),
 G('Emittentenrating','Kreditbeurteilung des bezeichneten Schuldners nach einer bestimmten Agenturmethodik. Die Kreditqualität einer einzelnen Verpflichtung kann zusätzlich durch Rang, Sicherheiten, Garantien und Struktur beeinflusst werden.','bonds-11','credit-risk','issue','Issuer Rating'),
 G('Emissionsrating','Beurteilung einer konkreten Schuldverpflichtung. Gegenüber der allgemeinen Emittentenbeurteilung können unter anderem Rang und erwarteter Vermögenszugriff relevant sein. Ein anderer Emissionsrang bedeutet nicht automatisch einen anderen operativen Schuldner.','bonds-11','credit-risk','issue','Issue Rating'),
 G('Split Rating','Unterschiedliche Einstufungen desselben betrachteten Gegenstands durch verschiedene Agenturen. Welche Note für eine Auswahl zählt, folgt der konkret verwendeten Regel; eine universelle automatische Auswahl wird nicht unterstellt.','bonds-11','credit-risk','scale'),
 G('Unrated','Im bezeichneten Ratingsystem nicht eingestuft. Das Fehlen einer Note ist kein Beweis besonders schlechter oder guter Bonität. Andere Informationen und eine eigene Analyse bleiben erforderlich.','bonds-11','credit-risk','scale','Not Rated'),
 G('Ratingmigration','Veränderung einer Ratingeinstufung. Eine Herabstufung kann über einen höheren geforderten Spread einen Marktpreisverlust begleiten, obwohl noch kein Ausfall eingetreten ist. Eine Spreadänderung ohne tatsächlich neue Note wird nicht automatisch Ratingmigration genannt.','bonds-11','credit-risk','migration','Rating Migration'),
 G('Spreadvolatilität','Schwankung eines ausdrücklich definierten Credit Spreads über einen angegebenen Zeitraum und eine Messfrequenz. Sie ist vom heutigen Spreadniveau und von der Varianz reiner Ausfallverluste zu unterscheiden. Die Preiswirkung hängt zusätzlich von der passenden Spreadsensitivität und anderen Faktoren ab.','bonds-11','credit-risk','volatility','Spread Volatility'),
 G('Physische PD','Ausfallwahrscheinlichkeit unter dem Realweltmaß als Prognose für eine bestimmte Definition und einen Horizont. Sie kann sich von dem risikoneutralen Gewicht unterscheiden, das einen gegebenen Marktpreis im verwendeten Bewertungsmodell erklärt.','bonds-10','credit-risk','pricing','Physical Default Probability'),
 G('Risikoneutrale PD','Ausfallgewicht im ausdrücklich benannten arbitragekonsistenten Bewertungsmodell. Es ist keine automatische tatsächliche Ausfallprognose. Zusammen mit Zahlungs- und Recoveryannahmen beeinflusst es den Modellpreis; ein Spread allein identifiziert es nicht universell.','bonds-10','credit-risk','pricing','Risk-Neutral Default Probability'),
 G('Diskretes Verlustquantil','Kleinster Verlustschwellenwert, bis zu dem mindestens das angegebene Konfidenzniveau Wahrscheinlichkeit liegt. Bei Wahrscheinlichkeitsmassen kann es sprunghaft wechseln und auch null sein, während der Mittelverlust positiv bleibt. Es ist keine Verlustobergrenze und nicht identisch mit dem mittleren Verlust jenseits der Schwelle.','bonds-10','credit-risk','quantile','Verlustquantil',[{label:'VaR',units:['credit-risk']},{label:'Value at Risk',units:['credit-risk']}]),
 G('Zinssensitivität','Beschreibung der Preis- oder Wertreaktion auf eine ausdrücklich angegebene Zinsrichtung. Eigene YTM, parallele Benchmarkverschiebung, einzelne Kurvenknoten und empirisch beobachtete Begleitbewegungen können verschiedene Richtungen sein. Relative Koeffizienten, Geldbeträge und historische Steigungen werden deshalb mit ihren jeweiligen Einheiten und kontrollierten Annahmen interpretiert.','bonds-08','curve-risk','risk-variable','Interest Rate Sensitivity',[{label:'Sensitivität',units:['curve-risk']},{label:'Sensitivitäten',units:['curve-risk']}]),
 G('Effective Duration','Zentrale relative Preissensitivität gegenüber einem ausdrücklich definierten Benchmarkkurvenschock. Sie wird aus dem vollen Preis nach negativem Schock minus dem Preis nach positivem Schock, geteilt durch zweimal Ausgangsvollpreis und halbe dezimale Schrittweite, geschätzt. Ein optionsgerechtes Modell bestimmt mögliche Ausübung und Zahlungen in jedem Szenario neu. Preisbasis, Kurve, Spread, Volatilitätsannahme und endliche Schrittweite gehören zur Definition.','bonds-08','curve-risk','effective','effektive Duration|EffDur'),
 G('Effective Convexity','Volle zentrale normierte zweite Preisdifferenz nach einer angegebenen Benchmarkkurvenbewegung einschließlich geänderter Optionsausübung. Die Summe der beiden Schockpreise minus zweimal Ausgangsvollpreis wird durch Ausgangspreis und Quadrat der halben Schrittweite geteilt. Der Taylorbeitrag enthält zusätzlich ein Halb. Das Maß kann bei Optionen negativ und bei diskreten Ausübungsknicken stark schrittweitenabhängig sein.','bonds-08','curve-risk','effective','effektive Konvexität|EffCon',[{label:'Konvexität',units:['curve-risk']}]),
 G('Key Rate Duration','Relative erste Preissensitivität nach einer bestimmten Benchmark-Knotenrichtung. Die vollständige Bumpform einschließlich Zwischenlaufzeiten, Quote und Bewertungsregel gehört zur Definition. Das Produkt jeder Knoten-Sensitivität mit ihrem eigenen dezimalen Schock und einem negativen Vorzeichen ergibt ihren linearen relativen Preisbeitrag. Eine einzelne Parallel-Duration enthält dieses gesamte Profil nicht.','bonds-08','curve-risk','key-definition','KRD|Key Rate Durations|Key-Rate-Duration'),
 G('Empirical Duration','Aus beobachteten Preis- oder ausdrücklich bereinigten Renditeänderungen und Benchmarkänderungen geschätzte Sensitivität. Bei einer einfachen Dezimal-zu-Dezimal-Regression ist sie die negative Steigung. Sie kann gemeinsam bewegte Spreads und weitere Faktoren aufnehmen und hängt von Datenfenster, Einheiten und Marktphase ab. Sie ist daher nicht automatisch dieselbe kontrollierte Ableitung wie bei festem Spread.','bonds-08','curve-risk','empirical-definition','empirische Duration'),
 G('Analytical Duration','Aus einem angegebenen Bewertungsmodell abgeleitete erste Zinssensitivität entlang einer kontrollierten Richtung. Welche Kurve oder Quote verändert wird und welche übrigen Eingaben konstant bleiben, muss benannt sein. Eine analytische Benchmark-Duration bei festem Spread kann von einer historischen Ein-Faktor-Steigung abweichen, ohne dass eine der Rechnungen allein deshalb falsch ist.','bonds-08','curve-risk','risk-variable','analytische Duration',[{label:'Benchmark-Duration',units:['curve-risk']}]),
 G('Key-Rate-Vektor','Geordnete Folge der Knoten-Sensitivitäten einer Position oder eines Portfolios. Zusammen mit dem gleich definierten Knotenschockvektor bestimmt er die erste Preisänderungsnäherung. Gleiche Summen können unterschiedliche Laufzeitverteilungen enthalten und auf Kurvendrehungen verschieden reagieren.','bonds-08','curve-risk','key-case','Key Rate Vector|Key-Rate-Profil'),
 G('Parallel Duration','Normierte erste Preisreaktion auf einen ausdrücklich definierten gemeinsamen parallelen Benchmarkkurvenschritt. Sie entspricht der Summe analytischer Key Rate Durations, wenn deren Bumpbasis gemeinsam genau diese Richtung reproduziert und die übrigen Bewertungsannahmen übereinstimmen. Endliche Schätzungen und andere Kurvenrichtungen benötigen einen eigenen Abgleich.','bonds-08','curve-risk','key-sum','Parallel-Duration|parallele Duration'),
 G('Kurvenschock','Vorgegebenes Szenario einer Änderung von Benchmarkkurvenquoten. Es kann einen gemeinsamen Parallelwert oder verschiedene Knotenwerte enthalten. Quote, Laufzeitbereiche, Interpolation und festgehaltene Modellannahmen bestimmen die tatsächliche Bewertungsrichtung. Ein gleicher Durchschnittswert beschreibt eine Kurvenverformung nicht vollständig.','bonds-08','curve-risk','basis','Curve Bump|Benchmark Curve Shock|Bump'),
 G('Bumpbasis','Vereinbarte Richtungsfunktionen, mit denen einzelne Knotenänderungen auf die gesamte bewertungsrelevante Kurve übertragen werden. Stückweise lineare Gewichte sind eine mögliche Wahl. Wenn sie sich überall zur gemeinsamen Parallelbewegung addieren, summieren sich auch die entsprechenden lokalen ersten Knotenbeiträge. Andere Randbedingungen oder Parameter können andere Profile erzeugen.','bonds-08','curve-risk','basis','Bump Basis|Key-Rate Basis|Bump Shape'),
 G('Einseitige effektive Duration','Relativer Preisgewinn nach einem festgelegten Benchmarkrückgang oder relativer Verlust nach einem gleich definierten Benchmarkanstieg, jeweils geteilt durch den positiven Schockbetrag. Die beiden Seiten können bei Optionen verschieden sein. Ihr Mittel ergibt die entsprechende zentrale effektive Duration bei derselben Preisbasis und Schrittweite.','bonds-08','curve-risk','one-sided','One-Sided Effective Duration|Up Effective Duration|Down Effective Duration'),
 G('Zinsbaumkalibrierung','Anpassung der Modellkurzraten oder anderer freigegebener Parameter, sodass der Baum die vorgegebene Benchmark-Diskontstruktur unter seiner Volatilitäts- und Gewichtungsregel reproduziert. Nach einem Kurvenschock wird die neue Struktur konsistent hergestellt. Eine freie Spreadanpassung zum bloßen Wiederherstellen des alten Bondpreises wäre ein anderes Experiment.','bonds-15','curve-risk','tree-calibration','Interest-Rate Tree Calibration'),
 G('Ausübungspolitik','Regel, die festlegt, ob und wann ein Optionsinhaber sein vertragliches Recht unter den jeweiligen Zuständen ausübt. Im einfachen wirtschaftlichen Modell vergleicht der Emittent den Fortsetzungsanspruch mit dem Kündigungsbetrag, der Anleger den Anspruch mit seinem Rückgaberecht. Kuponreihenfolge, Fristen, Kosten und Vertrag bestimmen die tatsächlich zulässigen Entscheidungen.','bonds-15','curve-risk','option-tree','Exercise Policy'),
 G('Hesse-Matrix','Matrix der zweiten partiellen Ableitungen einer skalaren Funktion nach ihren Eingaben. Bei mehreren Kurvenknoten beschreibt sie eigene und gemischte zweite Preisreaktionen. Für eine relative Preisnäherung werden die Einträge zusätzlich durch den vollen Ausgangspreis normiert; eine einzelne Parallel-Konvexität bestimmt diese gesamte Matrix nicht.','bonds-08','curve-risk','vector-convexity','Hessian|Hessian Matrix'),
 G('Partielle Ableitung','Lokale Änderungsrate einer Funktion nach einer einzelnen Eingabe bei festgehaltenen anderen Modellparametern. Bei einem Kurvenknoten muss die zugehörige Bump- und Interpolationsregel mitdefiniert sein. Eine entlang mehrerer gemeinsam veränderter Eingaben beobachtete Steigung muss nicht dieselbe partielle Ableitung sein.','bonds-08','curve-risk','key-definition','Partial Derivative'),
 G('Beobachtungsfenster','Ausgewählter Zeitraum und zugehörige Beobachtungsmenge einer empirischen Schätzung. Länge, Datenhäufigkeit, Marktphase und Zusammensetzung können den geschätzten Zusammenhang verändern. Ein größerer Datensatz ersetzt nicht die Prüfung, ob seine gemeinsame Faktorbewegung zur heutigen Risikofrage passt.','bonds-08','curve-risk','regimes','Sample Window'),
 G('Money Convexity','Zweite Ableitung des vollen Positionsmarktwerts nach der angegebenen dezimalen jährlichen Yieldquote. Sie entspricht Marktwert mal relativer Konvexität. Der quadratische Geldbeitrag ist die Hälfte dieses Koeffizienten mal dem Quadrat des konsistenten Yieldschocks. Der Koeffizient selbst ist weder Preisgewinn noch Gewinnwahrscheinlichkeit; bei Shortpositionen ist das Vorzeichen zu berücksichtigen.','bonds-08','convexity','money','Dollar Convexity|Geldkonvexität'),
 G('Konvexitätsanpassung','Quadratischer Zusatz einer lokalen Preisnäherung: ein Halb mal volle normierte zweite Preisableitung mal quadrierte dezimale Yieldänderung. Bei einem unveränderten positiven festen Zahlungsplan ist er in beiden Schockrichtungen positiv. Er korrigiert einen Teil des Fehlers der Durationgeraden; er ersetzt keine vollständige Neubewertung und keine Haltedauerrendite.','bonds-08','convexity','units','Convexity Adjustment|Konvexitätsbeitrag'),
 G('Periodenkonvexität','Normierte zweite Preisableitung nach der Yieldrate einer einzelnen Verzinsungsperiode. Bei nominaler Jahresquote gleich Periodenrate mal Frequenz wird die Periodenkonvexität durch das Quadrat der Frequenz geteilt. Die Schockquote muss zur verwendeten Ableitungsvariable passen.','bonds-08','convexity','frequency','Periodic Convexity'),
 G('Portfoliokonvexität','Normierte zweite Ableitung des Gesamtmarktwerts entlang einer ausdrücklich definierten gemeinsamen Risikorichtung. Bei identischer additiver Änderung konsistenter eigener Jahres-Yields ist sie das marktwertgewichtete Mittel der Einzelkonvexitäten. Eine beliebige Kurvenverformung, geänderte Spreads oder Netto-Marktwert null verlangen eine andere beziehungsweise unnormierte Rechnung.','bonds-08','convexity','portfolio','Portfolio Convexity'),
 G('Barbell-Portfolio','Anleiheportfolio mit Wertschwerpunkten in einem kurzen und einem langen Laufzeitbereich. Beim kontrollierten Vergleich mit einem mittleren Bullet werden Anfangsmarktwert, Yieldkonvention und Duration angeglichen. Größere Zahlungsstreuung erhöht unter diesen Bedingungen die Konvexität; sie garantiert nach Kosten, Finanzierung und verstrichener Zeit keinen Strategiegewinn.','bonds-08','convexity','barbell','Barbell|Barbell Portfolio|Barbell-Position'),
 G('Bullet-Portfolio','Portfolio mit konzentriertem Laufzeitbereich um einen mittleren Termin. Im Konvexitätsmodell ist es ein einzelner Nullkupon zum barwertgewichteten Termin der Vergleichs-Barbell, mit gleichem Anfangsmarktwert und gleicher Duration. Diese Portfoliostruktur ist von einem Bullet Bond zu unterscheiden: Ein endfälliger Bond kann davor zahlreiche Kupons zahlen.','bonds-08','convexity','barbell','Bullet Portfolio|Bulletvergleich|Bullet-Position',[{label:'Bullet',units:['convexity','curve-risk']}]),
 G('Zweite zentrale Preisdifferenz','Summe der Preise nach gleich großem positivem und negativem Yieldschritt minus zweimal Ausgangspreis. Division durch Ausgangspreis und Quadrat der halben Schrittweite schätzt die volle normierte zweite Ableitung. Ein zusätzlicher Faktor zwei im Nenner wäre falsch. Zu starke Preisrundung kann das kleine Differenzergebnis überdecken.','bonds-08','convexity','finite','Central Second Price Difference'),
 G('Portfolio-IRR','Einzelner interner Zins, der den aggregierten kompatiblen Zahlungsplan auf seinen gesamten heutigen Preis diskontiert. Auch wenn dieser Preis reproduziert wird, muss die Sensitivität nach diesem einheitlichen Zins nicht der Sensitivität entlang der ursprünglichen unterschiedlichen Spot- oder Einzel-Yields entsprechen. Gleicher Preis bedeutet nicht automatisch gleiche Ableitungen.','bonds-08','convexity','aggregate-case','Portfolio IRR'),
 G('Gemeinsame Yieldverschiebung','Gleiche additive Änderung der ausdrücklich angegebenen jährlichen Yieldquote jeder betroffenen Position. Quotierung und Schockeinheit müssen zusammenpassen. Diese Richtung erlaubt marktwertgewichtete erste und zweite Portfoliosensitivitäten. Sie ist nicht automatisch identisch mit jeder parallelen Benchmarkkurvenbewegung oder mit einer nicht parallelen Kurvenverformung.','bonds-08','convexity','parallel','Common Yield Shift'),
 G('Jensen-Ungleichung','Für eine konvexe Funktion mit nicht negativen Gewichten der Summe eins ist ihr gewichteter Funktionswert mindestens so groß wie der Funktionswert des gewichteten Mittels. Im flachen Nullkuponvergleich erklärt die Konvexität des Preisfaktors nach dem Zahlungstermin die Barbell-/Bullet-Ordnung. Diese besondere Modellordnung ist kein allgemeiner Gewinnsatz für alle Portfolios mit höherer Anfangskonvexität.','bonds-08','convexity','jensen','Jensen Inequality'),
 G('Money Duration','Voller Positionsmarktwert multipliziert mit Modified Duration. Hier wird sie als positive Verlustsensitivität einer Longposition je Einheit der dezimalen jährlichen Yieldquote angegeben; die vorzeichenbehaftete Wertableitung ist ihr negatives Gegenstück. Für einen Prozentpunkt wird mit 0,01, für einen Basispunkt mit 0,0001 multipliziert. Nominalbestand ist nicht automatisch Marktwert.','bonds-08','duration','money','Dollar Duration|Geld-Duration'),
 G('DV01','Geldbetrag für eine Änderung der ausdrücklich angegebenen Yieldquote um einen Basispunkt. Lineare Ableitungsschätzung, tatsächlicher Ein-bp-Anstiegsverlust, Ein-bp-Rückgangsgewinn und zentrale Neubewertungsdifferenz sind bei gekrümmten Preisfunktionen ähnlich, aber nicht exakt gleich. Verfahren, Währung, Bestand und Vorzeichenkonvention müssen genannt werden.','bonds-08','duration','pvbp','PVBP|BPV|Price Value of a Basis Point|Dollar Value of 01|Dollar Value of a Basis Point'),
 G('Yield Duration','Preissensitivitätsmaß gegenüber einer ausdrücklich bezeichneten Änderung der eigenen Bondrendite bei unverändertem Zahlungsplan. Es ist von einer Verschiebung einzelner Spotlaufzeiten oder modellabhängig veränderter Optionscashflows zu unterscheiden. Macaulay, Modified und daraus skalierte Geldmaße hängen unter passenden Konventionen zusammen.','bonds-08','duration','own-yield','YTM-Sensitivität'),
 G('Yield-Koordinate','Genaue Definition der Renditegröße, nach der eine Preisableitung gebildet wird. Nominale halbjährlich verzinste Jahres-YTM und effektive Jahres-YTM können denselben Ausgangspreis repräsentieren, haben aber unterschiedlich skalierte Ein-bp-Schritte. Die Kettenregel verbindet ihre Modified-Duration-Zahlen.','bonds-08','duration','coordinate','Yield Coordinate'),
 G('Relative Zinssensitivität','Normierte Preisänderung je Änderung einer angegebenen Zinsgröße. Bei der Modified Duration wird die negative Preisableitung durch den Vollpreis geteilt. Das Maß allein sagt noch keinen Geldverlust aus; dazu werden Marktwert und Schockgröße benötigt.','bonds-08','duration','modified','Relative Interest Rate Sensitivity'),
 G('Zentrale Yield-Differenz','Numerische Schätzung einer lokalen Preissteigung aus Neubewertungen bei symmetrisch kleinerem und größerem Yield. Die Preisdifferenz wird durch den vollständigen Yieldabstand geteilt und für Modified Duration zusätzlich durch den Ausgangspreis normiert. Eine Halb-Differenz ist nur beim angegebenen Ein-bp-Schritt direkt eine zentrale Ein-bp-Schätzung.','bonds-08','duration','finite','Central Yield Difference'),
 G('Einseitige PVBP','Aus einer ausdrücklich gerichteten Neubewertung gewonnener Geldbetrag für einen Basispunkt Yieldänderung. Bei positiven festen Cashflows ist der Verlust bei einem Anstieg meist etwas kleiner als der Gewinn bei einem gleich großen Rückgang. Die Richtung wird deshalb angegeben und von einer zentralen oder analytischen Näherung getrennt.','bonds-08','duration','one-bp','One-Sided PVBP'),
 G('Nominalbestand','Vertragliche Nennbetragssumme der gehaltenen Anleiheposition. Bei einer Preisquote je hundert ergibt sich der Marktwert aus Nominalbestand mal Vollpreis geteilt durch hundert. Zwei Positionen mit gleichem Nominal können wegen verschiedener Preisquoten unterschiedliche Marktwerte haben.','bonds-08','duration','position','Face Amount Held'),
 G('Positionsmarktwert','Voller aktueller Wert des gehaltenen Bestands in Währungseinheiten. Bei Anleihen mit Quote je hundert Nominal wird die gesamte volle Preisquote einschließlich etwaiger Stückzinsen verwendet. Money Duration skaliert die relative Sensitivität mit diesem Marktwert, nicht pauschal mit dem Nominal.','bonds-08','duration','position','Position Market Value'),
 G('DV01-Matching','Abstimmung entgegengesetzter Positionen auf denselben absoluten Ein-Basispunkt-Geldbeitrag in einer gemeinsamen Zinsrichtung. Es kann den ersten lokalen gemeinsamen Yield-Effekt neutralisieren. Unterschiedliche Creditspreads, Kurvenknoten, Konvexität, Liquidität und Finanzierung sind dadurch nicht automatisch abgesichert.','bonds-08','duration','hedge','PVBP Matching|DV01 Matching'),
 G('Preisnormierung','Division einer absoluten Preisreaktion durch den passenden Ausgangspreis, um eine relative Sensitivität zu bilden. Bei Modified Duration ist dieser Nenner der volle Preis des Zahlungsplans. Ein anderer Nenner oder eine andere Renditekoordinate verändert die resultierende Zahl und verlangt eine explizite Umrechnung.','bonds-08','duration','modified','Price Normalization'),
 G('Taylor-Näherung','Lokale Annäherung einer Funktion durch Wert und Ableitungen an einem Ausgangspunkt. Bei festen Bondcashflows liefert Modified Duration den linearen Preisbeitrag; die zweite Preisableitung ergänzt Krümmung. Je weiter ein Schock vom Ausgangspunkt entfernt ist, desto eher wird vollständige Neubewertung erforderlich.','bonds-08','duration','tangent','Taylor-Näherungen'),
 G('Anlagehorizont','Zeitraum vom betrachteten Anlagebeginn bis zu dem Termin, an dem Vermögen bewertet, entnommen oder für einen bestimmten Zweck gebraucht wird. Er ist nicht automatisch die Restlaufzeit eines gehaltenen Bonds. Vor dessen Fälligkeit ist ein Verkauf nötig, danach gegebenenfalls eine Wiederanlage der Tilgung.','bonds-09','bond-return','timeline','Investment Horizon'),
 G('Endvermögen','Gesamter Wert am ausdrücklich genannten Horizont. Bereits erhaltene Zahlungen werden mit ihren tatsächlichen oder angenommenen Wiederanlagefaktoren auf diesen Termin gebracht; hinzu kommt der Wert noch offener Ansprüche. Kaufpreis und Endvermögen bestimmen den Geldgewinn und die geometrisch annualisierte Vermögensrendite.','bonds-09','bond-return','terminal','Terminal Wealth'),
 G('Barwertgewicht','Anteil des Barwerts einer einzelnen Zahlung am gesamten Vollpreis des Zahlungsplans. Bei nicht negativen Zahlungen und positiver Diskontbasis sind diese Gewichte nicht negativ und summieren sich zu eins. Macaulay Duration gewichtet die Zeitpunkte mit genau diesen Preisanteilen.','bonds-09','bond-return','mac-definition','Present-Value Weight|Present Value Weight'),
 G('Kursrisiko','Unsicherheit des Marktwerts noch ausstehender Ansprüche. Im festen optionsfreien Zahlungsplan senkt ein höherer geforderter Diskontzins deren Preis. Für einen frühen Verkäufer kann dieser Effekt die bessere Kuponwiederanlage überwiegen. Ausfall-, Spread- und Liquiditätsänderungen können weitere Preisrisiken erzeugen.','bonds-09','bond-return','short','Price Risk'),
 G('Wiederanlagefaktor','Kapitalfaktor, der einen bereits erhaltenen Geldbetrag vom Empfangstermin auf einen bestimmten späteren Horizont bringt. Er kann mehrere unterschiedliche zeitliche Zinsabschnitte verketten. Ein Faktor kleiner als eins bedeutet einen Verlust auf den angelegten Betrag, nicht automatisch einen negativen vertraglichen Kupon.','bonds-09','bond-return','path','Reinvestment Factor'),
 G('Zins auf Kupons','Zusätzlicher Endbetrag aus der Wiederanlage bereits erhaltener Kupons, getrennt von den Kuponbeträgen selbst. Werden die ursprünglichen Kupons schon gezählt, wird nur dieser zusätzliche Zins ergänzt; alternativ werden direkt ihre vollständigen Endwerte summiert. Negative Wiederanlagesätze können einen negativen Zusatzbetrag ergeben.','bonds-09','bond-return','profit','Interest on Coupons|Coupon Reinvestment Income'),
 G('Horizontanalyse','Szenariorechnung, die Zahlungen, Wiederanlage und den Verkauf oder die Tilgung einer Anlage auf einen gemeinsamen Endtermin bezieht. Sie fragt nach dem Vermögen und der Rendite eines konkreten historischen Kaufs. Die beim späteren Marktpreis geltende Einstiegs-YTM eines neuen Käufers ist eine andere Größe.','bonds-09','bond-return','one-rate','Horizon Analysis'),
 G('Horizontmatching','Abstimmung eines festen Anlagehorizonts mit der anfänglichen Macaulay Duration. Im unveränderten positiven Zahlungsplan mit einmaliger sofortiger gemeinsamer Zinsänderung für Bewertung und Wiederanlage verschwindet dadurch der erste lokale Zinseinfluss auf das Endvermögen. Es ist keine Garantie gegen große oder nicht parallele Schocks, dynamische Pfade oder Kreditausfall.','bonds-09','bond-return','horizon-derivative','Horizon Matching|Duration Horizon Matching'),
 G('Barwertgewichtete Zeitvarianz','Streuung der Zahlungstermine um die Macaulay Duration, gewichtet mit ihren normierten Barwerten. Ihre Einheit ist Jahre zum Quadrat. Sie erklärt die Yieldabhängigkeit der Macaulay Duration und im einheitlichen Horizontmodell die verbleibende Krümmung am passenden Horizont; sie ist keine Volatilität zufälliger Anleiherenditen.','bonds-09','bond-return','yield','PV-Weighted Time Variance'),
 G('Historischer Kaufpreis','Tatsächlich bezahlter voller Einsatz eines konkreten früheren Kaufs. Für dessen realisierte Vermögensrendite wird dieser Preis durch einen später veränderten Marktpreis nicht rückwirkend ersetzt. Bei der Anleihe gehört gegebenenfalls der Stückzins zum bezahlten Vollpreis.','bonds-09','bond-return','short','Historical Purchase Price'),
 G('Tilgungswiederanlage','Erneute Anlage bereits zurückgezahlten Nominals bis zu einem noch späteren Bedarfstermin. Sie kann auch bei einem Nullkuponbond nötig sein, wenn der gewünschte Anlagehorizont nach dessen einziger Endzahlung liegt. Die ursprüngliche Bond-YTM allein bestimmt diese spätere zusätzliche Rendite nicht.','bonds-09','bond-return','after-maturity','Principal Reinvestment'),
 G('Einmaliger Zinsschock','Modellannahme einer genau einmaligen unmittelbaren Änderung des Diskont- und gegebenenfalls Wiederanlagezinses. Danach werden die angegebenen neuen Bedingungen konstant gehalten. Sie isoliert einen Mechanismus und darf nicht stillschweigend auf einen späteren oder mehrfach veränderten realen Zinspfad übertragen werden.','bonds-09','bond-return','one-rate','One-Time Yield Shock'),
 G('Restverkaufspreis','Vollwert der zum Verkaufszeitpunkt noch ausstehenden Ansprüche. Bereits separat erhaltene Kupons sind nicht nochmals darin enthalten. Beim Verkauf zwischen Kuponterminen müssen Abrechnungspreis, Stückzinsen, Restzeiten und verwendete Zinskonvention zusammenpassen.','bonds-09','bond-return','timeline','Remaining Sale Price'),
 G('Periodenduration','Macaulay Duration ausgedrückt als barwertgewichtete Zahl von Kuponperioden. Division durch die Kuponperioden pro Jahr liefert die Duration in Jahren. Eine Zahl von acht Halbjahresperioden bedeutet vier Jahre und darf nicht als acht Jahre interpretiert werden.','bonds-09','bond-return','periods','Duration in Periods'),
 G('Preisadditivität','Bewertungsprinzip, nach dem sich der Preis eines kombinierten Zahlungsplans aus den Preisen seiner einzelnen passenden Zahlungsbausteine ergibt. Identische Termine, Währung, Ansprüche und vergleichbare Handelsbedingungen sind Voraussetzung. Die Kosten eines replizierenden Nullkuponkorbs können deshalb mit dem Vollpreis eines entsprechenden Kuponbonds verglichen werden.','bonds-06','yield-curves','cashflows','Price Additivity'),
 G('Spotkurve','Folge heutiger Zinssätze für einzelne Zahlungen zu unterschiedlichen Endterminen. Jeder Spot beginnt heute und umfasst die gesamte Laufzeit bis zu seinem Endtermin. Verzinsung, Währung und Anspruchsbasis müssen zur zugehörigen Diskontkurve passen.','bonds-06','yield-curves','spot','Spot Curve|Zero Curve|Zero-Coupon Curve'),
 G('Parkurve','Folge der Kuponraten hypothetischer Benchmarkbonds, die bei der gegebenen Diskontkurve genau zu pari bewertet werden. Jeder Laufzeitpunkt bezeichnet einen eigenen Bond mit eigener Kuponstruktur. Kuponfrequenz, Tilgung und Bewertungszeitpunkt gehören zur Definition.','bonds-06','yield-curves','par','Par Curve|Par Yield Curve'),
 G('Forwardkurve','Darstellung heute impliziter Zinssätze für ausdrücklich definierte künftige Zeitabschnitte. Endliche Jahresforwards und momentane Forwards sind verschiedene Darstellungen. Die Raten folgen aus Faktorquotienten und sind keine sicheren Prognosen später beobachteter Spots.','bonds-06','yield-curves','forward','Forward Curve'),
 G('Par-Kuponrate','Konstante Kuponrate, die Kuponbarwerte und Endtilgungsbarwert eines passend definierten Benchmarks genau auf sein Nominal bringt. Sie hängt von allen Kuponterminfaktoren ab und ist nicht allgemein gleich dem letzten Spot. Ein mathematisch negativer Wert bedeutet negative Kuponpflichten dieses hypothetischen Benchmarks.','bonds-06','yield-curves','par','Par Rate|Par Yield|Parrate|Parrendite|Par Coupon Rate'),
 G('Einperiodenforward','Heute aus der Kurve abgeleitete Rate nur für einen einzelnen festgelegten künftigen Zinsabschnitt. Ein Einjahresforward vom zweiten zum dritten Jahr ist nicht der Dreijahresdurchschnitt seit heute. Anfang, Ende und Quotierung müssen angegeben sein.','bonds-06','yield-curves','forward','One-Period Forward Rate|Einjahresforward'),
 G('Mehrperiodenforward','Implizite Rate für einen später beginnenden Abschnitt, der mehrere Jahre oder Zinsperioden umfasst. Der Gesamtfaktor des Abschnitts wird mit der passenden Wurzel annualisiert; Gesamtzuwachs und jährliche Rate sind unterschiedliche Größen.','bonds-06','yield-curves','multi-period','Multi-Period Forward Rate'),
 G('Forwardabschnitt','Der ausdrücklich bestimmte Zeitraum zwischen dem künftigen Beginn und dem späteren Ende einer Forwardverzinsung. Das Endjahr allein reicht nicht aus. Seine Länge entscheidet über die Wurzel bei einer effektiven Jahresannualisierung.','bonds-06','yield-curves','multi-period','Forward Interval'),
 G('Momentanforward','Grenzrate eines infinitesimal kurzen künftigen Zinsabschnitts auf einer hinreichend glatten Kurve. Sie ist bei stetiger Darstellung die negative Ableitung des logarithmierten Diskontfaktors. Ein endlicher Jahresforward ist nicht automatisch derselbe Wert.','bonds-06','yield-curves','instantaneous','Instantaneous Forward Rate|momentane Forwardrate'),
 G('Stetiger Spotzins','Jährliche Spotquote, die den Faktor über eine Exponentialfunktion mit stetiger Verzinsung ausdrückt. Sie kann denselben Faktor wie eine passend umgerechnete periodische Quote darstellen, ist aber bei gleicher sichtbarer Prozentzahl nicht allgemein mit ihr identisch.','bonds-06','yield-curves','conventions','Continuously Compounded Spot Rate'),
 G('Zinskurven-Bootstrapping','Sukzessiver Kurvenaufbau: Bereits bekannte frühere Cashflow-Barwerte werden aus einem passenden Instrumentpreis herausgerechnet, um den nächsten unbekannten Diskontfaktor zu bestimmen. Es ist kein statistisches Resampling. Zusätzliche unbekannte Termine benötigen zusätzliche Daten oder Modellannahmen.','bonds-06','yield-curves','bootstrap','Yield Curve Bootstrapping',[{label:'Bootstrapping',units:['yield-curves']}]),
 G('Kurvenknoten','Explizit festgelegter Laufzeitpunkt einer Zins- oder Diskontkurve. Ein Knoten kann aus einem Instrument identifiziert oder durch ein Modell geschätzt sein. Zwischenwerte erfordern eine benannte Interpolations- oder Schätzregel.','bonds-06','yield-curves','interpolation','Curve Node|Zinsknoten'),
 G('Loglineare Faktorinterpolation','Ergänzung zwischen bekannten positiven Diskontfaktoren durch lineare Interpolation ihrer natürlichen Logarithmen. Sie erhält die Randknoten, erzeugt aber nicht allgemein dieselben Zwischenwerte wie lineare Spot- oder Faktorinterpolation. Die gewählte Methode gehört zur Modellbeschreibung.','bonds-06','yield-curves','interpolation','Log-Linear Discount Factor Interpolation'),
 G('Par-Benchmark','Hypothetischer Kuponbond, dessen konstant berechnete Kuponrate ihn unter der gewählten Kurve genau zu pari bewerten lässt. Die vollständige Kuponfrequenz, Endtilgung und Zeitbasis müssen feststehen. Er ist von einem tatsächlich beobachteten Bond mit beliebigem Vertragskupon zu unterscheiden.','bonds-06','yield-curves','par-case','Par Benchmark'),
 G('Zinsreplikation','Nachbildung eines bestimmten Zins-Zahlungsprofils durch kombinierte Anlagen und Finanzierungen mit passenden Terminen. Jeder Anfangs-, Zwischen- und Endfluss wird berücksichtigt. Eine aus Faktorgleichheit abgeleitete Arbitrageaussage verlangt zusätzlich ausführbare vergleichbare Konditionen.','bonds-06','yield-curves','replication','Forward-Replikation',[{label:'Replikation',units:['yield-curves']}]),
 G('Kurvenschätzung','Bestimmung einer Zins- oder Diskontkurve aus ausgewählten Marktinstrumenten und Modellannahmen. Glättung und Instrumentauswahl können dazu führen, dass nicht jeder Preis exakt getroffen wird. Ein Modellrestfehler allein beweist keine handelbare Arbitrage.','bonds-06','yield-curves','estimation','Yield Curve Estimation'),
 G('Ein-Kurven-Modell','Vereinfachte Bewertungswelt, in der passende Zahlungs- und Zinszusammenhänge aus einer konsistenten Kurve abgeleitet werden. Unterschiedliche Kredit-, Sicherheiten- und Fundingbedingungen können in realen Anwendungen mehrere Kurven erfordern.','bonds-06','yield-curves','curve-choice','Single-Curve Model'),
 G('Zinsstrukturkurve','Beziehung zwischen Laufzeit und einer klar definierten Zinsquote auf einer angegebenen Instrument- und Währungsbasis. Spot-, Par- und Forwardkurven sind verschiedene Darstellungen; sie bezeichnen nicht überall denselben Zeitraum oder dieselben Cashflows. Datum und Quotierung gehören zur Interpretation.','bonds-06','yield-curves','map','Yield Curve|Renditekurve|Zinskurve|Zinsstruktur'),
 G('Diskontkurve','Folge positiver heutiger Preisfaktoren für Zahlungen an verschiedenen zukünftigen Terminen. Aus ihr können passende Spot-, Par- und Forwardraten abgeleitet werden. Bei negativen Zinsen können einzelne Faktoren über eins liegen; die konkrete Kurve muss zum Anspruch passen.','bonds-06','yield-curves','discount','Discount Curve'),
 G('Forwardfaktor','Impliziter Wachstumsfaktor eines später beginnenden Zinsabschnitts, gewonnen aus dem Verhältnis der heutigen Diskontfaktoren von Beginn und Ende. Bei einem mehrjährigen Abschnitt wird er erst durch eine passende Wurzel zur jährlichen Effektivrate.','bonds-06','yield-curves','forward','Forward Growth Factor'),
 G('Market Reference Rate','Vertraglich definierte Markt-Referenzrate, auf die sich ein variabler Kupon bezieht. Zu ihrer Bedeutung gehören Index, Festsetzungszeitpunkt, Tagesregel und etwaige Aufzinsung. Eine ähnlich benannte andere Referenz muss nicht dieselben Zahlungen erzeugen.','bonds-02','floating-yields','coupon','Markt-Referenzzins',[{label:'MRR',units:['floating-yields']}]),
 G('Quoted Margin','Im Floatervertrag festgelegter Aufschlag oder Abschlag zur maßgeblichen Referenzrate. Er bestimmt die Kuponzahlung und bleibt bei einem unveränderten Vertrag grundsätzlich fest. Die später vom Markt geforderte Discount Margin kann davon abweichen.','bonds-02','floating-yields','margins','Vertragsmarge|vertragliche Marge',[{label:'QM',units:['floating-yields']}]),
 G('Discount Margin','Im jeweiligen Floater-Bewertungsmodell geforderter jährlicher Aufschlag zur Referenzrate, der angenommene Cashflows und Vollpreis in Einklang bringt. Sie ist von der festen Vertragsmarge und vom Geldmarkt-Diskontsatz verschieden. Ihre Zahl hängt auch von Referenz-, Zeit- und Cashflow-Annahmen ab.','bonds-02','floating-yields','dm-root','Required Margin|geforderte Marge',[{label:'DM',units:['floating-yields']}]),
 G('Flache Referenzannahme','Vereinfachung einer Floaterrechnung, bei der sämtliche künftigen Referenzraten gleich der gegenwärtigen Rate gesetzt werden. Sie legt einen bedingten Zahlungsplan fest und ist keine Garantie oder Beobachtung einer tatsächlich flachen künftigen Zinsentwicklung.','bonds-02','floating-yields','flat-model','Flat Reference Assumption'),
 G('Perioden-IRR','Interner Zinssatz pro genau definierter Zahlungsperiode. Bei regulären Quartalen liefert die Multiplikation mit vier eine nominale Jahresquote; eine effektive Jahresrate entsteht dagegen aus dem vierfachen Zinseszinsfaktor. Rate und Periodenlänge gehören zusammen.','bonds-02','floating-yields','dm-root','Periodic IRR'),
 G('Referenzzinsduration','Preisempfindlichkeit eines variablen Zahlungsanspruchs gegenüber Änderungen der maßgeblichen Referenzzinsen. Sie kann bei einem einfachen Floater eher von der Zeit bis zum nächsten Reset als von der Endfälligkeit bestimmt werden. Geänderte Kreditaufschläge oder bindende Optionen sind damit nicht automatisch abgesichert.','bonds-02','floating-yields','base-vs-spread','Reference Rate Duration'),
 G('Spread-Duration','Sensitivität des Preises gegenüber einer definierten Änderung des geforderten Aufschlags bei sonst festgehaltenen Bewertungsannahmen. Bei einem Floater kann sie trotz kurzer Referenzzinsbindung erheblich sein, weil der Vertragsaufschlag über die gesamte Restlaufzeit gilt. Die genaue Definition verlangt das verwendete Spreadmaß und Modell.','bonds-02','floating-yields','base-vs-spread','Spread Duration'),
 G('Zinsfestsetzung im Voraus','Vertragsregel, bei der die für eine Zinsperiode maßgebliche Rate bereits zu deren Beginn oder einem vorher festgelegten Termin feststeht. Die spätere Zahlung bleibt bis zum nächsten Reset durch diese Festsetzung gebunden. Das Zahlungsdatum ist davon zu unterscheiden.','bonds-02','floating-yields','timing','In Advance|Reset in Advance'),
 G('Zinsfestsetzung im Nachhinein','Regel, bei der die für eine Periode relevante Rate oder aufgelaufene Verzinsung erst im Verlauf oder am Ende dieser Periode bestimmbar wird. Die konkrete tägliche Beobachtung, Aufzinsung und Zahlungsverschiebung folgen dem Vertrag; nicht jedes In-arrears-Instrument verwendet dieselbe Rechnung.','bonds-02','floating-yields','coupon','In Arrears|Reset in Arrears'),
 G('Gesamtkupon-Floor','Untergrenze auf der gesamten Kuponrate nach Addition von Referenz und Vertragsmarge. Sie ist verschieden von einer Untergrenze allein auf dem Referenzzins. Bei negativer Referenz können die beiden Rechte deshalb unterschiedliche Zahlungen erzeugen.','bonds-02','floating-yields','negative','All-in Coupon Floor'),
 G('Referenzzins-Floor','Untergrenze allein auf dem vertraglich verwendeten Referenzzins, bevor die Marge hinzugefügt wird. Eine Nulluntergrenze auf dem Index bedeutet nicht dieselbe Kuponrechnung wie ein Floor von null auf der gesamten Rate.','bonds-02','floating-yields','negative','Index-Floor|Reference Rate Floor'),
 G('Geldmarktinstrument','Schuldinstrument mit typischer ursprünglicher Laufzeit von höchstens einem Jahr. Seine Quote kann etwa als endbetragsbezogener Diskontsatz oder kaufpreisbezogener Add-on-Satz vorliegen. Kurze Laufzeit beseitigt Kredit-, Liquiditäts- und Wiederanlagerisiken nicht.','bonds-02','floating-yields','money-contract','Money Market Instrument'),
 G('Diskontinstrument','Papier, dessen Ertrag bei gegebenem Endbetrag aus dem Abstand zwischen Kaufpreis und Endzahlung entsteht. Bei positivem Ertrag liegt der Preis unter dem Endbetrag, bei negativem Ertrag darüber. Die Diskontquote ist von der kaufpreisbezogenen Anlegerrendite zu unterscheiden.','bonds-02','floating-yields','discount','Discount Instrument'),
 G('Add-on-Instrument','Verzinstes Papier, bei dem ein vertraglicher Zins auf den ursprünglichen Anlagebetrag aufgeschlagen wird. Für einen späteren Käufer zählt die daraus erworbene Endzahlung relativ zu seinem eigenen Kaufpreis und seiner verbleibenden Haltedauer.','bonds-02','floating-yields','deposit','Add-on Instrument'),
 G('Geldmarkt-Diskontsatz','Einfach annualisierter Geldgewinn relativ zum Endbetrag eines Diskontinstruments. Die Jahresbasis muss genannt sein, zum Beispiel 360 Tage. Weil der Nenner die Endzahlung statt des eingesetzten Kaufpreises ist, ist diese Quote keine direkt kaufpreisbezogene Rendite.','bonds-02','floating-yields','discount','Bank Discount Yield|Money Market Discount Rate|Bankdiskontrendite'),
 G('Add-on-Rendite','Einfach annualisierter Geldgewinn relativ zum tatsächlich eingesetzten Anfangskapital. Sie enthält eine ausdrücklich festgelegte Tagesbasis. Einfache Skalierung der Haltedauerrendite ist von geometrischer Annualisierung und vom endbetragsbezogenen Diskontsatz zu unterscheiden.','bonds-02','floating-yields','addon','Add-on Yield|Add-on Rate|Add-on-Satz',[{label:'Add-on',units:['floating-yields']}]),
 G('CFA-Geldmarkt-BEY','Hier ausdrücklich verwendete Geldmarktkonvention für Bond-Equivalent Yield: einfache kaufpreisbezogene Add-on-Jahresquote auf 365-Tage-Basis. Sie ist nicht allgemein identisch mit einer geometrisch äquivalenten nominalen Halbjahresquote oder jeder Treasury-Investment-Rate. Die konkrete Marktverwendung des Namens muss geprüft werden.','bonds-02','floating-yields','bond-equivalent','Bond-Equivalent Yield|Bond Equivalent Yield|Money Market BEY',[{label:'BEY',units:['floating-yields']}]),
 G('Treasury-Investment-Rate','Spezifische Coupon-Equivalent-Quotierung von US-Treasury-Bills nach den maßgeblichen Berechnungsregeln. Die offizielle Rechenunterlage unterscheidet Laufzeiten bis zu einem halben Jahr und längere Laufzeiten sowie die anzuwendende Jahreslänge. Eine allgemeine einfache 365-Tage-Quote bildet daher nicht jeden Fall exakt ab.','bonds-02','floating-yields','treasury-convention','Treasury Investment Rate|Coupon-Equivalent Investment Rate'),
 G('Einfache Annualisierung','Lineare Skalierung eines Haltedauerertrags mit dem Verhältnis von Jahresbasis zu Haltedauer. Sie berücksichtigt innerhalb dieser Hochrechnung keinen Zinseszins. Eine andere Tagesbasis ändert die Quote, ohne die zugrunde liegenden Geldzahlungen zu verändern.','bonds-02','floating-yields','effective','Simple Annualization'),
 G('Sekundärmarktrendite','Rendite aus dem tatsächlich vom späteren Käufer gezahlten Betrag und den danach noch erworbenen Zahlungen. Der ursprüngliche Emissions- oder Einlagenzins ist dafür nicht automatisch die passende Rendite. Preis, Restdauer und Quotierung müssen zusammenpassen.','bonds-02','floating-yields','deposit','Secondary Market Yield'),
 G('Basisrisiko','Risiko, dass zwei zu vergleichende oder abzusichernde Größen unterschiedlich reagieren, etwa wegen verschiedener Referenzindizes, Laufzeiten oder Resettermine. Zwei variable Zinssätze sind deshalb nicht automatisch eine genaue Absicherung füreinander. Auch andere Absicherungsbeziehungen können Basisrisiko enthalten.','bonds-02','floating-yields','limits','Basis Risk'),
 G('Periodizität','Zahl der ausdrücklich angenommenen Verzinsungsperioden pro Jahr. Sie ist Teil einer Renditequote: dieselbe nominale Jahreszahl kann bei anderer Frequenz einen anderen effektiven Jahresfaktor erzeugen. Die passende Periodenrate gehört zu den verwendeten Zahlungszeitpunkten.','bonds-05','fixed-yields','period-rate','Periodicity|Compounding Frequency'),
 G('Nominale Jahresquote','Jährlich angegebene Renditequote, deren Rate pro gleich langer Zinsperiode durch Division durch die Frequenz entsteht. Hier bedeutet nominal eine Quotierung der Verzinsung und nicht die Gegenüberstellung nominaler Kaufkraft mit realer Rendite. Der Zinseszinseffekt wird über den Jahresfaktor erfasst.','bonds-05','fixed-yields','period-rate','Nominal Annual Yield',[{label:'nominale Jahresrate',units:['fixed-yields']}]),
 G('Renditeäquivalenz','Gleichheit des Jahreswachstumsfaktors zweier unterschiedlich quotierter Renditen. Die Umrechnung passt Periodenrate und Frequenz an, erzeugt aber keinen zusätzlichen Ertrag. Kosten, Steuern und unterschiedliche Zahlungsansprüche müssen zusätzlich abgestimmt werden.','bonds-05','fixed-yields','convert','Yield Equivalence'),
 G('Stetige Jahresrate','Logarithmus des positiven Jahreswachstumsfaktors. Diese Rate beschreibt denselben Kapitalzuwachs in stetiger Schreibweise. Sie wird nicht als zusätzlicher Aufschlag zur effektiven Jahresrendite addiert.','bonds-05','fixed-yields','continuous','Continuously Compounded Annual Yield|Continuous Annual Yield'),
 G('Current Yield','Jährlicher vertraglicher Kupon geteilt durch die ausdrücklich verwendete aktuelle Preisquote desselben Nominals. In den eigenen Fällen wird der angegebene Clean Price verwendet. Die Quote enthält weder vollständigen Kapitalgewinn oder -verlust bis zur Rückzahlung noch automatisch Wiederanlage, Call, Ausfall oder Kosten.','bonds-05','fixed-yields','current','Laufende Kuponrendite'),
 G('Yield to Call','Cashflow-IRR für einen konkret unterstellten vertraglichen Calltermin mit dessen Callpreis und den bis dahin zustehenden Kupons. Sie ist keine Wahrscheinlichkeit der Kündigung. Mehrere Calltermine und Preise können verschiedene Szenariorenditen erzeugen.','bonds-11','fixed-yields','call','YTC|Yield-to-Call'),
 G('Yield to Worst','Niedrigste Rechenrendite unter den angegebenen vollständigen Endfälligkeits- und vertraglichen Emittentencallszenarien, auf derselben Jahres- und Preisbasis. Das Minimum begrenzt nur diese Szenarienmenge; Ausfall, Kosten und tatsächliche Wiederanlage können schlechtere reale Ergebnisse erzeugen.','bonds-11','fixed-yields','worst','YTW|Yield-to-Worst'),
 G('Yield to Put','IRR eines unterstellten Rückverkaufs am vertraglichen Puttermin zum zugehörigen Preis. Beim Anlegerput entscheidet der Anleger über die Ausübung. Eine niedrige hypothetische Putrendite ist deshalb nicht automatisch ein vom Emittenten erzwingbarer Worst-Call-Ausgang.','bonds-15','fixed-yields','put','YTP|Yield-to-Put'),
 G('Anleihe-Callpreis','Vertraglicher Rückzahlungsbetrag bei Ausübung eines bestimmten Emittentencalls. Er kann vom Nominal abweichen und über Termine variieren. Der im jeweiligen Fall zusätzlich fällige Kupon wird gesondert berücksichtigt.','bonds-15','fixed-yields','call-case','Bond Call Price',[{label:'Callpreis',units:['fixed-yields']},{label:'Call Price',units:['fixed-yields']}]),
 G('Call Schedule','Vertraglicher Plan möglicher Emittentencalls mit Terminen, Rückzahlungspreisen und weiteren Bedingungen. Die chronologische Reihenfolge allein bestimmt nicht, welcher Fall die niedrigste Szenario-IRR erzeugt.','bonds-15','fixed-yields','call-case','Kündigungsplan'),
 G('G-Spread','Abstand einer Bond-YTM zur passenden tatsächlichen oder interpolierten staatlichen Vergleichs-YTM. Währung, Laufzeit, Beobachtungszeit und Renditekonvention werden abgestimmt. Der Abstand ist nicht automatisch reine Ausfallkompensation oder garantierte Überrendite.','bonds-11','fixed-yields','g-spread','G Spread|Government Yield Spread'),
 G('I-Spread','Abstand einer Bond-YTM zur passenden Swaprate derselben Vergleichslaufzeit und konsistenter Quotierung. Er unterscheidet sich vom G-Spread durch den Benchmark. I-Spread ist nicht identisch mit dem Swapspread zwischen Swaprate und Staatsrendite.','bonds-11','fixed-yields','i-spread','I Spread|Interpolated Spread'),
 G('Swapspread','Abstand der passenden festen Swaprate zur Staatsanleiherendite derselben Laufzeit unter benannten Konventionen. Er kann positiv oder negativ sein. Im eigenen abgestimmten Yieldvergleich entspricht er G-Spread minus I-Spread; er ist nicht der Bondyield-Abstand zur Swaprate selbst.','bonds-11','fixed-yields','i-spread','Swap Spread'),
 G('Anleihe-Yieldspread','Differenz ausdrücklich vergleichbar definierter Renditequoten. Ein Bondaufschlag kann Kredit-, Liquiditäts-, Options-, Steuer- und Benchmarkeffekte enthalten. Preis-Spread im Handel und Renditeabstand sind unterschiedliche Größen.','bonds-11','fixed-yields','drivers','Bond Yield Spread',[{label:'Spread',units:['fixed-yields']}]),
 G('Spreadkurve','Darstellung passend definierter Renditeabstände über verschiedene Laufzeiten. Vergleichsgruppen und Konventionen müssen konsistent sein. Ein steigender Verlauf beweist weder genaue Forward-Ausfallwahrscheinlichkeiten noch einen sicheren künftigen Rollgewinn.','bonds-11','fixed-yields','term-structure','Spread Term Structure|Credit Spread Curve'),
 G('Z-Spread','Konstanter Zinsaufschlag auf jeden zur Zahlung passenden Referenz-Spotzins, der die Barwerte fester Cashflows auf den gegebenen Vollpreis abstimmt. Er nutzt die ganze Referenzkurve und ist nicht allgemein gleich dem Abstand zweier einzelner YTMs. Zero-Volatility bezeichnet die deterministische Bewertungsannahme, keine Risikofreiheit.','bonds-11','fixed-yields','z-definition','Z Spread|Zero-Volatility Spread|Zero Volatility Spread'),
 G('Option-Adjusted Spread','Spreadaufschlag, mit dem ein optionsgerechtes Modell den vollen Marktpreis trifft. Kurve, Volatilität, Ausübung und Cashflow-Behandlung gehören zur Definition. Er bereinigt eine modellierte Optionswirkung, ist aber kein modellfreier reiner Ausfallwert; ein Z-Spread allein bestimmt ihn nicht eindeutig.','bonds-15','fixed-yields','oas','OAS|Option Adjusted Spread'),
 G('Zinsvolatilität','Ausmaß modellierter oder beobachteter Schwankungen von Zinssätzen. Für eingebettete Anleiheoptionen beeinflusst die angenommene Zinsentwicklung den Optionswert und die daraus gewonnene Spreadbereinigung. Sie ist von der bloßen Differenz zweier aktueller Zinssätze zu unterscheiden.','bonds-15','fixed-yields','oas','Interest Rate Volatility'),
 G('Optionsbereinigung','Berücksichtigung des Werts und der Ausübungsregeln eines eingebetteten Rechts innerhalb eines konsistenten Bewertungsmodells. Sie verändert gegebenenfalls Cashflows oder Werte und wird nicht durch Subtraktion ungleicher Geld- und Zinsgrößen ersetzt.','bonds-15','fixed-yields','option-value','Option Adjustment'),
 G('Monetärer Optionswert','Wert eines Optionsrechts in Geldeinheiten beziehungsweise denselben Preispunkten wie der zugehörige Anspruch. Gleiche Geldwerte können wegen der nichtlinearen Preisfunktion unterschiedliche Spreadabstände erzeugen. Ohne passende Modellrechnung darf der Betrag nicht direkt von Basispunkten abgezogen werden.','bonds-15','fixed-yields','option-case','Monetary Option Value'),
 G('Nominaler Yieldspread','Hier ausdrücklich die Differenz zweier einzelner passend quotierter Cashflow-YTMs. Die Bezeichnung grenzt diesen Vergleich von einem konstant auf mehrere Spotzinsen addierten Z-Spread ab. Preisfunktion und Kurvenform können beide Ergebnisse unterscheiden.','bonds-11','fixed-yields','z-nominal','Nominal Yield Spread'),
 G('Spreadkalibrierung','Bestimmung eines Spreadparameters so, dass die ausgewählte Bewertungsfunktion einen gegebenen Preis reproduziert. Das Suchintervall, gültige Diskontfaktoren, erworbene Cashflows und Vollpreis müssen passen. Exakte numerische Übereinstimmung beweist keine Richtigkeit aller Modellannahmen.','bonds-11','fixed-yields','z-root','Spread Calibration'),
 G('Renditebenchmark','Explizit gewählter Vergleich für eine Rendite- oder Spreadanalyse, etwa Staats-YTM, Swaprate oder passende Referenzkurve. Währung, Zeitpunkt, Laufzeit und Quotierung werden begründet. Eine andere Benchmark kann die Spreadzahl desselben Bonds ändern.','bonds-11','fixed-yields','benchmarks','Yield Benchmark',[{label:'Benchmark',units:['fixed-yields']}]),
 G('Yield to Maturity','Einheitliche Rechenrendite, bei der die Barwerte aller dem Käufer zustehenden versprochenen Zahlungen den heutigen Vollpreis ergeben. Sie ist eine Cashflow-IRR, nicht Kuponsatz oder Kupon durch Preis. Die tatsächlich erzielte Endvermögensrendite benötigt zusätzlich passende Zahlungs-, Horizont- und Wiederanlagebedingungen.','bonds-05','bond-prices','yield','YTM|Rendite bis Fälligkeit'),
 G('Anleihe-Periodenrendite','Zur einzelnen Diskontierungsperiode passende Rendite. Bei nominaler Jahres-YTM y mit m Verzinsungsperioden ist sie y/m; eine effektive Jahresrendite wird dagegen über eine Wurzel auf die Periode umgerechnet. Betrag, Periodenzahl und Rate müssen dieselbe Zeitbasis verwenden.','bonds-05','bond-prices','units','Bond Periodic Yield',[{label:'Periodenrendite',units:['bond-prices']}]),
 G('Nominale Jahres-YTM','Jährlich ausgewiesene Anleihe-Rechenrendite, deren Periodenrate durch Division durch die angegebene Verzinsungsfrequenz entsteht. Gleiche nominale Prozentzahlen bei verschiedener Frequenz bedeuten nicht automatisch gleiche effektive Jahresverzinsung.','bonds-05','bond-prices','units','Nominal Annual YTM'),
 G('Anleihebarwert','Heutiger Wert des konkret erworbenen zukünftigen Zahlungsplans unter angegebenen Diskontierungsannahmen. Der Barwert vollständiger erworbener Cashflows ergibt den Vollpreis; ein Clean Price entsteht erst nach gesonderter Stückzinsabgrenzung.','bonds-05','bond-prices','discount','Bond Present Value'),
 G('Kuponbereinigter Anleihepreis','Clean Price im eigenen Bewertungsmodell: voller Barwert des erworbenen Anspruchs abzüglich des nach passender Konvention abgegrenzten Kuponanteils. Diese Abgrenzung entfernt den mechanischen Stückzinsaufbau, garantiert aber weder einen konstanten Kurs noch pari.','bonds-05','bond-prices','accrual','Coupon-Accrual-Adjusted Bond Price',[{label:'Clean Price',units:['bond-prices']}]),
 G('Diskontierter Anleihevollwert','Heutiger Barwert aller dem Käufer zustehenden zukünftigen Zahlungen. Im normalen Zwischenkuponfall enthält er den ganzen nächsten Kupon; Stückzins wird zum Ableiten des Clean Price abgezogen und nicht nochmals zum Barwert addiert.','bonds-05','bond-prices','settlement','Discounted Full Bond Value',[{label:'Vollpreis',units:['bond-prices']},{label:'Full Price',units:['bond-prices']},{label:'Dirty Price',units:['bond-prices']}]),
 G('Kuponberechtigung','Vertragliche und marktbezogene Zuordnung, wer eine kommende Kuponzahlung erhält. Settlement, Record- oder Ex-Kupon-Regeln können dafür wichtig sein. Ohne den erworbenen Anspruch lässt sich weder eine vollständige Barwertsumme noch die passende Stückzinsüberleitung sicher festlegen.','bonds-05','bond-prices','claim','Coupon Entitlement'),
 G('Tageszählkonvention','Regel, nach der Tage und gegebenenfalls Bezugsperioden für Zinsabgrenzung oder Quotierung gezählt werden. Actual/Actual und 30/360 sind Familien mit weiteren Varianten. Kalenderdaten allein bestimmen ohne passende Regel nicht automatisch den Stückzins.','bonds-05','bond-prices','day-count','Day-Count Convention|Day Count Convention'),
 G('Stub Period','Unregelmäßig kurze oder lange Kuponperiode etwa am Anfang oder Ende einer Emission. Kuponbetrag und Diskontierungsregeln müssen dem Vertrag folgen; die Rentenformel für identische regelmäßige Perioden wird nicht ungeprüft verwendet.','bonds-05','bond-prices','day-count','Stub Periods'),
 G('Ex-Kupon','Markt- oder Vertragsregel, nach der ein Käufer innerhalb eines bestimmten Zeitraums die nächste Kuponzahlung nicht mehr erwirbt. Der fehlende Anspruch und die zugehörige Stückzinskonvention ändern die Abrechnung. Negative Stückzinsen in einzelnen Konventionen bedeuten nicht automatisch einen negativen Kupon.','bonds-05','bond-prices','day-count','Ex-Coupon|Ex Coupon'),
 G('Discount Bond','Anleihe mit einem Preis unter dem maßgeblichen Nominal beziehungsweise Rückzahlungsbezug. Bei regelmäßigen festen Kupons und Rückzahlung zu pari ergibt sich am Kupontermin ein Abschlag, wenn die passend quotierte YTM über dem Kuponsatz liegt. Abschlag allein beweist keine sichere Überrendite.','bonds-05','bond-prices','par','Discount Bonds'),
 G('Premium Bond','Anleihe mit einem Preis über dem maßgeblichen Nominal beziehungsweise Rückzahlungsbezug. Bei regelmäßiger Festzinsschuld zu pari kann der höhere Kupon gegenüber YTM den Aufschlag erklären. Sein späterer Abbau kompensiert einen Teil der Kuponzahlungen in der Gesamtrendite.','bonds-05','bond-prices','par','Premium Bonds'),
 G('Pull to Par','Annäherung des passenden verbleibenden Anleiheanspruchs an seine Rückzahlung bei kürzer werdender Restlaufzeit und konstanten Bewertungsannahmen. Kupon und Vollpreis müssen zeitlich abgegrenzt sein. Die Wertaufholung eines Discounts ist Teil der Rechenrendite und kein garantierter zusätzlicher Tagesgewinn.','bonds-05','bond-prices','pull-par'),
 G('Matrix Pricing','Schätzung von Rendite und Preis einer wenig oder nicht aktuell gehandelten Anleihe aus hinreichend vergleichbaren Instrumenten. Nach Auswahl und gegebenenfalls Interpolation einer passenden Rendite werden die Zielcashflows bewertet. Der Schätzwert ist keine ausführbare Quote.','bonds-05','bond-prices','matrix-process','Matrixbewertung'),
 G('Renditeinterpolation','Schätzung einer Zielrendite innerhalb beobachteter Vergleichspunkte, etwa mit nach Laufzeit gewichteten Renditen. Die lineare Form ist eine Annahme. Außerhalb der Vergleichslaufzeiten liegt Extrapolation vor; sie erfordert zusätzliche Begründung.','bonds-05','bond-prices','interpolation','Yield Interpolation'),
 G('Matrix-Schätzband','Band aus Neubewertungen desselben Zielzahlungsplans unter mehreren plausiblen geschätzten Renditen. Ohne statistisches Modell ist es eine deterministische Sensitivität, kein Konfidenzintervall. Es ist auch kein zugesagter Bid-/Ask-Spread.','bonds-05','bond-prices','matrix-band','Matrix Valuation Range'),
 G('Endvermögensrendite','Annualisierte Veränderung zwischen Anfangseinsatz und dem am Horizont tatsächlich angesammelten Vermögen einschließlich wiederangelegter Zwischenzahlungen. Der Wiederanlagesatz beeinflusst diese Rendite; die Cashflow-IRR derselben vertraglichen Zahlungstermine ist eine andere Kennzahl.','bonds-05','bond-prices','realized','Terminal-Wealth Return'),
 G('Macaulay Duration','Mit den heutigen einzelnen Zahlungsbarwerten relativ zum vollen Bondpreis gewichteter mittlerer Zahlungszeitpunkt. Erst die Division der Periodenduration durch die Zahl der Perioden pro Jahr liefert Jahre. Bei positiven Zahlungen liegt das Mittel innerhalb ihrer Termine. Es verbindet den festen Zahlungsplan mit lokaler Preissensitivität und dem ersten Zinseffekt auf Endvermögen bei passendem Horizont.','bonds-09','bond-return','mac-definition','',[{label:'Duration',units:['bond-return']}]),
 G('Modified Duration','Normierte negative Ableitung des vollen Anleihepreises nach der ausdrücklich angegebenen jährlichen Yieldquote. Bei nominaler periodischer YTM wird die Macaulay Duration in Jahren durch eins plus Perioden-YTM geteilt. Das Produkt mit einer kleinen konsistenten dezimalen Yieldänderung schätzt die relative Preisänderung mit negativem Vorzeichen. Marktwertskalierung ergibt Money Duration; große Schocks und veränderte Cashflows verlangen weitere Prüfung.','bonds-08','duration','modified','modifizierte Duration|Duration'),
 G('Konvexität','Volle zweite Ableitung des Preises nach der ausdrücklich angegebenen jährlichen Yieldquote, geteilt durch den vollen Ausgangspreis. Sie misst die relative Krümmung dieser Preisfunktion. Bei unveränderlichen positiven künftigen Zahlungen und positiver Zinsbasis ist sie positiv. Der Taylorbeitrag enthält zusätzlich ein Halb und den quadrierten dezimalen Yieldschock; Money Convexity skaliert den Koeffizienten mit dem Marktwert. Periodenquote, Jahresquote und geänderte Optionscashflows sind gesondert zu prüfen.','bonds-08','convexity','definition','Convexity'),
 G('Vergleichsanleihe','Für eine Zielbewertung herangezogenes Instrument mit möglichst passenden Währungs-, Kredit-, Rang-, Options-, Liquiditäts- und Laufzeiteigenschaften. Ähnliche Ratingnoten oder derselbe Emittent allein schaffen keine vollständige Vergleichbarkeit.','bonds-05','bond-prices','matrix-peers','Comparable Bond|Comparable Bonds'),
 G('Bruchteilsdiskontierung','Abzinsung einer Zahlung über eine nicht ganzzahlige Zahl einer definierten Zinsperiode. Im regelmäßigen Zwischenkuponmodell startet der erste Exponent mit dem verbleibenden Periodenbruchteil. Tatsächliche Markt-, Tageszähl- und Ex-Kupon-Regeln werden zusätzlich geprüft.','bonds-05','bond-prices','settlement','Fractional-Period Discounting'),
 G('Kuponfrequenz','Anzahl regelmäßiger Kuponzahlungen pro Jahr. Sie bestimmt bei gleich langen Perioden den Kuponbetrag je Zahlung und die passende Periodenrate einer nominalen Jahres-YTM. Die Endtilgung wird nicht ebenfalls durch die Frequenz geteilt.','bonds-05','bond-prices','units','Coupon Frequency'),

 G('Staats-Bill','Kurzlaufendes staatliches Schuldpapier nach der jeweiligen Marktbezeichnung. Im US-Treasury-Beispiel werden Bills zu Diskont oder pari ausgegeben und bei Fälligkeit zum Nominal bedient. Quotierung, Tagesbasis und tatsächliche Vertrags- und Marktrisiken werden gesondert geprüft.','bonds-02','government-funding','instruments','Government Bill|Treasury Bill',[{label:'Bill',units:['government-funding']},{label:'Bills',units:['government-funding']}]),
 G('Staatliche Note','Marktbezeichnung für ein staatliches Schuldpapier, häufig im mittleren Laufzeitsegment. Im betrachteten US-Treasury-Fall zahlt eine Note feste Kupons; die genaue Laufzeitabgrenzung und Zahlungsfrequenz sind marktbezogen. Name, Kuponrate und heutiger Kaufpreis sind getrennte Eigenschaften.','bonds-02','government-funding','instruments','Government Note|Treasury Note',[{label:'Note',units:['government-funding']},{label:'Notes',units:['government-funding']}]),
 G('Gilt','Bezeichnung für britische Staatsanleihen. Konventionelle und indexierte Formen haben unterschiedliche vertragliche Zahlungsbezüge; Kupon, Restlaufzeit, Preis und Auktionsregeln werden konkret gelesen. Der Marktname allein garantiert keine unveränderte Kaufkraft oder kostenfreie Handelbarkeit.','bonds-02','government-funding','instruments','Gilts'),
 G('Finanzierung in eigener Währung','Schuldaufnahme in der für den Emittenten betrachteten Heimatwährung. Ein Anleger mit anderer Rechenwährung kann trotzdem Wechselkursrisiko tragen. Die Zahlungswährung verleiht einer einzelnen Körperschaft oder Regierung nicht automatisch eine unbegrenzte Befugnis zur Schaffung von Zentralbankgeld.','bonds-02','government-funding','currency','Local-Currency Funding',[{label:'Local Currency',units:['government-funding']}]),
 G('Anleihe','Vertraglich bestimmter Schuldanspruch gegen einen Emittenten. Nominal, Zins- oder andere Zahlungen, Termine, Rang, Sicherheiten und bedingte Rechte prägen den Anspruch. Festverzinslich ist nur eine mögliche Ausgestaltung; ein Zahlungsversprechen ist keine Garantie der tatsächlichen Erfüllung oder eines konstanten Marktpreises.','bonds-01','bond-features','claim','Bond|Bonds'),
 G('Öffentliche Finanzierung','Beschaffung von Mitteln für einen souveränen, anderen öffentlichen, staatsnahen oder supranationalen Schuldner. Tatsächlicher Verpflichteter, Einnahmequelle, Währung und ausdrücklich zugesagte Garantie werden getrennt geprüft; ein öffentlicher Name schafft keinen zusätzlichen Anspruch.','bonds-02','government-funding','map','Public-Sector Funding'),
 G('Cash-Primärdefizit','Nichtzinsauszahlungen abzüglich nicht aus Kreditaufnahme stammender Einnahmen in einer definierten Cashperiode. Positiv bedeutet hier Fehlbetrag ohne Zins. Es ist von Gesamtdefizit einschließlich Zins und von Kapitaltilgung zu unterscheiden.','bonds-02','government-funding','cash-need','Cash Primary Deficit',[{label:'Primärdefizit',units:['government-funding']}]),
 G('Cash-Gesamtdefizit','In der verwendeten Haushaltskonvention Nichtzinsausgaben plus gezahlter Zins minus Einnahmen. Kapitaltilgung und Finanzierungstransaktionen werden getrennt betrachtet. Bereits enthaltener Zins darf bei der Cashplanung nicht nochmals addiert werden.','bonds-02','government-funding','cash-need','Overall Cash Deficit'),
 G('Bruttofinanzierungsbedarf','Neu zu beschaffende Mittel zur Deckung des definierten Defizits, fälliger Kapitalrückzahlungen und weiterer abgegrenzter Cashverwendungen wie einer Reserveaufstockung. Er unterscheidet sich von Nettozunahme des Schuldnominals; Ausgabeabschläge und Gebühren erfordern zusätzlich eine Cash-Nominal-Überleitung.','bonds-02','government-funding','gross-net','Gross Financing Need'),
 G('Nettozunahme des Schuldnominals','Neu ausgegebenes Nominal abzüglich zurückgezahltem Nominal bei ausdrücklich fehlenden weiteren Bestandsanpassungen. Bruttoaufnahme und Cashdefizit können wegen Ersatzfinanzierung, Ausgabeabweichungen und Reservebewegungen andere Beträge haben.','bonds-02','government-funding','gross-net','Net Face-Value Debt Increase'),
 G('Reservebewegung','Veränderung der verfügbaren Cashreserve über die betrachtete Periode. Eine Erhöhung bindet Mittel und erhöht unter sonst gleichen Bedingungen den Finanzierungsbedarf; Verbrauch einer vorhandenen Reserve mindert ihn. Die Richtung wird ausdrücklich angegeben.','bonds-02','government-funding','cash-need','Cash Reserve Change'),
 G('Fälligkeitenprofil','Zeitliche Verteilung vertraglicher Rückzahlungen und gegebenenfalls weiterer Schuldendienstzahlungen. Gleiche Gesamtschuld oder ähnliche Durchschnittslaufzeit kann unterschiedliche nahe Spitzen verbergen. Für Refinanzierung zählt der periodengenaue Ersatzbedarf.','bonds-02','government-funding','maturity','Redemption Profile|Maturity Profile'),
 G('General Obligation','US-Municipal-Bezeichnung für einen allgemeinen öffentlichen Zahlungsanspruch nach seinen konkreten Quellen und Befugnissen. Varianten können bestimmte Steuern oder allgemeine Haushaltsmittel betreffen. Das Label beweist keine überall unbegrenzte Steuerhoheit und kein pauschales Pfand an allen Vermögenswerten.','bonds-02','government-funding','general-obligation','General Obligation Bond|GO Bond|GO'),
 G('Revenue Bond','Im betrachteten US-Kontext Schuldinstrument mit definierten Einnahmen oder Zahlungsströmen als Deckungsquelle. Bruttoumsatz, verfügbarer Cashflow, tatsächlicher Obligor und weitere Rückgriffsrechte werden geprüft. Ein öffentliches Emissionslabel ist keine automatische umfassende Staatsgarantie.','bonds-02','government-funding','revenue','Revenue Bonds'),
 G('Schuldendienstdeckungsquote','Verfügbarer Cashflow geteilt durch den zu deckenden Zins und Kapitaldienst nach der verwendeten Definition. Im eigenen Projektfall ist der Zähler Umsatz nach Betriebskosten; tatsächliche Verträge können weitere Abzüge, Anpassungen und Perioden verlangen. Eine Quote ist kein allgemeines Garantieversprechen.','bonds-02','government-funding','project-case','DSCR|Debt Service Coverage Ratio'),
 G('Conduit-Finanzierung','Struktur, in der eine formale Ausgabestelle Wertpapiere zugunsten eines anderen wirtschaftlichen Trägers oder Projekts ausgibt. Dessen Zahlungsstrom kann die eigentliche Quelle sein; der formale öffentliche Emittent muss nicht jede Verpflichtung aus allgemeinen Mitteln garantieren.','bonds-02','government-funding','conduit','Conduit Financing|Conduit'),
 G('Official Statement','Informationsdokument einer Municipal-Emission im US-Kontext, das unter anderem tatsächlichen Schuldner, Zahlungsquellen, Rechte und Risiken beschreibt. Ein Kurzlabel wie GO oder Revenue ersetzt die dortige Anspruchs- und Quellenprüfung nicht.','bonds-02','government-funding','general-obligation'),
 G('Quasi-staatlicher Emittent','Staatsnahe Einrichtung mit eigener Finanzierung und einem bestimmten öffentlichen Bezug oder Auftrag. Eigentum, Aufsicht, Sondergesetz und ausdrückliche Garantie sind unterschiedliche Merkmale. Die einzelnen Schuldpapiere sind nicht allein durch den Namen direkte Sovereign-Schuld.','bonds-02','government-funding','agency','Quasi-Government Issuer|Quasi-government Entity',[{label:'Agency',units:['government-funding']}]),
 G('Explizite Staatsgarantie','Ausdrücklich zugesagter staatlicher Anspruch zur Unterstützung einer bestimmten Verpflichtung nach seinen Bedingungen. Umfang, Auslöser, Frist, Währung, Höchstbetrag und tatsächliche Erfüllung werden geprüft; nicht jede Garantie deckt jede denkbare Zahlung vollständig.','bonds-02','government-funding','guarantee','Explicit Government Guarantee'),
 G('Implizite Staatsunterstützung','Erwartung möglicher zukünftiger staatlicher Hilfe ohne damit bereits belegte umfassende vertragliche Garantie. Sie kann für Szenarien wichtig sein, ist aber von einem tatsächlich durchsetzbaren individuellen Anlegeranspruch zu unterscheiden.','bonds-02','government-funding','agency','Implicit Government Support'),
 G('Teilgarantie','Garantie mit begrenzter Deckung, beispielsweise Prozentsatz einer genau definierten unbezahlten Forderung und zusätzlichem Cap. Erst Bemessungsbetrag und Bedingungen feststellen, dann den gedeckten Cashbetrag berechnen; öffentliche Unterstützung bedeutet nicht automatisch vollen Ausgleich.','bonds-02','government-funding','guarantee','Partial Guarantee'),
 G('Supranationale Finanzierung','Finanzierung einer durch mehrere Staaten getragenen Institution aus ihrer eigenen Struktur von Vermögenswerten, Rückflüssen, Liquidität, Marktschuld und Mitgliedskapital. Institutionelle Unterstützung schafft nicht automatisch einen direkten Bondhalteranspruch gegen jede Mitgliedsregierung.','bonds-02','government-funding','supranational','Supranational Funding'),
 G('Callable Capital','Nach den Bedingungen einer Institution noch abrufbare Kapitalzusagen. Sie sind weder vollständig bereits gezahltes Cash noch automatisch ein individuelles Recht jedes Bondhalters, beliebige Mitgliedstaaten unmittelbar in Anspruch zu nehmen. Auslöser und Abrufverfahren bestimmen die Funktion.','bonds-02','government-funding','supranational','Abrufbares Kapital'),
 G('Paid-in Capital','Tatsächlich eingezahltes Kapital nach der betrachteten Struktur. Es unterscheidet sich von noch abrufbaren Zusagen und kann bereits in anderen Vermögenswerten gebunden sein. Eingezahlt bedeutet deshalb nicht automatisch vollständig als freie Liquidität vorhanden.','bonds-02','government-funding','supranational','Eingezahltes Kapital'),
 G('Primary Dealer','Im jeweiligen Markt anerkannter Intermediär mit bestimmten Zugangsrechten und Pflichten bei Emission, Handel oder verwandten Aufgaben. Anerkennung ist keine Staatsgarantie des Händlers und keine universelle Regel identischer direkter Anlegerzugänge.','bonds-02','government-funding','dealers','Primary Dealers'),
 G('GEMM','Gilt-Edged Market Maker im UK-Gilt-Markt. Die gelesene Operational Notice beschreibt unter anderem den Zugang zu Auktionen und die Abgabe von Kundengeboten über diese Händler. Rollen, Bedingungen und Konfliktpflichten sind konkret marktbezogen.','bonds-02','government-funding','dealers','Gilt-Edged Market Maker|GEMMs'),
 G('Competitive-Gebot','Auktionsgebot mit ausdrücklich vorgegebenem Preis, Yield oder einer anderen definierten Preisgröße und Menge. Annahme, Rang und Kürzung folgen der Auktionsregel; Abgabe garantiert keine vollständige Zuteilung.','bonds-02','government-funding','auction-rules','Competitive Bid'),
 G('Non-Competitive-Gebot','Auktionsgebot, das nach den zugelassenen Regeln Menge verlangt und die ermittelte maßgebliche Preisbedingung akzeptiert. Zugang, Mengenlimits, Priorität und tatsächlich anzuwendender Preis hängen vom Markt und Format ab.','bonds-02','government-funding','auction-rules','Noncompetitive Bid|Non-Competitive Bid',[{label:'Non-Competitive',units:['government-funding']},{label:'NC',units:['government-funding']}]),
 G('Uniform Price','Auktionsformat, bei dem angenommene Gebote nach der angekündigten Regel denselben Preis zahlen. Im eigenen Preisfall ist es der niedrigste noch angenommene Preis. Mengenpriorität, Grenzzuteilung und Non-Competitive-Behandlung müssen trotzdem definiert werden.','bonds-02','government-funding','formats','Uniform-Price|Single Price|Single-Price'),
 G('Multiple Price','Auktionsformat mit Zahlung der jeweiligen angenommenen Gebotspreise für die erfasste Gruppe. Ein Durchschnittspreis für Non-Competitive kann eine eigene Zusatzregel sein. Ein Vergleich mit Uniform Price muss offenlegen, ob Gebotsstrategien unverändert gehalten werden.','bonds-02','government-funding','formats','Multiple-Price|Discriminatory Auction'),
 G('Auktionsgrenzpreis','Letzter noch benötigter Preis nach der Sortierung und Mengenregel einer Preisauktion. Er bestimmt die Grenze der Annahme, aber nicht unter jedem Format den bezahlten Preis aller anderen Teilnehmer. Bei Yield-Geboten wird die passende Renditerichtung berücksichtigt.','bonds-02','government-funding','allocation','Auction Cutoff Price',[{label:'Grenzpreis',units:['government-funding']}]),
 G('Grenzzuteilung','Teil der noch benötigten Angebotsmenge, der der letzten angenommenen Preis- oder Yield-Gruppe zugewiesen wird. Eine Kürzungsquote setzt diesen Betrag zur eigenen Gebotsmenge in Beziehung; Rundungs- und Mengenregeln gehören zum konkreten Verfahren.','bonds-02','government-funding','allocation','Marginal Allocation'),
 G('Bid-to-Cover','Erfasste Gebotsmenge geteilt durch die dazu definierte Angebotsmenge einer Auktion. Gesamt- und Competitive-only-Varianten können andere Werte haben. Die Zahl beschreibt weder sämtliche Gebotspreise noch garantiert sie einen späteren Kursgewinn.','bonds-02','government-funding','cover','Bid to Cover|Auction Cover',[{label:'Cover',units:['government-funding']}]),
 G('Reopening','Zusätzliche Ausgabe eines bereits bestehenden Titels unter dessen fortbestehender Fälligkeit und Kupon- beziehungsweise Spread-Regel. Neuer Ausgabetermin, Kaufpreis und gegebenenfalls Stückzinsen können abweichen. Mehr Nominal bedeutet keine neue Kuponrate oder verdoppelten alten Zahlungsplan.','bonds-02','government-funding','reopening','Aufstockung|Wiedereröffnung'),
 G('Syndizierung','Koordinierte Platzierung einer Emission mit arrangierenden Intermediären und definierter Preis- und Allokationsfindung. Das Verfahren kann öffentliche ebenso wie unternehmerische Schuld betreffen. Rollen und Übernahmeverpflichtungen folgen der konkreten Vereinbarung.','bonds-02','government-funding','syndication','Syndication'),
 G('Gilt Tender','Besondere angekündigte Operation im UK-Gilt-Markt mit ausdrücklich festgelegten Preis-, Mengen- und Verfahrensregeln. Ein Tender kann je nach Ankündigung anders gestaltet sein als die reguläre Auktion. Die Zahlungsrichtung und das konkrete Regelwerk werden zuerst gelesen.','bonds-02','government-funding','issuance','Gilt Tenders',[{label:'Tender',units:['government-funding']}]),
 G('Reverse Auction','Im hier betrachteten Emittentenkontext Auktionsoperation zum Ankauf statt zur neuen Ausgabe von Schuldpapieren. Sie erzeugt einen anderen Cashpfeil und gegebenenfalls eine andere Bestandswirkung als ein gewöhnlicher Emissionsverkauf.','bonds-02','government-funding','secondary'),
 G('Switch Auction','Operation zum Tausch bestimmter alter gegen andere Schuldansprüche nach gegebenen Bedingungen. Alte und neue Nominalmengen, Preise und etwaige Cashdifferenzen werden gemeinsam abgestimmt; ein Tausch erzeugt nicht automatisch kostenlose zusätzliche Finanzmittel.','bonds-02','government-funding','secondary'),
 G('Non-Recourse-Finanzierung','Finanzierung mit nach der konkreten Struktur begrenzten Rückgriffsrechten. Im Municipal-Kontext sind tatsächlicher Obligor, verpfändete Zahlungsströme und weitere Zugriffe aus den Dokumenten zu lesen. Der Name beweist weder allgemeine Staatshaftung noch ein uneingeschränktes Recht auf jedes Projektvermögen.','bonds-02','government-funding','conduit','Non-Recourse|Nonrecourse'),
 G('Repo','Verkauf von Wertpapieren mit vereinbartem späterem Rückkauf äquivalenter Titel. Im gewöhnlichen Unternehmensfall erhält der Verkäufer heute Cash und zahlt später den Rückkaufpreis; wirtschaftlich ist dies besicherte Finanzierung. Sicherheiten reduzieren Exposition, beseitigen aber weder Gegenpartei-, Markt-, Liquiditäts- noch Abwicklungsrisiken.','bonds-02','corporate-funding','repo-legs','Repurchase Agreement'),
 G('Reverse Repo','Im gewöhnlichen Unternehmensfall die Cashgeberseite eines Repo: Wertpapiere kaufen, Cash verleihen und die äquivalenten Titel später gegen Rückkaufpreis zurückliefern. Spezielle Operationskonventionen können denselben Namen anders verwenden; tatsächliche Cash- und Lieferpfeile sowie Perspektive werden deshalb angegeben.','bonds-02','corporate-funding','repo-terms','Reverse Repurchase Agreement'),
 G('Haircut','Finanzierungsabschlag relativ zum Marktwert der gelieferten Sicherheiten. Bei Wert V und Haircut h beträgt das anfängliche Cash im einfachen Repo V mal eins minus h. Der nicht finanzierte Wert ist keine automatische Zinsgebühr; spätere Nachschussregeln und Marktwertänderungen werden gesondert behandelt.','bonds-02','corporate-funding','haircut','Sicherheitenabschlag'),
 G('Repo-Initial-Margin','Hier ausdrücklich das Verhältnis Sicherheitenmarktwert zu Anfangscash nach der Repo-Konvention der ICMA. Fünf Prozent Haircut ergeben etwa 105,263 Prozent Initial Margin, weil die Nenner verschieden sind. Andere Märkte können Initial Margin als Geldbetrag definieren; die Konvention muss genannt werden.','bonds-02','corporate-funding','initial-margin','Repo Initial Margin',[{label:'Initial Margin',units:['corporate-funding']}]),
 G('Cashbezogene Übersicherung','Sicherheitenwert abzüglich Cash, geteilt durch Cash. Diese Übersicherungsquote ist das Repo-Initial-Margin-Verhältnis minus eins und unterscheidet sich vom Haircut auf den Sicherheitenwert. Fünf Mio. Überschuss bei hundert Mio. Sicherheit und 95 Mio. Cash sind 5,263 Prozent des Cash.','bonds-02','corporate-funding','initial-margin','Cash Overcollateralization'),
 G('Sicherheiten-Nachschuss','Zusätzliche vertraglich verlangte Lieferung von Sicherheiten oder Cash nach einer Neubewertung. Im eigenen Repo-Lehrfall werden Wertpapiere geliefert und die ursprüngliche Cashschuld bleibt unverändert. Erforderliche Quote, Exposition, Mindesttransfer und Zinsbehandlung bestimmen den Betrag.','bonds-02','corporate-funding','margin-call','Collateral Top-up|Repo Margin Call',[{label:'Nachschuss',units:['corporate-funding']},{label:'Margin Call',units:['corporate-funding']}]),
 G('Repo-Kollateral','Im Repo zur Begrenzung der Exposition verwendete Wertpapiere nach den jeweiligen Eigentums- und Rücklieferungsregeln. Marktwert, Qualität, Währung, Konzentration und Verwertbarkeit zählen; anfängliche Übersicherung garantiert keine volle spätere Deckung.','bonds-02','corporate-funding','repo-risks','Repo Collateral',[{label:'Collateral',units:['corporate-funding']},{label:'Sicherheiten',units:['corporate-funding']}]),
 G('Unternehmens-CP','Hier die kurzfristige unbesicherte Note eines Unternehmens oder Finanzinstituts mit bestimmtem Zahlungstermin. Ein Emissionsprogramm garantiert nicht die erfolgreiche Erneuerung jeder Note. Asset-backed CP ist eine gesonderte vermögensgestützte Struktur.','bonds-02','corporate-funding','cp','Corporate CP|CP',[{label:'Commercial Paper',units:['corporate-funding']}]),
 G('CP-Diskontsatz','Auf das bei Fälligkeit zu zahlende Nominal bezogene Quotierung des Abschlags beim einfachen Diskontpapier. Eine Anlegerquote auf den Kaufpreis und Emittentenkosten auf den Nettoerlös haben andere Nenner; Tagesbasis und Gebühren bestimmen den Vergleich.','bonds-02','corporate-funding','cp-cost','CP Discount Rate'),
 G('Kreditlinie','Vereinbarter Rahmen für Kreditaufnahme bis zu einer Obergrenze. Nominales Limit, bereits gezogener Betrag, freie Kapazität und unter aktuellen Bedingungen tatsächlich nutzbarer Anteil werden getrennt. Eine ungezogene Linie ist kein bereits eingegangenes Cash.','bonds-02','corporate-funding','lines','Credit Line|Line of Credit'),
 G('Committed Kreditlinie','Kreditrahmen mit vertraglicher Bereitstellungsverpflichtung innerhalb der vereinbarten Bedingungen. Covenants, Ziehungsvoraussetzungen, Laufzeit und bereits beanspruchte Beträge begrenzen die tatsächliche Verfügbarkeit. Die Zusage ist keine bedingungslose Schenkung oder laufender Umsatz.','bonds-02','corporate-funding','lines','Committed Facility|Committed Credit Line'),
 G('Uncommitted Kreditlinie','Kreditrahmen ohne dieselbe verbindliche Bereitstellungszusage wie eine committed Facility. Ein nomineller Rahmen darf deshalb nicht unabhängig von Entscheidung und Bedingungen des Finanzierers als gesicherte Stressliquidität behandelt werden.','bonds-02','corporate-funding','lines','Uncommitted Facility|Uncommitted Credit Line'),
 G('Kreditrevolver','Kreditvereinbarung, die innerhalb der Laufzeit und Bedingungen wiederholte Ziehung, Tilgung und erneute Ziehung erlaubt. Kosten können Zins auf gezogene Mittel sowie vereinbarte Bereitstellungsgebühren umfassen. Ein Gesamtlimit ist nicht mit freier Liquidität gleichzusetzen.','bonds-02','corporate-funding','lines','Revolver|Revolving Credit Facility|Revolving Credit Agreement'),
 G('Backup-Linie','Für erwartete Zahlungs- oder Anschlussfinanzierungslücken vorgesehener Kreditrahmen. Als Liquiditätspuffer zählt nur der rechtzeitig freie und unter dem betrachteten Stress tatsächlich ziehbare Teil. Gemeinsame Covenants oder Gegenparteirisiken können die Absicherung begrenzen.','bonds-02','corporate-funding','backup','Backup Facility|Liquidity Backstop'),
 G('Zusätzliche Guthabenbindung','Durch die konkrete Finanzierung zusätzlich verlangtes, nicht frei verwendbares Guthaben. Bei den Kosten zählt die tatsächlich zusätzliche Bindung samt Verzinsung und Freigabezeitpunkt. Ein ohnehin unverändert benötigtes Guthaben wird nicht pauschal als neuer Vollbetrag abgezogen.','bonds-02','corporate-funding','bank-cost','Incremental Compensating Balance',[{label:'Compensating Balance',units:['corporate-funding']}]),
 G('Finanzierungs-Rollover','Ersatz einer fälligen Finanzierung durch eine neue Finanzierung. Neuer Satz, verfügbare Menge und erneute Zusage sind eigenständige Unsicherheiten; ein Programm oder heutiger Anfangssatz verlängert die einzelne Schuld nicht automatisch.','bonds-02','corporate-funding','rollover','Funding Rollover',[{label:'Rollover',units:['corporate-funding']}]),
 G('Sichteinlage','Einlage mit Abrufbarkeit nach den geltenden Kontobedingungen. Für die einlagenannehmende Bank ist sie eine Verpflichtung gegenüber dem Kunden. Abzugsverhalten, verfügbare Liquidität und konkrete Sicherungssysteme sind getrennte Prüffragen.','bonds-02','corporate-funding','deposits','Demand Deposit'),
 G('Termineinlage','Einlage mit bestimmter Laufzeit oder vereinbarter Frist nach den Kontobedingungen. Zins, Kündigung und vorzeitiger Zugriff werden konkret geprüft. Eine vertragliche Frist macht die Bank nicht unabhängig von ihrer übrigen Finanzierungs- und Liquiditätsstruktur.','bonds-02','corporate-funding','deposits','Time Deposit'),
 G('Negotiable Certificate of Deposit','Übertragbare Einlageforderung mit ihren vereinbarten Zahlungs- und Fristbedingungen. Handelbarkeit kann einen Verkauf ermöglichen, garantiert aber keinen sofortigen Nominalerlös oder jederzeitige Rücknahme durch den Emittenten.','bonds-02','corporate-funding','deposits','Negotiable CD|Handelbares Einlagenzertifikat'),
 G('Interbankfinanzierung','Geldaufnahme eines Instituts bei einem anderen Institut. Besicherung, Laufzeit und Gegenparteizugang bestimmen das Geschäft. Unbesicherter Interbankkredit und Repo haben unterschiedliche rechtliche und wirtschaftliche Sicherheitenstrukturen.','bonds-02','corporate-funding','fi-map','Interbank Funding'),
 G('Retail-Funding','Finanzierung aus dem breiteren Privatkunden- beziehungsweise entsprechenden Retail-Geschäft, beispielsweise Einlagen. Viele Einzelbeziehungen können Risiken anders verteilen, garantieren aber nicht unabhängig von Nachrichten, Konzentration und Zugriffsregeln stabile Gesamtbestände.','bonds-02','corporate-funding','deposits','Retail Funding'),
 G('Wholesale-Funding','Finanzierung über institutionelle oder andere großvolumige Marktgegenparteien, je nach Abgrenzung etwa Marktschuld oder Interbankmittel. Preis, Konzentration und kurzfristiger Rückzug können von Retail-Quellen abweichen; der Begriff allein bestimmt keine Besicherung.','bonds-02','corporate-funding','deposits','Wholesale Funding'),
 G('Unbelastete Sicherheiten','Vermögenswerte, die im betrachteten Zeitpunkt nicht bereits entgegenstehend gebunden sind und tatsächlich für eine neue vereinbarte Besicherung geliefert werden können. Marktwert, Zulässigkeit und operative Lieferbarkeit bleiben zusätzlich zu prüfen.','bonds-02','corporate-funding','liquidity-ladder','Unencumbered Collateral'),
 G('Finanzierungsliquidität','Fähigkeit, fällige Cashpflichten rechtzeitig aus verfügbaren eigenen Mitteln oder tatsächlich zugänglicher Finanzierung zu erfüllen. Sie unterscheidet sich von Marktliquidität, kann aber über Verkaufserlöse, Sicherheiten und Nachschüsse eng mit ihr zusammenhängen.','bonds-02','corporate-funding','liquidity-ladder','Funding Liquidity'),
 G('Wrong-Way Risk','Ungünstige Abhängigkeit zwischen der Zahlungsfähigkeit einer Gegenpartei und der Höhe beziehungsweise Deckung der Exposition. Im Repo kann der Sicherheitenwert gerade dann einbrechen, wenn der Schuldner ausfällt; heutige Übersicherung bildet diesen gemeinsamen Stress nicht vollständig ab.','bonds-02','corporate-funding','wrong-way','Wrong Way Risk'),
 G('Tri-Party-Repo','Repo mit ausgelagerten Sicherheiten- und Abwicklungsaufgaben bei einem dritten Agenten. Die Dienstleistung macht diesen nicht automatisch zum Kreditgaranten und ist nicht identisch mit einer zentralen Gegenpartei. Die wirtschaftliche Vereinbarung der beiden Finanzierungsparteien bleibt relevant.','bonds-02','corporate-funding','triparty','Tri-party Repo|Triparty Repo'),
 G('Tri-Party-Agent','Dienstleister für vereinbarte Auswahl, Verwahrung, Bewertung, Lieferung und Marginverwaltung von Sicherheiten. Agentenrolle und Übernahme des Kreditrisikos der anderen Parteien sind unterschiedliche Funktionen; eine Garantie folgt nicht allein aus der Bezeichnung.','bonds-02','corporate-funding','triparty','Tri-party Agent'),
 G('Overnight-Repo','Repo mit Rückabwicklung am nächsten vereinbarten Termin. Der heutige kurze Vertrag garantiert weder spätere Verlängerung noch unveränderte Sätze, Haircuts und Sicherheitenanforderungen für einen längeren Anlagehorizont.','bonds-02','corporate-funding','repo-terms','Overnight Repo'),
 G('Term Repo','Repo mit ausdrücklich vereinbarter bestimmter Laufzeit. Feste Laufzeit, Zinskonvention, Zwischenmargin und Sicherheitenrechte werden getrennt gelesen. Eine längere Zusage beseitigt keine Wertänderung oder Nachschusspflicht.','bonds-02','corporate-funding','repo-terms'),
 G('Open Repo','Repo ohne festes Enddatum, dessen Beendigung und gegebenenfalls Zinsanpassung den vereinbarten Regeln folgen. Offen bedeutet weder unendlich garantiert noch ohne Cashrückzahlungspflicht.','bonds-02','corporate-funding','repo-terms'),
 G('Finanzierungs-Renditespread','Differenz des betrachteten Unternehmensyield zum passend abgegrenzten Benchmark in gleicher Konvention. Dieser Rest kann Kredit-, Liquiditäts-, Options- und andere Vergleichseffekte enthalten; er ist kein garantierter Mehrertrag.','bonds-02','corporate-funding','yield-parts','Funding Yield Spread',[{label:'Spread',units:['corporate-funding','government-funding']}]),
 G('Fälligkeitenwand','Konzentration großer vertraglicher Tilgungen in einem nahen Zeitraum. Gesamtschuld oder durchschnittliche Laufzeit allein zeigen den dadurch entstehenden Ersatzbedarf nicht. Freie Mittel, Reserven und tatsächlich verfügbare Quellen werden termingenau gegenübergestellt.','bonds-02','corporate-funding','maturity-wall','Maturity Wall'),
 G('Liquiditätsspirale','Mögliche Rückkopplung aus fallenden Vermögenspreisen, höherem Finanzierungs- oder Sicherheitenbedarf und erzwungenen Verkäufen, die weitere Preisbewegungen auslösen. Sie ist ein Stressmechanismus und kein zwangsläufiger Verlauf jedes Kursrückgangs.','bonds-02','corporate-funding','spiral','Liquidity Spiral'),
 G('Repo-Close-out','Vertragliche Abwicklung beziehungsweise Beendigung nach einem relevanten Ereignis einschließlich Bewertung und möglicher Verwertung oder Ersatzbeschaffung. Ein momentaner Sicherheitenfehlbetrag ist nicht automatisch der endgültige Verlust; Zeit, Kosten, Rechte und weitere Ansprüche zählen.','bonds-02','corporate-funding','repo-risks','Repo Close-out',[{label:'Close-out',units:['corporate-funding']}]),
 G('Anleiheindex','Nach bestimmten Regeln abgegrenzter und gewichteter Korb festverzinslicher Instrumente samt definierter Messreihe. Universum, Preisquelle, Cashbehandlung, Währung und Umbautermine gehören zur Methodik. Ein fortlaufender Index hat nicht automatisch die Endfälligkeit eines heutigen Mitglieds und ist keine garantierte Anlagerendite.','bonds-04','bond-trading','index-map','Bond Index|Rentenindex'),
 G('Benchmark','Ausdrücklich abgegrenzter Vergleichsmaßstab für Markt- oder Anlageleistung. Währung, Kreditqualität, Laufzeit, Ertrags- und Kostenbehandlung sollten zum Mandat oder zu erklärten Abweichungen passen. Größe oder Bekanntheit allein machen eine Messlatte nicht für jedes Portfolio geeignet.','bonds-04','bond-trading','benchmark-fit','Benchmarks'),
 G('Investment Grade','Üblicher höherer Kreditqualitätsbereich nach der verwendeten Rating- oder Auswahlklassifikation. Die tatsächlich maßgeblichen Agenturen, Instrumente und Grenzen werden geprüft. Die Einordnung ist keine Garantie voller Zahlung und sagt allein wenig über Duration oder Handelbarkeit.','bonds-04','bond-trading','credit','Investment-Grade|IG'),
 G('High Yield','Übliche Bezeichnung für einen unterhalb des Investment-Grade-Bereichs eingeordneten Kreditmarkt beziehungsweise entsprechende Instrumente. Der höhere versprochene Yield ist keine Garantie höheren tatsächlichen Anlegerertrags. Fehlendes Rating und ausdrücklich niedriges Rating sind nicht automatisch derselbe Informationsstand.','bonds-04','bond-trading','credit','High-Yield'),
 G('Sovereign-Emittent','Staatlicher Schuldner auf zentralstaatlicher Ebene. Einnahmen, Währung, Finanzierungsfähigkeit und Zahlungsbereitschaft bestimmen die konkrete Analyse. Ein regionaler oder staatsnaher Emittent ist nicht allein wegen seiner Bezeichnung derselbe direkte Anspruch gegen den Zentralstaat.','bonds-04','bond-trading','issuers','Sovereign|Sovereign Issuer'),
 G('Supranationaler Emittent','Überstaatliche Institution mit eigenem Mandat, Kapital- und Finanzierungsrahmen. Die konkrete Verpflichtung und mögliche Unterstützung werden aus ihren Bedingungen beurteilt. Mitgliedschaft schafft nicht ohne weitere Grundlage eine unbegrenzte individuelle Garantie jedes Mitgliedstaats.','bonds-04','bond-trading','issuers','Supranational|Supranational Agency'),
 G('Cashflow Matching','Abstimmung vertraglicher oder modellierter Anlagezahlungen auf Verpflichtungen nach Betrag, Zeitpunkt und Währung. Bloß gleiches Endnominal genügt bei unterschiedlichen Terminen nicht. Kreditfähigkeit, Optionen und Durchsetzbarkeit bleiben zusätzlich zu prüfen; Cashflow Matching ist nicht automatisch dasselbe wie Duration Matching.','portfolio-09','bond-trading','liability','Cash Flow Matching|Cashflow-Matching'),
 G('Marktwertgewichtung','Gewichtung von Positionen nach ihren vergleichbaren Marktwerten relativ zum gesamten Korb. Bei Anleihen gehören Vollpreis, tatsächlich erfasstes Nominal und gegebenenfalls Währungsumrechnung dazu. Eine größere Schuldmenge kann das Gewicht erhöhen, ohne eine bessere Kreditqualität zu beweisen.','bonds-04','bond-trading','market-value','Market-Value Weighting'),
 G('Dirty Price','Voller Anleihepreis einschließlich der nach Konvention berücksichtigten Stückzinsen. In einer Notierung je hundert Nominal muss dieser Preis für den Geldbetrag durch hundert geteilt werden. Der volle Anfangswert gehört in die vollständige Anleger-Renditerechnung.','bonds-03','bond-trading','market-value','Vollpreis|Full Price'),
 G('Clean Price','Anleihepreis ohne die gesondert abgegrenzten Stückzinsen. Er ermöglicht einen Preisvergleich ohne deren laufenden Aufbau, ist aber nicht automatisch der gesamte zu zahlende Abrechnungsbetrag. Kaufseite, Notierungsbasis und Konvention müssen bekannt sein.','bonds-03','bond-trading','market-value'),
 G('Stückzins','Nach der maßgeblichen Konvention abgegrenzter aufgelaufener Kuponanteil. In einer gewöhnlichen Vollpreisrechnung wird er zum Clean Price addiert. Der Kupontermin verändert Cash und verbleibenden Anspruch; bereits bezahlte Stückzinsen werden nicht nochmals als neuer Gewinn gezählt.','bonds-03','bond-trading','coupon-date','Stückzinsen|Accrued Interest'),
 G('Anleihegesamtrendite','Vollständiger Wertzuwachs aus verbleibendem Bondwert und tatsächlichen zugehörigen Cashzahlungen relativ zum Anfangsvollwert. Tilgung muss zugleich den verbleibenden Nominalbestand vermindern. Währung, Kosten, Steuern und Wiederanlage hängen vom betrachteten Maß ab; Kupon oder Yield allein sind kein Ersatz.','bonds-04','bond-trading','return-formula','Bond Total Return',[{label:'Total Return',units:['bond-trading']},{label:'Gesamtrendite',units:['bond-trading']}]),
 G('Preisindex','Indexmaß, das die definierte Preisbewegung misst und nicht automatisch die vollständigen ausgeschütteten Erträge umfasst. Bei Performancevergleichen wird geprüft, ob das Gegenstück ebenfalls ein Preismaß oder ein vollständiges Ertragsmaß ist. Preis-, Stückzins- und Wiederanlagekonventionen bleiben wichtig.','bonds-04','bond-trading','reinvestment','Price Index'),
 G('Cashkuponbeitrag','Beitrag tatsächlich erhaltener Cashkupons relativ zum Anfangsmarktwert der betrachteten Positionen. Er ist für sich noch kein um Anfangs- und Endstückzinsen bereinigter Periodenzinsertrag. Mit der korrespondierenden vollständigen Preisänderung kann er eine korrekte Gesamtrenditezerlegung bilden.','bonds-04','bond-trading','return-formula','Cash Coupon Contribution'),
 G('Stückzinsbereinigter Ertragsbeitrag','Im eigenen Beispiel Cashkupon plus Änderung der Stückzinsen, geteilt durch Anfangsvollwert. So wird bereits im Kaufbetrag enthaltener Kuponanspruch vom neu entstandenen Periodenertrag unterschieden. Mit der konsistenten Clean-Price-Änderung ergibt sich die vollständige Gesamtrendite.','bonds-04','bond-trading','return-formula'),
 G('Anfangsmarktwertgewicht','Gewicht einer Position nach ihrem Marktwert vor der betrachteten Renditeperiode. Für unveränderte Bestände lässt sich damit die tatsächliche Korbrendite aus Einzelrenditen abstimmen. Endgewichte würden Gewinner nachträglich stärker gewichten und sind kein pauschaler Ersatz.','bonds-04','bond-trading','beginning-weights','Beginning-of-Period Weight'),
 G('Indexobergrenze','Methodisch definierte maximale Gewichtung eines Titels, Emittenten oder anderen Indexsegments. Gekappte Gewichte erfordern eine festgelegte Weiterverteilung und gegebenenfalls weitere Iterationen. Eine bloße Kürzung ohne Erklärung des Restgewichts beschreibt keine vollständige Normierung.','bonds-04','bond-trading','index-caps','Index Cap'),
 G('Indexumbau','Nach der Indexmethodik wirksame Änderung von Mitgliedern oder Gewichten. Fixing, Ankündigung und eigentlicher Wirksamkeitstermin können auseinanderfallen. Ein neutraler Umbau darf keinen fiktiven Anlagegewinn allein aus neuer Mengenbasis erzeugen und löscht keine vorherigen Verluste.','bonds-04','bond-trading','rebalancing','Index Rebalancing',[{label:'Rebalancing',units:['bond-trading']}]),
 G('Index-Fixing','Methodisch bestimmter Referenz- oder Festlegungstermin für den betrachteten Indexprozess. Er kann etwa Informationen für die künftige Zusammensetzung einfrieren. Das ist nicht automatisch derselbe Zeitpunkt wie ein heutiger ausführbarer Handelsquote oder die wirksame Umstellung der Performancebasis.','bonds-04','bond-trading','rebalancing','',[{label:'Fixing',units:['bond-trading']}]),
 G('Indexverkettung','Verknüpfung aufeinanderfolgender Renditeperioden beziehungsweise neutral normierter Indexbasen. Änderungen der Zusammensetzung werden so von tatsächlicher Anlageperformance getrennt. Gebühren und Ausführungsabweichungen eines realen Fonds verschwinden dadurch nicht.','bonds-04','bond-trading','rebalancing','Index Chaining'),
 G('Tracking Error','Streuung der abgegrenzten periodischen Renditedifferenzen eines Portfolios gegenüber seinem Vergleichsindex. Periodenfrequenz und eine mögliche Annualisierung werden angegeben. Ein konstanter Gebührenrückstand kann eine negative durchschnittliche Differenz erzeugen, ohne große Streuung; Tracking Error ist nicht die Differenz selbst.','portfolio-12','bond-trading','replication'),
 G('Tracking Difference','Abgegrenzte Renditedifferenz eines Portfolios zum passenden Vergleichsindex über den angegebenen Zeitraum. Gebühren, Cash, Titelwahl, Preisquelle und Umsetzung können beitragen. Sie ist von der Streuung periodischer Abweichungen, dem Tracking Error, zu unterscheiden.','portfolio-12','bond-trading','replication'),
 G('Sampling','Nachbildung wesentlicher Risiko- und Ertragseigenschaften eines größeren Universums mit einer ausgewählten Teilmenge. Das kann Umsetzung sparen, lässt aber Titel-, Cashflow- und weitere Risikodifferenzen gegenüber Vollreplikation zurück. Eine passende Durchschnittslaufzeit allein beweist keine vollständige Indexgleichheit.','path-portfolio-01','bond-trading','replication'),
 G('Anleihe-OTC','Außerbörsliche Handelsorganisation für bestehende Anleiheansprüche, häufig mit Händlerintermediation oder elektronischer Preisabfrage. OTC bedeutet weder automatisch unreguliert noch zwingend nur telefonisch. Tatsächliche Veröffentlichung und Ausführung folgen dem jeweiligen Markt- und Transaktionsrahmen.','bonds-04','bond-trading','venues','OTC-Rentenmarkt',[{label:'OTC',units:['bond-trading']}]),
 G('Request for Quote','Anfrage nach Preisen für ein bestimmtes Instrument, eine Seite, Größe und Abwicklung. Antworten können hinsichtlich Verbindlichkeit, Gültigkeitsdauer und verfügbarer Menge verschieden sein. Ein RFQ-Verfahren ist nicht allein ein zentrales durchgängiges Orderbuch.','bonds-04','bond-trading','venues','RFQ'),
 G('Firm Quote','Nach den angegebenen Bedingungen verwendbarer verbindlicher Preis-Mengen-Quote für eine bestimmte Seite und Gültigkeit. Gebühren, Frist und Abwicklung sind Teil der Umsetzung. Daraus wird keine unbegrenzte Ausführung jeder späteren oder größeren Order abgeleitet.','bonds-04','bond-trading','venues'),
 G('Indikativer Preis','Preisinformation, die allein noch keine vollständige verbindliche Ausführung der gewünschten Order zusagt. Instrument, Zeitpunkt, Seite und Größe werden mit tatsächlichen verfügbaren Gegenangeboten abgeglichen. Eine günstige indikative Zahl ist nicht automatisch die günstigste realisierbare Umsetzung.','bonds-04','bond-trading','transparency','Indicative Quote'),
 G('Anleihe-Bid','Preis, zu dem der betrachtete Händler nach seinen Quote-Bedingungen Anleihebestand kauft. Ein sofort verkaufender Anleger trifft diese Seite. Notierung, Stückzinsen, verfügbare Menge und separate Gebühren bestimmen erst gemeinsam den Geldbetrag.','bonds-04','bond-trading','quote','Bond Bid',[{label:'Bid',units:['bond-trading','government-funding']}]),
 G('Anleihe-Ask','Preis, zu dem der betrachtete Händler nach seinen Quote-Bedingungen Anleihebestand verkauft. Ein sofort kaufender Anleger trifft diese Seite. Der Clean Ask ist vor Hinzurechnung zutreffender Stückzinsen und Gebühren nicht automatisch der volle Abrechnungsbetrag.','bonds-04','bond-trading','quote','Bond Ask',[{label:'Ask',units:['bond-trading','government-funding']}]),
 G('Anleihe-Mid','Mittlerer Preis eines vergleichbaren Bid-/Ask-Paars, hier deren arithmetischer Mittelwert. Er kann eine gemeinsame Kostenvergleichsbasis sein, muss aber nicht selbst für jede Order ausführbar sein. Zeitpunkt, Instrument, Größe und Preisnotierung müssen zusammenpassen.','bonds-04','bond-trading','costs','Bond Mid',[{label:'Mid',units:['bond-trading','government-funding']}]),
 G('Anleihe-Quotenspread','Differenz zwischen vergleichbarem Ask und Bid desselben Instruments. Als relative Quote wird sie hier durch den Mid geteilt. Ein einseitiger Vergleich zum Mid, ein voller Roundtrip und ein Renditespread zu einer Zinskurve sind verschiedene Größen.','bonds-04','bond-trading','costs','Bond Quoted Spread',[{label:'Bid-Ask-Spread',units:['bond-trading','government-funding']}]),
 G('All-in-Kaufbetrag','Gesamter Geldbetrag der betrachteten Ausführung einschließlich voller Preisbasis und erfasster separater Gebühren. Vergleichbare Größe, Termin und tatsächlich verfügbare Quote sind vorausgesetzt. Ein niedrigerer Clean Ask kann nach festen Gebühren trotzdem teurer sein.','bonds-04','bond-trading','rfq','All-in Cost|All-in-Preis'),
 G('Roundtrip','Zusammen betrachtetes Hin- und Rückgeschäft, etwa sofortiger Kauf und Verkauf derselben Position. Im isolierten unveränderten Quote-Fall belastet der volle Spread statt nur eines halben Spreads; Gebühren beider Seiten kommen gegebenenfalls hinzu. Zeitliche Preisbewegung und andere Kosten erfordern zusätzliche Abgrenzung.','bonds-04','bond-trading','costs','Round Trip'),
 G('TRACE','Trade Reporting and Compliance Engine der FINRA für erfasste OTC-Transaktionsmeldungen nach den geltenden Regeln. Nachhandelstransparenz ist kein jederzeit ausführbarer Quote für jede Menge und kein universelles internationales Orderbuch. Quelle, Zeitpunkt, Größe und Anwendungsbereich werden gelesen.','bonds-04','bond-trading','transparency','Trade Reporting and Compliance Engine'),
 G('On-the-run','Im betrachteten Treasury-Markt typischerweise die neueste Benchmarkemission des relevanten Segments. Handelsaktivität kann sich von älteren abgelösten Titeln unterscheiden. Die Bezeichnung ist keine pauschale Garantie enger Spreads oder voller verfügbarer Tiefe in jedem Zustand.','bonds-04','bond-trading','liquidity','On the run'),
 G('Off-the-run','Ältere von einer neueren Benchmark abgelöste Emission im betrachteten Treasury-Kontext. Sie ist damit nicht automatisch fällig, wertlos oder absolut illiquide. Verwendbarkeit etwa für Futures-Lieferung und konkrete Marktbedingungen können die Nachfrage wesentlich verändern.','bonds-04','bond-trading','liquidity','Off the run'),
 G('Solvenz','Fähigkeit eines Schuldners, seine relevanten Verpflichtungen zu erfüllen. Sie ist von der schnellen Verkaufbarkeit eines bestimmten Anspruchs im Markt zu unterscheiden. Solvenz und Marktliquidität können sich im Stress gegenseitig beeinflussen, ohne dieselbe Kennzahl zu sein.','bonds-04','bond-trading','liquidity','Solvency'),
 G('Anleihemarktliquidität','Handelbarkeit eines konkreten Anleiheanspruchs in der gewünschten Größe, Zeit und Kostenspanne. Spread, Tiefe, Frequenz und tatsächlich verfügbare Gegenofferten gehören dazu. Gesamtschuld eines Emittenten oder ein ruhiger letzter Beobachtungskurs beweisen keine sofortige Vollausführung.','bonds-04','bond-trading','liquidity','Bond Liquidity',[{label:'Marktliquidität',units:['bond-trading']}]),
 G('Uniform-Price-Auktion','Auktionsverfahren mit einer nach den Regeln gemeinsamen Ergebnisrate beziehungsweise Preisbasis erfolgreicher Gebote. Gebotsreihenfolge, Grenzmenge und proportionale Zuteilung müssen separat festgelegt werden. Das Treasury-Beispiel ist ein konkretes Verfahren und keine universelle Regel jeder Auktion.','bonds-04','bond-trading','auction','Uniform-Price Auction'),
 G('Zuteilungsquote','Tatsächlich zugeteilter Betrag relativ zum maßgeblich angefragten Betrag. Dreißig zugeteilte Mio. bei fünfzig nachgefragten Mio. ergeben sechzig Prozent, nicht dreißig Prozent. Die Verteilung am Grenzsatz hängt vom vorgegebenen Verfahren ab.','bonds-04','bond-trading','auction','Allocation Fraction'),
 G('Nettoemissionserlös','Tatsächlich verfügbarer neuer Finanzierungszufluss nach der vereinbarten Preis- und Kostenabrechnung. Er ist vom vertraglichen Nominal und Bruttoerlös zu unterscheiden. Ein späterer Eigentümerwechsel derselben Stücke verändert den ursprünglichen Nettozufluss nicht rückwirkend.','bonds-04','bond-trading','issuance-case','Net Issue Proceeds'),
 G('Indexreplikation','Umsetzung eines Indexmandats durch einen tatsächlichen Bestand und seine erforderlichen Änderungen. Vollständige Nachbildung und Sampling sind verschiedene Verfahren. Theoretischer Referenzpreis, Mindeststückelung, Cash, Kosten und verfügbare Liquidität können die reale Performance vom Index abweichen lassen.','bonds-04','bond-trading','replication','Index Replication'),
 G('Tilgung','Rückführung des ausstehenden Schuldnominals. Im einfachen Zahlungsplan besteht die gesamte Rate aus Zins plus Tilgung; nur die Tilgung reduziert die bisherige Nominalschuld. Vorzeitige, planmäßige und bedingte Tilgung können andere Termine besitzen.','bonds-03','bond-cashflows','building-blocks','Tilgungen|Principal Repayment'),
 G('Restschuld','Nach den bis zum betrachteten Zeitpunkt geleisteten Tilgungen verbleibendes Schuldnominal, gegebenenfalls einschließlich vertraglich kapitalisierter Beträge. Sie ist weder automatisch der Marktwert noch die Summe aller noch fälligen Zinszahlungen. Der Zeitpunkt vor oder nach einer Rate muss angegeben werden.','bonds-03','bond-cashflows','building-blocks','Outstanding Principal|Restnominal'),
 G('Gleiche Tilgung','Zahlungsplan mit gleichen Nominalrückführungen an regelmäßigen Terminen. Bei festem positivem Zins auf die jeweils verbleibende Schuld fallen Zinsen und gesamte Rate im Zeitverlauf. Dies unterscheidet sich von einer Annuität mit konstanter gesamter Rate.','bonds-03','bond-cashflows','equal-principal','Equal Principal|Equal-Principal Amortization|Konstante Tilgung'),
 G('Annuität','Folge gleich hoher regelmäßiger Gesamtzahlungen. Bei einem vollständig tilgenden Darlehen mit positivem festem Zins enthält jede Rate sinkenden Zins und steigende Tilgung. Gleiche Gesamtzahlung ist daher nicht gleiche Tilgung. Allgemein lässt sich eine Annuität als nach- oder vorschüssige Zahlungsreihe bewerten.','quant-02','bond-cashflows','annuity-derivation','Annuitäten|Annuity'),
 G('Annuitätendarlehen','Darlehen mit konstanter regelmäßiger Schuldendienstrate aus Zins und Tilgung. Die Rate wird so bestimmt, dass die verbleibende Schuld nach der vereinbarten Zahl von Zahlungen vollständig abgebaut ist, sofern keine abweichende Ballonstruktur vorliegt. Zahlungsfrequenz und Zinskonvention müssen zusammenpassen.','bonds-03','bond-cashflows','annuity-case','Level-Payment Loan|Annuitätenkredit'),
 G('Vollamortisation','Vollständiger planmäßiger Abbau des anfänglichen Nominals durch die vereinbarten Tilgungen bis zum Endtermin. Finanzierungsamortisation bezeichnet hier Schuldentilgung, nicht die planmäßige Aufwandsverteilung eines immateriellen Vermögenswerts.','bonds-03','bond-cashflows','annuity-derivation','Fully Amortizing Loan|Fully Amortizing|Tilgungsamortisation',[{label:'Amortization',units:['bond-cashflows']}]),
 G('Ballonzahlung','Größere verbleibende Endzahlung bei einer Finanzierung mit vorheriger Teiltilgung. Endtilgung und letzter Zins werden getrennt ermittelt. Der Ballon reduziert gegenüber vollständiger Endfälligkeit je nach Plan das Refinanzierungsvolumen, beseitigt es aber nicht.','bonds-03','bond-cashflows','balloon','Balloon Payment|Balloon Loan|Ballonplan'),
 G('Weighted Average Life','Durchschnittlicher Zeitpunkt der Nominalrückführung, gewichtet mit den jeweiligen Tilgungsbeträgen. Kupons und Abzinsung werden nicht als Marktwertgewichte eingesetzt; deshalb ist WAL keine Duration. Bei unsicheren vorzeitigen Tilgungen sind die verwendeten Szenarien oder Erwartungen offenzulegen.','bonds-03','bond-cashflows','wal','WAL|Gewichtete Tilgungszeit'),
 G('Refinanzierungsrisiko','Risiko, dass fällige Verpflichtungen nicht oder nur zu ungünstigen Bedingungen durch neue Finanzierung ersetzt werden können. Ein großer Endtilgungsbetrag kann die Belastung konzentrieren. Das Risiko ist von laufendem Vertragszins und bloß positivem Buchgewinn zu unterscheiden.','bonds-03','bond-cashflows','balloon','Refinancing Risk'),
 G('Wiederanlagerisiko','Risiko veränderlicher Anlagebedingungen für früher erhaltene Zahlungen. Kupons, Tilgungen und ein Emittenten-Call können Cash vor dem ursprünglichen Anlagehorizont liefern, das dann zu einem ungünstigeren Satz wiederangelegt wird. Vergleichsvermögen werden auf denselben Endtermin gebracht.','bonds-03','bond-cashflows','reinvestment','Reinvestment Risk'),
 G('Nullkuponanleihe','Schuldinstrument ohne laufende Kuponzahlungen und mit vertraglicher Endzahlung. Der Preis ergibt sich aus Abzinsung dieser Endzahlung; der wirtschaftliche Zuwachs kann ohne zwischenzeitlichen Cashkupon entstehen. Kreditrisiko, Preisrisiko bei Verkauf und ein gegebenenfalls früherer Steueransatz bleiben möglich.','bonds-02','bond-cashflows','zero','Zero-Coupon Bond|Zero Coupon Bond',[{label:'Zero',units:['bond-cashflows']}]),
 G('Payment-in-Kind','Erfüllung einer Zinsverpflichtung durch zusätzliche Schuld statt sofortiger Cashzahlung. Im einfachen PIK-Modell wächst das ausstehende Nominal; bei weiterer Verzinsung entstehen Zinsen auch auf früher kapitalisierte Zinsen. Die Liquiditätsentlastung ist keine Zinsfreiheit.','bonds-03','bond-cashflows','pik','PIK|PIK-Zins|Payment in Kind'),
 G('PIK-Toggle','Vertraglich geregelte Wahl oder Umschaltung zwischen Cashzins und einer Zinszahlung durch zusätzliche Schuld. Berechtigung, Auslöser und möglicher anderer Satz werden gelesen; die Möglichkeit ist keine Garantie späterer Rückzahlung.','bonds-03','bond-cashflows','pik','PIK Toggle'),
 G('Deferred Coupon','Aufgeschobene vertragliche Kuponzahlung. Ob aufgeschobene Beträge selbst verzinst, dem Nominal zugeschlagen oder erst später separat bezahlt werden, hängt von den Bedingungen ab. Aufschub und vollständiger Zinsverzicht sind nicht dasselbe.','bonds-03','bond-cashflows','pik','Deferred-Coupon|Zinsaufschub'),
 G('Sinking Fund','Vertraglicher Mechanismus zur planmäßigen Rückführung einer Emission, etwa durch Mittelbereitstellung, Rückkauf oder Auswahl einzulösender Stücke. Die genaue Regel bestimmt, wann der einzelne Inhaber Kapital zurückbekommt. Sie beweist nicht allein, dass alle künftigen Rückführungsmittel bereits insolvenzfest vorhanden sind.','bonds-03','bond-cashflows','sinking','Sinking Funds'),
 G('Waterfall','Vertragliche Reihenfolge, in der verfügbare Zahlungen beziehungsweise nach eigenen Regeln Verluste auf Ansprüche verteilt werden. Zinsen, Tilgung, Reserven und Anspruchsklassen können getrennte Stufen besitzen. Eine Zahlungsreihenfolge ist nicht automatisch dieselbe Regel wie eine Verlustzuweisung.','bonds-13','bond-cashflows','waterfall','Zahlungswasserfall|Wasserfall'),
 G('Floater','Instrument mit nach einer Vertragsregel veränderlichem Kupon, etwa Referenzsatz plus festem Spread auf das ausstehende Nominal. Festlegung, Beobachtungsperiode, Zinsfraktion und Begrenzungen bestimmen den Cashbetrag. Anpassung des Referenzsatzes beseitigt weder Kredit- noch Marktspreadrisiko.','bonds-03','bond-cashflows','floating','Floating-Rate Note|Floating Rate Note|FRN'),
 G('Zinsreset','Vertragliche Neufestlegung einer Zinskomponente für eine bestimmte Periode. Ein vorschüssig festgelegter Satz und ein erst über die Periode beobachteter Satz erzeugen unterschiedliche Informations- und Berechnungszeitpunkte. Ein Referenzreset ist nicht automatisch eine Neuverhandlung des Kreditspreads.','bonds-03','bond-cashflows','floating','Reset|Rate Reset'),
 G('Kuponfloor','Vertragliche Untergrenze einer Kuponkomponente. Ob sie den Referenzsatz oder den gesamten Satz einschließlich Spread begrenzt, bestimmt den resultierenden Cashkupon. Ein Floor ist keine Garantie des Marktpreises oder der Zahlungsfähigkeit.','bonds-03','bond-cashflows','floor-cap','Coupon Floor|Zinsfloor',[{label:'Floor',units:['bond-cashflows']}]),
 G('Kuponcap','Vertragliche Obergrenze einer Kuponkomponente. Sie kann den Vorteil des Anlegers bei steigendem Referenzzins begrenzen. Die Bemessungsgrundlage und die Stelle der Begrenzung in der Zinsformel müssen bekannt sein.','bonds-03','bond-cashflows','floor-cap','Coupon Cap|Zinscap',[{label:'Cap',units:['bond-cashflows']}]),
 G('Inverse Floater','Instrument, dessen vertraglicher Kupon beispielsweise aus einer festen Größe minus einem Vielfachen des Referenzsatzes berechnet wird. Dann fällt der Kupon bei steigendem Referenzsatz, gegebenenfalls bis zu einem Floor. Variabel bedeutet deshalb nicht automatisch gleichgerichtet zum Marktzins.','bonds-03','bond-cashflows','floor-cap','Inverse-Floater'),
 G('Step-up-Kupon','Kupon, der nach festem Kalender oder bei einem genau definierten Ereignis um vereinbarte Beträge steigt. Planmäßiger Anstieg und bedingter Trigger sind verschiedene Regeln. Ein Aufschlag ist keine automatische vollständige Kompensation einer Kreditverschlechterung.','bonds-03','bond-cashflows','step-up','Step-up Coupon|Step-up|Step-Up Bond'),
 G('Indexanleihe','Anleihe mit vertraglich an einen Index gebundenen Zahlungen oder Bemessungsgrundlagen. Beispielsweise kann ein Preisindex das Nominal und damit den Geldkupon bei festem Kuponsatz verändern. Beobachtungsverzögerung, Basis, Floor und Steuerwirkung sind produktabhängig.','bonds-03','bond-cashflows','inflation','Index-linked Bond|Inflation-linked Bond|Inflationsindexierte Anleihe'),
 G('Treasury Inflation-Protected Securities','US-Treasury-Instrumente mit indexangepasstem Nominal und halbjährlichem Kupon auf dieses Nominal. Bei Fälligkeit gilt nach den beschriebenen Produktregeln mindestens das ursprüngliche Nominal. Das ist keine jederzeitige Marktpreis- oder sekundäre Kaufpreisgarantie und keine allgemeine Regel aller Indexanleihen.','bonds-03','bond-cashflows','inflation','TIPS'),
 G('Dual-Currency-Instrument','Instrument, dessen Vertragszahlungen in unterschiedlichen Währungen erfolgen können, etwa Kupon in einer und Tilgung in einer anderen. Zahlungswährung, Wechselkursnotierung und Anlegerwährung müssen je Zahlung erfasst werden. Eine zusätzliche Währungswahl wäre ein gesondertes Recht.','bonds-03','bond-cashflows','dual-currency','Dual-Currency Bond|Dual Currency Bond'),
 G('Emittenten-Call','Recht des Emittenten, einen Schuldanspruch nach den vereinbarten Preisen, Terminen und Bedingungen vorzeitig abzulösen. Der Anleger hat dieses Wahlrecht abgegeben und kann günstige spätere Kupons verlieren. Call-Preis und Ausübungsdatum bilden keinen jederzeit garantierten Mindestmarktpreis.','bonds-03','bond-cashflows','rights','Issuer Call|Callable Bond',[{label:'Call',units:['bond-cashflows']}]),
 G('Anleger-Put','Recht des Anlegers, eine Rücknahme nach vertraglichem Termin, Preis und Bedingungen zu verlangen. Es eröffnet eine Alternative zur Fortsetzung; Zahlungsfähigkeit und Durchsetzbarkeit bleiben wesentlich. Es ist keine jederzeitige Garantie eines bestimmten Börsenkurses.','bonds-03','bond-cashflows','put-case','Investor Put|Putable Bond|Puttable Bond',[{label:'Put',units:['bond-cashflows']}]),
 G('Call Protection','Vertraglicher Schutz vor ordentlicher Emittentenkündigung während eines definierten Zeitraums. Sonderkündigungen und spätere Ausübungstermine müssen zusätzlich geprüft werden. Ein erst später ausübbarer Call begrenzt nicht automatisch schon jeden heutigen Marktpreis auf seinen Ausübungsbetrag.','bonds-03','bond-cashflows','call-protection','Call-Schutz'),
 G('Make-Whole-Call','Kündigungsregel mit einem nach Vertragsformel bestimmten Ablösebetrag, beispielsweise anhand einer definierten Diskontierung verbleibender Zahlungen und eines Aufschlags. Die Formel, Referenzkurve, Frist und mögliche Mindestbeträge müssen gelesen werden; der Preis ist nicht automatisch Nominal.','bonds-03','bond-cashflows','call-protection','Make-Whole|Make-Whole Call'),
 G('Bermudische Ausübung','Optionsregel, die Ausübung an mehreren bestimmten Terminen erlaubt. Sie unterscheidet sich von einer einzigen europäischen Ausübung und einer während eines definierten Zeitraums laufend erlaubten amerikanischen Ausübung. Die konkreten Daten bleiben maßgeblich.','bonds-03','bond-cashflows','call-protection','Bermudan Exercise|Bermudisch'),
 G('Fortsetzungswert','Wert der verbleibenden Zahlungen, wenn der konkret betrachtete Anspruch fortgesetzt statt am Entscheidungstermin ausgeübt oder abgelöst wird. Er wird mit der tatsächlich erlaubten Alternative am selben Zeitpunkt verglichen. Er ist nicht die bloße unaufgezinste Summe späterer Zahlungen.','bonds-03','bond-cashflows','call-case','Continuation Value'),
 G('Bond Floor','Analytischer Wert eines vergleichbaren reinen Schuldanspruchs ohne Wandlungswahl. Er hilft bei der Einordnung einer Wandelanleihe, ist aber wegen Kreditrisiko und Vertragsabhängigkeit keine zugesagte jederzeitige Auszahlung. Voller Wandelpreis, sofortiger Aktienwert und Bond Floor werden getrennt behandelt.','bonds-03','bond-cashflows','conversion','Anleihefloor'),
 G('Sukuk','Instrumente mit über zulässige Vertrags- und Vermögensbeziehungen strukturierten Ansprüchen, etwa Nutzungs- oder Beteiligungsrechten. Zahlungsquelle, effektive Rechte, Rückkaufzusagen und Rechtsordnung bestimmen den konkreten Zugriff. Der Name allein garantiert weder gewöhnlichen Zinsdarlehenscharakter noch insolvenzfestes Eigentum oder volle Rückzahlung.','bonds-03','bond-cashflows','sukuk','Sukūk'),
 G('Asset-based Sukuk','Sukuk-Struktur, bei der vertragliche Zahlungs- oder Rückkaufverpflichtungen eines Originators wesentlich bleiben können, obwohl Vermögensbezug besteht. Tatsächlich übertragene und durchsetzbare Rechte müssen aus den Dokumenten bestimmt werden. Die Bezeichnung allein beweist keinen direkten insolvenzfesten Vermögenszugriff.','bonds-03','bond-cashflows','sukuk','Asset-based-Struktur'),
 G('Asset-backed Sukuk','Sukuk-Struktur mit wirksamen Vermögensrechten und realisierbarem Zugriff auf die zugrunde liegende Basis nach den tatsächlichen Bedingungen. Im historischen IFSB-Konzept ist die effektive Übertragung wesentlich. Vermögensbezug beseitigt Wert-, Ertrags- und Durchsetzungsrisiken nicht; heutige konkrete Regeln werden gesondert geprüft.','bonds-03','bond-cashflows','sukuk','Asset-backed-Struktur'),
 G('Domestic Bond','Im betrachteten heimischen Markt ausgegebene Anleihe eines dort heimischen Emittenten nach der verwendeten Marktklassifikation. Sitz, Angebotsmarkt und Währung werden zusammen gelesen. Der Begriff ist keine Bonitäts- oder Steuerfreistellung.','bonds-03','bond-cashflows','classification','Domestic Bonds'),
 G('Foreign Bond','Anleihe eines ausländischen Emittenten im betrachteten Inlandsmarkt, typischerweise in dessen Währung. Beispielsweise kann eine US-Gesellschaft JPY in Japan ausgeben. Zahlungswährung allein verändert nicht den Sitz des Schuldners.','bonds-03','bond-cashflows','classification','Foreign Bonds'),
 G('Eurobond','Anleihe einer internationalen beziehungsweise Offshore-Platzierung nach der jeweiligen Marktklassifikation. Euro bezeichnet hier nicht zwingend die Währung EUR: Eine Eurodollar-Ausgabe zahlt beispielsweise USD. Angebots- und Übertragungsregeln, Anlegerstatus und Steuern bleiben separat zu prüfen.','bonds-03','bond-cashflows','classification','Eurobonds|Eurodollar Bond|Eurodollar-/Eurobond'),
 G('Samurai Bond','Im üblichen Marktgebrauch JPY-Anleihe eines ausländischen Emittenten im japanischen Inlandsmarkt. Sie ist ein Foreign-Bond-Beispiel. Der Name sagt weder allein etwas über Ausfallsicherheit noch über die persönliche Anlegerbesteuerung.','bonds-03','bond-cashflows','classification','Samurai-Anleihe|Samurai'),
 G('Global Bond','Ausgabe, die nach ihrer Struktur mehrere große Märkte gleichzeitig erschließen kann. Tatsächliche Angebotswege und Tranchen können unterschiedliche Bedingungen besitzen. Der internationale Zugang erzeugt keine pauschale Ausnahme von allen Markt- und Steuerregeln.','bonds-03','bond-cashflows','classification','Global Bonds'),
 G('Regulation S','US-Regelrahmen für qualifizierende Offshore-Angebote und -Verkäufe im Hinblick auf bestimmte Registrierungspflichten des Securities Act. Die Voraussetzungen und Regeln für die konkrete Transaktion sowie spätere Übertragung müssen geprüft werden. Offshore ist kein allgemeines Gütesiegel oder Freibrief gegenüber sämtlichen Gesetzen.','bonds-03','bond-cashflows','regulation','Reg S'),
 G('Quellensteuer','Steuerabzug an der Quelle einer Zahlung. Er beeinflusst den unmittelbar ausgezahlten Betrag, ist aber nicht automatisch gleich der endgültigen Gesamtsteuer. Anrechnung oder Erstattung hängen von den tatsächlich geltenden Regeln, Anlegerstatus und Nachweisen ab.','bonds-03','bond-cashflows','withholding','Withholding Tax|Quellenabzug'),
 G('Steueranrechnung','Nach den jeweiligen Regeln erlaubte Berücksichtigung bereits gezahlter oder einbehaltener Steuer bei einer weiteren endgültigen Steuerberechnung. Berechtigung, Höhe, Grenze und Zeitpunkt müssen bekannt sein. Ein Quellenabzug wird nicht ohne Grundlage gleichzeitig als vollständig anrechenbar und als zusätzliche Endsteuer behandelt.','bonds-03','bond-cashflows','withholding','Tax Credit'),
 G('Original Issue Discount','Nach dem jeweiligen Regelwerk bestimmter ursprünglicher Ausgabediscount gegenüber der definierten Endrückzahlung. Steuerlicher Ertragsansatz kann vor Cashzufluss erfolgen; die IRS-Publikation beschreibt einen konkreten US-Geltungsbereich mit Ausnahmen. OID ist nicht jeder spätere Marktpreisrückgang.','bonds-03','bond-cashflows','oid','OID'),
 G('Market Discount','Discount, der durch einen späteren Erwerb unter einer maßgeblichen Basis entsteht. Er ist vom ursprünglichen Ausgabediscount zu unterscheiden; steuerliche Behandlung und Zeitpunkt hängen vom jeweiligen Regime ab. Ein Preis unter Nominal liefert allein noch keine vollständige Steuerrechnung.','bonds-03','bond-cashflows','oid','Sekundärmarktdiscount'),
 G('Bond Premium','Kaufbetrag einer Anleihe über der maßgeblichen Nominal- oder Steuerbasis. Der negative Preisbeitrag bei späterer Rückzahlung und seine mögliche steuerliche Berücksichtigung werden zusätzlich zum Kupon erfasst. Bilanzielle und steuerliche Amortisation sind nicht pauschal identisch.','bonds-03','bond-cashflows','premium','Anleihepremium',[{label:'Premium',units:['bond-cashflows']}]),
 G('Tax-equivalent Yield','Unter vereinfachter Vergleichbarkeit benötigte steuerpflichtige Bruttorendite, deren Nettorendite einer angegebenen steuerfreien Rendite entspricht. Bei vollständig besteuerten Zinsen wird die steuerfreie Rendite durch eins minus Steuersatz geteilt. Unterschiedliche Risiken, Zeitpunkte und Vertragsrechte werden dadurch nicht gleichgesetzt.','bonds-03','bond-cashflows','tax-comparison','Tax Equivalent Yield|Steueräquivalente Rendite'),
 G('Gross-up','Vertragliche zusätzliche Zahlung, die unter den definierten Bedingungen bestimmte Abzüge ausgleichen soll. Umfang, begünstigter Anlegerkreis, Ausnahmen und mögliche Kündigungsrechte sind Teil der Klausel. Der Begriff garantiert nicht automatisch einen bestimmten Nettobetrag für jeden Anleger.','bonds-03','bond-cashflows','issuer-tax','Gross-up-Klausel'),
 G('Nominalwert','Vertraglich genannter Geldbetrag beziehungsweise Forderungsbasis. Bei einer Anleihe sind Nennbetrag, Ausgabeerlös und aktueller Marktpreis verschiedene Größen. Die Kupon- und Tilgungsbasis folgt den Bedingungen; nominal bedeutet auch keine automatische Bereinigung um Kaufkraftänderungen.','bonds-01','bond-features','nominal','Nominal|Nennwert'),
 G('Kupon','Vertragliche Zinszahlung eines Schuldinstruments für eine definierte Periode. Der jährliche Kuponsatz ist von ihrem Geldbetrag zu unterscheiden. Bei gleichen regelmäßigen Perioden ergibt sich die Zahlung aus Nominal mal Jahressatz geteilt durch Frequenz; andere Verträge benötigen die passende Zinsfraktion.','bonds-01','bond-features','coupon','Coupon'),
 G('Kuponsatz','Vertraglicher Zinssatz auf die festgelegte Bemessungsgrundlage. Ein fester Jahressatz ist nicht automatisch dieselbe Quote wie Jahreskupon durch aktuellen Kaufpreis. Zahlungsfrequenz, Zeitraum, Nominalbasis und gegebenenfalls Referenzsatz gehören zur vollständigen Definition.','bonds-01','bond-features','coupon','Coupon Rate'),
 G('Indenture','Vertragswerk einer Anleihe mit Zahlungsbedingungen, erfassten Schuldnern, Garantien, Rang, Sicherheiten, Covenants und Regeln zu Verstößen, Vertretung und Änderungen. Dokumentform und Rechtsrahmen können sich unterscheiden. Definitionen und Ergänzungen werden zusammen mit der Zusammenfassung gelesen.','bonds-01','bond-features','indenture','Bond Indenture|Anleihevertragswerk'),
 G('Anleihe-Covenant','Vertragliche Pflicht oder Beschränkung zum Schutz des definierten Gläubigeranspruchs. Affirmative Covenants verlangen Handlungen, negative beschränken sie. Testzeitpunkt, Geltungsbereich, Ausnahmen, Kennzahlendefinition und Rechtsfolgen sind Teil der Klausel; die bloße Überschrift genügt nicht.','bonds-01','bond-features','indenture','Bond Covenant|Bond Covenants',[{label:'Covenant',units:['bond-features']},{label:'Covenants',units:['bond-features']}]),
 G('Affirmative Covenant','Vertragsklausel, die eine bestimmte Handlung oder Erhaltungspflicht verlangt, etwa definierte Informationen vorlegen oder benannte Versicherungen aufrechterhalten. Positiv beschreibt die Pflicht und garantiert keine günstige wirtschaftliche Entwicklung. Umfang und Ausnahmen folgen dem konkreten Vertrag.','bonds-01','bond-features','affirmative','Affirmative Covenants|Positive Covenant|Positive Covenants'),
 G('Negative Covenant','Vertragsklausel, die bestimmte Handlungen begrenzt, etwa zusätzliche Schuld, Sicherheitenbestellung, Ausschüttung oder Vermögensverkauf. Die ökonomische Beschränkung entscheidet, nicht allein das Wort nicht oder muss. Erlaubte Ausnahmen und gleichzeitige Bedingungen werden geprüft.','bonds-01','bond-features','negative','Negative Covenants'),
 G('Negative Pledge','Klausel zur Beschränkung der Bestellung von Sicherheiten im definierten Umfang. Sie ist kein pauschales Verbot jeder zusätzlichen unbesicherten Finanzierung und schafft selbst nicht automatisch ein gleichwertiges Sicherheitenrecht. Ausnahmen und mögliche gleichrangige Besicherung sind aus dem Vertrag zu lesen.','bonds-01','bond-features','negative-pledge','Negative Pledge Clause|Negativerklärung'),
 G('Trustee','Im entsprechenden Vertragsrahmen beauftragte Institution mit festgelegten Vertretungs-, Verwaltungs- oder Durchsetzungsaufgaben für Anleiheinhaber. Die Rolle macht ihre eigenen Mittel nicht automatisch zur Zahlungsgarantie. Genaue Aufgaben und Handlungsvoraussetzungen ergeben sich aus Vertrag und Rechtsrahmen.','bonds-01','bond-features','indenture','Indenture Trustee|Anleihetreuhänder|Treuhänder'),
 G('Covenant Headroom','Abstand einer konkret definierten Vertragsgröße zu ihrer Grenze. Im Auron-Modell sind es zulässige Nettoschulden minus tatsächliche definierte Nettoschulden bei festem EBITDA. Das ist weder eine verbindliche Kreditzusage noch ohne weitere Cash- und Vertragsprüfung ein zusätzlicher Bruttokreditbetrag.','bonds-01','bond-features','funding','Leverage-Spielraum|Covenant-Spielraum'),
 G('Anrechenbares Cash','Nach der konkreten Vertragsdefinition für eine Nettoverschuldungsquote zulässiger Kassenbetrag. Gesperrte, nicht erreichbare oder oberhalb eines Caps liegende Beträge können ausgeschlossen sein. Eine zulässige Obergrenze erzeugt kein tatsächlich zusätzlich vorhandenes Cash.','bonds-01','bond-features','definitions','Eligible Cash|Covenant-Cash'),
 G('Maintenance Covenant','Vertragsbedingung, die zu den definierten laufenden Prüfzeitpunkten einzuhalten ist, etwa an jedem Quartalsstichtag. Sie ist von einer nur bei einer bestimmten Handlung auslösenden Incurrence-Bedingung zu unterscheiden. Fristen, Rechtsfolgen und zulässige Anpassungen bleiben vertragsspezifisch.','bonds-01','bond-features','maintenance-incurrence','Maintenance Covenants'),
 G('Incurrence Covenant','Beschränkung, die bei einer benannten Handlung, etwa neuer Schuldaufnahme oder Ausschüttung, den definierten Test verlangt. Ein späterer Ertragsrückgang ohne die erfasste Handlung ist bei einer reinen solchen Klausel nicht automatisch derselbe Verstoß wie bei einer laufenden Maintenance-Pflicht.','bonds-01','bond-features','maintenance-incurrence','Incurrence Covenants'),
 G('Basket','Vertraglich definierter Betrags- oder Handlungsspielraum innerhalb einer Beschränkung. Umfang, frühere Nutzung, Messzeitpunkt und Kombinierbarkeit mit Quotenwegen bestimmen den tatsächlich verbleibenden Spielraum. Zwei Körbe oder Ausnahmen dürfen nicht ohne ausdrückliche Grundlage addiert werden.','bonds-01','bond-features','baskets','Debt Basket|Ausschüttungsbasket'),
 G('Add-back','Hinzurechnung zu einer definierten Ausgangskennzahl, etwa vertraglich zugelassene EBITDA-Anpassung. Zulässigkeit, Grenze und wirtschaftliche Begründung werden geprüft. Ein rechnerisch höherer Covenant-Nenner ist nicht automatisch zusätzlicher freier Cashflow oder eine vergleichbare bilanzielle Ergebnisgröße.','bonds-11','bond-features','baskets','Add-backs|EBITDA-Add-back|EBITDA-Add-backs'),
 G('Event of Default','Im Vertrag definierter Auslöser weitergehender Gläubigerrechte. Nicht jede zunächst nicht erfüllte Pflicht erfüllt ihn ohne weitere Mitteilung, Frist oder Bedingung. Ein Event of Default und eine vorgezogene Fälligstellung sind ebenfalls nicht automatisch in jeder Klausel derselbe Schritt.','bonds-01','bond-features','default','Events of Default'),
 G('Vorzeitige Fälligstellung','Nach den maßgeblichen Regeln vorgezogene Fälligkeit eines Anspruchs, etwa infolge eines definierten Ausfallereignisses. Manche Fälle verlangen eine Erklärung bestimmter Berechtigter, andere können ausdrücklich automatisch wirken. Der bloße schlechte Kennzahlenwert beweist diese Rechtsfolge nicht allein.','bonds-01','bond-features','default','Acceleration'),
 G('Cross-Default','Verknüpfungsklausel, die einen definierten Ausfall anderer erfasster Verpflichtungen als möglichen Auslöser behandelt. Schuldnerkreis, Betragsschwelle, Art des Ausfalls, Ausnahmen und Fristen gehören zur Prüfung. Sie ist von einer ausdrücklich erst an tatsächliche Fälligstellung anknüpfenden Cross-Acceleration zu unterscheiden.','bonds-01','bond-features','cross-default','Cross Default'),
 G('Cross-Acceleration','Verknüpfungsklausel, deren benannter Auslöser die tatsächliche vorgezogene Fälligkeit einer anderen erfassten Schuld ist. Eine bloß noch heilbare Berichtspflichtverletzung ohne Fälligstellung erfüllt diesen speziellen Auslöser nicht schon allein. Weitere Voraussetzungen und Ausnahmen bleiben zu prüfen.','bonds-01','bond-features','cross-default','Cross Acceleration'),
 G('Heilungsfrist','Für eine bestimmte Pflichtverletzung vorgesehener Zeitraum beziehungsweise Abhilferahmen. Beginn, Mitteilung, Umfang und Rechtsfolge unterscheiden sich nach Vertrag und Ereignis. Eine Frist für Berichtsverstöße darf nicht als universelle Frist für jede ausgebliebene Kupon- oder Tilgungszahlung verwendet werden.','bonds-01','bond-features','default','Cure Period|Grace Period|Nachfrist'),
 G('Waiver','Unter den maßgeblichen Berechtigungs- und Beschlussregeln erklärter Verzicht auf bestimmte Vertragsrechte oder die Behandlung eines bestimmten Verstoßes. Er ist nicht automatisch eine dauerhafte wirtschaftliche Heilung und hebt nicht ohne entsprechende Grundlage sämtliche übrigen Rechte oder Pflichten auf.','bonds-01','bond-features','consent','Covenant Waiver'),
 G('Pari Passu','Gleichrangige Stellung im konkret bezeichneten Anspruchskreis. Sie erzeugt nicht ohne Weiteres gleiche Gesamt-Recovery bei verschiedenen Sicherheiten, Schuldnern oder Vermögenspools. Ein besicherter Bankfehlbetrag kann in einem definierten freien Pool gleichrangig sein, obwohl die gesamte Bankforderung zusätzlich aus Sicherheit bedient wird.','bonds-01','bond-features','guarantees','Gleichrangigkeit'),
 G('Strukturelle Nachrangigkeit','Wirtschaftlich nachgelagerter Zugriff aufgrund verschiedener Rechtsträger, etwa wenn Holdinggläubiger nur den nach eigenen Tochterverbindlichkeiten verbleibenden Eigentümerrest erreichen. Eine Senior-Bezeichnung im Holdingvertrag beseitigt diesen Mechanismus nicht. Garantien oder andere unmittelbare Rechte können den Vergleich verändern.','bonds-01','bond-features','structural','Structural Subordination'),
 G('Vertragliche Nachrangigkeit','Durch die maßgeblichen Bedingungen nachgelagerte Stellung gegenüber benannten anderen Forderungen. Sie ist von Vorrang an bestimmten Sicherheiten und von nachgelagertem Zugriff zwischen verschiedenen Gesellschaften zu unterscheiden. Der konkrete Umfang entscheidet über die Verteilung.','bonds-01','bond-features','security','Contractual Subordination'),
 G('Besicherte Anleihe','Schuldanspruch mit im maßgeblichen Rahmen wirksamen Rechten an bestimmten Vermögenswerten. Umfang, Rang, Nettoverwertung und mögliche Fehlbetragsrechte bestimmen die Zahlung. Besicherung bedeutet weder Zugriff auf jedes Konzernvermögen noch garantierte vollständige Rückzahlung.','bonds-01','bond-features','security','Secured Bond'),
 G('Unbesicherte Anleihe','Schuldanspruch ohne die entsprechende spezifische Besicherung. Er kann je nach Bedingungen vorrangig oder nachrangig sein. Fehlende Sicherheit bedeutet nicht allein vertragliche Nachrangigkeit, kann aber gegenüber Gläubigern mit Zugriff auf bestimmte Vermögenswerte wirtschaftlich nachteilig sein.','bonds-01','bond-features','security','Unsecured Bond'),
 G('Senior Unsecured','Unbesicherter Anspruch mit der bezeichneten vorrangigen Stellung im relevanten Schuldner- und Anspruchskreis. Der Titel sagt allein nichts über gleiche Sicherheiten oder unmittelbare Tochterhaftung. Wirtschaftliche Recovery hängt weiterhin von Vermögenszugriff, Struktur und anderen Forderungen ab.','bonds-01','bond-features','security','Senior Unsecured Bond|Unbesicherte Senior-Forderung'),
 G('Sicherheitenfehlbetrag','Teil einer besicherten Forderung, der nach der Sicherheitenzahlung unbezahlt bleibt. Ob und mit welchem Rang er an anderen Mitteln teilnimmt, folgt den maßgeblichen Bedingungen. Im eigenen Auron-Modell nimmt dieser Fehlbetrag gleichrangig mit der Senior-Note am freien Pool teil.','bonds-01','bond-features','recovery','Deficiency Claim|Fehlbetragsanspruch|Bankfehlbetrag'),
 G('Sicherheitenrecht','Rechtlicher Zugriff auf bestimmte Vermögenswerte zur Absicherung einer benannten Forderung. Entstehung, Umfang, Rang und Durchsetzbarkeit sind zu prüfen. Ein bloßes Verbot zusätzlicher Sicherheiten ist nicht automatisch derselbe direkte Zugriff.','bonds-01','bond-features','security','Lien|Liens'),
 G('Garantiegeber','Rechtsträger mit einer im Umfang und unter den Bedingungen festgelegten zusätzlichen Zahlungspflicht. Zahlungsfähigkeit, Rang, Freigabe und Durchsetzbarkeit werden geprüft. Eine Garantie schafft nicht allein zusätzliche Gesamtmittel und erlaubt keine doppelte Einziehung derselben Forderung.','bonds-01','bond-features','guarantees','Guarantor'),
 G('Zahlungsschuldner','Rechtsträger, gegen den der definierte Zahlungsanspruch besteht. Ein Markenname, Konzernabschluss oder Eigentumsverhältnis ist nicht allein ein zusätzlicher Schuldbeitritt anderer Gesellschaften. Emittent und gegebenenfalls tatsächlich verpflichtete Garanten werden getrennt identifiziert.','bonds-01','bond-features','issuer','Obligor'),
 G('Restlaufzeit','Ab dem betrachteten Zeitpunkt verbleibende Zeit bis zum definierten Endtermin. Sie unterscheidet sich von ursprünglicher Laufzeit und von Duration als Risikomaß. Verbleibende Kupontermine werden mit Zahlungsfrequenz und tatsächlichem Zeitstrahl bestimmt.','bonds-01','bond-features','maturity','Remaining Maturity'),
 G('Nominalgewicht','Gewicht einer Position nach dem für die jeweilige Abstimmung maßgeblichen Forderungsnominal. Bei einer entsprechenden Klausel zählen nicht automatisch Kaufpreis, Marktwert oder Zahl der Inhaber. Berechtigung, ausgeschlossene Stücke und die genaue Schwelle gehören zur Rechnung.','bonds-01','bond-features','consent','Nominalstimmgewicht|Principal-Weighted Vote'),
 G('Bullet Bond','Anleihe mit der im Vertrag vorgesehenen einmaligen Rückzahlung des ausstehenden Nominals am Endtermin, statt laufender planmäßiger Teiltilgung. Kupons können davor mehrfach anfallen. Kündigung, Ausfall oder andere ausdrücklich vereinbarte Rechte können den tatsächlichen Pfad verändern.','bonds-01','bond-features','schedule','Bullet|Endfällige Anleihe'),
 G('Covenant-Zinsdeckung','Im Vertrag definierte Deckungsquote einer Ertragsgröße gegenüber einer dort abgegrenzten Zinsbasis. Das eigene Auron-Modell verwendet Pro-forma-EBITDA und annualisierte vertragliche Cashzinsen. Das ist nicht automatisch dieselbe Quote wie bilanzieller EBIT durch Zinsaufwand.','bonds-01','bond-features','funding','Vertragliche Zinsdeckung|Pro-forma Zinsdeckung',[{label:'Zinsdeckung',units:['bond-features']}]),
 G('Vertragliche Netto-Leverage','Verhältnis der im Vertrag definierten Nettoschuld zu seiner Ertragsgröße, im eigenen Auron-Fall EBITDA. Cash-Anrechnung, Caps, Ertragsanpassungen und Prüfzeitpunkt gehören zur Definition. Eine andere allgemeine Verschuldungsquote kann deshalb einen anderen Wert liefern.','bonds-01','bond-features','definitions','Netto-Leverage|Covenant Leverage'),
 G('Capital Asset Pricing Model','Gleichgewichtsmodell der geforderten erwarteten Rendite: risikofreier Satz plus Marktbeta mal erwartete Marktprämie. Es bepreist unter seinen Annahmen den gemeinsamen Risikobeitrag zum Marktportfolio. Ein einzelner tatsächlicher Jahresertrag und die Gesamtvolatilität sind keine gleichwertigen Ersatzgrößen.','portfolio-04','equity-factors','capm','CAPM'),
 G('Arbitrage Pricing Theory','Theoretische Beziehung zwischen erwarteter Rendite und mehreren systematischen Faktorexpositionen unter geeigneter Faktorstruktur, Diversifizierbarkeit spezifischer Risiken und fehlender Arbitrage. Sie schreibt nicht eindeutig Zahl und Identität der Faktoren vor. Gleiche geschätzte Betas einzelner Aktien beseitigen ihre Restunsicherheit nicht.','portfolio-05','equity-factors','apt','APT'),
 G('Security Market Line','Wertpapiermarktlinie des CAPM mit Beta auf der Risikoachse und geforderter erwarteter Rendite auf der Ertragsachse. Achsenabschnitt ist der passende risikofreie Satz, Steigung die erwartete Marktprämie. Sie gilt für Wertpapiere und Portfolios; die Kapitalmarktlinie verwendet dagegen Gesamtstandardabweichung effizienter Kombinationen.','portfolio-04','equity-factors','sml','SML|Wertpapiermarktlinie'),
 G('Faktormodell','Modell, das Renditen oder ihre Risiken über gemeinsame Treiber, Expositionen und einen Rest beschreibt. Makroökonomische Überraschungen und handelbare Faktorspreads besitzen verschiedene Konventionen. Ein gutes historisches Modell beweist weder einen kausalen Mechanismus noch garantierte künftige Prämien.','portfolio-05','equity-factors','factor-logic','Faktormodelle|Faktor'),
 G('Exposition','Empfindlichkeit einer Anlage oder eines Portfolios gegenüber einem definierten Treiber. Einheit und Skalierung des Treibers gehören zur Aussage. Markt-, Size- und Value-Exposition können verschieden sein; eine einzelne Null-Exposition macht das gesamte Portfolio nicht risikofrei.','portfolio-05','equity-factors','portfolio','Exposure|Expositionen'),
 G('Marktmodell','Statistisches Renditemodell mit Marktkomponente, Intercept und Rest. Eine Roh-Renditeregression und eine Überschussrenditeregression besitzen unterschiedliche Intercept-Konventionen. Historische Parameter und eine Marktprognose werden erst unter zusätzlichen Zukunftsannahmen zu einer Renditeerwartung; das Modell allein ist keine CAPM-Gleichgewichtsbedingung.','equity-06','equity-factors','market-model','Market Model'),
 G('Systematisches Risiko','Gemeinsames, im betrachteten Anlagemodell nicht durch reine Streuung firmeneigener Positionen beseitigtes Risiko. Im CAPM wird es über Marktbeta beschrieben; ein Mehrfaktormodell kann weitere gemeinsame Treiber unterscheiden. Nicht jeder gemeinsame Faktor ist deshalb automatisch mit einer bekannten positiven Prämie bepreist.','portfolio-04','equity-factors','co-risk','Systematic Risk'),
 G('Spezifisches Risiko','Auf einzelne Anlagen bezogene Restunsicherheit relativ zum gewählten Modell. Bei passenden Gewichten und ausreichend schwach abhängigen Resten kann sie durch Diversifikation sinken. Ein Einfaktorrest kann aber ausgelassene gemeinsame Faktoren enthalten und ist dann nicht vollständig durch mehr Titel beseitigbar.','portfolio-04','equity-factors','diversification','Idiosynkratisches Risiko|Idiosyncratic Risk|Unsystematisches Risiko|Nonsystematic Risk'),
 G('Marktrisikoprämie','Erwartete Marktrendite abzüglich passender risikofreier Rendite derselben Periode. Eine angegebene Prämie wird nicht nochmals um risikofrei bereinigt. Historischer Durchschnitt und vorwärts gerichtete Erwartung sind verschiedene Größen und können andere Ergebnisse liefern.','equity-06','equity-factors','premium','Equity Risk Premium|Market Risk Premium|ERP'),
 G('Faktorprämie','Angesetzte erwartete Vergütung pro Einheit einer definierten systematischen Faktorexposition beziehungsweise erwartete Rendite eines entsprechend konstruierten Faktorspreads. Skalierung und Modellkonvention entscheiden über die genaue Bedeutung. Sie ist von der später tatsächlich realisierten Faktorrendite zu unterscheiden.','portfolio-05','equity-factors','factor-conventions','Factor Premium|Factor Risk Premium'),
 G('Faktorüberraschung','Realisierter Faktorwert minus seine zuvor für denselben Horizont gebildete Erwartung. Die Erwartung dieser so definierten Überraschung ist unter dem Modell null. Erwartete Gesamtrendite plus Exposition mal Überraschungen ist von risikofreier Basis plus vollen Faktorrenditen zu unterscheiden.','portfolio-05','equity-factors','factor-conventions','Factor Surprise'),
 G('Roh-Rendite-Intercept','Achsenabschnitt einer Regression der unbereinigten Aktienrendite auf die unbereinigte Marktrendite. Er ist nicht automatisch identisch mit dem Alpha einer Überschussrenditeregression. Bei konstantem risikofreiem Satz lautet die Überleitung Alpha plus eins minus Beta mal risikofrei.','equity-06','equity-factors','excess','Raw-Return Intercept'),
 G('Marktproxy','Beobachtbares Portfolio oder Index, mit dem das theoretische Marktportfolio in einer empirischen Rechnung angenähert wird. Abdeckung, Region, Währung und Gewichtung beeinflussen das geschätzte Beta. Ein verfügbarer Aktienindex ist nicht automatisch der vollständige Markt aller riskanten Anlagen.','portfolio-04','equity-factors','estimation','Market Proxy'),
 G('Faktor-Neutralität','Im gewählten Modell fehlende Nettoexposition gegenüber den benannten gemeinsamen Faktoren. Sie muss für jeden relevanten Faktor geprüft werden. Nicht erfasste Faktoren, Residuen, Finanzierung, Leihe und Kosten können weiterhin Risiken erzeugen.','portfolio-05','equity-factors','portfolio','Factor Neutrality|faktor-neutral'),
 G('Marktneutralität','Fehlende Nettoexposition gegenüber dem definierten Marktfaktor. Gleiche Long- und Short-Beträge allein garantieren dies nicht; die Betas müssen passen. Marktneutralität beseitigt auch bei Beta null nicht automatisch andere systematische oder spezifische Risiken.','portfolio-05','equity-factors','portfolio','Market Neutrality|marktneutral'),
 G('Faktorportfolio','Nach offengelegten Regeln gebildeter handelbarer oder rechnerischer Portfoliokontrast, dessen Rendite einen gemeinsamen Treiber abbilden soll. Ein Long-Short-Spread unterscheidet sich von einem Unternehmensmerkmal und von der Exposition einer einzelnen Aktie gegenüber diesem Spread.','portfolio-05','equity-factors','factor-types','Factor Portfolio'),
 G('SMB','Small Minus Big: definierter Renditespread kleiner gegenüber großen Aktienportfolios. Sortierung, Gewichtung und Modellversion sind Teil der Definition. Im veröffentlichten Fünf-Faktor-Ansatz wird SMB aus mehreren Größen-Sortierungen zusammengefasst; ein positives Ergebnis ist nicht für jede Periode garantiert.','portfolio-05','equity-factors','fama-french','Small Minus Big'),
 G('HML','High Minus Low: definierter Renditespread von Aktienportfolios mit hohem gegenüber niedrigem Book-to-Market. Ein Unternehmensverhältnis, die Faktorrendite und ein geschätztes HML-Beta sind verschiedene Größen. Hohes Book-to-Market allein beweist keine Unterbewertung.','portfolio-05','equity-factors','fama-french','High Minus Low'),
 G('RMW','Robust Minus Weak: Faktorspread robuster gegenüber schwacher operativer Profitabilität nach der jeweiligen Portfoliodefinition. Er gehört zur erweiterten Fama-French-Modellfamilie. Historische Prämie, erwartete künftige Prämie und einzelne Firmenprofitabilität werden unterschieden.','portfolio-05','equity-factors','fama-french','Robust Minus Weak'),
 G('CMA','Conservative Minus Aggressive: Faktorspread konservativer gegenüber aggressiver Investition nach den jeweiligen Konstruktionsregeln. Er ist keine allgemeine Empfehlung, dass jede reale Firma weniger investieren sollte; Projektwert hängt weiterhin von Zahlungen und Kapitalkosten ab.','portfolio-05','equity-factors','fama-french','Conservative Minus Aggressive'),
 G('Mehrfaktormodell','Modell mit mehreren gemeinsamen Rendite- oder Risikotreibern. Es kann unterschiedliche Expositionen trotz gleichen Marktbetas darstellen. Erwartete Renditebeiträge, Faktorüberraschungen, Kovarianzen und Restunsicherheit benötigen jeweils eine konsistente Rechnung. Zusätzliche Faktoren können auch Überanpassung und instabile Schätzungen erzeugen.','portfolio-05','equity-factors','factor-logic','Multi-Factor Model|Multifaktormodell|Multifaktormodelle'),
 G('Faktorattribution','Zuordnung eines Rendite- oder Risikobeitrags zu den Expositionen und Faktorwerten des gewählten Modells. Der verbleibende Intercept beziehungsweise Rest hängt von Modell, Zeitraum und Konventionen ab. Eine neue Faktorspezifikation kann auch bisherige Koeffizienten verändern.','portfolio-05','equity-factors','model-alpha','Factor Attribution'),
 G('Regressionsfenster','Ausgewählter historischer Zeitraum zur Parameterschätzung. Ein längeres Fenster enthält mehr Beobachtungen, kann aber frühere Geschäfts- oder Finanzierungsbedingungen stärker gewichten. Fensterlänge, Datenfrequenz, Marktproxy und möglicher Strukturbruch werden gemeinsam beurteilt.','equity-06','equity-factors','estimation','Estimation Window'),
 G('Researchbericht','Nachvollziehbare Analyse eines Wertpapiers oder Unternehmens, die Quellen, Geschäftsverständnis, Prognose, passende Bewertung, Schlussfolgerung und wesentliche Risiken verbindet. Umfang folgt Zweck und Empfänger. Ein Modellname oder eine Einstufung ersetzt die wirtschaftliche Begründung nicht.','equity-07','research','blueprint','Equity Research Report|Aktienresearchbericht'),
 G('Sell Side','Researchfunktion typischerweise für externe Kunden eines Researchanbieters oder Intermediärs. Ein Bericht kann Unternehmensabdeckung, Prognosen, definierte Einstufung und Kursziel bieten. Vertriebs- und Vergütungsmodelle unterscheiden sich; die Rolle allein beweist weder mangelnde noch vorhandene Objektivität.','equity-07','research','sell-side','Sell-Side|Sell-Side-Research'),
 G('Buy Side','Researchfunktion zur Unterstützung der Kapitalanlage einer Organisation oder ihrer Kunden. Sie verbindet Einzelwertanalyse mit konkretem Mandat, vorhandenen Positionen, Alternativen und Risikobudget. Eine positive Wertschätzung muss deshalb nicht zu einem weiteren Kauf führen.','equity-07','research','buy-side','Buy-Side|Buy-Side-Research'),
 G('Investmentmemo','Interne schriftliche Begründung einer konkreten Anlage- oder Portfolioentscheidung. Es kann die These, Daten, Bewertung, Gegenargumente, Risiken, Umsetzung und Überwachung enthalten. Entscheidend ist die prüfbare Grundlage, nicht eine bestimmte Seitenzahl.','equity-07','research','buy-side','Investment Memorandum'),
 G('Investmentkomitee','Gremium, das Anlagevorschläge im Rahmen seiner zugewiesenen Aufgaben beurteilt oder entscheidet. Eine interne Analyse muss Wertpapierthese, Mandat, Risiken und Alternativen verständlich verbinden. Eine frühere Zustimmung ersetzt keine Aktualisierung bei neuer wesentlicher Information.','equity-07','research','buy-side','Investment Committee'),
 G('Erststudie','Umfassendere Einführung bei Aufnahme einer Unternehmens- oder Wertpapierabdeckung. Sie erschließt typischerweise Geschäft, Branche, Prognose, Bewertung und Risiken. Ein späteres Update kann enger gefasst sein, muss seinen Umfang und wesentliche Änderungen aber klar benennen.','equity-07','research','audience','Initiation Report|Initiating Coverage'),
 G('Anlagethese','Begründete wirtschaftliche Erklärung einer möglichen Anlagechance oder eines möglichen Nachteils relativ zum betrachteten Preis und Zweck. Sie verbindet abweichende Annahmen, Wertwirkung, Zeit und Widerlegung. Die Aussage ein Modellwert sei höher als der Preis ist allein noch keine vollständige These.','equity-07','research','thesis','Investment Thesis'),
 G('Variant Perception','Begründete abweichende Sicht auf wirtschaftliche Treiber oder Risiken gegenüber einem klar benannten Vergleich beziehungsweise Preisbild. Eine Preisrückrechnung identifiziert nicht automatisch die tatsächlichen Annahmen aller Marktteilnehmer. Die abweichende Sicht benötigt überprüfbare Evidenz.','equity-07','research','thesis','abweichende Marktsicht'),
 G('Kurszielhorizont','Ausdrücklich benannter zukünftiger Zeitpunkt beziehungsweise Zeitraum einer Preisannahme. Ein heutiger innerer Wert und ein nächstjähriges Kursziel können wegen Ausschüttung, Entwicklung und neuer Information verschieden sein. Renditevergleiche müssen auf denselben Horizont und Anspruch bezogen werden.','equity-07','research','horizon','Price Target Horizon'),
 G('Informationsstichtag','Zeitliche Grenze der für eine Analyse verfügbaren Information. Berichtsperiode, Veröffentlichungsdatum und Preiszeitpunkt sind gesondert zu prüfen. Später bekannt gewordene Angaben dürfen nicht unbemerkt eine frühere Entscheidung begründen.','equity-07','research','sources','Information Cutoff'),
 G('Annahmenbrücke','Dokumentierte Folge vollständiger Modellneuberechnungen zwischen zwei beschriebenen Inputkombinationen. Die Reihenfolge kann einzelne Beiträge verändern, während Start- und Endwert gleich bleiben. Isolierte Änderungen auf derselben alten Basis dürfen nicht ungeprüft als gemeinsame Gesamtwirkung addiert werden.','equity-07','research','joint','Assumption Bridge'),
 G('Wertbandbreite','Bereich bedingter Wertschätzungen unter ausdrücklich benannten Annahmen oder Szenarien. Grenzen und wirtschaftliche Plausibilität müssen erklärt werden. Eine solche Spanne ist ohne zusätzliches statistisches Verfahren kein Konfidenzintervall und keine kalibrierte Wahrscheinlichkeitsaussage.','equity-07','research','sensitivity','Valuation Range'),
 G('Finanzielle Sensitivität','Empfindlichkeit einer Finanzgröße wie Wert, Ergebnis oder modellierte Rendite gegenüber einem benannten Treiber. Lokale Ableitungen und kontrollierte Neuberechnungen halten andere Größen fest; bei größeren Schocks kann Nichtlinearität wichtig werden. Sie ist von der Trefferquote eines Klassifikators und von Wahrscheinlichkeitsaussagen zu unterscheiden.','equity-07','research','sensitivity','Bewertungssensitivität|Valuation Sensitivity|Modellsensitivität',[{label:'Sensitivität',units:['research','industry','company','valuation-model','valuation-overview','multiples','dcf-equity','forecasting','working-capital','capital-allocation','capital-structure','business-models','equity-returns','standard-v','tvm','ratios','simulation','equity-factors'],legacyFinance:true,exceptLessons:['quant-06','quant-14']}]),
 G('Szenarioanalyse','Vergleich ausdrücklich zusammengehöriger Kombinationen wirtschaftlicher Annahmen. Preis, Menge, Marge, Kapitalbedarf und Risiko können gemeinsam verändert werden. Ein Szenario ist von einer isolierten Sensitivität und von einer bereits kalibrierten Wahrscheinlichkeitsverteilung zu unterscheiden.','equity-07','research','scenarios','Scenario Analysis'),
 G('Szenariogewicht','Expliziter Anteil eines Szenarios in einer bestimmten Modellzusammenfassung. Gewichte können hypothetisch, subjektiv oder aus einem Verfahren abgeleitet sein; ihre Herkunft muss erkennbar sein. Summe eins allein beweist keine korrekten Wahrscheinlichkeiten oder passende Risikodiskontierung.','equity-07','research','scenarios','Scenario Weight'),
 G('Anlageempfehlung','Begründetes Urteil mit offengelegter Skala, Bezugsgröße, Zeithorizont und wesentlichen Risiken. Buy, Hold und Sell bedeuten nicht bei jedem Anbieter dasselbe. Eine allgemeine Wertpapiereinschätzung ist nicht automatisch die passende Positionsentscheidung für jedes Portfolio.','equity-07','research','recommendation','Investment Recommendation'),
 G('Bedingter Modellwert','Wertschätzung, die aus einer bestimmten wirtschaftlichen Konstruktion und ausdrücklich benannten Inputs folgt. Mathematische Richtigkeit beweist nicht die Inputs oder künftige Marktpreise. Die Aussage benötigt Anspruch, Stichtag, Methode und Grenzen.','equity-07','research','case','Conditional Model Value'),
 G('Wettbewerbsstrategie','Begründete Wahl, welche Kunden mit welchem besonderen Nutzen oder Kostenvorteil bedient werden und welche zusammenpassenden Aktivitäten dafür erforderlich sind. Eine angekündigte Strategie ist noch keine erreichte Position; Kosten, Kapital, Konkurrenz und Umsetzung müssen ihre Tragfähigkeit bestätigen.','equity-05','company','strategy','Competitive Strategy'),
 G('Wettbewerbsposition','Tatsächliche relative Stellung eines Unternehmens gegenüber passenden Kundenalternativen, etwa nach Leistung, Kosten, Ressourcen und Zugang. Sie wird aus Belegen beurteilt und ist von der geplanten Strategie sowie allgemeiner Branchenattraktivität zu unterscheiden.','equity-05','company','position','Competitive Position'),
 G('Kostenführerschaft','Strategische Fähigkeit, eine vergleichbar abgegrenzte relevante Leistung mit geringeren vollständigen Kosten als passende Wettbewerber bereitzustellen. Niedriger Verkaufspreis allein beweist dies nicht; Qualität, Ressourceneinsatz und Kapitalbedarf gehören zum Vergleich.','equity-05','company','strategy','Cost Leadership'),
 G('Differenzierung','Für die Zielkundschaft bedeutsame Unterscheidung einer Leistung, etwa durch Zuverlässigkeit, Service oder Funktion. Die zusätzliche Zahlungsbereitschaft muss die zugehörigen Kosten und den Kapitalbedarf rechtfertigen. Eine Preisprämie allein beweist keine höhere Wirtschaftlichkeit.','equity-05','company','strategy','Differentiation'),
 G('Fokusstrategie','Ausrichtung auf eine ausdrücklich engere Kundengruppe, Region oder Leistungsfrage. Sie kann kosten- oder differenzierungsorientiert sein. Eine kleine Zielgruppe garantiert keinen Schutz und kann zusätzliche Konzentrations- und Ausführungsrisiken erzeugen.','equity-05','company','strategy','Focus Strategy'),
 G('Strategic Fit','Wirtschaftliche Passung der Aktivitäten und Ressourcen einer Strategie. Leistung, Beschaffung, Fertigung, Vertrieb und Service sollen dieselbe Zielposition tragen. Mehrere attraktive Einzelversprechen ergeben ohne tragfähige gemeinsame Kosten- und Kapitalstruktur noch keine überzeugende Gesamtstrategie.','equity-05','company','strategy','strategische Passung'),
 G('Economic Moat','Vermuteter Schutz eines wirtschaftlichen Wettbewerbsvorteils gegen Erosion durch Konkurrenz und Kundenalternativen. Marke, Zugang, Netzwerke oder Wechselaufwand können Ursachen sein, benötigen aber Belege zu Wirkung und Dauer. Hohe historische Buchrendite allein beweist keinen dauerhaften Schutz.','equity-05','company','advantage','ökonomischer Burggraben'),
 G('Preissetzungsmacht','Fähigkeit, Preis- und andere Erlösbedingungen relativ zu Kosten und Kundenalternativen wirtschaftlich durchzusetzen. Realisierter Preis, Menge, Bindung und Ressourcenkosten werden gemeinsam untersucht. Eine höhere Preisliste oder ein durch Produktmix gestiegener Durchschnittspreis reicht als Beweis nicht.','equity-05','company','pricing','Pricing Power'),
 G('Umsatztreiber','Wirtschaftliche Größen, aus denen vergleichbare Erlöse erklärt oder prognostiziert werden, etwa verkaufte Menge, realisierter Preis, Produkt- und Kundenmix, Vertragsbestand, Währung und Firmenumfang. Treiber benötigen passende Definitionen und dürfen nicht doppelt berücksichtigt werden.','equity-05','company','revenue','Revenue Driver'),
 G('Realisierter Nettopreis','Tatsächlich erzielter Erlös je passend definierter verkaufter Einheit nach relevanten Rabatten, Retouren und Erlösbedingungen. Er kann vom Listenpreis abweichen. Zeitraum, Produktqualität und Leistungsumfang müssen im Vergleich übereinstimmen.','equity-05','company','revenue','realisierter Preis|Realized Net Price'),
 G('Umsatzbrücke','Dokumentierte Zerlegung einer Umsatzänderung in passende Preis-, Mengen-, Mix-, Währungs- und Umfangsbeiträge. Bei multiplizierten Effekten beeinflusst die Reihenfolge die Teilbeiträge. Die gesamte Änderung muss ohne ausgelassenen oder doppelten Kreuzterm abgestimmt werden.','equity-05','company','bridge','Revenue Bridge'),
 G('Bogenelastizität','Verhältnis einer endlichen relativen Mengenänderung zur relativen Preisänderung unter einer benannten Basis, hier den Mittelpunkten beider Beobachtungen. Sie beschreibt nicht automatisch eine vollständige Nachfragekurve. Für kausale Preiswirkung müssen andere Nachfrageveränderungen getrennt werden.','equity-05','company','elasticity','Arc Elasticity'),
 G('Bruttomarge','Umsatz abzüglich der passend abgegrenzten Umsatzkosten relativ zum Umsatz. Sie liegt vor weiteren außerhalb der Umsatzkosten erfassten Aufwendungen. Unterschiedliche Kostenklassifikation, Vertrieb, Entwicklung, Abschreibung und Kapitalbedarf begrenzen direkte Firmenvergleiche.','equity-05','company','margins','Gross Margin'),
 G('Normalisierter EBIT','Begründete analytische Schätzung eines vergleichbaren operativen Gewinns nach erklärter Behandlung von Sondereffekten, Zyklus und Umfang. Berichteter Gewinn, Anpassungen und Folgeeffekte werden übergeleitet. Die Bezeichnung adjusted beweist weder Einmaligkeit noch sichere Fortsetzbarkeit.','equity-05','company','normalization','Normalized EBIT'),
 G('Kapazitätssprung','Zusätzlicher Ressourcenbedarf, sobald eine Menge den mit vorhandenen Mitteln bedienbaren Bereich überschreitet. Er kann Personal, Miete, Investition oder andere Kosten betreffen. Ein bisher als fix behandelter Block bleibt deshalb nicht für beliebig großes Wachstum konstant.','equity-05','company','costs','Capacity Step'),
 G('Degree of Operating Leverage','Relative Empfindlichkeit des operativen Gewinns gegenüber einer reinen Mengen- beziehungsweise bei festem Preis entsprechenden Umsatzänderung. Im linearen Modell ist DOL Deckungsbeitrag geteilt durch Ausgangs-EBIT. Preis, Stückkosten und Kapazitätskosten bleiben fest; bei EBIT null ist der Quotient nicht endlich definiert.','corporate-07','company','operating-leverage','DOL|operativer Hebel|Operating Leverage'),
 G('Degree of Financial Leverage','Relative Empfindlichkeit von Nettogewinn beziehungsweise bei fester Aktienzahl EPS gegenüber EBIT. Bei festem Zins, gleicher unmittelbar nutzbarer Steuer und ohne andere Ansprüche entspricht DFL EBIT relativ zu EBIT abzüglich Zins. Nullgewinn vor Steuer, wechselnde Finanzierung oder Vorzugsansprüche verlangen eine andere genaue Rechnung.','corporate-07','company','financial-leverage','DFL|finanzieller Hebel|Financial Leverage'),
 G('Degree of Total Leverage','Kombinierter relativer Gewinnhebel aus operativer Kostenstruktur und Finanzierung an derselben Ausgangsstelle. DTL entspricht DOL mal DFL nur unter den gemeinsam passenden Mengen-, Preis-, Kosten-, Zins-, Steuer- und Aktienannahmen. Es ist kein allgemeiner Multiplikator für jede Umsatzveränderung und von der gleich abgekürzten Deferred Tax Liability zu unterscheiden.','corporate-07','company','financial-leverage','Gesamthebel',[{label:'DTL',units:['company']}]),
 G('Operativer Sicherheitsabstand','Relativer Abstand der betrachteten Menge oder bei konstantem Preis des Umsatzes zur operativen Gewinngrenze eines benannten Kostenmodells. Er ist von der Sicherheitsmarge zwischen geschätztem Aktienwert und Preis zu unterscheiden. Die Gleichung mit dem Kehrwert von DOL benötigt dieselben linearen Modellannahmen.','corporate-07','company','breakeven','MOS|Sicherheitsabstand|Operative Margin of Safety',[{label:'Margin of Safety',units:['company']}]),
 G('Erhaltungsinvestition','Zahlungsbedarf zum Erhalten der für die analysierte Leistung erforderlichen wirtschaftlichen Kapazität und Qualität. Er entspricht nicht automatisch historischer Abschreibung. Anlagenalter, Ersatzpreise, Wartung und neue Technik müssen berücksichtigt werden.','equity-05','company','investment','Maintenance Capex'),
 G('Wachstumsinvestition','Zusätzlicher Ressourceneinsatz zur Erweiterung oder Veränderung künftiger Leistungen. Sie kann Anlagen und operative Bestände sowie wirtschaftliche Aufbauausgaben betreffen. Positives Umsatzwachstum beweist ohne zusätzliche Zahlungen, Kapitalanforderung und Risiko keine Wertschaffung.','equity-05','company','investment','Growth Capex'),
 G('Liquiditätsreserve','Tatsächlich zugängliche Mittel beziehungsweise belastbar verfügbare Zahlungsfähigkeit für geplante Ausgaben und Unsicherheit. Ein gewünschter Jahresend-Cashbestand ist nur eine Modellbedingung und belegt weder unterjährige Spitzenabdeckung noch eine Kreditzusage.','equity-05','company','growth-funding','Liquidity Buffer'),
 G('Finanzierungslücke','Differenz zwischen zu einem Zeitpunkt benötigten Zahlungen beziehungsweise Zielmitteln und den bis dahin verfügbaren Finanzmitteln. Sie wird aus einer zeitlich passenden Mittelrechnung abgeleitet. Positiver Gewinn oder gute Zinsdeckung schließen eine solche Lücke nicht aus.','equity-05','company','growth-funding','Funding Gap'),
 G('Kundenkonzentration','Abhängigkeit von einer kleinen Zahl wirtschaftlich wichtiger Kunden oder gemeinsam beeinflusster Kundengruppen. Umsatzbindung und Wachstum können diese Abhängigkeit verdecken. Ausfall, Verhandlungsmacht, Ausbaukosten und Verlust eines großen Kunden werden gemeinsam beurteilt.','equity-05','company','contracts','Customer Concentration'),
 G('Net Debt','Verzinsliche Schulden abzüglich ausdrücklich passend verfügbaren Cashs auf derselben Anspruchs- und Stichtagsbasis. Gebundene, eingeschränkte oder für den Betrieb notwendige Mittel sind nicht ungeprüft für jede Schuldenzahlung verfügbar. Nettoschulden ersetzen weder Fälligkeitsplan noch Untersuchung weiterer Verpflichtungen.','start-06','company','financing','Nettoschulden|Nettoverbindlichkeiten'),
 G('Eigenkapitalbuchrendite','Passender Periodennettogewinn relativ zum ausdrücklich gewählten Buch-Eigenkapitalbestand. Hier wird Anfangskapital benutzt. Finanzierung und ein kleiner Buchnenner können die Quote erhöhen, ohne operative Überlegenheit zu beweisen; sie ist keine garantierte Aktienmarktrendite.','equity-05','company','financial-leverage','Buch-ROE|Book ROE'),
 G('Branchenanalyse','Strukturierte Untersuchung eines abgegrenzten wirtschaftlichen Umfelds: Teilnehmer, Größe, Wachstum, Profitabilität, Konkurrenz und äußere Einflüsse. Sie begründet Prognosetreiber und Risiken, beweist aber allein weder Firmenqualität noch Unterbewertung einer Aktie.','equity-04','industry','workflow','Industry Analysis'),
 G('Marktabgrenzung','Explizite Festlegung der betrachteten Produkte, Kunden, Region, Zeit und Wertschöpfungsstufe. Für einen Marktanteil müssen Firmenumsatz und Gesamtmarkt dieselbe Frage erfassen. Analytische Abgrenzung ist nicht automatisch eine abschließende rechtliche Marktdefinition.','equity-04','industry','boundaries','Market Definition'),
 G('Branchenklassifikation','Standardisierte Zuordnung wirtschaftlicher Tätigkeiten oder Unternehmen nach einer benannten Systematik. Sie unterstützt Datenorganisation und Vergleich, ersetzt aber keine Untersuchung von Kundenaustauschbarkeit, Kapitalbedarf und Wettbewerbsposition.','equity-04','industry','taxonomies','Industry Classification'),
 G('Global Industry Classification Standard','Von MSCI und S&P Dow Jones Indices entwickeltes Unternehmenseinordnungssystem mit Sector, Industry Group, Industry und Sub-Industry. Eine Firma erhält je Stufe eine Zuordnung nach ihrer Hauptaktivität; Umsatz, Ergebnis und Marktwahrnehmung werden methodisch berücksichtigt.','equity-04','industry','taxonomies','GICS'),
 G('Industry Classification Benchmark','FTSE-Russell-Unternehmensklassifikation mit Industry, Supersector, Sector und Subsector. Die Tätigkeit, ihre Umsätze und weitere öffentliche Informationen unterstützen die Zuordnung. Die Hierarchiewörter bezeichnen nicht dieselben Stufen wie bei GICS.','equity-04','industry','taxonomies','ICB'),
 G('North American Industry Classification System','Produktionsorientiertes statistisches System, das Betriebsstätten nach ähnlichen Produktionsprozessen gruppiert. Die Einheit ist nicht automatisch der gesamte Konzern; unterschiedliche Betriebsstätten einer Gruppe können verschiedene Tätigkeiten besitzen.','equity-04','industry','taxonomies','NAICS'),
 G('Erhebungseinheit','Wirtschaftliche Einheit, für die eine Datenquelle Informationen erfasst, etwa Betrieb, Betriebsstätte, Segment oder konsolidierte Unternehmensgruppe. Unterschiedliche Einheiten beeinflussen Umfang, Vergleichbarkeit und mögliche Doppelzählung einer Branchenkennzahl.','equity-04','industry','data','Statistical Unit'),
 G('Marktgröße','Umfang eines ausdrücklich definierten Markts in einem Zeitraum, etwa Umsatz oder verkaufte Menge. Installierter Bestand und jährlicher Absatz sind verschiedene Größen. Die Ermittlung verlangt passende Teilnehmer, Wertschöpfungsstufe und überschneidungsfreie Erfassung.','equity-04','industry','size','Market Size'),
 G('Marktanteil','Passender Firmenabsatz relativ zum gesamten Absatz desselben Markts und Zeitraums. Umsatz- und Mengenanteile können sich durch Preise und Produktmix unterscheiden. Ein höherer absoluter Umsatz bedeutet keinen Anteilsgewinn, wenn der Markt noch schneller wächst.','equity-04','industry','shares','Market Share'),
 G('Preisprämie','Höherer realisierter Preis gegenüber einer ausdrücklich passenden Vergleichsleistung oder einem genannten Durchschnittspreis. Sie kann etwa Qualität, Service oder Markenwahrnehmung widerspiegeln. Höherer Preis beweist ohne Kosten, Kapitalbedarf und Nachfrageprüfung weder höheren Gewinn noch dauerhafte Preissetzungsmacht.','equity-04','industry','shares','Price Premium|Preisaufschlag'),
 G('Wertmäßiger Marktanteil','Firmenumsatz geteilt durch Gesamtmarktumsatz auf derselben Abgrenzung. Ein höherer Preis kann den Umsatzanteil erhöhen, ohne dass der Mengenanteil steigt. Der Wertanteil ist keine Kapitalrendite oder Unternehmensbewertung.','equity-04','industry','shares','Revenue Share'),
 G('Mengenmäßiger Marktanteil','Vergleichbare verkaufte Einheiten einer Firma relativ zu allen Einheiten desselben Markts. Einheit, Qualität und Angebotsmix müssen sinnvoll vergleichbar sein. Bei anderen realisierten Preisen kann der Umsatzanteil deutlich abweichen.','equity-04','industry','shares','Volume Share'),
 G('Total Addressable Market','Ergänzender Planungsbegriff für ein begründetes Gesamtmarktpotenzial unter ausdrücklich benannter Bedarfs-, Angebots- und Preisdefinition. Er misst nicht automatisch den heutigen verkauften Markt oder künftig garantierte Firmenumsätze.','equity-04','industry','potential','TAM'),
 G('Serviceable Available Market','Teil des definierten Gesamtpotenzials, der unter den angenommenen geografischen, technischen und sonstigen Zugangsvoraussetzungen zum Angebot passt. Bedienbarkeit bedeutet noch keine tatsächlich gewonnene Kundschaft.','equity-04','industry','potential','SAM'),
 G('Serviceable Obtainable Market','Plausibel innerhalb eines genannten Zeithorizonts erreichbarer Teil des bedienbaren Potenzials. Konkurrenz, Abschlusswahrscheinlichkeit, verfügbare Ressourcen und Ausführung begrenzen ihn; eine Kapazitätsobergrenze ist allein keine Absatzgarantie.','equity-04','industry','potential','SOM'),
 G('Compound Annual Growth Rate','Geometrisch geglättete jährliche Wachstumsrate zwischen positivem Anfangs- und Endwert über eine angegebene Periodenzahl. Sie reproduziert den Endpunkt, beschreibt aber nicht automatisch jedes Zwischenjahr oder die Unsicherheit des Verlaufs.','equity-04','industry','growth','CAGR'),
 G('Organisches Wachstum','Wachstum einer vergleichbar abgegrenzten Geschäftsbasis nach ausdrücklich benannter Behandlung von Übernahmen, Veräußerungen und anderen Umfangsänderungen. Es ist nicht automatisch identisch mit preisbereinigtem oder währungsbereinigtem Wachstum.','equity-04','industry','growth','Organic Growth'),
 G('Constant Currency','Darstellung einer Veränderung auf einer festgehaltenen Wechselkursbasis, um Übersetzungseffekte abzugrenzen. Sie entfernt nicht automatisch Preis-, Mengen-, Mix- oder Übernahmeeffekte. Die konkret verwendete Vergleichsmethode wird benannt.','equity-04','industry','growth','währungsbereinigtes Wachstum'),
 G('Installierte Anlagenbasis','Bestand relevanter bereits vorhandener Anlagen zu einem bestimmten Zeitpunkt. Er kann laufenden Service und Ersatzbedarf treiben, ist aber kein jährlicher Neuverkaufsstrom. Stilllegung, Nutzung und externe Vergabe bestimmen die tatsächlich bedienbare Nachfrage.','equity-04','industry','cycle','Installed Base|installierte Basis'),
 G('Branchenlebenszyklus','Orientierungsmuster aus Entstehung, Wachstum, Bereinigung, Reife und Rückgang einer Branche. Es ist kein zwangsläufiger Ablauf; Teilmärkte, neue Technik und Regionen können andere Phasen besitzen. Ein Einzeljahr oder Firmenalter beweist die Phase nicht.','equity-04','industry','lifecycle','Industry Life Cycle'),
 G('Logistische Diffusion','Mathematisches Lehrmodell einer Durchdringung mit positiver Geschwindigkeit und festgehaltener Sättigungsgrenze. Absolute und relative Zunahme verlaufen unterschiedlich. Das Modell allein begründet weder die tatsächliche Marktgrenze noch Wettbewerb oder Profitabilität.','equity-04','industry','lifecycle','Logistic Diffusion'),
 G('Aggregierte Branchenmarge','Passend summierter Branchengewinn relativ zu entsprechend summierten Umsätzen. Bei vergleichbaren EBIT-Größen entspricht sie dem umsatzgewichteten Firmenmargenmittel. Ein ungewichteter Mittelwert oder selektiver Ausschluss von Verlustfirmen beantwortet eine andere Frage.','equity-04','industry','profitability','Industry Profit Margin'),
 G('Aggregierter Branchen-ROIC','Gesamter vergleichbarer operativer Nachsteuerertrag relativ zum passenden gesamten operativen Kapital einer abgegrenzten Gruppe. Die Bestandskonvention muss übereinstimmen. Umsatzgewichte sind nicht automatisch die passenden Gewichte der einzelnen Kapitalrenditen.','equity-04','industry','capital','Industry ROIC'),
 G('Five Forces','Porters Rahmen zur Untersuchung von Rivalität vorhandener Anbieter, neuem Eintritt, Käufermacht, Lieferantenmacht und Substituten. Er erklärt strukturelle Konkurrenzmechanismen; eine ungewichtete qualitative Durchschnittsnote liefert nicht automatisch eine Gewinnprognose.','equity-04','industry','five-forces','Porter’s Five Forces|Porters Five Forces'),
 G('Rivalität','Wettbewerbsdruck zwischen bestehenden Anbietern eines abgegrenzten Markts. Er kann Preis, Leistung, Werbung, Service und Kapazität betreffen. Fixe Ressourcen, langsames Nachfragewachstum und schwieriger Ausstieg können Preisdruck verstärken, ohne jede tatsächliche Reaktion festzulegen.','equity-04','industry','rivalry','Competitive Rivalry'),
 G('Eintrittsbarrieren','Bedingungen, die Aufbau eines neuen glaubwürdigen Wettbewerbers erschweren, etwa Zugang, Ressourcen, Qualifikation oder relevante Größen- und Netzvorteile. Hoher absoluter Investitionsbedarf allein beweist keinen dauerhaften Schutz, wenn attraktive Renditen und Finanzierung erreichbar sind.','equity-04','industry','entry','Barriers to Entry|Eintrittsbarriere'),
 G('Käufermacht','Fähigkeit eines Abnehmers, aufgrund glaubwürdiger Alternativen und seiner wirtschaftlichen Bedeutung Preis, Qualität, Service oder Zahlungsbedingungen durchzusetzen. Größe allein reicht ohne Wechselmöglichkeiten nicht. Längere Zahlung kann Kapital binden, obwohl die Marge gleich bleibt.','equity-04','industry','buyers','Buyer Power|Abnehmermacht'),
 G('Lieferantenmacht','Fähigkeit eines Ressourcenanbieters, Preise und andere Bedingungen durchzusetzen, wenn passende Alternativen oder Wechselmöglichkeiten begrenzt sind. Die Wirkung hängt zusätzlich von eigener Kostenweitergabe, Mengenreaktion, Vorräten und Ressourcenbedarf des Kundenunternehmens ab.','equity-04','industry','suppliers','Supplier Power'),
 G('Substitut','Andersartige Lösung desselben grundlegenden Kundenbedürfnisses, etwa Eigenwartung statt externem Service; Substitution bezeichnet ihre Verwendung anstelle der bisherigen Lösung. Leistungsfähigkeit, vollständige Kosten, Wechselaufwand und Risiko beeinflussen die Bedrohung. Ein Substitut muss kein bestehender Anbieter des enger definierten Markts sein.','equity-04','industry','substitutes','Substitute|Substitution'),
 G('PESTLE','Rahmen zur Ordnung politischer, wirtschaftlicher, sozialer, technologischer, rechtlicher und ökologischer äußerer Einflüsse. Finanzielle Folgen benötigen begründete Wirkungskanäle und Zeitpunkte. Dieselbe Zahlung wird trotz mehrerer zutreffender Kategorien nicht doppelt erfasst.','equity-04','industry','pestle','PESTLE Framework'),
 G('Überwachstum','Hier Firmenwachstum oberhalb des Wachstums seines unverändert abgegrenzten Markts. Es verlangt steigenden Marktanteil und kann innerhalb desselben vollständigen Markts nicht unbegrenzt fortgesetzt werden. Neue Märkte müssen ausdrücklich mit eigenen Ressourcen und Konkurrenz modelliert werden.','equity-04','industry','share-limits','Growth Outperformance'),
 G('Abschlussprognosemodell','Verknüpfte Prognose von Ergebnisrechnung, Bilanz und Cashflowrechnung aus dokumentierten Geschäftstreibern. Umsatz, Kosten, Investitionen, operative Bestände, Steuern und Finanzierung werden gemeinsam übergeleitet. Ein geschlossener Abschluss prüft die Rechnungslogik, beweist aber nicht die wirtschaftliche Erreichbarkeit seiner Annahmen.','statements-15','valuation-model','architecture','Financial Statement Forecast Model|Abschlussmodell'),
 G('Bewertungsarchitektur','Begründete Verbindung von Prognosetreibern, freien Zahlungen, Endphase, Diskontierung und Anspruchsbrücke. Sie legt fest, welcher Betrieb, welches Risiko und welche Eigentümerrechte bewertet werden. Die Wahl richtet sich nach dem Unternehmen und der Bewertungsfrage.','equity-09','valuation-model','architecture'),
 G('Marginale Investitionsrendite','Zusätzlicher künftiger Nachsteuerertrag relativ zum dafür neu gebundenen operativen Kapital. Sie ist von der Rendite des gesamten vorhandenen Kapitals zu unterscheiden. Bei stabilem Ertragswachstum bestimmt sie den benötigten zusätzlichen Kapitalbetrag, wenn Zeitpunkte und Ertragsbasis passend definiert sind.','equity-09','valuation-model','terminal-capital','Rendite neuer Investitionen|Marginal Return on New Investment'),
 G('Operative Nettoinvestition','Zunahme des wirtschaftlich gebundenen operativen Kapitals. Im einfachen Modell ohne andere Bestandsbewegungen entspricht sie Capex abzüglich Abschreibung zuzüglich Anstieg des nicht liquiden operativen Working Capital. Sie ist weder allein Brutto-Capex noch jede beliebige Geldanlage.','equity-09','valuation-model','assets','Net Operating Reinvestment'),
 G('Kapitalintensität','Menge benötigten operativen Kapitals relativ zu Umsatz oder Produktion auf ausdrücklich definierter Bestandsbasis. Bei ähnlicher Gewinnmarge kann höherer Kapitalbedarf Wachstum stärker belasten und die Kapitalrendite senken. Ein Anlagenbuchwertverhältnis erfasst physische Kapazität und immaterielle Ressourcen nur unvollständig.','equity-09','valuation-model','investment-growth','Capital Intensity'),
 G('Anlagenquote','In einem bestimmten Modell verwendetes Verhältnis des Nettoanlagenbestands zum Umsatz. Eine unveränderte Quote kann den gewünschten Anlagenendbestand planen, ist aber kein Beweis verfügbarer Kapazität. Anlagenalter, Abschreibung, Bauzeit und Ersatzpreise benötigen zusätzliche Prüfung.','equity-09','valuation-model','assets','Net-PPE-to-Sales Ratio'),
 G('Anlagenjahrgang','Gruppe von Anlagen mit vergleichbarem Zugangs- oder Inbetriebnahmezeitpunkt. Jahrgangsplanung kann Abschreibung, Lebensdauer und Ersatzbedarf genauer verbinden als eine pauschale Buchwertquote. Künftige Investitionszahlung und Beginn der Nutzung sind nicht immer derselbe Termin.','statements-15','valuation-model','assets','Asset Vintage'),
 G('Kapazitätsprüfung','Abgleich geplanter Absatz- oder Produktionsmengen mit wirtschaftlich und technisch verfügbaren Ressourcen. Eine geschlossene Prognosebilanz oder konstante Anlagenquote beweist diese Kapazität nicht. Auslastung, Bauzeit, Engpässe und Wartung können Investitionen und Umsatz begrenzen.','statements-15','valuation-model','assets','Capacity Check'),
 G('Stabile EBIT-Marge','Für die langfristige Phase begründetes operatives Ergebnis nach Abschreibung relativ zum Umsatz. Sie kann von der letzten Detailmarge abweichen und erfordert eine gesonderte Ertrags- und Investitionskonstruktion. Eine höhere stabile Marge erhöht den Modellwert nur unter dazu passenden wirtschaftlichen Annahmen.','equity-09','valuation-model','terminal','Mature EBIT Margin'),
 G('Endphasenübergang','Überleitung von expliziten Prognosejahren in eine langfristige Ertrags-, Wachstums- und Kapitalstruktur. Ändern sich Margen oder Kapitalrenditen, wird die erste stabile Zahlung neu berechnet. Der Übergang kann abrupt vereinfachen oder schrittweise Wettbewerbsanpassung darstellen.','equity-09','valuation-model','terminal','Terminal Transition'),
 G('Eigentümerbeitrag','Zusätzlicher von Eigentümern eingezahlter Kapitalbetrag. Er ist Finanzierung und kein operativer Umsatz oder Gewinn. Ob neue Aktien entstehen, wie bisherige Ansprüche verwässern und ob eine Zahlung tatsächlich verfügbar ist, hängt von den Finanzierungsbedingungen ab.','equity-09','valuation-model','case-opening','Owner Contribution'),
 G('Bedingter Fortführungswert','Wertschätzung eines weiter betriebenen Unternehmens unter ausdrücklich vorausgesetzten wirtschaftlichen und finanziellen Bedingungen. Ein positiver Barwert beweist keine tatsächlich verfügbare Finanzierung für zwischenzeitliche Defizite. Erforderliche Beiträge, Kredit und mögliche Verwässerung müssen genannt werden.','equity-09','valuation-model','limitations','Conditional Going-Concern Value'),
 G('Buchkapital-Roll-forward','Überleitung vom Anfangs- zum Endbuchkapital mit Gewinn, Ausschüttungen und sonstigen Eigentümer- oder Ergebnisbewegungen. Im einfachen Clean-Surplus-Fall genügt Anfangsbuchkapital plus Gewinn minus Dividende; zusätzliche Beiträge, Rückkäufe und OCI verlangen passende Erweiterung.','equity-09','valuation-model','balance-check','Equity Roll-forward'),
 G('Mengen-Preiseffekt','Gemeinsame Wirkung einer Absatzmengen- und Preisänderung auf den Umsatz. Die Wachstumsfaktoren werden multipliziert, sodass ein Kreuzterm entsteht. Bei mehreren Produkten wirkt zusätzlich die Absatzmischung; ein Durchschnittspreis ist deshalb nicht immer eine reine Preiserhöhung.','equity-05','valuation-model','revenue','Volume-Price Effect'),
 G('Reverse DCF','Diagnose der Annahmen, die unter fixierten anderen Modellgrößen einen beobachteten Preis tragen würden. Sie kann etwa eine erforderliche stabile Marge berechnen, identifiziert jedoch keine eindeutige gesamte Markterwartung. Ihre Bedingungen und wirtschaftliche Plausibilität bleiben zu prüfen.','equity-09','valuation-model','reverse','Umgekehrte DCF-Bewertung|Reverse Discounted Cash Flow'),
 G('Modellkonsistenz','Widerspruchsfreie Behandlung von Größen, Perioden, Kapitalansprüchen und wirtschaftlichen Regeln innerhalb einer Rechnung. Bilanz, Zahlungsüberleitung und alternative Wertdarstellung helfen bei der Prüfung. Konsistenz ist notwendig, beweist aber nicht, dass Zukunftsannahmen zutreffen.','equity-09','valuation-model','forecast-controls','Model Consistency'),
 G('Price-Earnings Ratio','Preis je betrachteter Stammaktie relativ zum Gewinn je Aktie auf einer ausdrücklich definierten Periode und Aktienbasis. Trailing, Forward, berichtete und normalisierte Gewinne erzeugen verschiedene Quoten. Verluste oder ein kleiner Nenner begrenzen die gewöhnliche Billigkeitsinterpretation; niedrigeres P/E kann Risiko, Verschuldung oder einen Zyklusgewinn abbilden.','equity-10','multiples','definitions','P/E|Kurs-Gewinn-Verhältnis|KGV'),
 G('Price-to-Book Ratio','Stammkapitalpreis relativ zu dessen passendem Buchkapital. Preis, Buchwert und Aktienbestand müssen denselben Anspruch und Stichtag abbilden. Ein Abschlag kann zu einer erwarteten Kapitalrendite unter Eigenkapitalkosten passen. Bilanzierungsregeln und nicht aktivierte Ressourcen beeinflussen die Vergleichbarkeit.','equity-10','multiples','pb','P/B|Kurs-Buchwert-Verhältnis|KBV'),
 G('EV/EBITDA','Definierter operativer Enterprise Value geteilt durch ein zeitlich und hinsichtlich Konsolidierung passendes EBITDA. Das Verhältnis reduziert unmittelbare Finanzierungsmischungen, erfasst aber nicht automatisch Steuern, Anlagenersatz oder zusätzliche Kapitalbindung. Sein Ergebnis benötigt für den Stammaktienwert eine vollständige Anspruchsbrücke.','equity-10','multiples','ebitda'),
 G('Trailing P/E','Heutiger Aktienpreis relativ zum vergleichbar abgegrenzten vergangenen Gewinn je Aktie, häufig der zurückliegenden zwölf Monate. Das Gewinnhoch eines Zyklus oder ein Sondergewinn kann die Quote künstlich niedrig erscheinen lassen. Trailing P/E ist nicht unmittelbar mit einem Forward-P/E-Peer vergleichbar.','equity-10','multiples','periods','Trailing PE|historisches P/E'),
 G('Forward P/E','Heutiger Aktienpreis relativ zum prognostizierten Gewinn je Aktie einer ausdrücklich genannten zukünftigen Periode. Nächstes Geschäftsjahr und nächste zwölf Monate können unterschiedliche Horizonte sein. Die Prognose ist noch nicht verdient; ein kleinerer Quotient garantiert keine günstigere Bewertung.','equity-10','multiples','periods','Forward PE'),
 G('Forward-Bewertungsbasis','Bewertungsrelation auf eine ausdrücklich benannte zukünftige Prognosegröße, etwa kommenden Gewinn oder kommendes EBITDA. Forward beschreibt in diesem Kapitel die Datenperiode und keinen Terminkontrakt. Preisdatum, Prognosehorizont und Definition müssen zwischen Zielunternehmen und Peers übereinstimmen.','equity-10','multiples','periods','vorausschauende Bewertungsbasis',[{label:'Forward',units:['multiples']}]),
 G('Prognosegeschäftsjahr','Durch Datenanbieter oder Analysten definiertes Geschäftsjahr einer Prognose. FY1 bezeichnet das erste nach ihrer Konvention erfasste, FY2 das folgende Prognosegeschäftsjahr. Der Zeitraum kann von den nächsten zwölf Monaten ab heute abweichen; Jahresende und aktuelle Informationsbasis werden deshalb ausdrücklich geprüft.','equity-10','multiples','calendar','FY1|FY2'),
 G('Trailing Twelve Months','Zurückliegender Zwölfmonatszeitraum ab einem angegebenen Stichtag. Für EPS müssen Perioden, Aktienbasis und Bereinigungen vergleichbar sein; unterschiedlich gewichtete Quartals-EPS sind nicht immer schlicht addierbar. TTM ist von einer annualisierten Zwischenperiode zu unterscheiden.','equity-10','multiples','periods','TTM'),
 G('Next Twelve Months','Kommender Zwölfmonatszeitraum ab dem Bewertungsstichtag. Eine zugehörige Gewinnprognose kann Teile zweier Geschäftsjahre enthalten. NTM ist deshalb nicht automatisch identisch mit FY1; Saisonverläufe und Aktienveränderungen müssen berücksichtigt werden.','equity-10','multiples','calendar','NTM'),
 G('Calendarization','Angleichung wirtschaftlicher Bezugsgrößen auf denselben Kalenderhorizont. Zeitanteilige Gewichtung ganzer Geschäftsjahre ist nur bei passenden Saison- und Aktienannahmen eine Näherung. Die Angleichung schafft keine Sicherheit über die Prognose und erlaubt keine damals unbekannten Informationen.','equity-10','multiples','calendar','Kalenderanpassung'),
 G('Look-ahead Bias','Verzerrung eines historischen Tests durch Angaben, die am angenommenen Entscheidungsstichtag noch nicht verfügbar waren. Auch später veröffentlichte alte Periodenergebnisse, heutige Restatements oder später realisierte Gewinne können diesen Fehler erzeugen. Berichtszeitraum und Veröffentlichungsdatum sind getrennt zu prüfen.','practice-02','multiples','calendar'),
 G('Method of Comparables','Relative Bewertung anhand beobachteter Marktpreise wirtschaftlich geeigneter Vergleichsunternehmen. Multiplikatoren werden einheitlich definiert und relevante Unterschiede erklärt. Eine gesamte Vergleichsgruppe kann gemeinsam falsch bepreist sein; relative Günstigkeit beweist keine absolute Unterbewertung.','equity-10','multiples','workflow','Comparables-Methode'),
 G('Method of Forecasted Fundamentals','Herleitung einer Wertrelation aus konsistent prognostizierten Cashflows, Wachstum, Kapitalbindung und Renditeforderung. Das Zahlungsmodell wird auf eine passende fundamentale Bezugsgröße standardisiert. Der entstehende gerechtfertigte Multiplikator bleibt von den Modellannahmen abhängig.','equity-10','multiples','workflow','Forecasted-Fundamentals-Methode'),
 G('Justified Multiple','Fundamental gerechtfertigter Multiplikator aus einem ausdrücklich beschriebenen Wertmodell. Er ist eine bedingte Schätzung und kein weiterer beobachteter Marktpreis. Die Gewinn- oder Kapitalbasis muss zu der des zugrunde liegenden Modells passen.','equity-10','multiples','forward-pe','gerechtfertigter Multiplikator|justified P/E'),
 G('Normalisiertes EPS','Begründete Schätzung eines vergleichbaren oder nachhaltigen Stammgewinns je Aktie nach erklärten Anpassungen. Sondereffekte, Zyklus, Steuern, Aktienbasis und Folgeeffekte sind zu prüfen. Ein managementseitig bereinigter Gewinn ist nicht allein durch seine Bezeichnung nachhaltig.','equity-10','multiples','normalization','Normalized EPS|normalisierter Gewinn'),
 G('Earnings Yield','Passender Gewinn je Aktie relativ zum positiven Aktienpreis, üblicherweise als Prozent angegeben. Bei von null verschiedenem Gewinn ist es der Kehrwert des P/E; bei Verlusten negativ und bei Nullgewinn null. Es ist keine garantierte Dividenden- oder Gesamtrendite.','equity-10','multiples','pe-negative','E/P|Ergebnisrendite'),
 G('P/E-to-Growth Ratio','P/E relativ zu erwarteter Gewinnwachstumsrate, gewöhnlich ausgedrückt als Prozentzahl im Nenner. PEG berücksichtigt Risiko, Ausschüttung, Reinvestition und Wachstumsdauer nicht vollständig. Nullwachstum und Vorzeichenprobleme begrenzen die Interpretation; ein Wert unter eins ist keine allgemeine Kaufregel.','equity-10','multiples','peg','PEG'),
 G('Relatives P/E','P/E eines Unternehmens relativ zu einem ausdrücklich benannten, gleich definierten Vergleichs-P/E. Ein Wert unter eins bedeutet eine niedrigere Quote gegenüber diesem Benchmark, aber nicht automatisch absolute Unterbewertung oder gleiche ökonomische Voraussetzungen.','equity-10','multiples','peg','Relative P/E'),
 G('Price-to-Sales Ratio','Stammkapitalpreis relativ zu passendem Umsatz, als Gesamtwerte oder auf derselben Aktienbasis gerechnet. Nettomarge und Finanzierung bestimmen, wie viel vom Umsatz den Stammaktionären nützt. Ein niedriger Umsatzmultiplikator kann geringe Margen statt Unterbewertung anzeigen.','equity-10','multiples','ps','P/S|Preis-Umsatz-Verhältnis'),
 G('EV/Sales','Abgegrenzter operativer Enterprise Value relativ zum Umsatz desselben Geschäftsumfangs und derselben Periodenbasis. Das Verhältnis benötigt zusätzlich eine Analyse operativer Marge, Steuern und Kapitalbindung. Umsatz ist weder Gewinn noch freier Cashflow.','equity-10','multiples','ps','EV/Revenue'),
 G('EV/EBIT','Operativer Enterprise Value relativ zum passenden Ergebnis nach operativen Abschreibungen, aber vor Zinsen und Steuern. Bei gleichem EV und positiver Abschreibung ist es höher als EV/EBITDA. Abschreibungsregeln, Anlagealter und Kapitalbedarf begrenzen die Vergleichbarkeit.','equity-10','multiples','ebitda'),
 G('Cash Earnings','Hier Gewinn zuzüglich ausdrücklich bestimmter nicht zahlungswirksamer Aufwendungen. Die grobe Kennzahl ist von CFO und FCFE zu unterscheiden: Working Capital, Anlagenzahlungen und Finanzierung werden nicht automatisch vollständig erfasst. Andere nicht zahlungswirksame Erträge benötigen passende Bereinigungen.','equity-10','multiples','pcf'),
 G('Tangible Book Value','Nach ausdrücklich festgelegten Regeln um immaterielle Buchposten vermindertes Buchkapital. Unterschiedliche Abgrenzungen und Eigentümeransprüche sind zu prüfen. Entfernung aus dem Nenner bedeutet nicht, dass die betreffenden immateriellen Ressourcen wirtschaftlich wertlos wären.','equity-10','multiples','pb','materieller Buchwert'),
 G('Gewichtetes harmonisches Mittel','Kehrwert einer gewichteten Summe der Kehrwerte positiver Beobachtungen; Gewichte summieren sich auf eins. Bei passenden positiven P/E-Daten und Marktwertgewichten entspricht es Gesamtmarktwert durch Gesamtgewinn. Andere Gewichte beantworten eine andere Frage.','equity-10','multiples','aggregate','Weighted Harmonic Mean'),
 G('Aggregiertes P/E','Gesamter betrachteter Marktwert relativ zum gesamten entsprechend erworbenen Gewinnanspruch. Bei positiven passenden Einzelgrößen entspricht es dem marktwertgewichteten harmonischen P/E, nicht allgemein dem arithmetischen Mittel. Verlustbeiträge und Aktienbasen verlangen zusätzliche Prüfung.','equity-10','multiples','aggregate','Aggregate P/E'),
 G('Selection Bias','Verzerrung durch eine nicht für die Frage repräsentative Auswahl von Beobachtungen. Im Multiplikatorvergleich kann etwa das Entfernen aller Verlustfirmen die scheinbare Branchenbasis verändern. Ein Median heilt keine selektiv zusammengestellte Vergleichsgruppe.','equity-10','multiples','summary','Auswahlverzerrung'),
 G('Dividend Discount Model','Direkte Aktienbewertung über den Barwert erwarteter Dividenden und gegebenenfalls eines konsistent begründeten späteren Restanspruchs. Die Zahlungen gehören zum betrachteten Stammkapital und werden mit dessen Renditeforderung diskontiert. Eine aktuelle Null-Dividende bedeutet nicht automatisch Wert null; spätere Eigentümerleistungen und Kapitalverwendung sind entscheidend.','equity-08','dcf-equity','ddm','DDM|Dividendenmodell|Dividendenmodelle'),
 G('Residual Income','Für den betrachteten Stammkapitalanspruch verfügbarer Gewinn nach Abzug der kalkulatorischen Eigenkapitalbelastung auf seinen Anfangsbuchwert. Positiver Gewinn kann trotzdem negativen Residualgewinn ergeben. RI ist kein weiterer ausgezahlter Cashflow; unter konsistenter Buchwertfortschreibung bewertet man den Buchwert plus künftige Überschüsse.','equity-11','dcf-equity','residual-charge','Residualgewinn|RI'),
 G('Clean Surplus','Buchwertfortschreibung, die Ergebnis und Eigentümerleistungen vollständig erklärt. Im einfachen Fall ohne weitere Transaktionen entspricht Endbuchwert dem Anfangsbuchwert plus Gewinn minus Dividende. Direkt im Eigenkapital gebuchte Effekte sowie Aktienausgaben und Rückkäufe müssen für ein konsistentes Residualgewinnmodell ausdrücklich abgegrenzt werden.','equity-11','dcf-equity','clean-surplus','Clean-Surplus-Beziehung'),
 G('Transversalitätsbedingung','Grenzbedingung einer unendlichen Bewertung, die einen unbegründeten abgezinsten Restanspruch in unendlich ferner Zukunft ausschließt. Im Dividendenmodell soll der diskontierte verbleibende Wert gegen null gehen; erst dann lässt sich der heutige Wert allein durch die unendliche Dividendenreihe ausdrücken. Sie ist keine Garantie wirtschaftlich plausibler Prognosen.','equity-08','dcf-equity','horizon','Transversality Condition'),
 G('Einbehaltungsquote','Anteil eines konsistent abgegrenzten Gewinns, der nach Dividenden im Unternehmen verbleibt. Bei konstantem ROE, geeigneter Kapitalfortschreibung und ohne externe Eigenkapitalveränderungen verbindet ihr Produkt mit ROE Einbehaltung und nachhaltiges Wachstum. Die Quote ist weder selbst die Wachstumsrate noch automatisch wertsteigernd.','equity-08','dcf-equity','retention','Retention Ratio|Thesaurierungsquote'),
 G('Sustainable Growth Rate','Langfristig mit Ressourcen, Finanzierung und Kapitalrendite vereinbare Wachstumsannahme. Im einfachen Eigenkapitalmodell ergibt sie sich aus Einbehaltung mal konstantem Anfangsbuchwert-ROE. Veränderte Renditen, Finanzierung oder Aktienzahl begrenzen die Anwendung. Nachhaltig bedeutet nicht garantiert; auch die absolute Marktgröße ist zu prüfen.','equity-08','dcf-equity','retention','Nachhaltige Wachstumsrate|nachhaltiges Wachstum'),
 G('Eigenkapitalbelastung','Kalkulatorischer Kostenbetrag aus erforderlicher Eigenkapitalrendite mal passendem Anfangsbuchkapital. Er ist keine zusätzliche vertragliche Auszahlung. Die Belastung ermöglicht, bilanziellen Gewinn und wirtschaftlichen Überschuss nach Eigenkapitalkosten zu unterscheiden.','equity-11','dcf-equity','residual-charge','Equity Charge'),
 G('Present Value of Growth Opportunities','Wertunterschied zwischen einem Modell mit künftigen Investitionsgelegenheiten und einem ausdrücklich definierten Vergleich ohne weitere Investition, der den nächsten Gewinn dauerhaft ausschüttet. PVGO kann positiv, null oder negativ sein; Wachstum allein garantiert keine Wertschaffung.','equity-08','dcf-equity','growth-value','PVGO|Barwert der Wachstumsgelegenheiten'),
 G('Hochwachstumsphase','Begrenzter Modellabschnitt mit über dem späteren stabilen Zustand liegenden Wachstumsannahmen. Jede Zahlung wird einzeln prognostiziert und diskontiert. Wachstum oberhalb des Diskontsatzes kann in einer endlichen Phase rechnerisch möglich sein; seine unbegrenzte Fortschreibung als positive ewige Reihe wäre nicht konvergent.','equity-08','dcf-equity','two-stage','Supernormal Growth|High-Growth Stage'),
 G('Übergangsphase','Prognoseabschnitt, in dem Wachstum, Rentabilität, Kapitalbindung oder Finanzierung allmählich zum langfristigen Zustand gelangen. Die Zahlungsbasis wird jährlich fortgeschrieben; ein Durchschnitt der Raten ersetzt die Folge nicht exakt. Zusätzliche Phasen sind nur bei wirtschaftlich begründeten Annahmen hilfreich.','equity-08','dcf-equity','transition','Transition Stage|Growth Fade'),
 G('Stabiles Wachstum','Modellannahme eines langfristig gleichbleibenden Wachstumszustands mit dazu passenden Kapitalrenditen, Investitionen, Finanzierung und Risiko. Die ewige positive Cashflowreihe benötigt Wachstum unterhalb ihres passenden Diskontsatzes. Die mathematische Bedingung allein beweist keine wirtschaftliche Tragfähigkeit.','equity-08','dcf-equity','limitations','Stable Growth'),
 G('Terminalwertanteil','Anteil des heutigen Gesamtmodellwerts, der aus dem auf heute abgezinsten Fortführungswert stammt. Ein hoher Anteil macht Annahmen über den stabilen Zustand besonders bedeutsam. Ein zukünftiger Endwert darf nicht ungezinst mit einem heutigen Gesamtwert verglichen werden.','equity-08','dcf-equity','two-stage','Terminal Value Share'),
 G('Normalisierung der Endphase','Neuberechnung der ersten stabilen Zahlung aus langfristig konsistenten Margen, Kapitalrenditen, Reinvestition, Finanzierung und Ausschüttung. Sie verhindert, dass eine ungewöhnliche letzte Detailzahlung oder alte Überrendite mechanisch in einen anderen reifen Zustand übertragen wird.','equity-09','dcf-equity','terminal-normalization','Terminal Normalization'),
 G('Fortgesetzter Residualgewinn','Nach der expliziten Prognose noch erwarteter wirtschaftlicher Überschuss über die Eigenkapitalbelastung. Im endlichen RI-Modell entspricht sein Wert am Prognoseende dem dortigen Eigenkapitalwert abzüglich Buchwert. Wenn beide gleich sind, kann der Restüberschuss null sein, obwohl das Geschäft einen positiven Wert besitzt.','equity-11','dcf-equity','continuing-ri','Continuing Residual Income'),
 G('Nicht kündbare Vorzugsaktie','Vorzugsaktie ohne das betreffende vertragliche Kündigungsrecht des Emittenten. Weitere Rechte, Fälligkeit und Zahlungsausfallrisiko bleiben zu prüfen. Nicht kündbar bedeutet für sich weder ewige Laufzeit noch feste Dividende oder garantierte Rückzahlung.','equity-01','dcf-equity','preferred','Non-Callable Preferred Stock'),
 G('Vorzugsaktie mit fester Dividende','Vorzugsanspruch mit fester vertraglicher Dividendenberechnung, häufig als Prozentsatz eines Nominalbetrags. Zahlung, Bezugsbetrag und heutiger Wert sind verschiedene Größen. Für die Bewertung werden auch Frequenz, Fälligkeit, Aufschub, Ausfall und weitere Vertragsrechte geprüft.','equity-01','dcf-equity','preferred','Fixed-Rate Preferred Stock'),
 G('Kündigungswert','Wert einer konkret modellierten Zahlungsfolge unter Kündigung nach dem Vertrag. Kündigungspreis am späteren Termin und heutiger Barwert sind nicht identisch. Ein Kündigungsrecht des Emittenten kann bei sonst gleichen Ansprüchen Anlegerwert vermindern; vollständige Bewertung hängt von Ausübungsbedingungen und Szenarien ab.','equity-01','dcf-equity','contingencies','Call Scenario Value'),
 G('Innerer Wert','Begründete Schätzung des wirtschaftlichen Werts eines klar abgegrenzten Anspruchs auf Basis seiner erwarteten Vorteile, Zeit und Risiken. Er ist kein direkt beobachtbarer sicherer zweiter Marktpreis. Aussage, Stichtag und Unsicherheit hängen von Modell, Daten und Annahmen ab.','equity-08','valuation-overview','price-value','Intrinsic Value|Fundamental Value|Fundamentaler Wert'),
 G('Marktpreis','Zu einem angegebenen Zeitpunkt beobachtete Quotierung oder tatsächlich ausgehandelter Preis eines bestimmten Anspruchs. Er ist vom geschätzten inneren Wert zu unterscheiden. Ein einzelner Stückpreis garantiert nicht die Handelbarkeit einer beliebig großen Gesamtposition zu diesem Preis.','equity-08','valuation-overview','price-value','Market Price'),
 G('Margin of Safety','Hier ausdrücklich als Abstand zwischen geschätztem innerem Wert und Preis relativ zum geschätzten Wert definiert. Derselbe Abstand relativ zum Preis ergibt einen anderen Prozentsatz. Eine Sicherheitsmarge kann Unsicherheit berücksichtigen, garantiert aber weder richtige Bewertung noch spätere Kursgewinne.','equity-07','valuation-overview','gap','Sicherheitsmarge'),
 G('Bewertungsstichtag','Zeitpunkt, auf den sich eine Wertschätzung bezieht. Preis, Aktienbestand, Ansprüche, Daten und abgezinstes Zahlungsprofil müssen dazu konsistent sein. Ein heutiger Wert und ein erwarteter zukünftiger Verkaufspreis sind nicht ohne weitere Anpassung dasselbe.','equity-08','valuation-overview','workflow','Valuation Date'),
 G('Kursziel','Erwarteter oder unter einem Szenario angenommener Aktienpreis für einen ausdrücklich genannten zukünftigen Zeitpunkt. Er ist von einem geschätzten heutigen inneren Wert zu unterscheiden. Für eine erwartete Gesamtrendite sind zusätzlich Ausschüttungen, Einsatz und gegebenenfalls Kosten relevant.','equity-08','valuation-overview','gap','Price Target'),
 G('Catalyst','Mögliches Ereignis, das neue Informationen sichtbar macht oder wirtschaftliche Bedingungen verändert und dadurch eine Preis-Wert-Differenz beeinflussen könnte. Eintritt, Wirkung und Zeitpunkt der Marktreaktion sind nicht garantiert. Ein genanntes Ereignis ersetzt keine Bewertung seiner konkreten Folgen.','equity-07','valuation-overview','uncertainty','Bewertungskatalysator'),
 G('Buchwert des Eigenkapitals','Differenz der nach den angewandten Rechnungslegungsregeln angesetzten Aktiva und Verbindlichkeiten. Für den Buchwert der Stammaktionäre sind darin enthaltene fremde Tochteranteile und andere Eigenkapitalansprüche passend abzugrenzen. Buchwert ist weder automatisch innerer Wert noch garantierter Liquidationserlös.','statements-03','valuation-overview','book','Book Value of Equity'),
 G('Buchwert je Aktie','Den betrachteten Aktionären zurechenbarer Eigenkapitalbuchwert geteilt durch die dazu passende ausstehende Aktienzahl am selben Stichtag. Gesamtes Konzerneigenkapital oder die zeitgewichtete Jahresaktienzahl können für diese Rechnung unpassend sein. Unterschiedliche Aktienrechte sind gesondert zu beachten.','equity-10','valuation-overview','book','Book Value per Share|BVPS'),
 G('Market Capitalization','Marktwert des betrachteten ausstehenden Aktienkapitals: bei einer Klasse Kurs mal aktuelle Aktienzahl, bei mehreren Klassen Summe der jeweiligen Klassenwerte. Der volle Wert umfasst auch Bestände außerhalb des Free Float. Er ist kein Beweis, dass sämtliche Aktien gleichzeitig zum beobachteten Stückpreis handelbar sind.','equity-01','valuation-overview','market-cap','Marktkapitalisierung|Market Cap'),
 G('Enterprise Value','Wert des operativen Geschäfts nach einer ausdrücklich definierten Anspruchs- und Vermögensabgrenzung. Eine übliche Marktwertbrücke addiert zu Stammkapital Schulden, Vorzüge und passende externe Tochteranteile und entfernt separat erfasste nicht operative Werte. Kasse, Leasing und weitere Verpflichtungen müssen konsistent mit Cashflows und Vergleichsgrößen behandelt werden.','start-06','valuation-overview','enterprise','EV|Unternehmenswert'),
 G('Equity Value','Wert eines definierten Eigenkapitalanspruchs. Es muss klar sein, ob gesamtes Eigenkapital oder nur das Stammkapital bestimmter Eigentümer gemeint ist. Eine operative Unternehmensbewertung benötigt dafür eine Anspruchsbrücke; eine vollständige direkte Eigenkapitalbewertung erhält diese Abzüge nicht automatisch nochmals.','equity-08','valuation-overview','bridge','Eigenkapitalwert'),
 G('Going-Concern-Wert','Wert unter der Annahme, dass das Geschäft fortgeführt wird. Er berücksichtigt die erwarteten wirtschaftlichen Vorteile der fortbestehenden Organisation und erforderliche Investitionen. Er kann von einer Einzelverwertung abweichen; Fortführung ist keine Garantie eines höheren Werts.','equity-11','valuation-overview','basis','Going Concern Value|Fortführungsbewertung'),
 G('Liquidationswert','Geschätzter Nettoerlös einer definierten Verwertung nach Ansprüchen, Zeit- und Kostenfolgen. Geordnete Auflösung und Notverkauf können verschiedene Ergebnisse erzeugen. Buchwerte bilden keinen sicheren Mindestbetrag; Verfügbarkeit, Übertragbarkeit und tatsächliche Nettoerlöse sind zu prüfen.','equity-11','valuation-overview','assets','Liquidation Value'),
 G('Kontrollprämie','Mögliche Wert- oder Preisdifferenz für tatsächlich erworbene Einflussrechte und daraus erreichbare wirtschaftliche Änderungen gegenüber einem passenden Minderheitsvergleich. Ein pauschaler Zuschlag ist nicht universell gerechtfertigt. Bereits eingepreiste Kontrolle, umsetzbare Synergien und Kosten sind zu unterscheiden.','equity-12','valuation-overview','basis','Control Premium'),
 G('Vermögensorientierte Bewertung','Bewertung anhand konsistent geschätzter Vermögenswerte abzüglich Verpflichtungen, zusätzlicher Kosten und fremder Ansprüche. Sie übernimmt nicht einfach ungeprüfte Bilanzwerte. Immaterielle Ressourcen, Verbundeffekte und Verwertungsbedingungen können die Aussage gegenüber einer Fortführungsbewertung begrenzen.','equity-11','valuation-overview','assets','Asset-Based Valuation'),
 G('Sum of the Parts','Bewertung eines Unternehmens aus den separat ermittelten Werten seiner Geschäfte oder Beteiligungen mit anschließender Abstimmung von Eigentumsquoten, Holdingkosten, Schulden und weiteren Ansprüchen. Eine bloße Bruttosumme kann Anteile überschätzen oder gemeinsame Posten doppelt erfassen.','equity-11','valuation-overview','selection','SOTP'),
 G('Discounted Cashflow','Bewertungsverfahren, das erwartete zukünftige Cashflows und verbleibende Ansprüche mit passenden Diskontsätzen auf einen gemeinsamen Stichtag überführt. Zahlungsumfang, Kapitalgeber, Währung und Zeit müssen zusammenpassen. Ein operativer Barwert und ein direkter Eigenkapitalbarwert benötigen unterschiedliche nachfolgende Anpassungen.','equity-09','valuation-overview','present-value','DCF|Discounted Cash Flow'),
 G('Multiple','Bewertungsrelation zwischen einem definierten Wert und einer dazu passenden fundamentalen Größe. Marktbeobachtete Vergleichsmultiplikatoren und fundamental hergeleitete Multiplikatoren sind zu unterscheiden. Anspruch, Periode, Rechnungslegung, Wachstum und Risiko bestimmen die Vergleichbarkeit; ein niedriger Quotient allein beweist keine Unterbewertung.','equity-10','multiples','scope','Multiplikator|Multiplikatoren|Multiples'),
 G('Vergleichsunternehmen','Unternehmen, dessen Bewertungsrelation als Vergleich dienen soll. Eignung folgt wirtschaftlichen Gemeinsamkeiten in Wachstum, Risiko, Rentabilität, Investitionsbedarf und Rechnungslegungsbasis. Ein gemeinsamer Branchenname allein schafft keine vollständige Vergleichbarkeit.','equity-10','multiples','peers','Peer Company|Peers|Comparable Companies'),
 G('Dividende','Ausschüttung einer Gesellschaft an die für die konkrete Maßnahme berechtigten Eigentümer. Sie kann in Bargeld oder anderen Vermögenswerten bestehen. Eine Barausschüttung überträgt vorhandenen Wert; eine proportionale Ausgabe eigener identischer Aktien verändert zunächst die Stückelung. Beschluss, Anspruch und tatsächliche Zahlung sind zu unterscheiden.','corporate-09','equity-returns','forms','Dividenden'),
 G('Bardividende','Ausschüttung von Zahlungsmitteln je berechtigter Aktie nach den festgelegten Bedingungen. Der Anspruch kann schon am Ex-Tag vom gehandelten Aktienpaket abgetrennt werden, obwohl die Zahlung erst später erfolgt. Sie ist ein Bestandteil der Gesamtrendite und allein kein Beweis eines Vermögenszuwachses.','corporate-09','equity-returns','wealth','Cash Dividend'),
 G('Reguläre Dividende','Wiederkehrende Ausschüttung nach der bisherigen oder angekündigten Politik der Gesellschaft. Sie kann Erwartungen an Kontinuität schaffen; die Historie garantiert aber keine unbeschränkte Fortsetzung. Künftige Beschlüsse, Zahlungsfähigkeit und Beschränkungen bleiben relevant.','corporate-09','equity-returns','forms','Regular Cash Dividend'),
 G('Sonderdividende','Zusätzliche oder unregelmäßige Ausschüttung, häufig aus einmalig verfügbaren Mitteln. Die Bezeichnung allein bestimmt weder ihre Nachhaltigkeit noch die Ex-Tag-Regeln. Ein besonderer US-Abwicklungsfall für sehr große Zahlungen ist nicht automatisch auf jede Sonderdividende übertragbar.','corporate-09','equity-returns','exceptions','Special Dividend|Extra Dividend'),
 G('Liquidationsausschüttung','Rückgabe von Vermögen im Zuge einer vollständigen oder teilweisen Abwicklung. Sie ist von einem nachhaltigen laufenden Ertrag zu unterscheiden. Für den Vermögensvergleich müssen Ausschüttung und verbleibende Ansprüche gemeinsam bewertet werden.','corporate-09','equity-returns','forms','Liquidating Dividend'),
 G('Stock Dividend','Ausschüttung in Form von Aktien. Bei proportionaler Ausgabe zusätzlicher identischer eigener Aktien steigt die Stückzahl, während der theoretische Stückwert entsprechend sinkt. Der Gesamtwert wächst dadurch allein nicht. Aktien einer anderen Gesellschaft oder abweichende Zuteilungsrechte erfordern eine gesonderte Analyse.','corporate-09','equity-returns','stock-dividend','Stock Dividends|Aktiendividende'),
 G('Declaration Date','Tag der Bekanntgabe beziehungsweise des Beschlusses einer konkreten Ausschüttung und ihrer Bedingungen. Er ist vom Registerstichtag, Ex-Tag und tatsächlichen Auszahlungstag zu unterscheiden. Eine Ankündigung ist kein sofortiger Geldzufluss.','corporate-09','equity-returns','dates','Dividend Declaration Date'),
 G('Dividend Record Date','Registerstichtag für die Zuteilung einer konkreten Ausschüttung. Die endgültige wirtschaftliche Berechtigung ergibt sich zusammen mit Ex-Tag, Handelsabwicklung und möglichen Weiterleitungspflichten. Er ist nicht automatisch mit einem Stimmrechtsstichtag oder Zahlungstag identisch.','corporate-09','equity-returns','dates','Dividendenstichtag'),
 G('Ex-Dividenden-Tag','Erster Handelstag, an dem die Aktie ohne das Recht auf die betreffende Ausschüttung gehandelt wird. Bei einer normalen Ex-Transaktion behält der zuvor berechtigte Verkäufer den abgetrennten Anspruch. Der Termin folgt den konkreten Markt- und Maßnahmeregeln und kann in Sonderfällen erst nach der Zahlung liegen.','equity-01','equity-returns','dates','Ex-Dividenden|Ex-Dividend Date|Ex-Date'),
 G('Payment Date','Vorgesehener Auszahlungstag einer beschlossenen Ausschüttung. Ein zuvor separat bestehender Dividendenanspruch wird durch die Zahlung erfüllt; die Zahlung ist dann kein zweiter unabhängiger Vermögenszuwachs. Weiterleitung über Verwahrer und Sonderregeln können die praktische Zuordnung beeinflussen.','corporate-09','equity-returns','dates','Dividend Payment Date'),
 G('Settlement','Abwicklung eines abgeschlossenen Wertpapiergeschäfts durch Lieferung und Zahlung. Handelsabschluss und Abwicklung können an verschiedenen Tagen liegen. T+1 bezeichnet einen Geschäftstag nach dem Abschluss; Kalender, Ausnahmen und Marktregeln sind zu prüfen.','equity-02','equity-returns','settlement','Wertpapierabwicklung'),
 G('Due Bill','Im Ausschüttungskontext eine Verpflichtung, ein zunächst erhaltenes Geld- oder Aktienrecht an den nach den Transaktionsregeln wirtschaftlich Berechtigten weiterzureichen. Dies kann relevant werden, wenn der Ex-Tag nach dem Register- oder Zahlungstag liegt. Registerempfang bedeutet dann nicht zwingend endgültiges Behalten.','corporate-09','equity-returns','exceptions','Due Bills'),
 G('Cum Dividende','Handelsstatus einer Aktie einschließlich des Rechts auf die betreffende bevorstehende Ausschüttung. Im Ex-Status wird dieselbe Aktie ohne dieses Recht gehandelt. Der Anspruch darf bei der Bewertung nicht zugleich im Cum-Preis und als zusätzlicher separater Vermögenswert gezählt werden.','equity-01','equity-returns','exprice','Cum-Dividend'),
 G('Dividendenrendite','Dividende je Aktie für eine festgelegte Periode geteilt durch den angegebenen Aktienpreis. Historische und prognostizierte Dividenden ergeben unterschiedliche Aussagen. Eine hohe Quote kann auch durch einen gefallenen Kurs entstehen und garantiert weder die nächste Zahlung noch eine positive Gesamtrendite.','corporate-09','equity-returns','yield','Dividend Yield'),
 G('Ausschüttungsquote','Passend abgegrenzte Dividende geteilt durch den dazugehörigen Gewinn; auf konsistenter Aktienbasis auch Dividende je Aktie geteilt durch EPS. Sie unterscheidet sich von der Dividendenrendite, deren Nenner der Preis ist. Bei negativem oder sehr kleinem Gewinn ist die übliche positive Quote oft wenig aussagekräftig.','corporate-09','equity-returns','yield','Dividend Payout Ratio|Payout Ratio'),
 G('Aktienrückkauf','Erwerb eigener Aktien durch die Gesellschaft. Verkäufer erhalten Geld; nicht verkaufende Anleger erhalten daraus keinen unmittelbaren eigenen Cashflow. Werden erworbene Aktien nicht mehr als ausstehend gezählt, steigt deren relative Beteiligung. Wertwirkung und EPS-Effekt hängen zusätzlich von Rückkaufpreis, Finanzierung und weiteren Aktienbewegungen ab.','corporate-09','equity-returns','repurchases','Share Buyback|Rückkauf|Rückkäufe|Share Repurchase'),
 G('Treasury Shares','Von einer Gesellschaft gehaltene eigene Aktien. Im beschriebenen Modell gehören sie nicht zu den ausstehenden Aktien; eine spätere Wiederausgabe kann diese wieder erhöhen. Eigene Aktien, rechtlich ausgegebene Aktien und ausstehende Aktien sind verschiedene Bestände. Rechte und Bilanzierung folgen dem anwendbaren Rahmen.','corporate-09','equity-returns','repurchases','Treasury Stock|Eigene Aktien'),
 G('Aktiensplit','Umstellung jeder alten Beteiligung in eine festgelegte proportionale Zahl neuer Aktien. Bei unverändertem Gesamtwert steigt die Stückzahl im gleichen Faktor, um den der theoretische Preis je Aktie sinkt. Historische Kurse, Dividenden und EPS müssen für Vergleiche auf eine gemeinsame Stückbasis gebracht werden.','equity-01','equity-returns','splits','Stock Split'),
 G('Reverse Split','Zusammenlegung mehrerer alter Aktien zu weniger neuen. Der theoretische Preis je Aktie steigt im reinen Modell entsprechend, während der Gesamtwert gleich bleibt. Die Maßnahme behebt allein kein operatives Problem; Bruchteilsbehandlung und rechtliche Voraussetzungen sind gesondert zu prüfen.','equity-01','equity-returns','reverse','Reverse Stock Split'),
 G('Bruchteilsabfindung','Bargeldzahlung für einen nach einer Kapitalmaßnahme nicht als ganzes Stück gelieferten Aktienbruchteil, soweit die konkreten Bedingungen dies vorsehen. Betrag und Preisbasis müssen aus der Abrechnung stammen. Für die Rendite ist die Zahlung zusätzlich zu den tatsächlich verbleibenden ganzen Aktien zu berücksichtigen.','equity-01','equity-returns','reverse','Cash in Lieu'),
 G('Adjusted Close','Historischer Schlusskurswert mit vom Datenanbieter definierten Anpassungen, etwa für Splits und gegebenenfalls Ausschüttungen. Die Methodik muss geprüft werden. Sind Dividenden bereits in einer Gesamtrenditereihe berücksichtigt, dürfen sie für dieselbe Renditekonvention nicht erneut addiert werden.','quant-03','equity-returns','normalization','Adjusted Closing Price'),
 G('Dividend Reinvestment Plan','Verfahren zur Wiederanlage von Dividenden in zusätzliche Aktien nach den jeweiligen Bedingungen. Ausführungspreis, Gebühren, Steuerabzug und Bruchteile beeinflussen den Bestand. Die zusätzlichen Aktien erhöhen die künftige Kurs- und Dividendenexponierung; Wiederanlage garantiert keine Überlegenheit gegenüber gehaltenem Bargeld.','corporate-09','equity-returns','reinvestment','DRIP'),
 G('Total Return','Gesamtrendite aus der Veränderung des Aktienwerts und den dazugehörigen Ausschüttungen auf konsistenter Beteiligungsbasis. Bei mehreren Zahlungen müssen Wiederanlage, Bargeldhaltung oder Entnahme ausdrücklich festgelegt werden. Splits werden korrekt bereinigt; Gebühren und Steuern bestimmen, ob die Rendite brutto oder netto ist.','practice-02','equity-returns','returns','Gesamtrendite') ,
 G('Primärmarkt','Markt für die Platzierung neu ausgegebener Wertpapiere. Bei einer Aktienausgabe fließen die vereinbarten Erlöse abzüglich der Emittentenkosten zur Gesellschaft. Ein öffentliches Angebot kann daneben Verkäufe bereits bestehender Aktien enthalten; deren Erlöse sind separat zuzuordnen.','equity-02','equity-trading','flows','Primary Market'),
 G('Sekundärmarkt','Handel bereits bestehender Wertpapiere zwischen Anlegern oder mit Handelspartnern. Der Verkaufspreis wird nicht automatisch zu neuem Eigenkapital des Emittenten. Übertragbarkeit und Preisbildung können die Bedingungen künftiger Primärfinanzierung dennoch indirekt unterstützen.','equity-02','equity-trading','secondary','Secondary Market'),
 G('Bookbuilding','Sammlung von Kaufinteresse zu Mengen und Preisen im Rahmen einer Emission. Das Verfahren unterstützt Angebotspreis und Zuteilung. Interessenbekundungen, verbindliche Zeichnung und tatsächlich später ausgeführter Handel sind zu unterscheiden; Überzeichnung garantiert keine Rendite.','equity-02','equity-trading','pricing'),
 G('Underpricing','Abstand eines niedrigeren Angebotspreises zu einem angegebenen späteren Marktvergleich, häufig dem ersten Schlusskurs. Ein nachträglich beobachteter Abstand beweist nicht, dass vorher das gesamte Angebot sicher zum späteren Kurs hätte verkauft werden können. Die Rendite eines späteren Käufers hängt von dessen eigenem Einstieg ab.','equity-02','equity-trading','pricing'),
 G('Firm Commitment','Emissionsvereinbarung, bei der ein Underwriter nach den festgelegten Bedingungen die vereinbarte Ausgabe übernimmt und das entsprechende Weiterverkaufsrisiko trägt. Diese Übernahmeverpflichtung ist keine Garantie des späteren Börsenkurses.','equity-02','equity-trading','underwriting'),
 G('Best Efforts','Platzierungsvereinbarung, bei der der Vermittler sich um den Verkauf bemüht, ohne in derselben Weise wie bei einem Firm Commitment die gesamte Ausgabe zu übernehmen. Tatsächlich platzierte Menge und eventuelle Mindestbedingungen bestimmen den Finanzierungserfolg.','equity-02','equity-trading','underwriting'),
 G('Underwriter','Bei einer Emission beteiligte Bank beziehungsweise übernehmender oder platzierender Intermediär. Aufgaben können Strukturierung, Preisfindung, Vertrieb und je nach Vertrag Risikoübernahme umfassen. Verpflichtungen und Vergütung werden aus der konkreten Vereinbarung abgeleitet.','equity-02','equity-trading','underwriting'),
 G('Folgeemission','Weitere Wertpapierausgabe nach einer früheren öffentlichen Kapitalaufnahme. Bei neuen Aktien kann sie zusätzliches Eigenkapital schaffen. Ein Angebot bestehender Aktionäre ist von einer solchen Neuausgabe zu unterscheiden; öffentliches Angebot allein bestimmt den Geldempfänger nicht.','equity-02','equity-trading','underwriting','Follow-on Offering'),
 G('Bezugsrecht','Nach den Bedingungen bestehende Möglichkeit eines Aktionärs, an einer neuen Ausgabe teilzunehmen. Verhältnis, Bezugspreis, Frist und mögliche Handelbarkeit bestimmen die praktische Wirkung. Das Recht ist keine Pflicht zur Mitzeichnung und verhindert ohne Ausübung oder Verwertung nicht automatisch jede wirtschaftliche Benachteiligung.','equity-02','equity-trading','underwriting','Bezugsrechte|Subscription Right'),
 G('Market Maker','Händler, der nach seinem Geschäftsmodell und den geltenden Verpflichtungen Kauf- und Verkaufskurse stellt. Verfügbare Mengen, Bestandsrisiko und Marktbedingungen beeinflussen seine Quotierung. Ein angezeigter Kurs garantiert nicht unbegrenzte Handelbarkeit zu diesem Preis.','equity-02','equity-trading','secondary'),
 G('Alternative Trading System','Alternative elektronische Ausführungsstruktur; im beschriebenen US-Rahmen ein reguliertes System außerhalb der nationalen Börsenkategorie. Es kann auch börsennotierte Aktien handeln. Rechtlicher Status, Informationsanzeige und tatsächliche Ausführung sind getrennt zu prüfen.','equity-02','equity-trading','venues','ATS|Alternative Trading Systems'),
 G('Internalisierung','Ausführung von Kundeninteresse innerhalb der Handelsstruktur eines Intermediärs, etwa gegen dessen eigenen Bestand, statt unmittelbarer Weiterleitung an ein externes Orderbuch. Die genaue Ausgestaltung und Regeln sind zu prüfen. Internalisierung beweist weder automatisch bessere Preise noch Kostenfreiheit.','equity-02','equity-trading','venues','Internalization'),
 G('Dark Pool','Handelsmechanismus mit begrenzter öffentlicher Anzeige der Kauf- und Verkaufsinteressen vor Ausführung. Das ist von der nachträglichen Veröffentlichung oder Meldung ausgeführter Geschäfte zu unterscheiden. Im US-ATS-Beispiel bedeutet fehlende öffentliche Quotierung nicht fehlende Meldepflicht.','equity-02','equity-trading','transparency','Dark Pools'),
 G('Pre-Trade Transparency','Sichtbarkeit von Kauf- und Verkaufsinteressen beziehungsweise Quotierungen vor einem Abschluss. Sie unterscheidet sich von Post-Trade Transparency, die Informationen über bereits ausgeführte Geschäfte betrifft.','equity-02','equity-trading','transparency','Vorhandelstransparenz'),
 G('Post-Trade Transparency','Verfügbarkeit von Informationen über bereits ausgeführte Geschäfte nach den geltenden Melde- und Veröffentlichungsregeln. Eine Ausführung ohne vorher öffentlich angezeigte Order kann trotzdem Nachhandelstransparenz besitzen.','equity-02','equity-trading','transparency','Nachhandelstransparenz'),
 G('Bid-Ask-Spread','Differenz zwischen Briefkurs und Geldkurs für den betrachteten Zeitpunkt und Markt. Absolut wird sie in Geldeinheiten je Stück gemessen; relativ benötigt sie einen ausdrücklich benannten Nenner, etwa den Mittelpunkt. Ein enger Spread sagt ohne verfügbare Mengen wenig über die Kosten großer Aufträge.','equity-02','equity-trading','spread','Quoted Spread|Spread'),
 G('Market Order','Auftrag, zum verfügbaren Markt auszuführen, ohne einen bestimmten Preis zu garantieren. Größere Mengen können mehrere Preisstufen beanspruchen. Fehlende Liquidität, Unterbrechungen oder andere Bedingungen können auch die Ausführung beeinträchtigen.','equity-02','equity-trading','orders','Marktorder'),
 G('Limit Order','Auftrag mit maximal zulässigem Kaufpreis oder minimal zulässigem Verkaufspreis. Die Preisgrenze garantiert keine Ausführung oder vollständige Menge. Weitere Bedingungen bestimmen Gültigkeit und Behandlung eines Restauftrags.','equity-02','equity-trading','orders','Limitorder|Limitorders'),
 G('Markttiefe','Verfügbare Kauf- oder Verkaufsmengen auf beziehungsweise nahe bestimmten Preisstufen. Große Aufträge können die besten Stufen aufbrauchen und schlechtere Preise erreichen. Tiefe zu einem Zeitpunkt ist keine unveränderliche Zusage für spätere Ausführung.','equity-02','equity-trading','depth','Market Depth'),
 G('Orderbuch','Geordnete Kauf- und Verkaufsinteressen mit Preisen und Mengen an einem Handelsplatz. Angezeigte Tiefe kann sich durch neue Orders, Ausführung oder Stornierung ändern und bildet mögliche andere Handelsplätze oder verdeckte Mengen nicht automatisch ab.','equity-02','equity-trading','orders','Order Book'),
 G('Midpoint','Mittelpunkt eines zusammengehörenden Geld- und Briefkurses zum angegebenen Zeitpunkt. Er kann als Referenz für relative Spreads und Ausführungskosten dienen, ist aber nicht automatisch ein tatsächlich ausführbarer Preis für die gewünschte Menge.','equity-02','equity-trading','spread','Kursmittelpunkt'),
 G('Float Ratio','Anteil des nach der angegebenen Methodik investierbaren Free Float an der passenden ausstehenden Aktienzahl. Eigene Aktien und überlappende Ausschlussgruppen dürfen nicht mehrfach abgezogen werden. Bestandsverfügbarkeit ist von tatsächlich gehandeltem Volumen zu trennen.','equity-02','equity-trading','float','Float-Anteil'),
 G('Average Daily Volume','Arithmetischer Durchschnitt des einmal gezählten Aktienhandelsvolumens über eine definierte Zahl von Handelstagen. Einheit sind Aktien je Handelstag. Fenster, Plätze, Datenabdeckung, Ausreißer und Splitbereinigung beeinflussen die Aussage. Der Durchschnitt garantiert keine künftige Ausführungskapazität.','equity-02','equity-trading','volume','ADV'),
 G('Average Daily Traded Value','Durchschnittlich gehandelter Geldwert je Handelstag im definierten Fenster. Er ergibt sich aus den tatsächlichen Preis-Mengen-Produkten der Geschäfte, nicht allgemein aus Durchschnittspreis mal durchschnittlicher Aktienmenge.','equity-02','equity-trading','volume','ADTV'),
 G('Floatbezogener Umschlag','Handelsvolumen eines Zeitraums relativ zu einem konsistent bestimmten Floatbestand. Mehr als hundert Prozent sind möglich, weil dieselbe Aktie wiederholt gehandelt werden kann. Die Quote belegt weder den Handel jeder einzelnen Aktie noch gleichzeitige Verkaufbarkeit des ganzen Bestands.','equity-02','equity-trading','capacity','Float Turnover'),
 G('Handelsteilnahmequote','Für einen Auftrag angesetzter oder gemessener eigener Anteil am gesamten Handelsvolumen des betrachteten Zeitraums. Zusammen mit Volumenannahme und Positionsgröße kann sie eine modellierte Ausführungsdauer liefern. Diese Dauer ist keine Preis- oder Liquiditätsgarantie.','equity-02','equity-trading','capacity','Trading Participation Rate'),
 G('Rebalancing','Ausrichtung tatsächlich gehaltener Gewichte auf die Zielgewichte einer Strategie oder Indexmethodik. Unterschiedliche Kursbewegungen können Gewichte zwischen Anpassungen verändern. Umsetzung verursacht gegebenenfalls Handel und Kosten; Reconstitution bezeichnet dagegen die Änderung von Mitgliedern.','equity-03','equity-trading','rebalancing'),
 G('Price Return Index','Index, dessen Rendite die entsprechende Kursentwicklung misst und gewöhnliche Ausschüttungen nicht als wiederangelegten Gesamtertrag hinzuzählt. Er ist von einem Total Return Index und dessen Steuerkonvention zu unterscheiden.','equity-03','equity-trading','return-types','Kursindex'),
 G('Gross Total Return Index','Index mit methodisch vorgesehener Wiederanlage der Bruttodividenden ohne den in einer Nettoindexvariante angesetzten Dividendensteuereinbehalt. Er ist ein theoretischer Vergleich und enthält nicht automatisch die tatsächlichen Kosten eines Fonds.','equity-03','equity-trading','return-types','Gross Total Return'),
 G('Net Total Return Index','Gesamtrenditeindex mit einer festgelegten Steuerannahme für Ausschüttungen. Netto bedeutet hier nicht automatisch nach sämtlichen Fondsgebühren oder nach der individuellen Besteuerung jedes Anlegers. Die konkrete Methodik ist für Vergleiche maßgeblich.','equity-03','equity-trading','return-types','Net Total Return'),
 G('Mehrstimmrechtsaktie','Aktie mit mehr als einer beziehungsweise mehr als der sonst maßgeblichen Zahl von Stimmen je Aktie. Dadurch kann die Quote an Stimmen erheblich über der wirtschaftlichen Beteiligung liegen. Geltungsbereich, Übertragung und mögliches Auslaufen ergeben sich aus den konkreten Regeln; zusätzliche Stimmen erzeugen nicht automatisch zusätzliche Dividenden.','equity-01','voting','leverage','Mehrstimmrechte|High-Vote Shares'),
 G('Stimmrechtsquote','Anteil der einem Anleger für einen konkreten Gegenstand zustehenden Stimmen an der dafür maßgeblichen gesamten Stimmenbasis. Aktienzahlen werden zuerst mit ihrem jeweiligen Stimmgewicht multipliziert. Die Quote an ausstehenden Stimmen ist von der Quote unter tatsächlich abgegebenen Stimmen zu unterscheiden.','equity-01','voting','weights','Voting Power'),
 G('Sunset-Mechanismus','Vertraglich oder gesetzlich bestimmtes Auslaufen eines Sonderrechts nach einer Frist oder einem Ereignis. Bei Mehrstimmrechten kann etwa eine wirksame Umwandlung das künftige Stimmgewicht verändern. Der Begriff allein legt weder den Auslöser noch das Schicksal anderer Aktienrechte fest.','equity-01','voting','leverage','Sunset'),
 G('Klassenabstimmung','Gesonderte Abstimmung innerhalb einer bestimmten Aktienklasse, wenn die maßgeblichen Regeln deren Zustimmung verlangen. Die Stimmen anderer Klassen ersetzen diese Voraussetzung nicht. Eine Schutzmöglichkeit für einzelne Änderungen bedeutet keine allgemeine Unternehmenskontrolle.','equity-01','voting','class-votes','Class Vote'),
 G('Quorum','Vorgeschriebene Mindestvertretung der nach den konkreten Regeln maßgeblichen Anteile oder Stimmen, damit eine Versammlung oder Abstimmung beschlussfähig ist. Bezugsgröße, inklusive oder strikte Schwelle und Behandlung einzelner Stimmkategorien müssen bekannt sein. Erfülltes Quorum ist noch keine Zustimmung zum Antrag.','equity-01','voting','quorum','Beschlussfähigkeitsquorum'),
 G('Enthaltung','Abgegebene Erklärung, weder zuzustimmen noch abzulehnen. Ob sie für Quorum oder Mehrheitsnenner zählt, bestimmt die konkrete Regel. Sie kann das Erreichen einer Mehrheit erschweren, bleibt aber als Kategorie von Nein-Stimmen, fehlender Weisung und ungültigen Stimmen getrennt.','equity-01','voting','denominators','Enthaltungen|Abstention'),
 G('Supermajority','Erhöhtes Mehrheitserfordernis, etwa mindestens zwei Drittel einer ausdrücklich bestimmten Stimmenbasis. Ohne Nenner und genaue Schwelle ist die Regel unvollständig. Zwei Drittel gültiger Ja- und Nein-Stimmen können einen anderen Beschluss ergeben als zwei Drittel aller ausstehenden Stimmen.','equity-01','voting','denominators','qualifizierte Mehrheit'),
 G('Broker Non-Vote','Fehlende Brokerstimme zu einem Gegenstand im US-Abstimmungsverfahren, wenn der Intermediär keine Kundenweisung und keine entsprechende eigene Ausübungsbefugnis hat. Die vertretene Position kann nach den geltenden Regeln beim Quorum anders behandelt werden als beim Mehrheitsnenner. Sie ist nicht automatisch eine Enthaltung oder Nein-Stimme.','equity-01','voting','nonvotes','Broker Non-Votes'),
 G('Plurality Voting','Wahlregel, bei der die Kandidaten mit den höchsten gültigen Stimmenzahlen die verfügbaren Sitze erhalten. Eine absolute Mehrheit ist dabei nicht zwingend erforderlich. Ob kumulierte Stimmen zugelassen sind und was bei Gleichstand geschieht, sind zusätzliche Verfahrensfragen.','equity-01','voting','elections'),
 G('Majority Voting','Wahlverfahren mit einer ausdrücklich festgelegten Mehrheitsschwelle. Stimmenbasis, Behandlung von Enthaltungen und Folgen des Nichterreichens müssen aus den Regeln hervorgehen. Die höchste Stimmenzahl allein erfüllt eine strikte Mehrheit nicht unbedingt.','equity-01','voting','elections'),
 G('Straight Voting','Wahlverfahren ohne Kumulierung sämtlicher Sitzstimmen auf einen einzigen Kandidaten. Bei einem entsprechenden Verfahren kann ein geschlossener Mehrheitsblock alle Sitze besetzen. Davon ist Cumulative Voting zu unterscheiden, das die Konzentration mehrerer Wahlstimmen auf einzelne Kandidaten erlaubt.','equity-01','voting','elections'),
 G('Voting Record Date','Für eine konkrete Abstimmung maßgeblicher Stichtag zur Feststellung der Stimmberechtigung nach dem geltenden Verfahren. Er ist nicht automatisch Versammlungstag, Depotbankfrist oder Dividendenstichtag. Bestand und Nachweiskette müssen zu diesem Stichtag passen.','equity-01','voting','record','Stimmberechtigungsstichtag'),
 G('Registered Owner','Unmittelbar im Register der Gesellschaft verzeichneter Inhaber. Im beschriebenen US-Verfahren erhält er einen Proxy zur direkten Ausübung gegenüber dem Emittenten. Ein über einen Intermediär wirtschaftlich berechtigter Anleger kann eine andere Person sein.','equity-01','voting','chain','Record Holder'),
 G('Beneficial Owner','Im Depot- und Abstimmungskontext wirtschaftlich berechtigter Anleger, dessen Aktien über einen Intermediär statt unmittelbar auf seinen eigenen Namen im Gesellschaftsregister gehalten werden. Im US-Street-Name-Verfahren erteilt er typischerweise Weisungen an den Intermediär. Der allgemeine Begriff Beneficial Ownership kann in anderen Regeln einen abweichend definierten Umfang haben.','equity-01','voting','chain'),
 G('Voting Instruction Form','Weisungsformular des wirtschaftlich berechtigten Inhabers an den Intermediär im beschriebenen US-Abstimmungsprozess. Es gibt vor, wie die betroffenen Aktien auszuüben sind. Die Weisung ist weder ein Eigentumsübertrag noch allein ein Nachweis der erfolgreichen Auszählung.','equity-01','voting','chain','VIF'),
 G('Asset Owner','Kapitalverantwortlicher wie ein Pensionsfonds oder eine Stiftung, der Ziele und zulässige Vorgaben für das Vermögen festlegt. Er kann Aufgaben an Asset Manager delegieren und deren Erfüllung überwachen. Die maßgeblichen Begünstigten müssen vom bloßen Auftraggeber oder Sponsor unterschieden werden.','equity-01','voting','owners'),
 G('Asset Manager','Vermögensverwalter, der Anlage- und gegebenenfalls Stimmrechtsentscheidungen innerhalb eines Mandats trifft und umsetzt. Umfang der Vollmacht, Kundeninteresse, Konfliktbehandlung und Ausführungsnachweis bleiben maßgeblich. Verwaltung macht ihn nicht zum wirtschaftlichen Eigentümer des Kundenvermögens.','equity-01','voting','managers','Vermögensverwalter'),
 G('Stewardship','Verantwortlicher Umgang mit anvertrautem Kapital, der im Anlagekontext Überwachung, Dialog mit Emittenten und gegebenenfalls Stimmrechtsausübung umfassen kann. Welche Aufgaben bestehen, hängt von Recht, Mandat und offengelegter Politik ab. Eine allgemeine Zusage ersetzt keinen Nachweis ihrer Umsetzung.','equity-01','voting','managers'),
 G('Engagement','Im institutionellen Anlagekontext der sachbezogene Austausch mit einem Emittenten über relevante Unternehmens- und Governancefragen. Ein Gespräch kann die Analyse und Einflussnahme unterstützen, ist aber kein Nachweis, dass eine Stimme wirksam abgegeben wurde.','equity-01','voting','managers','Shareholder Engagement'),
 G('Proxy Adviser','Stimmrechtsberater, der Abstimmungsunterlagen analysiert und Empfehlungen nach einer Methodik oder Kundenrichtlinie erstellt. Manche Anbieter unterstützen auch die Ausführung. Empfehlung, technische Dienstleistung und autorisierte Entscheidung bleiben getrennt; der zuständige Manager muss Aktualität, Eignung und wesentliche Konflikte beurteilen.','equity-01','voting','advisers','Proxy Advisor|Stimmrechtsberater'),
 G('Stammaktie','Gewöhnliche Aktie mit einem Residualanspruch nach vorrangigen Verpflichtungen und vertraglichen Vorzügen. Sie kann am weiteren Unternehmenserfolg teilnehmen, aber ihren gesamten Wert verlieren. Ausschüttungs-, Stimm- und Informationsrechte folgen der konkreten Klasse und Rechtsordnung; Gewinn ist nicht automatisch eine sofortige Dividende.','equity-01','equity-features','common','Common Stock|Common Shares|Ordinary Shares|Stammaktien'),
 G('Fully Paid Shares','Aktien, für die die vereinbarte Einlage vollständig geleistet wurde. Im haftungsbeschränkten Grundfall begrenzt der bloße Aktienbesitz den persönlichen Rückgriff; gesonderte Garantien und weitere Verpflichtungen bleiben separat zu prüfen. Vollständige Einzahlung schützt nicht vor vollständigem Wertverlust.','equity-01','equity-features','claim','vollständig eingezahlte Aktien'),
 G('Liquidationsvorzug','Vertragliche bevorzugte Beteiligung einer Klasse an der nach vorrangigen Verpflichtungen verfügbaren Verwertungsmasse. Höhe, Rang, Dividendenrückstände und mögliche weitere Teilnahme hängen von den Bedingungen ab. Der nominelle Vorzug garantiert keine vollständige tatsächliche Zahlung.','equity-01','equity-features','waterfall','Liquidationspräferenz|Liquidation Preference'),
 G('Kumulative Vorzugsdividende','Vorgesehene Vorzugsdividende, deren ausgelassene Beträge nach den Bedingungen vor einer Ausschüttung an Stammaktionäre nachzuholen sind. Das Nachholrecht garantiert weder einen sofortigen Zahlungstermin noch ausreichende Liquidität; es begründet für sich auch keine bestimmte IAS-32-Klassifikation.','equity-01','equity-features','cumulative','Cumulative Preferred Shares|kumulative Vorzugsaktie'),
 G('Nicht kumulative Vorzugsdividende','Vorzugsdividende ohne automatischen Nachholanspruch für ausgelassene frühere Perioden. Ein laufender Ausschüttungsvorrang kann trotzdem bestehen. Weitere Sonderrechte und die konkrete Beschluss- und Zahlungslage sind gesondert zu prüfen.','equity-01','equity-features','cumulative','Non-Cumulative Preferred Shares|nicht kumulative Vorzugsaktie'),
 G('Dividendenrückstände','Bisher nicht gezahlte vorgesehene Dividendenbeträge, die etwa bei einem kumulativen Vorzug für spätere Ausschüttungen relevant bleiben. Rückstand, rechtlich beschlossene Zahlung und bilanzielle Verbindlichkeit sind nicht ohne Prüfung gleichzusetzen. Verzinsung besteht nur, wenn die Bedingungen sie vorsehen.','equity-01','equity-features','cumulative','Dividends in Arrears'),
 G('Teilnehmende Vorzugsaktie','Vorzugsaktie mit zusätzlicher Beteiligung an definierten Gewinnen, Ausschüttungen oder Exit-Erlösen neben dem Basisvorzug. Bezugsgröße, Schwellen und Deckelung bestimmen die tatsächliche Zahlung. Eine Quote auf den Rest nach Vorzug ist nicht dieselbe Quote auf den gesamten Erlös.','equity-01','equity-features','participation','Participating Preferred Shares|Participating Preferred Stock'),
 G('Wandelbare Vorzugsaktie','Vorzugsaktie mit einer nach Bedingungen vorgesehenen Umwandlung in Stammaktien. Bei freiwilliger Wandlung werden im Grundfall die bisherigen Vorzugsrechte zugunsten der Stammrechte aufgegeben. Sofortiger Wandlungswert, Wert des Behaltens und Pflichtwandlung sind getrennt zu beurteilen.','equity-01','equity-features','conversion','Convertible Preferred Shares|Convertible Preferred Stock'),
 G('Wandlungsverhältnis','Anzahl der Aktien, die bei Umwandlung eines Instruments nach den maßgeblichen Bedingungen geliefert werden. Anpassungsklauseln und Verwässerung können relevant sein. Das Verhältnis ist keine Kundenkonversionsrate eines Geschäftsmodells.','equity-01','equity-features','conversion','Conversion Ratio'),
 G('Wandlungswert','Wert der bei Wandlung lieferbaren Aktien unter den jeweiligen Preis-, Frist- und Übertragungsbedingungen. Er ergibt sich im einfachen Fall aus Aktienzahl mal passendem Aktienpreis. Das gesamte wandelbare Instrument kann wegen weiterer Rechte mehr wert sein als die sofortige Wandlungsalternative.','equity-01','equity-features','conversion','Conversion Value'),
 G('Wandlungspreis','Aus einem vertraglichen Bezugsbetrag und dem Wandlungsverhältnis abgeleiteter Preis je gelieferter Aktie. Er ist nicht automatisch der aktuelle Marktpreis oder eine Prognose. Für eine Entscheidung zählt der Vergleich der tatsächlich verfügbaren Rechte und Zahlungen.','equity-01','equity-features','conversion','Conversion Price'),
 G('Nicht teilnehmender Vorzug','Vorzugsanspruch ohne die betreffende zusätzliche Beteiligung am Rest. Enthält er ein freiwilliges Wandlungsrecht, wird im einfachen Exit-Fall zwischen Vorzugszahlung und Zahlung nach Wandlung gewählt; beide Alternativen werden nicht addiert.','equity-01','equity-features','exit','Non-Participating Preferred'),
 G('Callable Shares','Aktien mit einem Rückkauf- beziehungsweise Einlösungsrecht des Emittenten zu vertraglichen Preisen, Zeiten und Bedingungen. Dieses Recht kann den Erfolg bei fallenden Renditeforderungen begrenzen und Wiederanlagerisiko erzeugen. Es ist kein Rückgaberecht des Inhabers.','equity-01','equity-features','options','Callable Preferred Shares'),
 G('Putable Shares','Aktien mit einem vertraglichen Rückgaberecht des Inhabers. Es eröffnet eine zusätzliche Alternative unter bestimmten Bedingungen, ist aber keine vom Emittentenrisiko unabhängige Zahlungsgarantie. Die bilanzielle Behandlung erfordert eine gesonderte Vertragsprüfung.','equity-01','equity-features','options','Putable Preferred Shares'),
 G('Call-Preis','Vertraglich festgelegter Preis bei Ausübung eines Rückkauf- oder Einlösungsrechts durch den Emittenten. Der Ausübungszeitpunkt und eventuell vorher anfallende Zahlungen sind Teil der Bewertung; ein erst später geltender Call-Preis ist nicht immer eine harte Grenze des heutigen Marktpreises.','equity-01','equity-features','options','Call Price'),
 G('Aktienklasse','Gruppe ausgegebener Aktien mit bestimmten Rechten. Klassen können sich bei Ausschüttung, Stimmen, Rang, Umwandlung und Übertragung unterscheiden. Gleiche Stückzahlquoten müssen deshalb weder gleiche Kontrollmacht noch gleiche zustandsabhängige Zahlungen bedeuten.','equity-01','equity-features','classes','Share Class|Share Classes|Aktienklassen'),
 G('Private Placement','Platzierung von Wertpapieren außerhalb eines gewöhnlichen öffentlichen Angebots, etwa unter einem passenden Ausnahmeregime. Sie kann Eigen- oder Fremdkapital sowie öffentliche oder private Emittenten betreffen. Zulassung, Information und Übertragbarkeit hängen vom Rechtsraum und konkreten Angebot ab.','equity-01','equity-features','funding','Privatplatzierung'),
 G('Private Investment in Public Equity','Private Platzierung von Eigenkapitalinstrumenten eines öffentlichen beziehungsweise börsennotierten Emittenten. Der private Finanzierungsweg macht den Emittenten nicht automatisch privat und beseitigt mögliche Beschränkungen der neu ausgegebenen Instrumente nicht.','equity-01','equity-features','funding','PIPE'),
 G('Growth Equity','Beteiligungskapital zur Expansion eines bereits entwickelten Geschäfts. Es ist von sehr früher Gründungsfinanzierung und stark fremdfinanziertem Unternehmenskauf zu unterscheiden, wobei Übergänge möglich sind. Wachstum allein belegt weder Profitabilität noch eine garantierte Exitmöglichkeit.','alternatives-04','equity-features','funding','Wachstumskapital'),
 G('Venture Capital','Beteiligungsfinanzierung junger Unternehmen mit unsicherer Entwicklung und häufig weiteren Finanzierungsrunden. Wert hängt von wirtschaftlichem Erfolg, Finanzierungsbedingungen, Verwässerung und realisierbarem Exit ab. Nicht jede private Beteiligung ist Venture Capital.','alternatives-04','equity-features','funding','VC'),
 G('Marktliquidität','Möglichkeit, eine gewünschte Position zeitnah zu einem angemessenen Preis zu handeln. Sie hängt unter anderem von Größe, Marktbreite, Informationen und Übertragungsbedingungen ab. Sie ist von der Zahlungsfähigkeit des Emittenten und von einem bloß geschätzten Wert getrennt.','equity-02','equity-features','liquidity','Market Liquidity'),
 G('Depositary Receipt','Hinterlegungsschein mit einem wirtschaftlichen Bezug auf hinterlegte Aktien über eine Verwahr- und Vertragsstruktur. Verhältnis, Kosten, Ausschüttungsweiterleitung und Stimmrechtsabwicklung bestimmen die konkrete Beteiligung. Ein Schein kann mehrere Aktien oder nur einen Bruchteil repräsentieren.','equity-01','equity-features','depositary','Depositary Receipts|Hinterlegungsschein|Hinterlegungsscheine'),
 G('American Depositary Receipt','In einem US-Programm begebenes Instrument mit Bezug auf Aktien eines nicht US-amerikanischen Emittenten. ADRs werden in Dollar gehandelt; das beseitigt den Währungseinfluss der zugrunde liegenden Aktie nicht. Börsen-/OTC-Handel, Gebühren und Rechteweiterleitung richten sich nach dem Programm.','equity-01','equity-features','depositary','ADR|ADRs'),
 G('Global Depositary Receipt','Hinterlegungsschein für den Zugang zu Aktien über ein internationales Programm. Konkrete Handelsplätze, Anlegerkreise, Verhältnis, Gebühren und Rechte richten sich nach den Bedingungen; das Etikett garantiert weder freie Übertragbarkeit noch Währungsabsicherung.','equity-01','equity-features','depositary','GDR|Global Depositary Receipts'),
 G('Geschäftsmodell','Wirtschaftliche Funktionsweise eines Unternehmens: für wen es welchen Nutzen erzeugt, über welche Tätigkeiten und Kanäle es diesen liefert und wie daraus Erlöse, Kosten und Kapitalbedarf entstehen. Ein Preismodell oder eine Wachstumsvorgabe allein ist noch keine vollständige Beschreibung.','corporate-03','business-models','map','Business Model'),
 G('Value Proposition','Konkretes Nutzenversprechen gegenüber einer bestimmten Kundengruppe und ihren Alternativen. Eine Eigenschaft wird erst dann zum relevanten Nutzen, wenn sie ein wichtiges Problem löst, etwa Kosten, Zeitbedarf oder Ausfallrisiko reduziert. Sie ist vom Zahlungsmechanismus zu unterscheiden.','corporate-03','business-models','value','Nutzenversprechen'),
 G('Value Creation','Schaffung wirtschaftlichen Nutzens gegenüber den benötigten Ressourcen und verfügbaren Alternativen. Der geschaffene Gesamtüberschuss kann auf Kunden, Beschäftigte, Lieferanten und Anbieter verteilt werden; er verbleibt nicht automatisch beim betrachteten Unternehmen.','corporate-03','business-models','value','Wertschöpfung'),
 G('Value Capture','Anteil des geschaffenen wirtschaftlichen Nutzens, den eine Partei durch Preise, Rechte und Verhandlungsmacht für sich beanspruchen kann. Hoher Kundennutzen oder große Nutzerzahl allein beweisen noch keine nachhaltige Ertragsmöglichkeit des Anbieters.','corporate-03','business-models','value','Wertabschöpfung'),
 G('B2B','Business-to-Business: Geschäftsbeziehung zwischen Unternehmen. Nutzer, Einkaufsentscheider und zahlende Organisation können verschiedene Rollen einnehmen; Beschaffung, Integration und Budget beeinflussen die Nachfrage.','corporate-03','business-models','customers','Business-to-Business'),
 G('B2C','Business-to-Consumer: Verkauf oder Leistung eines Unternehmens an private Endkunden. Nutzerzahl, Kaufhäufigkeit, Zahlungsbereitschaft und tatsächliche zahlende Kunden müssen trotzdem getrennt gemessen werden.','corporate-03','business-models','customers','Business-to-Consumer'),
 G('B2B2C','Business-to-Business-to-Consumer: Ein Unternehmen erreicht Endkunden über einen Geschäftspartner. Zugang, Kundendaten, Preisrechte und Abhängigkeit vom Partner bestimmen, welcher Nutzen und Beitrag beim jeweiligen Unternehmen verbleibt.','corporate-03','business-models','customers','Business-to-Business-to-Consumer'),
 G('Value Chain','Wertschöpfungskette: zusammenhängende Tätigkeiten von Beschaffung und Entwicklung über Herstellung und Vertrieb bis zur Betreuung, einschließlich unterstützender Funktionen. Die Aufteilung zwischen Unternehmen verändert Kosten, Kontrolle und Risiken.','corporate-03','business-models','value-chain','Wertschöpfungskette'),
 G('Vertikale Integration','Zusammenfassung mehrerer aufeinanderfolgender Stufen der Wertschöpfung in derselben Unternehmensorganisation. Sie kann Koordination und Kontrolle erleichtern, aber auch Kapitalbindung, Fixkosten und interne Komplexität erhöhen.','corporate-03','business-models','value-chain','Vertical Integration'),
 G('Outsourcing','Bezug zuvor intern oder grundsätzlich intern ausführbarer Tätigkeiten von externen Partnern. Eigene Anlagen oder Personal können dadurch sinken; wirtschaftliche Verpflichtungen, Qualitätsrisiken und Abhängigkeit verschwinden jedoch nicht automatisch.','corporate-03','business-models','value-chain'),
 G('Asset-light','Geschäftsgestaltung mit relativ geringer eigener Bindung in bestimmten Vermögenswerten, etwa durch externe Produktion. Sie bleibt auf Ressourcen und Verträge angewiesen; Mindestabnahmen, Entwicklung, Marke und Liquiditätsbedarf können weiterhin erhebliche Kosten oder Risiken erzeugen.','corporate-03','business-models','value-chain'),
 G('Cost-plus Pricing','Preisfindung durch einen Aufschlag auf eine ausdrücklich festgelegte Kostenbasis. Sie vereinfacht die Kalkulation, belegt aber weder ausreichende Zahlungsbereitschaft noch die vollständige Deckung aller Fix- und Kapitalkosten.','corporate-03','business-models','pricing','kostenorientierte Preisbildung'),
 G('Value-based Pricing','Preisfindung anhand des Nutzens und der verfügbaren Alternativen einer Kundengruppe. Sie verlangt belastbare Kenntnisse der Zahlungsbereitschaft und eine Prüfung möglicher Mengen-, Bindungs- und Wettbewerbsreaktionen.','corporate-03','business-models','pricing','wertorientierte Preisbildung'),
 G('Deckungsbeitrag','Erlös abzüglich der jeweils zugeordneten variablen Kosten, etwa je Stück oder Auftrag. Der verbleibende Betrag deckt gemeinsame Fixkosten und erst danach Gewinn. Welche Kosten enthalten sind, muss vor Vergleich und Interpretation ausdrücklich festgestellt werden.','corporate-03','business-models','unit-economics','Contribution Margin'),
 G('Unit Economics','Analyse der Erlöse und Kosten je wirtschaftlich sinnvoller Einheit, etwa Kunde, Auftrag oder Transaktion. Ein positiver Beitrag vor Akquisition, Entwicklung oder gemeinsamen Kosten ist noch kein vollständiger Unternehmensgewinn oder Kapitalwert.','corporate-03','business-models','unit-economics'),
 G('Subscription Model','Abonnementmodell mit wiederkehrender Zahlung für vereinbarten Zugang oder wiederkehrende Leistung. Umfang, Nutzungskosten, Laufzeit und Kündigung bestimmen die tatsächliche Planbarkeit; wiederkehrende Abrechnung garantiert weder Bindung noch Profitabilität.','corporate-03','business-models','recurring','Abonnementmodell'),
 G('Monthly Recurring Revenue','Auf einen Monat normierter wiederkehrender Umsatz- beziehungsweise Vertragsbestand nach der offengelegten Definition des Unternehmens. MRR ist keine automatische Messung des aktuellen Zahlungseingangs oder des bereits bilanziell verdienten Umsatzes. Einmalige Gebühren und variable Nutzung benötigen klare Abgrenzungen.','corporate-03','business-models','recurring','MRR'),
 G('Annual Recurring Revenue','Annualisierter wiederkehrender Bestand; im hier verwendeten Modell zwölfmal MRR. ARR ist eine Stichtagskennzahl und weder garantierter nächster Jahresumsatz noch der Barwert zukünftiger Kundenbeiträge. Definitionen können zwischen Firmen variieren.','corporate-03','business-models','recurring','ARR'),
 G('Customer Churn Rate','Kundenabgangsquote über einen angegebenen Zeitraum und eine definierte Ausgangsgruppe. Hier verlorene Anfangskunden geteilt durch deren Anfangsbestand. Neukunden gehören nicht in diese Bindungsmessung; monatliche und jährliche Übergänge müssen konsistent verknüpft werden.','corporate-03','business-models','retention','Churn|Kunden-Churn|Kundenabgangsquote'),
 G('Gross Revenue Retention','Bruttoumsatzbindung einer festen Anfangskohorte nach Kündigungen und Verkleinerungen, ohne ausgleichende Expansion oder neue Kunden. GRR zeigt, wie viel der ursprünglichen Umsatzbasis ohne zusätzliche Vertragsausweitungen bestehen bleibt.','corporate-03','business-models','retention','GRR|Bruttoumsatzbindung'),
 G('Net Revenue Retention','Nettoumsatzbindung einer festen Anfangskohorte einschließlich Expansion derselben Kunden, aber ohne neue Akquisition. NRR kann trotz tatsächlicher Kündigungen hundert Prozent oder mehr erreichen. Der genaue Umgang mit Preisen, Währungen und Reaktivierungen ist zu prüfen.','corporate-03','business-models','retention','NRR|Nettoumsatzbindung'),
 G('Kohortenanalyse','Verfolgung einer nach einem gemeinsamen Merkmal abgegrenzten Gruppe über die Zeit, etwa Kunden aus demselben Akquisitionsmonat. Vergleichbare Altersstufen und konstante Gruppendefinition helfen, Bindung von ständig neuer Akquisition zu unterscheiden.','corporate-03','business-models','retention','Cohort Analysis|Kohorte|Kohorten'),
 G('Customer Acquisition Cost','Passend abgegrenzte Akquisitionsausgaben je tatsächlich gewonnenem Kunden. CAC verlangt eine konsistente Zuordnung von Kosten, Kundenzugang und Zeitverzögerung. Der historische Durchschnitt kann die Kosten der nächsten zusätzlichen Kundengruppe unterschätzen.','corporate-03','business-models','lifetime','CAC|Kundenakquisitionskosten'),
 G('Customer Lifetime Value','Barwert der unter ausdrücklichen Bindungs-, Beitrags- und Zeitannahmen erwarteten Kundenbeiträge; im hier verwendeten Modell nach einmaligen heutigen CAC. CLV-Definitionen unterscheiden sich bei Akquisition und gemeinsamen Kosten. Erste Zahlung, Wiederkehr, laufende Kosten und Diskontierung müssen vor Formelvergleichen abgeglichen werden.','corporate-03','business-models','lifetime','CLV|Customer Lifetime Value Model'),
 G('Amortisationsdauer','Zeitraum bis kumulierte Rückflüsse eine anfängliche Ausgabe decken. Einfache, erwartete und diskontierte Rückflussrechnungen können verschiedene Ergebnisse liefern. Die Kennzahl misst keinen vollständigen Kapitalwert und ignoriert je nach Definition Zahlungen nach dem Rückflusszeitpunkt.','corporate-04','business-models','payback','Payback Period|Rückflussdauer'),
 G('Freemium','Geschäfts- beziehungsweise Preismodell mit dauerhaft kostenlosem Grundumfang und bezahlten zusätzlichen Funktionen oder Leistungen. Die zahlenden Beiträge müssen je nach Modell auch kostenlose Nutzung und gemeinsame Kosten finanzieren. Eine nur zeitlich begrenzte kostenlose Testphase ist etwas anderes.','corporate-03','business-models','freemium'),
 G('Konversionsrate','Anteil einer genau definierten Ausgangsgruppe, der eine gewünschte Handlung vollzieht, etwa vom kostenlosen zum zahlenden Nutzer wird. Nenner, Zeitraum und Handlungsdefinition sind offenzulegen; Konversion allein belegt weder dauerhafte Bindung noch positiven Kundenwert.','corporate-03','business-models','freemium','Conversion Rate'),
 G('Cost per Mille','Preis pro tausend relevante Kontakte, häufig in der Werbung. CPM ist aus Sicht des Werbekäufers ein Kostenmaß und aus Sicht des Anbieters ein Erlöstreiber. Verfügbare und tatsächlich zum angesetzten Preis vermarktete Kontakte müssen getrennt werden.','corporate-03','business-models','freemium','CPM|Tausenderkontaktpreis'),
 G('Razor-and-Blades Pricing','Günstiges oder subventioniertes Basisprodukt mit profitablen späteren Verbrauchsgütern beziehungsweise Ergänzungen. Tragfähigkeit hängt von tatsächlicher Nutzung, eigenem Anteil der Folgekäufe, Kosten und Zahlungszeitpunkten ab. Eine große installierte Basis allein garantiert keinen positiven Wert.','corporate-03','business-models','complements','Razor-and-Blades'),
 G('Add-on Pricing','Zusätzlich bepreiste optionale Leistung oder Funktion neben einer Basisleistung. Ein Add-on muss kein regelmäßig verbrauchtes komplementäres Gut sein. Für die Analyse zählen tatsächlicher Gesamtpreis, Zusatzkosten und die Wahl der Kundengruppen.','corporate-03','business-models','complements'),
 G('Bundling','Gemeinsames Angebot mehrerer Bestandteile als Paket. Es kann Suchkosten reduzieren oder neue Nachfrage gewinnen, aber bisherige Einzelkäufe auch durch einen niedrigeren Paketpreis ersetzen. Der Vergleich braucht kundensegmentbezogene Alternativen und zusätzliche Kosten.','corporate-03','business-models','complements','Bündelung'),
 G('Licensing','Einräumung definierter Nutzungsrechte, etwa an Technologie oder Marke, gegen vereinbarte Vergütung. Das wirtschaftliche Modell hängt von Rechteumfang, Qualität, Durchsetzung, Erneuerung und Kosten ab. Es ist nicht automatisch gleichbedeutend mit einem vollständigen Franchisesystem.','corporate-03','business-models','rights','Lizenzierung'),
 G('Royalty','Vertragliche Vergütung für die Nutzung bestimmter Rechte, häufig umsatz- oder nutzungsabhängig. Bezugsgröße, Laufzeit, Mindestbeträge und zusätzliche Leistungen bestimmen die wirtschaftliche Wirkung. Der Gesamtumsatz des Nutzers ist nicht automatisch Umsatz des Rechtegebers.','corporate-03','business-models','rights','Royalties'),
 G('Franchising','Wirtschaftliches Modell, in dem ein Anbieter typischerweise Marke, Geschäftssystem und Unterstützung gegen Gebühren an eigenständige Betreiber weitergibt. Investitionen, Kosten, Kontrolle und Anreize verteilen sich auf beide Seiten; Systemumsatz und eigener Gebührenumsatz sind getrennt. Konkrete Rechte und Pflichten hängen von Vertrag und Rechtsraum ab.','corporate-03','business-models','rights','Franchisesystem'),
 G('Gross Merchandise Value','Nach einer offengelegten Konvention erfasstes Handels- oder Transaktionsvolumen, häufig auf einem Marktplatz. GMV ist weder automatisch eigener Umsatz noch Gewinn. Retouren, Steuern, Versand und abgebrochene Vorgänge können je nach Definition unterschiedlich behandelt werden. In der Portfoliotheorie steht GMV dagegen für das Global Minimum Variance Portfolio.','corporate-03','business-models','platforms','',[{label:'GMV',units:['business-models']}]),
 G('Take Rate','Anteil des Vermittlungs- oder Dienstumsatzes an einer ausdrücklich definierten Volumenbasis, häufig GMV. Im einfachen Provisionsmodell ist es der Gebührensatz. Zusatzdienste und abweichende Volumenabgrenzungen können die Kennzahl verändern; ein höheres Handelsvolumen garantiert bei sinkender Take Rate keinen höheren Gewinn.','corporate-03','business-models','platforms'),
 G('Netzwerkeffekt','Veränderung des Nutzens für Teilnehmer durch Anzahl, Qualität oder Aktivität anderer relevanter Teilnehmer. Direkte Effekte wirken innerhalb einer Gruppe, indirekte zwischen Gruppen. Mehr Teilnehmer können auch Überlastung oder Konkurrenz erzeugen. Kostensenkung durch größere Produktionsmenge ist für sich ein Skaleneffekt, kein Beweis eines Netzwerkeffekts.','corporate-03','business-models','networks','Network Effect|Netzwerkeffekte'),
 G('Multi-Homing','Gleichzeitige Nutzung mehrerer vergleichbarer Plattformen durch Teilnehmer. Geringe zusätzliche Kosten können Bindung und dauerhafte Gebührenmacht einer einzelnen Plattform begrenzen, ohne mögliche Netzwerkeffekte vollständig auszuschließen.','corporate-03','business-models','networks'),
 G('Cross-Selling','Verkauf weiterer Produkte oder Leistungen an vorhandene Kunden. Das kann Akquisitionskosten verteilen und Beiträge erhöhen, aber auch Rabatte, Betreuung und Kannibalisierung erzeugen. Entscheidend ist die zusätzliche Wirkung gegenüber realistischen Alternativen.','corporate-03','business-models','hybrids'),
 G('Kapitalstruktur','Zusammensetzung der Finanzierung eines Unternehmens aus Schulden, Eigenkapital und gegebenenfalls weiteren Ansprüchen wie Vorzugskapital. Quoten benötigen eine klare Markt- oder Buchwertbasis. Auch Fälligkeiten, Rang, Währung und vertragliche Rechte beeinflussen das Finanzierungsrisiko.','corporate-06','capital-structure','claims','Capital Structure'),
 G('Business Risk','Unsicherheit der operativen Leistung vor der Wirkung der Finanzierung, etwa durch Nachfrage, Preise, Wettbewerb und feste Betriebskosten. Zwei Firmen mit gleichem heutigen EBIT können bei einem Umsatzrückgang sehr unterschiedlich reagieren.','corporate-06','capital-structure','drivers','Geschäftsrisiko'),
 G('Financial Risk','Zusätzliches Risiko für Eigentümer aus vorrangigen festen Finanzierungsverpflichtungen. Ein unveränderter operativer Rückgang trifft nach Zins- und Rückzahlungsansprüchen auf einen kleineren residualen Eigenkapitaleinsatz. Mehr erwartete Eigenkapitalrendite beweist deshalb keine zusätzliche Wertschaffung.','corporate-06','capital-structure','leverage-earnings','Finanzierungsrisiko'),
 G('Weighted Average Cost of Capital','Gewichtete durchschnittliche Kapitalkosten aus passenden Markt- beziehungsweise Zielmarktwerten und zukunftsbezogenen Kosten der einzelnen Finanzierungsansprüche. Im einfachen Modell werden nur abzugsfähige Zinsen um den tatsächlich nutzbaren Unternehmenssteuervorteil bereinigt. WACC passt zu konsistent definiertem FCFF; er ist weder allein der Kreditpreis noch für jedes anders riskante Projekt automatisch geeignet.','corporate-06','capital-structure','wacc','WACC|gewichtete Kapitalkosten'),
 G('Eigenkapitalkosten','Für das übernommene Risiko geforderte erwartete Gesamtrendite der Eigentümer, einschließlich Ausschüttungen und erwarteter Wertänderung. Sie sind Opportunitätskosten und bestehen auch bei einbehaltenen Gewinnen oder ausbleibender Dividende. CAPM und Dividendenmodelle schätzen sie unter unterschiedlichen Annahmen.','equity-06','capital-structure','equity-cost','Cost of Equity'),
 G('Fremdkapitalkosten','Heutige Kosten einer zur betrachteten Finanzierung passenden Verschuldung. Sie hängen unter anderem von Laufzeit, Währung, Rang und Bonität ab. Historischer Kupon und aktuelle Rendite sind nicht identisch; bei Ausfallrisiko ist zudem versprochene YTM von erwarteter Rendite zu trennen. Eine Nachsteuerangabe enthält einen ausdrücklich begründeten Zinssteuervorteil.','corporate-06','capital-structure','debt-cost','Cost of Debt'),
 G('Vorzugsaktie','Aktie mit bevorzugten Ausschüttungs- oder Liquidationsrechten gegenüber Stammaktien gemäß den konkreten Bedingungen. Sie steht gewöhnlich hinter Schulden und kann kumulative Zahlungen, zusätzliche Teilnahme, besondere Stimm-, Rückkauf- oder Wandlungsrechte besitzen. Bezugsbetrag, laufende Dividende und Marktwert sind getrennt. Der gewöhnliche Zinssteuerfaktor gilt nicht automatisch für Dividenden.','equity-01','equity-features','preferred','Preferred Stock|Preference Shares|Vorzugsaktien|Vorzugskapital'),
 G('Gordon-Growth-Modell','Dividendenbewertung mit dauerhaft konstanter Wachstumsrate unterhalb der Eigenkapitalkosten. Der Preis entspricht der nächsten erwarteten Dividende geteilt durch Renditeforderung minus Wachstum. Umgestellt sind die Eigenkapitalkosten nächste Dividendenrendite plus Wachstum. Unbeständiges Wachstum oder unpassende Ausschüttungen begrenzen die Anwendung.','equity-08','capital-structure','equity-cost','Gordon-Modell|Gordon'),
 G('Target Capital Structure','Angestrebte Finanzierungsmischung, häufig als Bandbreite von Marktwertanteilen. Sie ist von der aktuellen beobachteten Struktur und einem modelltheoretischen Wertmaximum zu unterscheiden. Umsetzungskosten, Reserven und Refinanzierungsbedarf können begründen, kleine Abweichungen vorübergehend zu akzeptieren.','corporate-07','capital-structure','target','Zielkapitalstruktur|Zielstruktur'),
 G('Optimale Kapitalstruktur','Finanzierungsmischung, die unter den betrachteten vollständigen Annahmen den Unternehmenswert maximiert. Bei konstanten bewerteten operativen Cashflows entspricht dies der Minimierung des passenden WACC. Ändert Finanzierung auch Cashflows, müssen diese Wirkungen ausdrücklich berücksichtigt werden. Eine beobachtete Branchenquote beweist kein individuelles Optimum.','corporate-07','capital-structure','tradeoff','Optimal Capital Structure'),
 G('Modigliani-Miller-Theorem','Zusammenhang zwischen Kapitalstruktur, Wert und Renditeforderungen unter ausdrücklich idealisierten Bedingungen. Ohne Steuern und weitere Friktionen verändert die reine Aufteilung identischer operativer Zahlungen den Gesamtwert nicht; Eigenkapitalkosten passen sich dem Hebel an. Mit Unternehmenssteuern kann ein nutzbarer Zinssteuervorteil Wert schaffen. Diese Modellfälle sind keine Behauptung, reale Finanzierung sei stets irrelevant.','corporate-07','capital-structure','mm-assumptions','Modigliani-Miller|MM-Theorem'),
 G('Homemade Leverage','Vom Anleger selbst hergestellter Finanzierungshebel durch Kreditaufnahme zusätzlich zu einem unverschuldeten Anspruch. Bei gleichen Kreditbedingungen, fehlenden Friktionen und passender Zustandsabdeckung können dadurch die Zahlungen verschuldeten Eigenkapitals nachgebildet werden. Gleichheit bloßer Erwartungswerte reicht für die Replikation nicht.','corporate-07','capital-structure','replication'),
 G('MM Proposition I','Modigliani–Miller-Aussage zum Gesamtwert: Ohne Steuern und weitere relevante Friktionen besitzen sonst identische Firmen unabhängig von der Finanzierung denselben Wert. Im speziellen Modell ewiger konstanter Schulden mit vollständig nutzbarem Unternehmenssteuervorteil kommt zum unverschuldeten Wert der Steuerbarwert hinzu. Die jeweils verwendete Modellwelt muss genannt werden.','corporate-07','capital-structure','mm-assumptions','MM Proposition 1'),
 G('MM Proposition II','Modigliani–Miller-Zusammenhang zwischen Eigenkapitalkosten, unverschuldeten Kapitalkosten und Finanzierungshebel. Im Modell ohne Steuern erhöht die Differenz zwischen unverschuldeten und Fremdkapitalkosten, multipliziert mit Markt-D/E, die Eigenkapitalkosten. Das entsprechende Unternehmenssteuermodell verändert diesen Hebelbeitrag um den Steuerfaktor.','corporate-07','capital-structure','mm-no-tax','MM Proposition 2'),
 G('Zinssteuervorteil','Verminderung tatsächlich zu zahlender Unternehmenssteuer durch abzugsfähige Zinsen. Die jährliche Steuerersparnis ist eine Zahlung; ihr Barwert bewertet eine ganze zeitliche Folge. Steuersatz mal Schulden als Barwert setzt besondere Bedingungen wie dauerhaft konstante Schulden, Nutzbarkeit und eine passende Diskontierung voraus.','corporate-06','capital-structure','tax-shield','Interest Tax Shield'),
 G('Adjusted Present Value','Bewertungsansatz, der den Wert eines Geschäfts ohne die betrachteten Finanzierungseffekte und den Barwert dieser Effekte getrennt berechnet. Dazu können Steuerersparnisse, Emissions- oder Krisenkosten gehören. Das Verfahren kann veränderliche Schuldenpläne verdeutlichen; bereits in Cashflows oder Diskontsätzen erfasste Wirkungen dürfen nicht erneut addiert oder abgezogen werden.','corporate-07','capital-structure','finite-shield','APV'),
 G('Financial Distress','Finanzielle Schwierigkeiten bei der Erfüllung von Verpflichtungen. Direkte Kosten wie zusätzliche Rechtsberatung und indirekte Kosten wie Kundenverluste können Wert vernichten; indirekte Schäden sind bereits vor förmlicher Insolvenz möglich. Ein reiner Verlust eines Anspruchs durch Umverteilung ist nicht automatisch in gleicher Höhe ein Ressourcenverlust des Unternehmens.','corporate-07','capital-structure','distress','finanzielle Schwierigkeiten'),
 G('Trade-off-Theorie','Erklärung der Kapitalstruktur durch Abwägung zusätzlicher Finanzierungsnutzen und -kosten, insbesondere nutzbarer Zinssteuerersparnisse gegenüber Krisenkosten. An einem inneren glatten Wertmaximum gleichen sich marginale Nutzen und Kosten aus; ihre gesamten Barwerte müssen nicht gleich groß sein.','corporate-07','capital-structure','tradeoff','Trade-off Theory'),
 G('Pecking-Order-Theorie','Finanzierungserklärung mit einer typischen Präferenz für interne Mittel, danach Schulden und zuletzt neue externe Stammaktien, unter anderem wegen asymmetrischer Information und damit verbundener Emissionsnachteile. Interne Mittel bleiben wirtschaftlich kostenpflichtiges Eigenkapital; die Rangfolge ist keine universelle Handlungsvorschrift.','corporate-07','capital-structure','pecking-order','Pecking Order|Pecking-order Theory'),
 G('Finanzielle Flexibilität','Fähigkeit, unerwartete Belastungen und zukünftige Investitionsmöglichkeiten mit verfügbaren Mitteln oder belastbaren Finanzierungszugängen zu bewältigen. Ungenutzte Schuldenkapazität und Reserven können deshalb wertvoll sein. Ihr Nutzen ist gegen Bereitstellungskosten und mögliche Fehlanreize abzuwägen.','corporate-07','capital-structure','pecking-order','Financial Flexibility'),
 G('Asset-Beta','Marktrisikosensitivität des operativen Geschäfts vor der Wirkung der gewählten Verschuldung. Das aus einem Aktienbeta abgeleitete unverschuldete Beta hängt von Annahmen über Schuldenrisiko, Steuern und Finanzierungsregel ab. Es ist nicht allgemein identisch mit dem beobachteten Aktienbeta und misst nicht das gesamte Geschäftsrisiko.','equity-06','capital-structure','beta','Asset-Betas|unlevered Beta|unverschuldetes Beta'),
 G('Unlevering','Herausrechnen des Finanzierungshebels aus einem Eigenkapital-Risikomaß, etwa Beta, unter ausdrücklich gewählten Steuer- und Schuldenannahmen. Damit können operativ vergleichbare Firmen trotz unterschiedlicher Verschuldung untersucht werden.','corporate-06','capital-structure','beta'),
 G('Relevering','Übertragen eines unverschuldeten Geschäfts-Risikomaßes in eine neue Kapitalstruktur. Bei Beta wird dafür ein zur Zielverschuldung, Steuerwelt und Schuldenrisiko passender Hebelfaktor verwendet. Ein bereits verschuldetes Vergleichs-Beta darf nicht ohne vorherige Bereinigung nochmals vollständig gehebelt werden.','corporate-06','capital-structure','beta'),
 G('Kapitalallokation','Entscheidung über Einsatz und Rückführung finanzieller Ressourcen anhand erwarteter Wertbeiträge, Risiken, Pflichten und realer Grenzen. Sie umfasst Projektvergleich, Umsetzung und spätere Nachprüfung. Die höchste prozentuale Rendite ist nicht automatisch der größte Wertbeitrag.','corporate-04','capital-allocation','process','Capital Allocation'),
 G('Net Present Value','Kapitalwert: Summe aller zusätzlichen Zahlungen, auf denselben heutigen Zeitpunkt mit einer passenden Renditeforderung abgezinst, einschließlich der negativen Anfangszahlung. Ein positiver NPV bedeutet im vollständig spezifizierten Modell Mehrwert nach Vergütung von Zeit und Risiko. Er ist ein heutiger Geldbetrag, kein jährlicher Gewinn und keine Renditequote.','corporate-04','capital-allocation','npv','NPV|Kapitalwert'),
 G('Internal Rate of Return','Interner Zinsfuß: Rate je Zahlungsperiode, bei der die gegebene Zahlungsreihe Kapitalwert null besitzt. Bei einer anfänglichen Auszahlung und danach positiven Rückflüssen ist die übliche Vergleichsregel mit der Renditeforderung anwendbar. Spätere Vorzeichenwechsel können mehrere Lösungen erzeugen; Projektgröße und Zeitstruktur begrenzen eine Rangliste nur nach IRR.','corporate-04','capital-allocation','irr','IRR|interner Zinsfuß'),
 G('Return on Invested Capital','Operativer Nachsteuergewinn relativ zum passend definierten investierten Kapital, häufig mit einem Periodendurchschnitt im Nenner. ROIC ist typischerweise eine unternehmensweite Buchkapitalrendite, keine direkt aus dem heutigen Aktienpreis ableitbare Anlegerrendite. Cash-, Goodwill-, Leasing- und Periodenkonventionen müssen vor Vergleichen angeglichen werden.','equity-04','capital-allocation','roic','ROIC'),
 G('NOPAT','Net Operating Profit After Tax: operatives Nachsteuerergebnis vor Finanzierungsaufwand. Bei einfacher sofort nutzbarer proportionaler Besteuerung entspricht es EBIT mal eins minus operativem Steuersatz. Es ist weder EBITDA noch automatisch operativer Cashflow; nicht zahlungswirksame Posten und Reinvestitionen benötigen eigene Überleitungen.','corporate-04','capital-allocation','cashflow-bridge','Net Operating Profit After Tax'),
 G('Invested Capital','Das für eine Kapitalrendite zugrunde gelegte investierte Kapital. Eine einfache Finanzierungsdefinition umfasst verzinsliche Schulden plus Buch-Eigenkapital; operative Varianten bereinigen etwa nicht benötigte Liquidität. Ergebniszähler, Bestand, Zeitraum und Anpassungen müssen dieselbe wirtschaftliche Abgrenzung verwenden.','corporate-04','capital-allocation','roic','investiertes Kapital'),
 G('Hurdle Rate','Mindestrendite beziehungsweise Renditehürde im jeweiligen Kontext. In der Projektbewertung ist sie die passende Renditeforderung unter Berücksichtigung von Risiko und Zahlungsabgrenzung. In Private-Markets-Verträgen kann sie eine Vorzugsrendite vor bestimmter Carry-Verteilung bezeichnen. Die Vertrags- oder Modellbedeutung muss ausdrücklich festgestellt werden.','alternatives-02','capital-allocation','discount-consistency','Hurdle|Vorzugsrendite'),
 G('Inkrementeller Cashflow','Zusätzlicher Zahlungsstrom als Differenz zwischen einer realistischen Situation mit und ohne betrachtete Entscheidung. Er umfasst auch Opportunitätskosten und Auswirkungen auf andere Unternehmensbereiche. Bereits nicht mehr rückholbare Ausgaben verändern die heutige Entscheidungsdifferenz nicht.','corporate-04','capital-allocation','incremental','Incremental Cash Flow|Incremental Cashflow'),
 G('Kannibalisierung','Verdrängung eigener bestehender Umsätze oder Beiträge durch ein neues Angebot. Für die Investitionsrechnung zählt die zusätzliche Wirkung gegenüber dem realistischen Fall ohne Projekt, einschließlich möglicher Verdrängung durch Wettbewerber. Verlorener Umsatz ist nicht automatisch gleich verlorener Deckungsbeitrag.','corporate-04','capital-allocation','incremental','Cannibalization'),
 G('Post-Audit','Nachprüfung einer umgesetzten Investition anhand dokumentierter Annahmen, tatsächlicher Ergebnisse und Ausführung. Sie trennt steuerbare Umsetzung, Prognosequalität und erst später bekannt gewordene Umstände. Ein einzelner Verlust beweist noch keine schlechte ursprüngliche Entscheidung.','corporate-04','capital-allocation','process'),
 G('Independent Projects','Projekte, die unter den angegebenen Bedingungen gemeinsam umgesetzt werden können, ohne einander auszuschließen oder ihre relevanten Zahlungswirkungen zu verändern. Bei fehlenden bindenden Ressourcenbeschränkungen können mehrere Projekte mit positivem NPV angenommen werden.','corporate-04','capital-allocation','process','unabhängige Projekte'),
 G('Mutually Exclusive Projects','Investitionsalternativen, die sich gegenseitig ausschließen, beispielsweise unterschiedliche Maschinen für denselben einzigen Standort. Unter vergleichbaren vollständigen Bewertungsannahmen wird der höchste Kapitalwert bevorzugt; die höchste IRR allein kann wegen Umfang oder Zeitstruktur irreführen.','corporate-04','capital-allocation','process'),
 G('Complementary Projects','Projekte, deren gemeinsame Umsetzung positive Wechselwirkungen erzeugt. Ihre kombinierte Zahlungskette kann deshalb mehr wert sein als die Summe isoliert geschätzter Projekte. Synergien müssen realistisch zusätzlich sein und dürfen nicht mehrfach gezählt werden.','corporate-04','capital-allocation','process'),
 G('Crossover Rate','Diskontsatz, bei dem zwei Projektkapitalwerte übereinstimmen. Er lässt sich aus dem Kapitalwert der Differenzzahlungsreihe bestimmen. Er ist vom internen Zinsfuß eines einzelnen Projekts zu unterscheiden; mehrere oder fehlende Schnittpunkte sind je nach Zahlungsstruktur möglich.','corporate-04','capital-allocation','timing','Kreuzungssatz'),
 G('Kapitalrationierung','Bindende Begrenzung des verfügbaren Investitionsbudgets, durch die nicht alle vorteilhaften Projekte umgesetzt werden können. Die wertmaximierende zulässige Kombination hängt von Teilbarkeit, Abhängigkeiten und weiteren Restriktionen ab. Eine einfache Rangliste einzelner Kennzahlen kann deshalb scheitern.','corporate-04','capital-allocation','rationing','Capital Rationing'),
 G('Profitability Index','In der hier verwendeten Definition Barwert späterer positiver Zuflüsse geteilt durch die positive Anfangsausgabe. Er entspricht bei dieser Zahlungsstruktur eins plus NPV geteilt durch Anfangsausgabe. Als Rangmaß unter Knappheit sind insbesondere Teilbarkeit und Projektabhängigkeiten zu beachten; andernorts verwendete Nettoquoten benötigen eine Definitionsprüfung.','corporate-04','capital-allocation','rationing','PI'),
 G('Realoption','Konkretes wirtschaftliches Recht, eine spätere Projektentscheidung nach neuer Information anzupassen, etwa abwarten, erweitern, umstellen oder abbrechen. Zugang, Ausübungskosten, Informationszeitpunkt und Risikobewertung bestimmen den Wert. Bereits im Basiszahlungsplan enthaltene Flexibilität darf nicht erneut als Aufschlag addiert werden.','corporate-05','capital-allocation','options-map','Real Option|Realoptionen'),
 G('Erweiterungsoption','Recht, zusätzliche Kapazität oder ein weiteres Projekt bei günstigen späteren Bedingungen zu realisieren. Bewertet wird der zusätzliche Nutzen nach der dann nötigen Ausgabe, abzüglich gesonderter heutiger Vorbereitungskosten. Finanzierung und tatsächlicher Zugang müssen gesichert beziehungsweise angemessen berücksichtigt sein.','corporate-05','capital-allocation','expand-abandon','Expansion Option'),
 G('Abbruchrecht','Möglichkeit, ein Projekt später zu beenden und einen Nettoverwertungswert statt des Fortführungswerts zu erhalten. Der Zusatznutzen ist die Verbesserung gegenüber der jeweils aufgegebenen Fortführung, nicht der volle Verkaufserlös zusätzlich zu ihr. Abwicklungs- und Bereitstellungskosten sind relevant.','corporate-05','capital-allocation','expand-abandon','Abbruchoption|Abandonment Option'),
 G('Working Capital','Der Begriff braucht eine ausdrückliche Abgrenzung. Bilanzielles Net Working Capital ist kurzfristiges Vermögen minus kurzfristige Verbindlichkeiten, einschließlich kurzfristiger Kasse und Finanzschulden. Operatives Working Capital grenzt dagegen die im Betrieb gebundenen Posten ab; hier Vorräte plus Kundenforderungen minus Lieferantenverbindlichkeiten. Ein positiver Bestand garantiert keine jederzeitige Zahlungsfähigkeit.','corporate-08','working-capital','definitions','Nettoumlaufvermögen|NWC|Net Working Capital'),
 G('Operatives Working Capital','Operative Kapitalbindung in ausdrücklich gewählter Abgrenzung. Im Kapitel Working Capital: Vorräte plus Forderungen aus Lieferungen und Leistungen minus Lieferantenverbindlichkeiten. Überschüssige Kasse und verzinsliche Kredite sind hier ausgeschlossen. Andere Modelle ergänzen weitere operative Posten; Bestände und Veränderungen dürfen nicht verwechselt werden.','corporate-08','working-capital','definitions','Operating Working Capital|OWC'),
 G('Liquiditätsplan','Zeitlich gegliederte Planung verfügbarer Anfangsmittel, Einzahlungen, Auszahlungen und Finanzierung. Er zeigt zwischenzeitliche Fehlbeträge und den höchsten benötigten Kreditrahmen, die in einer Jahressumme verborgen bleiben können. Verfügbarkeit, Fristen und Stressannahmen sind Teil der Planung.','corporate-08','working-capital','cash-budget','Cash Budget|Liquiditätsplanung'),
 G('Overtrading','Ausweitung des Geschäfts über die Tragfähigkeit der verfügbaren Finanzierungsressourcen hinaus. Bei positiver operativer Kapitalbindung kann auch profitables Umsatzwachstum zusätzliche Mittel benötigen. Unveränderte Tageskennzahlen verhindern dann nicht einen höheren Bedarf in Euro.','corporate-08','working-capital','sensitivity'),
 G('Window Dressing','Gestaltung von Stichtagswerten, um einen günstigeren Eindruck zu erzeugen. Beispielsweise kann die Tilgung kurzfristiger Schulden mit Kasse eine Current Ratio über eins weiter erhöhen, während zugleich weniger Geld verfügbar ist. Ein einzelner Geschäftsvorfall ist nicht automatisch problematisch; entscheidend sind Substanz, Transparenz und Schlussfolgerung.','corporate-08','working-capital','ratio-traps'),
 G('Drag on Liquidity','Belastung der Liquidität durch verzögerte oder ausbleibende Zuflüsse, etwa langsameren Forderungseinzug oder länger gebundene Vorräte. Die Finanzierungslücke kann wachsen, obwohl sich der eigene Zahlungstermin nicht ändert. Davon wird ein Pull durch vorgezogene Abflüsse unterschieden.','corporate-08','working-capital','sources-drags','Drags on Liquidity'),
 G('Pull on Liquidity','Belastung der Liquidität durch vorgezogene oder zusätzlich erforderliche Abflüsse, etwa verkürzte Lieferantenzahlungsfristen. Weniger Lieferantenfinanzierung verlängert bei gleichen übrigen Komponenten den Cash Conversion Cycle. Der konkrete Zahlungsmechanismus ist zu erklären.','corporate-08','working-capital','sources-drags','Pulls on Liquidity'),
 G('Just-in-Time','Abstimmung von Beschaffung oder Produktion möglichst nahe am tatsächlichen Verbrauch. Sie kann Lagerbindung senken, verlangt aber verlässliche Abläufe und kann bei knappen Reserven die Störanfälligkeit erhöhen. Ein niedriger Vorratsbestand ist deshalb kein vollständiger Qualitätsmaßstab.','corporate-08','working-capital','inventory-policy','JIT'),
 G('Sicherheitsbestand','Zusätzlicher Vorratspuffer gegen unerwartete Nachfrage, Lieferverzögerung oder andere Unsicherheit. Er bindet Kapital und verursacht gegebenenfalls Lagerkosten, kann aber Fehlbestände und Produktionsausfälle begrenzen. Seine Höhe ist eine wirtschaftliche Abwägung.','corporate-08','working-capital','inventory-policy','Safety Stock'),
 G('Altersstrukturanalyse','Aufteilung ausstehender Forderungen nach Alter beziehungsweise überfälliger Dauer. Sie kann problematische alte Positionen sichtbar machen, die eine durchschnittliche Forderungslaufzeit verdeckt. Hoher Forderungsbestand, langsamer Einzug und Ausfallrisiko sind verwandte, aber nicht identische Sachverhalte.','corporate-08','working-capital','credit-policy','Aging Schedule'),
 G('Skonto','Preisabzug bei Zahlung innerhalb einer festgelegten kurzen Frist. Ein Verzicht verschafft zusätzlichen Zahlungsaufschub, kostet aber den Rabatt relativ zum sonst zu zahlenden rabattierten Betrag. Einfache Annualisierung und effektive Jahresrate unterscheiden sich; Gebühren und alternative Finanzierung sind ebenfalls zu prüfen.','corporate-08','working-capital','trade-discount','Cash Discount|Settlement Discount'),
 G('Factoring','Übertragung von Forderungen an einen Finanzierer, häufig mit Vorschuss, Einzug und je nach Vertrag Schutz gegen definierte Kreditverluste. Vorschussquote, Gebühren, Zins, Restzahlung und Rückgriff bestimmen Nutzen und Kosten. Der volle Forderungsnennbetrag ist nicht automatisch sofort verfügbar.','corporate-08','working-capital','factoring'),
 G('Invoice Discounting','Finanzierung gegen Forderungen, bei der Betreuung oder Einzug häufig stärker beim Unternehmen verbleiben als beim klassischen Factoring. Genaue Rechte, Rückgriff, Sicherheiten und Kosten hängen vom Vertrag ab. Die Produktbezeichnung allein klärt weder Risikoübertragung noch Bilanzierung.','corporate-08','working-capital','factoring'),
 G('Rückgriff','Vertragliche Möglichkeit, den Forderungsverkäufer für bestimmte Nichtzahlungen in Anspruch zu nehmen. Ohne Rückgriff kann Schutz gegen definierte Kreditrisiken bestehen, während Leistungsstreit, Garantien oder andere Ausschlüsse dennoch beim Verkäufer verbleiben. Umfang und Durchsetzbarkeit richten sich nach dem Vertrag.','corporate-08','working-capital','factoring','Recourse'),
 G('Commercial Paper','Kurzfristige handelbare Schuldverschreibung, typischerweise von Emittenten mit geeignetem Kapitalmarktzugang. Sie kann kurzfristigen Bedarf finanzieren, erzeugt aber bei fortbestehendem Bedarf ein Refinanzierungsrisiko. Fälligkeit und künftiger Marktzugang sind von einem aktuellen günstigen Zinssatz zu trennen.','corporate-08','working-capital','funding-cost'),
 G('Compensating Balance','Im Zusammenhang mit einer Finanzierung verlangtes Guthaben, das dem Kreditnehmer je nach Vertrag nicht frei zur Verfügung steht. Ein unverzinslich gebundener Betrag vermindert die nutzbaren Mittel und kann die effektive Finanzierungslast erhöhen. Freigabetermin, Verzinsung und tatsächliche Nutzbarkeit bestimmen den Effekt.','corporate-08','working-capital','funding-cost','Mindestguthaben'),
 G('Permanent Working Capital','Dauerhaft benötigter Sockel operativer Kapitalbindung. Einzelne Waren oder Forderungen können rasch ausgetauscht werden, während der Gesamtbedarf bestehen bleibt. Die Finanzierungslaufzeit sollte deshalb nicht allein aus der Lebensdauer eines einzelnen Postens abgeleitet werden.','corporate-08','working-capital','policy'),
 G('Seasonal Working Capital','Vorübergehende zusätzliche operative Kapitalbindung aufgrund saisonaler Geschäftsspitzen. Sie ist vom dauerhaften Sockel zu trennen. Höhe, Zeitpunkt und Rückbildung bestimmen den passenden Finanzierungsbedarf; Jahresdurchschnitte können die Spitze verdecken.','corporate-08','working-capital','policy'),
 G('Corporate Governance','System der Zuständigkeiten, Information, Anreize, Kontrolle und Rechenschaft bei Unternehmensentscheidungen. Es soll delegierte Aufgaben und Interessengegensätze angemessen steuern. Formale Organstruktur oder viele Richtlinien allein beweisen keine tatsächliche Wirksamkeit.','corporate-02','governance','delegation','Unternehmensführung'),
 G('Prinzipal','Auftraggeber einer delegierten Aufgabe. Er überträgt dem Agenten Entscheidungs- oder Handlungsspielraum und benötigt geeignete Informationen sowie Kontrollmöglichkeiten. Welche Pflichten gelten, hängt von Rolle, Mandat und rechtlichem Rahmen ab.','corporate-02','governance','delegation','Principal'),
 G('Agent','Beauftragter, der für einen Prinzipal eine Aufgabe übernimmt. Eigene Ziele und Informationsvorsprünge können Konflikte erzeugen, ohne dass jede Delegation automatisch Fehlverhalten bedeutet. Auch ein Aufsichtsgremium kann selbst Teil einer Delegationskette sein.','corporate-02','governance','delegation'),
 G('Principal-Agent-Problem','Problem delegierter Entscheidungen bei abweichenden Interessen und begrenzter Beobachtbarkeit oder Kontrolle. Eine schlechte Realisierung allein beweist keine Pflichtverletzung; Handlungsqualität, Information und Ergebnis sind getrennt zu prüfen.','corporate-02','governance','delegation','Principal-Agent|Agency-Problem'),
 G('Agency-Konflikt','Interessengegensatz in einer Delegationsbeziehung, etwa wenn Management private Vorteile zulasten der Eigentümer bevorzugt. Er bezeichnet den Konflikt selbst; Überwachung, Bindung und verbleibender Nachteil bilden dagegen die gesonderten Agency-Kosten.','corporate-02','governance','conflict-map','Agency Conflict'),
 G('Agency-Kosten','Wirtschaftliche Kosten einer Delegationsbeziehung mit Interessengegensätzen. Klassisch umfassen sie Monitoring-Aufwand, Bonding-Aufwand und den trotz Gegenmaßnahmen verbleibenden Verlust. Sie sind nicht identisch mit dem zugrunde liegenden Agency-Konflikt.','corporate-02','governance','agency-costs','Agency Costs'),
 G('Monitoring','Überwachung delegierter Entscheidungen oder ihrer Ergebnisse. Sie benötigt Ressourcen und geeignete Informationen. Mehr Überwachung kann den verbleibenden Schaden senken, muss aber nach tatsächlichem Nutzen, Kosten und geltenden Pflichten beurteilt werden.','corporate-02','governance','agency-costs'),
 G('Bonding','Im Agency-Modell die glaubwürdige Bindung oder Zusicherung eines Agenten, durch die Interessen angenähert werden sollen. Ihre Kosten gehören zu den Agency-Kosten. Der Begriff bezeichnet in diesem Zusammenhang keine Anleihe.','corporate-02','governance','agency-costs'),
 G('Residual Loss','Im Agency-Modell der trotz Überwachungs- und Bindungsmaßnahmen verbleibende wirtschaftliche Nachteil gegenüber der konfliktfreien Vergleichssituation. Er ist von einem Residualanspruch des Eigenkapitals und von statistischen Residuen zu unterscheiden.','corporate-02','governance','agency-costs'),
 G('Board of Directors','Zentrales Leitungs- und Aufsichtsgremium im jeweiligen Governance-System. Es überwacht wesentliche Entscheidungen und die Geschäftsführung; genaue Zuständigkeiten hängen von der Organstruktur und den geltenden Regeln ab. Unabhängigkeit, Kompetenz und Informationszugang bestimmen die tatsächliche Wirkung.','corporate-02','governance','board-structure','Board'),
 G('Audit Committee','Ausschuss, der typischerweise Berichterstattung, Abschlussprüfung und relevante interne Kontrollen überwacht. Er ersetzt weder die operative Verantwortung des Managements noch die Verantwortung des gesamten Boards. Aufgaben und Besetzung folgen dem jeweiligen Rahmen.','corporate-02','governance','committees','Prüfungsausschuss'),
 G('Remuneration Committee','Ausschuss zur Beurteilung und Gestaltung der Vergütung und ihrer Anreize. Er soll insbesondere Interessenkonflikte bei der Bezahlung von Führung und Organmitgliedern begrenzen; seine Wirksamkeit hängt von Unabhängigkeit, Kompetenz und Mandat ab.','corporate-02','governance','committees','Vergütungsausschuss'),
 G('Nomination Committee','Ausschuss, der passende Kandidaten, Zusammensetzung und Nachfolge für Unternehmensorgane vorbereitet. Transparente Auswahlkriterien und die tatsächlich benötigten Fähigkeiten sind wichtiger als die bloße Existenz eines Ausschussnamens.','corporate-02','governance','committees','Nominierungsausschuss'),
 G('Malus','Mechanismus, der noch nicht endgültig ausgezahlte oder unverfallbare variable Vergütung unter bestimmten Bedingungen vermindern kann. Er ist von der Rückforderung bereits gezahlter Vergütung durch Clawback zu unterscheiden. Auslöser und Durchsetzbarkeit hängen von den maßgeblichen Regeln ab.','corporate-02','governance','bonus-horizon'),
 G('Clawback','Rückforderung zuvor gezahlter Vergütung bei Eintritt festgelegter Voraussetzungen. Bei Führungskräften können etwa fehlerhafte Erfolgszahlen relevant sein; bei Private-Equity-Fonds kann es um zu viel gezahlten Carry gehen. Der konkrete Vertrag und rechtliche Rahmen bestimmen Umfang und Durchsetzbarkeit.','path-private-04','governance','bonus-horizon','Clawbacks'),
 G('Related-Party-Geschäft','Transaktion mit einer nahestehenden Person oder Einheit, etwa aufgrund von Kontrolle oder Schlüsselstellung. Die Beziehung schafft Prüfbedarf, macht ein Geschäft aber nicht automatisch unangemessen. Offenlegung ersetzt keine Prüfung von Preis, Verfahren und Interessenkonflikten.','corporate-02','governance','minority-protection','Related Party Transaction'),
 G('Proxy Voting','Stimmabgabe über einen bevollmächtigten Vertreter beziehungsweise ein entsprechendes Vertretungsverfahren. Es ermöglicht die Nutzung von Eigentümerrechten ohne eigene physische Teilnahme. Regeln, Vollmacht und Information sind zu beachten; es ist kein Verkauf der Aktien.','corporate-02','governance','shareholder-rights'),
 G('Cumulative Voting','Wahlverfahren, bei dem Stimmen aus mehreren gleichzeitig zu besetzenden Sitzen auf einzelne Kandidaten konzentriert werden können. Es kann den Vertretungseinfluss einer Minderheit erhöhen. Ein konkretes Ergebnis hängt von Aktienzahl, Sitzanzahl, Teilnahme und Wahlregeln ab.','corporate-02','governance','shareholder-rights','kumulatives Wahlrecht'),
 G('Staggered Board','Board mit zeitlich gestaffelter Wahl oder Erneuerung von Mandaten. Dies kann Kontinuität fördern und zugleich einen schnellen Austausch erschweren. Ob der Mechanismus nützlich oder schädlich wirkt, hängt vom konkreten Kontext ab.','corporate-02','governance','shareholder-rights'),
 G('Interne Revision','Unabhängige und objektive Prüfung und Beratung innerhalb einer Organisation zur Beurteilung von Governance, Risikomanagement und Kontrollen. Geeigneter Berichtskanal, Kompetenz und Ressourcen sind nötig; operative Eigenverantwortung kann die spätere unabhängige Prüfung derselben Tätigkeit beeinträchtigen.','corporate-02','governance','reporting-controls','Internal Audit'),
 G('Management Override','Umgehung oder Übersteuerung vorgesehener Kontrollen durch die Leitung. Eine formal vorhandene Kontrolle kann dadurch unwirksam werden. Unabhängige Prüfung, nachvollziehbare Ausnahmen und Eskalation helfen, solche Risiken zu beurteilen.','corporate-02','governance','reporting-controls'),
 G('Whistleblowing','Meldung möglicher erheblicher Missstände über geeignete Wege. Ein wirksames Verfahren benötigt angemessene Vertraulichkeit, Untersuchung und Schutz vor unzulässigen Nachteilen. Eine Meldung ist noch kein abschließender Beweis; ihre geringe Anzahl kann auch fehlendes Vertrauen widerspiegeln.','corporate-02','governance','other-mechanisms'),
 G('Stakeholder','Person oder Gruppe, die ein Unternehmen beeinflusst oder von ihm betroffen ist. Im weiten hier verwendeten Sinn zählen auch Aktionäre und Gläubiger dazu. Dieselbe Person kann mehrere Rollen haben; deren Zahlungsansprüche, Ziele und Risiken sind getrennt zu beurteilen.','corporate-02','stakeholders','stakeholder-map','Stakeholdern|Anspruchsgruppe'),
 G('Residualanspruch','Anspruch auf das, was nach Erfüllung vorrangiger Verpflichtungen verbleibt. Bei gewöhnlichen Stammaktien kann dieser Rest null sein; er steigt bei weiterem Erfolg, ohne dass im Grundmodell eine feste Obergrenze versprochen wird. Nicht mit einer garantierten Restzahlung verwechseln.','corporate-01','stakeholders','waterfall','Residual Claim'),
 G('Seniorität','Vertraglich oder rechtlich bestimmter Vorrang eines Anspruchs gegenüber einem anderen. Rang, besicherter Vermögenswert und schuldender Rechtsträger sind getrennt zu prüfen. Eine vorrangige Forderung kann bei zu wenigen verfügbaren Mitteln trotzdem ausfallen.','bonds-10','stakeholders','seniority','Seniority'),
 G('Nachrang','Stellung eines Anspruchs hinter bestimmten anderen Ansprüchen in der maßgeblichen Zahlungsreihenfolge. Bei Knappheit kann die nachrangige Klasse deshalb bereits Verluste tragen, obwohl die vorrangige noch vollständig bezahlt wird.','bonds-10','stakeholders','seniority','Subordination'),
 G('Recovery Rate','Anteil des relevanten Forderungsbetrags, der im Ausfall zurückgewonnen wird. Rang, Sicherheiten, Kosten, Zeitpunkte und Forderungsbasis beeinflussen die Quote; eine durchschnittliche Gesamtdeckung ist nicht automatisch die Recovery jeder einzelnen Klasse.','bonds-10','stakeholders','seniority','Recovery|Rückgewinnungsquote'),
 G('Asset Substitution','Ersetzung einer vorhandenen Strategie oder Anlage durch eine riskantere nach Kreditvergabe. Bei unveränderter alter Schuld können Aktionäre wegen ihres nach unten begrenzten Residualanspruchs profitieren, während Gläubiger zusätzliche Verluste tragen. Der Effekt schafft nicht zwingend neuen Gesamtwert.','corporate-02','stakeholders','risk-shifting','Risk Shifting'),
 G('Debt Overhang','Unterinvestitionsproblem bei hoher bestehender Schuld: Ein Teil des Nutzens eines neuen guten Projekts verbessert die Deckung alter Gläubiger. Müssen Aktionäre den neuen Einsatz allein tragen, kann ihr eigener Nutzen darunter liegen, obwohl das Gesamtprojekt einen positiven Kapitalwert hat.','corporate-06','stakeholders','debt-overhang','Schuldenüberhang'),
 G('Negative Externalität','Kosten einer Tätigkeit, die andere tragen und die der Verursacher nicht vollständig in seiner privaten Rechnung berücksichtigt. Spätere Regeln, Haftung oder Marktreaktionen können einen Teil finanziell auf ihn zurückwirken lassen; externe Wirkung und heutige Unternehmensbelastung sind dennoch getrennte Größen.','economics-01','stakeholders','tradeoffs','negative Externalitäten'),
 G('Shareholder Theory','Ansatz der Unternehmensführung, der die Eigentümerperspektive in den Mittelpunkt stellt. Langfristige Wertschaffung kann verlässliche Beziehungen zu anderen Beteiligten erfordern. Der Ansatz rechtfertigt nicht automatisch Rechtsverletzungen oder jede kurzfristige Aktienkurssteigerung.','corporate-02','stakeholders','tradeoffs'),
 G('Stakeholder Theory','Ansatz, der weitere berechtigte Interessen der vom Unternehmen betroffenen oder auf es einwirkenden Gruppen ausdrücklich berücksichtigt. Daraus folgt keine Pflicht zu identischen Zahlungen an alle Gruppen und keine automatische Auflösung tatsächlicher Interessenkonflikte.','corporate-02','stakeholders','tradeoffs'),
 G('ESG','Environmental, Social und Governance: Umwelt-, Sozial- und Unternehmensführungsfaktoren. In der Finanzanalyse werden konkrete Risiken und Chancen über Absatz, Kosten, Investitionen, Ausfall und Finanzierung verfolgt. Ein ESG-Etikett oder Rating ist weder Renditegarantie noch alleiniger Nachweis positiver Wirkung.','statements-16','stakeholders','esg-channels','Environmental Social Governance'),
 G('Finanzielle Wesentlichkeit','Relevanz einer Information für die wirtschaftliche Beurteilung eines Unternehmens oder seines Wertpapiers. Bei ESG hängt sie unter anderem von Branche, Geschäftsmodell, Standort, Anspruch und Zeithorizont ab. Gesellschaftliche Bedeutung und finanzielle Wirkung können verbunden sein, sind aber nicht identisch.','statements-16','stakeholders','esg-channels','Financial Materiality'),
 G('Physisches Klimarisiko','Risiko aus physischen Klimaereignissen oder längerfristigen Veränderungen, etwa Überflutung, Hitze oder Wasserknappheit. Standort, Schutz, Versicherung und Anpassungsmöglichkeiten bestimmen, wie stark sich die Exposition in Schäden und Zahlungen übersetzt.','statements-16','stakeholders','climate','Physical Climate Risk|physische Klimarisiken'),
 G('Übergangsrisiko','Risiko aus der Umstellung auf eine andere Wirtschafts- oder Technologiebasis; im Klimakontext etwa durch emissionsärmere Technik, veränderte Nachfrage oder Politik. Es unterscheidet sich vom direkten physischen Klimaschaden und kann zugleich Chancen für andere Produkte schaffen.','statements-16','stakeholders','climate','Transition Risk|Übergangsrisiken'),
 G('Kostenweitergabe','Übertragung eines Kostenanstiegs auf Abnehmer durch höhere Erlöse. Das mögliche Ausmaß hängt etwa von Wettbewerb, Verträgen und Nachfrage ab. Eine Rechnung mit konstanter Absatzmenge muss diese Annahme nennen; höhere Preise können sonst die Menge reduzieren.','economics-02','stakeholders','climate','Cost Pass-Through'),
 G('Emissionsintensität','Emissionsmenge relativ zu einer angegebenen Bezugsgröße, etwa Produktionsmenge oder Umsatz. Zähler, Nenner, Erfassungsgrenze und Zeitraum müssen übereinstimmen. Sinkende Intensität kann mit steigenden absoluten Emissionen einhergehen.','statements-16','stakeholders','measurement','Emissions Intensity'),
 G('Greenwashing','Irreführende Darstellung ökologischer Eigenschaften oder Wirkungen, beispielsweise durch selektive Kennzahlen oder verschwiegene Erfassungsgrenzen. Behauptung, Ziel und tatsächlich gemessene Wirkung sind getrennt zu prüfen; eine niedrige Ratingnote allein beweist keine absichtliche Täuschung.','statements-16','stakeholders','measurement'),
 G('ESG-Rating','Verdichtete Beurteilung nach einer bestimmten Methodik zu Umwelt-, Sozial- und Governancefaktoren. Themen, Gewichtung, Vergleichsgruppe und Daten unterscheiden sich zwischen Anbietern. Die Note ist deshalb weder universeller Wirkungsmaßstab noch Garantie einer bestimmten Anlagerendite.','statements-16','stakeholders','measurement','ESG Rating'),
 G('Körperschaftsteuer','Gewinnsteuer auf Ebene einer nach dem maßgeblichen Recht eigenständig steuerpflichtigen Körperschaft. Steuerbasis, Befreiungen und Satz sind gesondert zu bestimmen. Eine zusätzliche Eigentümersteuer auf ausgeschüttete Gewinne betrifft eine andere Ebene; Börsennotierung ist kein notwendiges Merkmal dieser Besteuerung.','statements-08','issuer-forms','taxation','Corporation Tax'),
 G('Corporate Issuer','Unternehmen, das Eigen- oder Fremdkapitalinstrumente ausgibt, um Kapital aufzunehmen. Die Aktien müssen dafür nicht zwingend börsennotiert sein; Eigenkapitaleigentum, Ausgabeweg und öffentliche Berichtspflichten sind getrennt zu prüfen.','corporate-01','issuer-forms','dimensions','Unternehmensemittent'),
 G('Sole Proprietorship','Einzelunternehmen einer natürlichen Person. Im typischen Grundmodell gehören Leitung und Eigentum derselben Person; gewöhnliche Betriebsschulden können auch ihr Privatvermögen betreffen. Mehrere gewöhnliche Miteigentümer benötigen eine andere Struktur.','corporate-01','issuer-forms','forms','Einzelunternehmen'),
 G('General Partnership','Partnerschaft mit grundsätzlich persönlich haftenden General Partners nach dem jeweiligen Recht. Vertraglich geregelte Gewinnanteile begrenzen externe Gläubigerrechte nicht automatisch. Rechtliche Eigenständigkeit und konkrete Haftung unterscheiden sich zwischen Rechtsordnungen.','corporate-01','issuer-forms','forms'),
 G('Limited Partnership','Partnerschaft mit mindestens einem General Partner und daneben Limited Partners. Das Grundmodell trennt geschäftsführende Partnerhaftung von unter Voraussetzungen begrenzter Haftung der übrigen Kapitalgeber. Es ist nicht mit einer Limited Liability Partnership gleichzusetzen.','corporate-01','issuer-forms','forms'),
 G('General Partner','Geschäftsführender und im Grundmodell unbeschränkt haftender Partner einer Partnerschaft. Der Partner kann selbst eine Gesellschaft sein; ihre eigene Haftung ist dann von der persönlichen Haftung ihrer Anteilseigner zu unterscheiden. In privaten Fonds übernimmt der General Partner häufig die Fondsleitung.','alternatives-01','issuer-forms','liability','GP'),
 G('Limited Partner','Partner mit unter den maßgeblichen Regeln begrenzter Haftung und eingeschränkter Leitungsrolle, etwa Kapitalgeber einer Limited Partnership. Die konkreten Schutzvoraussetzungen und Vertragsrechte müssen geprüft werden; Gewinnbeteiligung allein macht jemanden noch nicht zum Limited Partner.','alternatives-01','issuer-forms','forms','LP|LPs'),
 G('Limited Liability Partnership','Rechtsform einer Partnerschaft mit Haftungsbegrenzung ihrer Mitglieder nach dem jeweiligen Recht. Sie ist von der Limited Partnership mit einem grundsätzlich unbeschränkt haftenden General Partner zu unterscheiden. Steuer- und Organregeln sind gesondert zu bestimmen.','corporate-01','issuer-forms','forms','LLP'),
 G('Limited Liability Company','Unter dem jeweiligen Recht organisierte haftungsbeschränkte Gesellschaft. Bei einer US-LLC wird die Bundessteuerklassifikation gesondert anhand der maßgeblichen Regeln und Wahlen bestimmt; Haftungsbegrenzung bedeutet nicht automatisch eine bestimmte Besteuerung.','corporate-01','issuer-forms','taxation','LLC'),
 G('Kapitalgesellschaft','Eigenständige Gesellschaft, an der Eigentümer Kapitalanteile halten. Sie besitzt ihr Betriebsvermögen selbst und haftet grundsätzlich mit diesem Vermögen; die zusätzliche Haftung der Anteilseigner ist im gewöhnlichen vollständig eingezahlten Grundfall begrenzt. Konkrete Organ-, Einlage- und Haftungsregeln hängen von der Rechtsordnung ab.','corporate-01','issuer-forms','identity-control','Corporation'),
 G('Beschränkte Haftung','Begrenzung des zusätzlichen persönlichen Rückgriffs für Unternehmensschulden auf den Eigentümer. Sie schützt nicht vor vollständigem Verlust des investierten Eigenkapitals. Garantien, offene Einlagepflichten und andere eigene Haftungsgründe müssen separat betrachtet werden.','corporate-01','issuer-forms','liability','Limited Liability'),
 G('Steuerliche Transparenz','Besteuerungsmodell, bei dem ein Unternehmensgewinn für die maßgebliche Steuer den Eigentümern zugerechnet wird. Zurechnung und tatsächliche Auszahlung können auseinanderfallen. Ob dieses Modell gilt, folgt aus konkreter Steuerklassifikation, nicht allein aus privater Eigentümerschaft oder beschränkter Haftung.','corporate-01','issuer-forms','retention','Pass-through Taxation'),
 G('Initial Public Offering','Erstmaliges öffentliches Aktienangebot eines Unternehmens im hier behandelten Börsengangskontext. Es kann neue Aktien, Altaktien oder beide enthalten. Nur die neue Ausgabe bringt der Gesellschaft selbst Emissionserlös; Altaktienerlöse fließen ihren Verkäufern zu.','corporate-01','issuer-forms','ipo','IPO|Börsengang'),
 G('Direct Listing','Börsenzugang durch direkte Notierung ohne klassische vorgelagerte Aktienplatzierung. Eine reine Altaktiennotierung schafft keinen neuen Gesellschaftscash; zugelassene Primary-Direct-Listing-Varianten können dagegen neue Aktien und Kapitalaufnahme enthalten. Die konkrete Struktur entscheidet.','corporate-01','issuer-forms','listing-paths','Direktnotierung'),
 G('SPAC','Special Purpose Acquisition Company: zunächst zur späteren Akquisition finanzierte börsennotierte Gesellschaft. Bei der Kombination mit einem operativen Ziel beeinflussen unter anderem Rückgaben, Zusatzfinanzierung, Kosten und Sponsoransprüche den verfügbaren Cashbetrag und die Beteiligungsquoten.','corporate-01','issuer-forms','listing-paths','Special Purpose Acquisition Company'),
 G('Leveraged Buyout','Unternehmenskauf mit erheblichem Fremdfinanzierungsanteil. Der kleinere Eigenkapitaleinsatz kann günstige Entwicklungen stärker in Eigenkapitalrendite übersetzen, verstärkt aber auch Verluste und Schuldendienstrisiken. Nicht jeder Rückzug von der Börse ist ein Leveraged Buyout.','alternatives-04','issuer-forms','going-private','LBO'),
 G('Going Private','Übergang einer öffentlich gehandelten Eigenkapitalstruktur in privates Eigentum, etwa durch Übernahme und anschließendes Ende der Aktiennotierung. Operativer Betrieb, Schulden und gegebenenfalls andere Berichtspflichten können fortbestehen.','corporate-01','issuer-forms','going-private'),
 G('Cap Table','Übersicht über die Verteilung der ausstehenden und je nach Zweck potenziellen Anteile sowie der zugehörigen Rechte. Neue Ausgabe, Verkauf bestehender Anteile und Umwandlung einer Aktienklasse wirken unterschiedlich auf Stückzahlen, Stimmen und Erlösempfänger.','corporate-01','issuer-forms','primary-secondary','Capitalization Table'),
 G('Pre-Money-Bewertung','Angenommener Eigenkapitalwert eines Unternehmens unmittelbar vor einer neuen Eigenkapitalfinanzierung. Er wird von der Bewertung nach Zufluss getrennt. Preis je Anteil und Sonderrechte müssen mit der verwendeten Bewertungsbasis übereinstimmen.','corporate-01','issuer-forms','primary-secondary','Pre-Money Valuation'),
 G('Post-Money-Bewertung','Eigenkapitalwert nach einer neuen Eigenkapitalfinanzierung. Im einfachen Modell ohne Kosten oder weitere Wertänderungen entspricht er Vorfinanzierungswert plus neuem Geld. Dieser Modellzusammenhang darf nicht ungeprüft auf beliebige Vertragsrechte oder Bewertungseffekte übertragen werden.','corporate-01','issuer-forms','primary-secondary','Post-Money Valuation'),
 G('Konsignation','Überlassung von Waren an einen Händler, bei der der Lieferant nach den konkreten Vertragsbedingungen zunächst die Kontrolle behält. Der reine Transport kann dann weder Umsatz noch Abgang aus den eigenen Vorräten begründen. Rückforderungsrechte und Zahlungspflichten helfen bei der Beurteilung.','statements-04','income-statement','revenue-estimates','Consignment'),
 G('Leistungsfortschritt','Maß für den bereits erfüllten Anteil einer über die Zeit zu erbringenden Vertragsleistung. Die Messgröße muss die tatsächliche Leistung abbilden. Beim geeigneten Kostenverfahren wird der kumulierte Fortschritt aus anrechenbaren Kosten und ihrer aktuellen Gesamtschätzung ermittelt.','statements-04','income-statement','revenue-estimates','Measure of Progress'),
 G('Gewährleistungsrückstellung','Geschätzte Verpflichtung aus bereits verkauften Waren mit einer Zusage zur vereinbarten Beschaffenheit. Bei erfüllten Ansatzvoraussetzungen entsteht Aufwand, bevor sämtliche Schäden bezahlt sind; spätere Erfüllung reduziert die Verpflichtung. Eine eigenständige Servicegarantie ist gesondert zu prüfen.','statements-04','income-statement','expense-patterns','Warranty Provision'),
 G('Working Capital Turnover','Jahresumsatz relativ zum durchschnittlichen Nettoumlaufvermögen. In der hier verwendeten Definition ist der Nenner kurzfristiges Vermögen minus kurzfristige Verbindlichkeiten. Ein sehr kleiner oder negativer Nenner begrenzt die gewöhnliche Effizienzinterpretation.','statements-12','ratios','additional-ratios','WCT'),
 G('Fixed Asset Turnover','Jahresumsatz relativ zum durchschnittlichen Nettosachanlagenbestand. Eine hohe Quote kann auf gute Auslastung, aber auch auf alte stark abgeschriebene Anlagen zurückgehen. Altersstruktur und Ersatzbedarf gehören zur Interpretation.','statements-12','ratios','additional-ratios','FAT'),
 G('Return on Common Equity','Für Stammaktionäre verfügbares Periodenergebnis relativ zu ihrem durchschnittlichen Eigenkapital. Relevante Vorzugsdividenden werden aus dem Ergebnis entfernt; Vorzugskapital gehört nicht in den Nenner. Die Abkürzung ROCE kann in anderen Quellen Return on Capital Employed bedeuten.','statements-12','ratios','additional-ratios'),
 G('Combined Ratio','Schadenquote plus Kostenquote eines Versicherers. Bei einer gemeinsamen verdienten Prämienbasis zeigt eine Quote unter 100 % im einfachen Fall einen positiven Zeichnungsbeitrag. Abweichende Prämienbasen, Rückversicherung und Reserveeffekte müssen geprüft werden; Kapitalanlageergebnis und Steuer sind nicht enthalten.','statements-14','ratios','industry-cases'),
 G('Pro forma','Unter einem klar bezeichneten Zweck aufbereitete Rechnung. Im Abschlussmodell bedeutet dies eine Projektion unter expliziten Annahmen; in anderem Kontext kann der Begriff bereinigte historische Angaben bezeichnen. Zeitraum, Ausgangsbasis und Anpassungen müssen deshalb erkennbar sein.','statements-15','forecasting','architecture'),
 G('Top-down-Ansatz','Prognose von übergeordneten Größen zur Firma, etwa von Marktumsatz und Marktanteil zum Unternehmensumsatz. Die Marktdefinition und die wert- oder mengenmäßige Anteilsbasis müssen übereinstimmen. Eine Gegenprüfung mit Unternehmenskapazität und einzelnen Treibern bleibt nötig.','equity-05','forecasting','industry-company','Top-down'),
 G('Bottom-up-Ansatz','Aufbau einer Prognose aus einzelnen betrieblichen Treibern wie Kunden, Standorten, verkauften Mengen und Preisen. Die addierten Unternehmenspläne werden gegen Marktgröße, Wettbewerb und verfügbare Ressourcen geprüft.','equity-05','forecasting','industry-company','Bottom-up'),
 G('Produktmix','Zusammensetzung des Absatzes aus verschiedenen Produkten. Eine Verschiebung zu teureren Produkten kann den durchschnittlichen Erlös je Einheit erhöhen, ohne dass ein einzelner Produktpreis steigt. Margen und Kapitalbedarf können ebenfalls durch den Mix beeinflusst werden.','equity-05','forecasting','sales-drivers','Sales Mix'),
 G('Finanzierungsbedarf','Zusätzliche Mittel, die unter einer angegebenen Zahlungsplanung benötigt werden, um Verpflichtungen und ein definiertes Liquiditätsziel zu erfüllen. Er kann trotz positiven Gewinns entstehen. Eine rechnerische Lücke beweist keine tatsächliche Verfügbarkeit des benötigten Kredits.','statements-15','forecasting','funding','Funding Need'),
 G('Zirkularität','Rückkopplung im Modell, bei der eine Ergebnisgröße ihre eigene Berechnungsgrundlage beeinflusst. Neuer Kredit kann etwa Zinsen erzeugen, die erneut Kredit erfordern. Eine Lösung benötigt konsistente Annahmen und gegebenenfalls algebraische oder kontrolliert iterative Berechnung.','statements-15','forecasting','circularity','Circularity'),
 G('Outside View','Beurteilung eines Vorhabens anhand einer sachgerecht gewählten Vergleichsgruppe und ihrer beobachteten Ergebnisse. Sie kann unbegründeten Optimismus begrenzen, muss aber technologische, zeitliche und wirtschaftliche Unterschiede berücksichtigen.','equity-05','forecasting','biases'),
 G('Verankerung','Übermäßige Bindung eines Urteils an eine zuerst gesehene Zahl, etwa eine Managementprognose. Eine unabhängig aufgebaute Treiberrechnung vor dem Vergleich mit der Vorgabe hilft, die spätere Anpassung weniger von dieser Ausgangszahl bestimmen zu lassen.','portfolio-08','forecasting','biases','Anchoring'),
 G('Bestätigungsfehler','Einseitige Suche oder Gewichtung von Informationen zugunsten einer bereits bevorzugten Erklärung. Vorab benannte mögliche Gegenbelege und eine systematische Suche nach ihnen verbessern die Prüfung einer Prognose.','portfolio-08','forecasting','biases','Confirmation Bias'),
 G('Überkonfidenz','Überhöhtes Vertrauen in die Genauigkeit des eigenen Urteils, beispielsweise eine zu enge Prognosebandbreite. Die Aufzeichnung und Auswertung früherer Prognosefehler hilft, Unsicherheit anhand tatsächlich verfügbarer Information zu kalibrieren.','portfolio-08','forecasting','biases','Overconfidence'),
 G('Reinvestitionsquote','Anteil eines passend abgegrenzten Gewinns, der für weitere Investitionen gebunden wird. Im stabilen operativen Modell verbindet sie Wachstum und Rendite auf neues Kapital. Sie ist nicht automatisch die Wachstumsrate oder die Quote einbehaltener Dividenden.','equity-09','forecasting','continuing','Reinvestment Rate'),
 G('Sensitivitätsanalyse','Berechnung der Wirkung einer gezielten Änderung einzelner Modellannahmen bei sonst gleichen Bedingungen. Sie zeigt Abhängigkeit, liefert aber weder automatisch eine Eintrittswahrscheinlichkeit noch alle gemeinsamen Änderungen eines Stressszenarios.','statements-15','forecasting','scenarios','Sensitivity Analysis'),
 G('Expliziter Prognosehorizont','Zeitraum, für den wesentliche Treiber und Abschlüsse einzeln projiziert werden. Seine Länge folgt etwa Investitionszyklen, Übergang zu nachhaltigen Margen und wirtschaftlicher Lebensdauer. Mehr Detailjahre bedeuten ohne bessere Information nicht automatisch höhere Genauigkeit.','statements-15','forecasting','horizon','Explicit Forecast Horizon'),
 G('Berichtsqualität','Verlässlichkeit und Entscheidungsnützlichkeit der veröffentlichten Finanzinformation: wichtige Vorgänge werden sachgerecht erfasst, vollständig erläutert und unverzerrt dargestellt. Eine schlechte wirtschaftliche Lage kann in einem qualitativ guten Bericht zutreffend wiedergegeben sein.','statements-13','reporting-quality','dimensions','Financial Reporting Quality'),
 G('Ergebnisqualität','Wirtschaftliche Tragfähigkeit und Wiederholbarkeit von Gewinnen, Cashflows und Bilanzpositionen als Grundlage einer Prognose. Ein realer einmaliger Gewinn kann korrekt berichtet sein und trotzdem keine wiederkehrende Ertragsbasis darstellen.','statements-13','reporting-quality','economic-quality','Earnings Quality|Results Quality'),
 G('Vorsicht','Sorgfältiges Urteilen bei unsicheren Schätzungen. Im IFRS-Rahmenkonzept unterstützt Vorsicht die Neutralität; sie erlaubt keine beliebige absichtliche Unterbewertung von Aktiva oder Überbewertung von Schulden. Konkrete asymmetrische Standardregeln sind davon zu unterscheiden.','statements-13','reporting-quality','prudence','Prudence'),
 G('Earnings Smoothing','Glättung des ausgewiesenen Ergebnisverlaufs, etwa durch zeitliche Verschiebung von Aufwendungen und späteren Auflösungen. Ein konstanterer Berichtswert beweist kein entsprechend geringeres wirtschaftliches Risiko. Zulässigkeit und zugrunde liegende Belege sind einzeln zu prüfen.','statements-13','reporting-quality','smoothing','Ergebnisglättung'),
 G('Big Bath','Bündelung großer Ergebnisbelastungen in einer bereits schlechten Periode, wodurch spätere Perioden günstiger aussehen können. Eine tatsächlich erforderliche hohe Abschreibung ist nicht allein wegen ihres Umfangs manipulativ; entscheidend sind Ansatzgrund und sachgerechte Höhe.','statements-13','reporting-quality','smoothing'),
 G('Non-GAAP-Kennzahl','Zusätzliche Finanzkennzahl mit einer vom maßgeblichen Abschlussregelwerk abweichenden Definition oder Bereinigung. Sie kann Informationen ergänzen, benötigt aber eine nachvollziehbare Überleitung und kritische Prüfung von Symmetrie, Wiederholbarkeit und Vergleichbarkeit.','statements-13','reporting-quality','adjusted','Non-GAAP Measure|Non-GAAP-Kennzahlen'),
 G('Management-defined Performance Measure','Durch IFRS 18 abgegrenzte, in öffentlicher Kommunikation verwendete Erfolgszwischensumme zur Darstellung einer Managementsicht auf die Leistung des Unternehmens. Qualifizierende MPM benötigen besondere Anhangangaben. Nicht jede operative Kennzahl oder Cashflowgröße gehört automatisch dazu.','statements-13','reporting-quality','presentation','MPM|Management-defined Performance Measures'),
 G('Rationalization','Innere Rechtfertigung eines problematischen Handelns, etwa die Behauptung, ein heute unzulässiger Umsatz werde durch spätere gute Ergebnisse wieder ausgeglichen. Im Betrugsrisikomodell ist sie von äußerem Druck und Gelegenheit zu unterscheiden.','statements-13','reporting-quality','incentives','Rationalisierung'),
 G('Ergebnissteuerung','Gezielte Beeinflussung berichteter Ergebnisse durch Bilanzierungsentscheidungen, Schätzungen oder tatsächliche operative Handlungen. Die Wirkung kann über mehrere Perioden laufen; wirtschaftlicher Schaden, Regelverstoß und Absicht sind jeweils gesondert zu beurteilen.','statements-13','reporting-quality','smoothing','Earnings Management'),
 G('Abgrenzungsindikator','Hier Gewinn minus operativer Cashflow, gegebenenfalls geteilt durch durchschnittliche Aktiva. Er zeigt eine zu erklärende Erfolgs-/Zahlungsdifferenz; er ist weder eine universelle Betrugsschwelle noch ein Ersatz für die Untersuchung konkreter Bestandsbewegungen.','statements-13','reporting-quality','warning-signs','Cash-flow-based Accrual Indicator'),
 G('Normalisierter Cashflow','Analytische Zahlungsgröße, bei der klar benannte außergewöhnliche oder vorübergehende Effekte für einen Vergleich oder eine Prognose angepasst werden. Sie verändert nicht den tatsächlich historischen Cashbestand; Definition und Annahmen müssen offengelegt werden.','statements-13','reporting-quality','cash-window','Normalized Cash Flow'),
 G('FIFO','First In, First Out: Kostenflussannahme, bei der die ältesten verfügbaren Kosten zuerst den verkauften oder verbrauchten Einheiten zugeordnet werden. Im Endbestand bleiben jüngere Kosten. Die rechnerische Reihenfolge beweist keine entsprechende physische Lagerentnahme.','statements-05','inventory','cost-flows','First In First Out'),
 G('LIFO','Last In, First Out: Kostenflussannahme, bei der jüngere verfügbare Kosten zuerst dem Verbrauch zugeordnet werden. Laufende und periodische Berechnung können verschiedene Ergebnisse liefern. IAS 2 erlaubt LIFO nicht; für einen US-Vergleich sind Zulässigkeit und konkrete Methodik zu prüfen.','statements-05','inventory','cost-flows','Last In First Out'),
 G('LIFO-Reserve','Offengelegte Differenz zwischen einem Vergleichskostenwert des Vorrats und seinem LIFO-Wert. Im üblichen Lehrmodell ist sie FIFO minus LIFO. Für die Bilanzanpassung zählt der Endbestand der Reserve, für die Umsatzkostenanpassung ihre Periodenänderung; die tatsächliche Veröffentlichungsdefinition ist zu lesen.','statements-05','inventory','reserve','LIFO Reserve'),
 G('LIFO-Liquidation','Abbau von Vorratsmengen, der unter LIFO in alte Kostenschichten hineinreicht. Bei historisch steigenden Kosten kann dadurch die aktuelle Marge steigen, obwohl die operative Leistung nicht entsprechend besser geworden ist. Eine sinkende Reserve allein beweist noch keine solche Liquidation.','statements-05','inventory','liquidation','LIFO Liquidation'),
 G('Kostenflussannahme','Rechenregel zur Zuordnung der verfügbaren Vorratskosten auf Verbrauch und Endbestand, etwa FIFO oder gewogener Durchschnitt. Sie beschreibt eine Bewertung und muss nicht mit dem tatsächlichen physischen Warenfluss identisch sein.','statements-05','inventory','cost-flows','Cost Flow Assumption'),
 G('Gewogener Periodendurchschnitt','Vorratskostenmethode, die sämtliche für die betrachtete Periode verfügbaren Kosten durch die zugehörige Menge teilt. Verkäufe werden zum gemeinsamen Periodenkostenbetrag bewertet. Ein einfacher Mittelwert der Einkaufspreise wäre bei verschiedenen Mengen falsch.','statements-05','inventory','timing','Periodic Weighted-Average Cost'),
 G('Gleitender Durchschnitt','Laufende Vorratskostenmethode, bei der nach einem Zugang die bisherigen Restkosten plus neue Kosten durch die neue Gesamtmenge geteilt werden. Bereits gebuchte Verkäufe erhalten durch spätere Einkäufe keinen rückwirkend geänderten Kostenbetrag.','statements-05','inventory','timing','Moving-Average Cost'),
 G('Nettoveräußerungswert','Geschätzter Verkaufserlös im gewöhnlichen Geschäftsverlauf abzüglich noch erforderlicher Fertigstellungs- und notwendiger Verkaufskosten. Er begrenzt im gewöhnlichen IAS-2-Kostenmodell den Vorratsbuchwert, erlaubt aber keinen Ansatz über Kosten.','statements-05','inventory','nrv','Net Realizable Value|NRV'),
 G('Lower of Cost or Market','US-Niederstwertmodell für insbesondere LIFO- und Retail-Vorräte. Der technische Market-Betrag sind Wiederbeschaffungskosten, begrenzt nach oben durch NRV und nach unten durch NRV minus normalen Gewinnbetrag. Dieser begrenzte Wert wird anschließend mit den Kosten verglichen.','statements-05','inventory','us-market','LCM'),
 G('Normale Kapazität','Bei der Zuordnung fixer Produktionsgemeinkosten maßgebliche unter normalen Umständen erwartete Produktionsleistung. Unterauslastung darf nicht beliebig höhere Stückkosten und damit höhere Vorratswerte erzeugen; nicht zugeordnete Fixkosten werden im Grundfall als Periodenaufwand erfasst.','statements-05','inventory','cost','Normal Capacity'),
 G('Wiederbeschaffungskosten','Kosten, die für einen vergleichbaren Ersatz heute anfallen würden. Sie sind weder automatisch historische Anschaffungskosten noch Verkaufserlös. Beim US-LIFO-Niederstwerttest gelten zusätzliche Ober- und Untergrenzen.','statements-05','inventory','us-market','Replacement Cost'),
 G('Vorratsumschlag','Verhältnis der Umsatzkosten zu einem sachgerecht durchschnittlichen Vorratsbuchwert. Höherer Umschlag kann geringere Kapitalbindung anzeigen, aber auch mechanisch durch eine Abwertung entstehen: Umsatzkosten steigen und der Bestandsnenner sinkt.','statements-05','inventory','write-down-effects','Inventory Turnover|Lagerumschlag'),
 G('Vorratsabwertung','Verminderung des Vorratsbuchwerts wegen eines niedrigeren maßgeblichen Realisations- oder Market-Betrags. Sie belastet das Ergebnis ohne automatisch einen aktuellen Geldabfluss auszulösen. Zulässige spätere Zuschreibungen hängen vom Rechnungslegungsrahmen ab.','statements-05','inventory','reversal','Inventory Write-down'),
 G('Lineare Abschreibung','Zeitlich gleichmäßige Verteilung von Kosten abzüglich Restwert über die geschätzte Nutzungsdauer ab Nutzungsbereitschaft. Sie ist eine Aufwandsverteilung, keine jährliche neue Kaufzahlung. Bei Schätzungsänderungen wird der verbleibende Betrag neu verteilt.','statements-06','long-assets','depreciation','Straight-line Depreciation'),
 G('Leistungsabhängige Abschreibung','Verteilung des abschreibbaren Betrags entsprechend dem Anteil der tatsächlich verbrauchten Einheiten am erwarteten gesamten Leistungspotenzial. Eine Maschine mit stärkerer aktueller Nutzung erhält dadurch höheren aktuellen Aufwand als bei gleicher Restmenge ohne Nutzung.','statements-06','long-assets','depreciation','Units-of-Production Depreciation'),
 G('Degressive Abschreibung','Abschreibungsverfahren mit zunächst höheren und später niedrigeren Aufwandsbeträgen, etwa einem festen Satz auf den sinkenden Buchwert. Der Restwert darf nicht unterschritten werden; die vollständige Verteilung bis Nutzungsende kann einen Wechsel zur linearen Restverteilung erfordern.','statements-06','long-assets','depreciation','Declining-Balance Depreciation'),
 G('Restwert','Geschätzter nach maßgeblichen Regeln verbleibender Nettoabgangswert eines Vermögenswerts am Ende seiner Nutzung. Er vermindert den abschreibbaren Betrag. Eine erhöhte Restwertschätzung kann künftigen Aufwand senken, erzeugt aber weder automatisch Cash noch eine Buchwertaufwertung.','statements-06','long-assets','depreciation','Residual Value'),
 G('Nutzungsdauer','Geschätzter Zeitraum oder Leistungsumfang, über den ein Vermögenswert dem Unternehmen zur Verfügung steht. Sie hängt unter anderem von Nutzung, technischem Wandel und rechtlichen Grenzen ab. Neue belastbare Schätzungen verändern grundsätzlich die zukünftige Verteilung.','statements-06','long-assets','estimate-change','Useful Life'),
 G('Kumulierte Abschreibung','Summe der bisher auf einen Vermögenswert oder eine Gruppe erfassten planmäßigen Abschreibungen. Sie ist ein Bestandsbetrag, kein einzelner Jahresaufwand. Abgänge entfernen auch die dazugehörigen kumulierten Abschreibungen aus der Überleitung.','statements-06','long-assets','roll-forward','Accumulated Depreciation'),
 G('Recoverability Test','Erste Stufe des gewöhnlichen US-GAAP-Wertminderungstests für langfristige in Nutzung gehaltene Anlagen: Buchwert wird mit geeigneten undiskontierten Cashflows verglichen. Scheitert der Test, wird der Verlust anschließend anhand des Fair Value gemessen, nicht anhand der Testunterschreitung.','statements-06','long-assets','us-impairment'),
 G('Held for Sale','Klassifikation eines Vermögenswerts als zum Verkauf bestimmt nach konkreten Voraussetzungen, insbesondere unmittelbarer Verfügbarkeit und hochwahrscheinlichem Verkauf. Sie führt im IFRS-Grundfall zum Vergleich mit Fair Value nach Verkaufskosten und zum Ende planmäßiger Abschreibung. Eine bloße ferne Verkaufsabsicht reicht nicht.','statements-06','long-assets','held-for-sale','Held-for-Sale'),
 G('Neubewertungsmodell','Zulässiges Rechnungslegungsmodell, bei dem geeignete Vermögenswerte nach den jeweiligen Regeln auf aktuelle Bewertungsbeträge gebracht werden. IAS 16 verlangt die Betrachtung ganzer Anlagenklassen; Ausweis über OCI oder Gewinnrechnung hängt auch von früheren Wertänderungen ab.','statements-06','long-assets','revaluation','Revaluation Model'),
 G('Neubewertungsrücklage','Eigenkapitalbestandteil aus entsprechend erfassten Neubewertungen, grundsätzlich über OCI. Eine spätere Wertsenkung derselben Anlage kann vorhandene Beträge verbrauchen. Die Rücklage ist kein eigener Zahlungsmittelbestand und nicht automatisch frei ausschüttbar.','statements-06','long-assets','revaluation','Revaluation Surplus'),
 G('Anlagenspiegel','Überleitung von Anlagenanfangs- zu Endbeständen anhand von Zugängen, Abgängen, Abschreibung, Wertminderung und weiteren Veränderungen. Bruttokosten, kumulierte Korrekturen und Nettobuchwerte müssen konsistent abgegrenzt sein; Zugänge entsprechen nicht immer bezahlten Investitionen.','statements-06','long-assets','roll-forward','PP&E Roll-forward'),
 G('Steuerbasis','Steuerlicher Wert eines Aktivums oder einer Verpflichtung für die Ermittlung künftiger Steuerfolgen. Bei Aktiva zählen insbesondere noch abzugsfähige Beträge; bei Verpflichtungen ist im gewöhnlichen Fall der Buchwert um künftig abzugsfähige Erfüllungsbeträge vermindert. Die spätere steuerliche Behandlung bestimmt die Basis.','statements-08','income-taxes','tax-base','Tax Base'),
 G('Temporäre Differenz','Unterschied zwischen Buchwert und Steuerbasis eines Vermögenswerts oder einer Verpflichtung, der bei Rückgewinnung oder Erfüllung zukünftige Steuerwirkungen erzeugt. Er kann auch außerhalb der Gewinnrechnung entstehen, etwa durch eine Neubewertung über OCI.','statements-08','income-taxes','temporary-permanent','Temporary Difference'),
 G('Permanente Differenz','Im Vergleich von Buchgewinn und steuerpflichtigem Gewinn dauerhaft verschieden behandelter Ertrag oder Aufwand, etwa nach der vorgegebenen Steuerregel steuerfreier Ertrag oder nie abzugsfähige Geldbuße. Ohne spätere Umkehr entsteht daraus für sich keine latente Steuerentlastung.','statements-08','income-taxes','temporary-permanent','Permanent Difference'),
 G('Deferred Tax Liability','Latente Steuerverbindlichkeit aus steuerpflichtigen temporären Differenzen nach den einschlägigen Ansatzregeln. Beispiel: Vorzeitige Steuerabschreibung lässt weniger zukünftiges Abzugspotenzial als buchmäßigen Restverbrauch. DTL ist weder automatisch heute zahlbar noch ein gewöhnlicher verzinslicher Kredit.','statements-08','income-taxes','signs','DTL|latente Steuerverbindlichkeit'),
 G('Deferred Tax Asset','Latenter Steueranspruch aus passenden abzugsfähigen Differenzen, Verlusten oder Gutschriften, soweit die maßgeblichen Ansatz- und Nutzbarkeitsbedingungen erfüllt sind. Er steht für mögliche künftige Entlastung und ist kein automatisch sofort verfügbares Guthaben.','statements-08','income-taxes','signs','DTA|latenter Steueranspruch'),
 G('Valuation Allowance','US-Wertberichtigung auf einen rechnerischen latenten Steueranspruch, soweit dessen Nutzung nach dem maßgeblichen Evidenzmaßstab nicht hinreichend wahrscheinlich ist. Ihre GuV-wirksame Auflösung erhöht den Nettogewinn, ohne durch diese Buchung selbst eine Steuererstattung auszulösen.','statements-08','income-taxes','valuation-allowance'),
 G('Verlustvortrag','Nach dem jeweiligen Steuerrecht in spätere Perioden übertragbarer Verlust zur Verrechnung mit geeigneten Gewinnen. Verfall, jährliche Grenzen, Einkunftsart und Steuergebiet können die Nutzung beschränken. Der nominale Verlust ist größer als sein bei gegebenem Satz möglicher Steuervorteil.','statements-08','income-taxes','loss-carryforward','Loss Carryforward'),
 G('Current Tax Expense','Laufender Ertragsteueraufwand auf die maßgebliche steuerliche Bemessungsgrundlage einschließlich einschlägiger Anpassungen. Er ist von latenten Steuerwirkungen und von der tatsächlich geleisteten Zahlung zu unterscheiden.','statements-08','income-taxes','vocabulary','laufender Steueraufwand'),
 G('Current Tax Payable','Am Stichtag noch offene laufende Ertragsteuerverbindlichkeit nach Berücksichtigung relevanter Zahlungen. Ihr Aufbau bedeutet bei sonst gleichen Bedingungen, dass ein Teil des laufenden Aufwands noch nicht bezahlt wurde.','statements-08','income-taxes','vocabulary','laufende Steuerverbindlichkeit'),
 G('Effective Tax Rate','Gesamter Ertragsteueraufwand relativ zum passenden Buchgewinn vor Ertragsteuern. Abweichungen vom gesetzlichen Bezugssatz können aus permanenten Differenzen, Ländergewichten oder einmaligen Neubewertungen entstehen. Kleine oder negative Nenner erschweren die Interpretation.','statements-08','income-taxes','tax-rates','ETR|effektiver Steuersatz'),
 G('Cash Tax Rate','Zahlungsbezogene Steuerquote mit ausdrücklich anzugebendem Nenner; hier tatsächlich gezahlte Ertragsteuern geteilt durch Buchgewinn vor Steuern. Sie kann durch zeitliche Abzüge und Zahlungsabgrenzung vom effektiven Steuersatz abweichen.','statements-08','income-taxes','tax-rates','CTR'),
 G('Statutory Tax Rate','Gesetzlicher Steuersatz des betrachteten Steuergebiets. Er ist ein Bezugspunkt für die Steuerüberleitung und nicht automatisch der effektive Satz eines Konzerns mit mehreren Ländern, dauerhaften Ausnahmen und Einmalwirkungen.','statements-08','income-taxes','tax-rates','gesetzlicher Steuersatz'),
 G('Steuerquotenüberleitung','Erklärung der Differenz zwischen gesetzlichem Referenzsteuerbetrag und ausgewiesenem Steueraufwand beziehungsweise ihrer Quoten. Die einzelnen Ursachen werden auf Abgrenzung, Wiederholbarkeit und Zahlungswirkung geprüft, bevor eine zukünftige Steuerquote prognostiziert wird.','statements-08','income-taxes','reconciliation','Tax Rate Reconciliation'),
 G('Abschlussanalyse','Systematische Auswertung von Abschlüssen und ergänzenden Informationen für eine konkrete Entscheidung. Sie verbindet Datenprüfung, vergleichbare Aufbereitung, Ursachenanalyse, Prognose und Nachverfolgung; die Berechnung einer Kennzahl allein ist noch keine vollständige Analyse.','statements-01','analysis-framework','process','Financial Statement Analysis'),
 G('Anhang','Bestandteil der Finanzberichterstattung mit Erläuterungen zu Methoden, Schätzungen, Aufgliederungen, Fälligkeiten und Risiken. Er erklärt den Inhalt verdichteter Abschlusspositionen und ist für Vergleiche häufig unverzichtbar.','statements-01','analysis-framework','notes','Notes to the Financial Statements'),
 G('Management Discussion and Analysis','Managementkommentar zu Ergebnissen, Geschäftsentwicklung, Liquidität und Aussichten. Er liefert wertvolle Zusammenhänge aus Sicht der Unternehmensleitung, muss aber hinsichtlich Definitionen, Bereinigungen, Anreizen und Prüfungsumfang kritisch gelesen werden.','statements-01','analysis-framework','management','MD&A'),
 G('Unqualified Opinion','Uneingeschränktes Prüfungsurteil im maßgeblichen Prüfungsrahmen. Es betrifft die wesentliche regelkonforme Darstellung des Abschlusses und bietet keine absolute Fehlerfreiheit, Betrugsfreiheit oder Garantie künftiger Zahlungsfähigkeit.','statements-01','analysis-framework','audit','Unmodified Opinion|uneingeschränktes Prüfungsurteil'),
 G('Qualified Opinion','Eingeschränktes Prüfungsurteil wegen eines wesentlichen, aber hinsichtlich seiner Reichweite abgegrenzten Problems. Die Einschränkung und ihre Auswirkungen sind konkret zu lesen; sie ist von einem umfassend negativen Urteil oder der Nichtabgabe eines Urteils zu unterscheiden.','statements-01','analysis-framework','audit','eingeschränktes Prüfungsurteil'),
 G('Adverse Opinion','Negatives Prüfungsurteil bei festgestellten wesentlichen und umfassenden Abweichungen, sodass der Abschluss nach dem maßgeblichen Rahmen kein angemessenes Gesamtbild vermittelt. Es unterscheidet sich von fehlender Möglichkeit, überhaupt ein Urteil zu bilden.','statements-01','analysis-framework','audit'),
 G('Disclaimer of Opinion','Nichtabgabe eines Prüfungsurteils, etwa weil eine schwerwiegende Nachweisbeschränkung ein belastbares Urteil verhindert. Fehlende Erkenntnis ist nicht gleichbedeutend mit dem Nachweis, dass sämtliche Zahlen falsch sind.','statements-01','analysis-framework','audit'),
 G('Critical Audit Matters','Im Prüfungsbericht besonders erläuterte anspruchsvolle Prüfungsangelegenheiten nach dem einschlägigen Standard. Ihr Vorliegen ist kein automatischer Betrugsnachweis und ändert ein uneingeschränktes Urteil nicht von selbst. Die konkrete Erläuterung und betroffene Abschlussposition sind gemeinsam zu prüfen.','statements-01','analysis-framework','audit','Critical Audit Matter|CAM'),
 G('IASB','International Accounting Standards Board: Standardsetzer für IFRS Accounting Standards innerhalb der IFRS Foundation. Standardsetzung ist von lokaler Übernahme, behördlicher Durchsetzung und unabhängiger Abschlussprüfung zu unterscheiden.','statements-01','analysis-framework','comparability','International Accounting Standards Board'),
 G('FASB','Financial Accounting Standards Board: US-Standardsetzer für Rechnungslegung nichtstaatlicher Unternehmen. Die FASB Accounting Standards Codification ist die maßgebliche strukturierte Quelle; Accounting Standards Updates dokumentieren Änderungen daran.','statements-01','analysis-framework','comparability','Financial Accounting Standards Board'),
 G('IFRS 18','IFRS-Standard zur Darstellung und Offenlegung in Abschlüssen, verpflichtend für Geschäftsjahre ab dem 1. Januar 2027 mit erlaubter früher Anwendung. Zugehörige IAS-7-Änderungen betreffen unter anderem den Startpunkt der indirekten Cashflowrechnung und die Klassifikation von Zinsen und Dividenden.','statements-01','analysis-framework','standards-change'),
 G('Immaterieller Vermögenswert','Identifizierbarer nicht monetärer Vermögenswert ohne körperliche Substanz, etwa ein geeignetes Patent oder eine Lizenz. Ansatz und Bewertung setzen die einschlägigen Kriterien voraus; wirtschaftlich wertvolles Wissen oder eine intern geschaffene Marke werden nicht deshalb automatisch bilanziert.','statements-06','balance-sheet','intangibles','immaterielle Vermögenswerte|Intangible Asset'),
 G('Entwicklungskosten','Kosten der Umsetzung von Erkenntnissen in neue oder wesentlich verbesserte Produkte und Prozesse. Unter IAS 38 werden zurechenbare Kosten erst ab belegtem Erfüllen aller Ansatzbedingungen aktiviert; früher erfasster Aufwand wird dadurch nicht nachträglich zum Vermögenswert.','statements-06','balance-sheet','research-development','Development Costs'),
 G('Amortisation','Im Zusammenhang mit immateriellen Vermögenswerten planmäßige Verteilung des abschreibbaren Betrags über eine endliche Nutzungsdauer ab Nutzungsbereitschaft. Sie ist keine neue Zahlung. In Finanzierungszusammenhängen kann der englische Begriff amortization auch Tilgung oder die Auflösung eines Auf- bzw. Abschlags bezeichnen.','statements-06','balance-sheet','amortisation','Amortization'),
 G('Goodwill','Erwerbsrestbetrag aus Gegenleistung, gegebenenfalls nicht beherrschenden Anteilen und bereits gehaltenen Beteiligungen abzüglich des nach Erwerbsregeln identifizierten Nettovermögens. Er ist von separat erkannten Marken oder Technologien zu trennen und kann neben Synergien auch Überzahlung enthalten. Intern geschaffener Goodwill wird nicht entsprechend angesetzt.','statements-06','balance-sheet','goodwill'),
 G('Minderheitsanteil','Nicht beherrschender Eigentumsanteil an einer konsolidierten Tochtergesellschaft. Seine Bewertung beim Erwerb kann unter IFRS für geeignete gewöhnliche Anteile entweder zum Fair Value oder proportional zum identifizierbaren Nettovermögen erfolgen; dies beeinflusst auch den Goodwillansatz.','statements-10','balance-sheet','partial-goodwill','Non-controlling Interest|Non-controlling Interests|NCI|nicht beherrschender Anteil'),
 G('Zahlungsmittelgenerierende Einheit','Kleinste identifizierbare Gruppe von Vermögenswerten mit im Wesentlichen unabhängigen Mittelzuflüssen. Sie bildet unter IAS 36 eine relevante Ebene der Werthaltigkeitsprüfung; die US-GAAP-Reporting-Unit für Goodwill ist nicht automatisch dieselbe Abgrenzung.','statements-06','balance-sheet','impairment','Cash-generating Unit|CGU'),
 G('Erzielbarer Betrag','Nach IAS 36 der höhere Betrag aus Nutzungswert und beizulegendem Wert abzüglich Veräußerungskosten. Ein Vergleich mit dem passenden Buchwert dient der Prüfung einer Wertminderung; es wird nicht einfach der kleinere der beiden Werte gewählt.','statements-06','balance-sheet','impairment','Recoverable Amount'),
 G('Nutzungswert','Barwert geeigneter erwarteter künftiger Zahlungsströme aus Nutzung und abschließendem Abgang eines Vermögenswerts bzw. einer Einheit nach IAS 36. Er hängt von Cashflow- und Diskontannahmen ab und ist von einem beobachtbaren Verkaufspreis zu unterscheiden.','statements-06','balance-sheet','impairment','Value in Use|VIU'),
 G('Wertminderung','Außerplanmäßige Buchwertsenkung bei unzureichender Werthaltigkeit nach dem einschlägigen Standard. Sie ist im Buchungszeitpunkt gewöhnlich kein neuer Geldabfluss, kann aber verschlechterte wirtschaftliche Erwartungen anzeigen. Regeln zu Testebene, Messung und späterer Zuschreibung unterscheiden sich; IFRS-Goodwill wird nicht zugeschrieben.','statements-06','balance-sheet','impairment','Impairment'),
 G('SPPI','Solely Payments of Principal and Interest: IFRS-9-Prüfung, ob vertragliche Zahlungen einer grundlegenden Kreditbeziehung mit Zins und Kapitalrückzahlung entsprechen. Sie ist neben dem Geschäftsmodell zu erfüllen, damit ein Schuldinstrument für Amortized Cost oder Schuldinstrument-FVOCI in Betracht kommt.','statements-10','balance-sheet','financial-assets'),
 G('Amortized Cost','Fortgeführter Betrag eines Finanzinstruments nach der Effektivzinsmethode, angepasst um Zahlungen und gegebenenfalls Kreditverlustkorrekturen. Er bildet nicht jede Marktpreisbewegung unmittelbar ab; Bilanzkategorie und Instrumentenart bestimmen die anwendbaren Regeln.','statements-10','balance-sheet','measurement-example','fortgeführte Anschaffungskosten|fortgeführter Betrag'),
 G('FVOCI','Fair Value through Other Comprehensive Income: Fair-Value-Bewertung mit bestimmten Änderungen im sonstigen Ergebnis. Bei IFRS-Schuldinstrumenten gehören unter anderem Effektivzins und relevante Kreditverluste in die GuV, mit grundsätzlich späterem Recycling des entsprechenden OCI. Die unwiderrufliche Wahl für geeignete Eigenkapitalanlagen besitzt dagegen kein Wertänderungs-Recycling in die GuV.','statements-10','balance-sheet','equity-instruments'),
 G('FVTPL','Fair Value through Profit or Loss: Bewertung zum beizulegenden Wert mit grundsätzlich erfolgswirksamer Erfassung seiner Änderungen. Welche Instrumente dieser Kategorie angehören, richtet sich nach Instrumentenart, Regelwerk und möglichen Designationen oder speziellen Sicherungsregeln.','statements-10','balance-sheet','financial-assets'),
 G('Expected Credit Losses','Erwartete Kreditverluste in den einschlägigen Rechnungslegungsmodellen. Sie betreffen das Risiko unvollständiger vertraglicher Zahlungen und sind nicht mit jedem Marktwertverlust, etwa durch veränderte risikofreie Zinsen, gleichzusetzen. Der konkrete Ansatz hängt von Kategorie und Kreditrisikoentwicklung ab.','statements-10','balance-sheet','measurement-example','ECL'),
 G('Rückstellung','Bilanzierte Verpflichtung mit Unsicherheit hinsichtlich Betrag oder Zeitpunkt. IAS 37 verlangt im Grundfall eine gegenwärtige Verpflichtung aus einem vergangenen Ereignis, einen wahrscheinlichen Mittelabfluss und verlässliche Schätzung. Bloß erwartete zukünftige Betriebsverluste reichen nicht.','statements-01','balance-sheet','maturity-provisions','Provision'),
 G('Covenant','Vertragliche Schutz-, Informations- oder Verhaltensbedingung einer Finanzierung. Definition, Erfüllungszeitpunkt und Folgen eines Verstoßes sind entscheidend. Für IFRS-Schuldklassifikation ist insbesondere zu unterscheiden, ob eine Bedingung am bzw. vor dem Bilanzstichtag oder erst später einzuhalten ist.','bonds-11','balance-sheet','maturity-provisions','Covenants'),
 G('Zahlungsmitteläquivalente','Kurzfristige hochliquide Anlagen, die leicht in einen bekannten Zahlungsmittelbetrag umgewandelt werden können und nur unwesentlichem Wertänderungsrisiko unterliegen. Eine kurze Restlaufzeit allein genügt nicht; Laufzeit ab Erwerb und Zweck der Liquiditätshaltung sind zu prüfen.','statements-01','cashflow-preparation','scope','Cash Equivalents'),
 G('Kapitalflussrechnung','Überleitung der Zahlungsmittel anhand operativer, investiver und finanzierender Zahlungsströme sowie gesonderter Bestandswirkungen wie Währungsumrechnung. Sie erklärt Zahlungen einer Periode; Gewinn, nicht zahlungswirksame Erwerbe und Bilanzbestandsänderungen sind davon abzugrenzen.','statements-01','cashflow-preparation','scope','Cashflow Statement|Cash Flow Statement'),
 G('Operativer Cashflow','Nettozahlungsstrom aus laufender Geschäftstätigkeit nach dem angewandten Regelwerk. Zins-, Dividenden- und Steuerklassifikation müssen für Vergleiche ausdrücklich geprüft werden; eine Umgliederung kann CFO verändern, ohne neue Zahlungsmittel zu schaffen.','statements-02','cashflow-preparation','categories','Cash Flow from Operations|CFO'),
 G('Cash Flow from Investing','Zahlungsstrom aus Investitionstätigkeit, etwa bezahlten langfristigen Anlagenzugängen und vollständigen Verkaufserlösen. Ein Veräußerungsgewinn allein ist nicht der Erlös; nicht zahlungswirksame Zugänge werden nicht als fiktive Auszahlungen erfasst.','statements-01','cashflow-preparation','investing-financing','CFI|Investitions-Cashflow'),
 G('Cash Flow from Financing','Zahlungsstrom aus Aufnahme und Rückzahlung von Kapital sowie nach Regelwerk zugeordneten Vergütungen an Kapitalgeber. Kredittilgung, neue Kreditaufnahme, Aktienemission und Rückkauf werden vom operativen Gewinn unterschieden; Zinsklassifikation benötigt einen Regelwerksbezug.','statements-01','cashflow-preparation','investing-financing','CFF|Finanzierungs-Cashflow'),
 G('Direkte Cashflowmethode','Darstellung des operativen Cashflows anhand wesentlicher tatsächlicher Ein- und Auszahlungsarten. Bei geeigneten Zusatzdaten können diese aus Erlös, Aufwand und bereinigten Bestandsüberleitungen rekonstruiert werden. Der Gesamtsaldo muss bei gleicher Klassifikation der indirekten Methode entsprechen.','statements-02','cashflow-preparation','direct','Direct Method'),
 G('Indirekte Cashflowmethode','Überleitung einer Ergebnisgröße zum operativen Cashflow durch Korrektur nicht zahlungswirksamer, anders klassifizierter und zeitlich abgegrenzter Komponenten. IFRS 18 verwendet dafür Operating Profit als Startpunkt; die Herleitung muss stets zum angegebenen Ausgangsergebnis passen.','statements-02','cashflow-preparation','indirect','Indirect Method'),
 G('Nicht zahlungswirksame Transaktion','Vorgang, der Vermögen, Schulden oder Ergebnis verändern kann, ohne aktuell Zahlungsmittel zu bewegen, etwa ein Anlagenzugang gegen neue Leasingverbindlichkeit. Er kann offenzulegen und analytisch relevant sein, darf aber nicht als erfundener Cashzufluss und Cashabfluss erscheinen.','statements-02','cashflow-preparation','noncash','Non-cash Transaction'),
 G('Free Cash Flow to the Firm','Freier Zahlungsstrom für sämtliche Kapitalgeber nach den im Modell benötigten operativen Ausgaben und Investitionen, vor Finanzierungsverteilung. Seine Ableitung muss Zinsklassifikation und Finanzierungssteuervorteile konsistent entfernen. FCFF ist eine Bewertungsgröße, keine Garantie rechtlich frei ausschüttbarer Liquidität.','equity-09','cashflow-analysis','free-cashflow','FCFF'),
 G('Free Cash Flow to Equity','Nach operativen Ausgaben, Investitionen und Fremdfinanzierungswirkungen für Eigenkapitalgeber verbleibender Zahlungsstrom. Neue Kredite erhöhen, Tilgungen vermindern ihn; deshalb beweist negatives FCFE allein keine schlechte operative Leistung. Er ist von tatsächlich gezahlten Dividenden zu unterscheiden.','equity-09','cashflow-analysis','fcfe','FCFE'),
 G('Net Borrowing','Neue Kreditaufnahme abzüglich Kredittilgungen in derselben Periode und Abgrenzung. Ein positiver Betrag erhöht den verfügbaren Eigenkapitalcashflow, ohne operative Wertschöpfung darzustellen; ein negativer Betrag bezeichnet Nettotilgung.','equity-09','cashflow-analysis','fcfe','Nettokreditaufnahme'),
 G('Investitionsausgaben','Zahlungen für langfristige operative Vermögenswerte. Bruttozugänge, tatsächliche Barzahlungen und um Verkaufserlöse verminderte Nettoinvestitionen sind zu unterscheiden. Ein bilanzieller Zugang kann auch durch Leasing oder eine noch offene Rechnung entstehen.','statements-15','cashflow-analysis','investment','Capital Expenditures|Capex'),
 G('Tax Shield','Steuerentlastung durch steuerlich abzugsfähige Aufwendungen, etwa Zinsen oder Abschreibungen. Die einfache Rechnung Abzugsbetrag mal Steuersatz setzt einen tatsächlich nutzbaren Abzug und passende Zahlungszeitpunkte voraus. Verlustvorträge, Abzugsgrenzen und latente Steuern können die Wirkung verändern.','corporate-06','cashflow-analysis','classification','Steuervorteil'),
 G('Cash Conversion Ratio','Hier Verhältnis von operativem Cashflow zu Periodengewinn. Es vergleicht Zahlungs- und Erfolgsgröße, ist bei sehr kleinem oder negativem Gewinn aber schwierig zu interpretieren. Klassifikation, Working Capital und nicht zahlungswirksamer Aufwand können die Quote verändern; sie ist nicht der Cash Conversion Cycle.','statements-02','cashflow-analysis','performance-ratios'),
 G('Cash-Zinsdeckung','Deckungskennzahl für Zinszahlungen auf Cashflowbasis. Im Kapitel wird CFO nach Zins und Steuer um beide Zahlungen erhöht und durch den gezahlten Zins geteilt. Andere Definitionen sind möglich; ein Covenant muss nach seinem eigenen Wortlaut gerechnet werden.','statements-12','cashflow-analysis','coverage-ratios','Cash Interest Coverage'),
 G('Schuldendienstdeckung','Verhältnis einer festgelegten verfügbaren Zahlungsgröße zu Zins und planmäßiger Tilgung. Welche Steuern, Investitionen und sonstigen Zahlungen vorher abgezogen werden, muss ausdrücklich angegeben werden; ein guter Jahreswert garantiert keine ausreichende Liquidität an jedem einzelnen Fälligkeitstag.','statements-12','cashflow-analysis','coverage-ratios','Debt Service Coverage'),
 G('Geopolitik','Wechselwirkung von räumlichen Bedingungen, Macht, Interessen und internationalen Beziehungen. In der Anlageanalyse zählt der konkrete Übertragungsweg auf Zahlungsströme, Rechte und Finanzierung, nicht allein die politische Schlagzeile.','economics-12','geopolitics','actors','Geopolitics'),
 G('Soft Power','Einfluss durch Attraktivität, Vertrauen und Überzeugung, etwa über Kultur, Bildung oder glaubwürdige Institutionen. Sie unterscheidet sich von unmittelbarem Zwang, kann sich aber mit wirtschaftlichen oder sicherheitspolitischen Instrumenten verbinden.','economics-12','geopolitics','cooperation'),
 G('Globalisierung','Zunehmende grenzüberschreitende Verflechtung von Gütern, Dienstleistungen, Kapital, Wissen und Menschen. Sie kann Spezialisierung und Risikoteilung ermöglichen, schafft zugleich Abhängigkeiten und ungleich verteilte Anpassungskosten.','economics-12','geopolitics','globalization','Globalization'),
 G('Reshoring','Rückverlagerung zuvor im Ausland ausgeübter Produktion in das Inland. Sie kann bestimmte grenzüberschreitende Risiken verringern, garantiert aber weder niedrigere Gesamtkosten noch Unabhängigkeit von ausländischen Vorleistungen.','economics-12','geopolitics','globalization'),
 G('Nearshoring','Verlagerung von Tätigkeiten in geografisch näher gelegene Länder oder Standorte. Kürzere Wege können Lieferzeiten verringern; gemeinsame vorgelagerte Engpässe bleiben trotzdem möglich.','economics-12','geopolitics','globalization'),
 G('Friendshoring','Ausrichtung von Lieferketten auf politisch als verlässlicher eingeschätzte Partner. Die Strategie verändert Abhängigkeiten und kann neue Konzentrationen sowie höhere Beschaffungskosten erzeugen.','economics-12','geopolitics','globalization'),
 G('Deglobalisierung','Rückgang oder Fragmentierung grenzüberschreitender Verflechtungen. Sie kann einzelne Branchen, Technologien oder Finanzbeziehungen betreffen, ohne dass sämtlicher internationaler Austausch gleichzeitig zurückgeht.','economics-12','geopolitics','globalization','Deglobalization'),
 G('Autarkie','Streben nach Selbstversorgung und geringer externer Abhängigkeit. In einem Handelsmodell bezeichnet das Autarkiegleichgewicht den Zustand ohne internationalen Güteraustausch; dies ist nicht automatisch wirtschaftlich effizient.','economics-09','geopolitics','archetypes','Autarky'),
 G('Hegemonie','Beziehungsstruktur, in der eine dominante Macht Regeln und Abhängigkeiten stark prägt. Wirtschaftliche Integration kann dabei fortbestehen, aber mit asymmetrischer Verhandlungs- und Durchsetzungsmacht verbunden sein.','economics-12','geopolitics','archetypes','Hegemony'),
 G('Bilateralismus','Zusammenarbeit auf der Ebene jeweils zweier Partner. Sie kann auf spezifische Interessen zugeschnitten werden, zugleich aber ein komplexes Netz voneinander abweichender Vereinbarungen erzeugen.','economics-12','geopolitics','archetypes','Bilateralism'),
 G('Multilateralismus','Koordination mehrerer Akteure durch gemeinsame Regeln und Institutionen. Verlässlichkeit und breitere Beteiligung werden gegen Abstimmungsaufwand und Einschränkungen einzelstaatlicher Freiheit abgewogen.','economics-12','geopolitics','archetypes','Multilateralism'),
 G('IMF','International Monetary Fund bzw. Internationaler Währungsfonds: Institution mit Aufgaben in makroökonomischer und finanzieller Stabilität, Überwachung, Beratung und Finanzierung bei Zahlungsbilanzproblemen. Er ist von der entwicklungsorientierten Weltbank und dem Handelsregelwerk der WTO zu unterscheiden.','economics-12','geopolitics','institutions','International Monetary Fund|Internationaler Währungsfonds|IWF'),
 G('Weltbank','Entwicklungsinstitution mit langfristiger Finanzierung und Expertise unter anderem für Armutsbekämpfung und Infrastruktur. Die Weltbank im engeren Sinn umfasst IBRD und IDA; die Weltbank-Gruppe enthält weitere Einrichtungen mit anderen Aufgaben.','economics-12','geopolitics','institutions','World Bank'),
 G('WTO','World Trade Organization: institutioneller Rahmen für Handelsabkommen, Verhandlungen, Überwachung und handelsbezogene Streitverfahren. Sie ist keine allgemeine Kreditinstitution für Staaten oder Unternehmen.','economics-12','geopolitics','institutions','World Trade Organization|Welthandelsorganisation'),
 G('Event Risk','Risiko eines abgrenzbaren Ereignisses mit unsicherem Ausgang oder Wirkung, beispielsweise einer terminierten Wahl. Seine Folgen können längerfristige Themenrisiken verstärken; ein bekannter Termin macht den Ausgang nicht sicher.','economics-12','geopolitics','risk-types','Ereignisrisiko'),
 G('Thematic Risk','Längerfristiges strukturelles Risiko, etwa technologische Fragmentierung oder geopolitische Neuordnung. Es entwickelt sich über Zeit und kann durch einzelne Ereignisse beschleunigt werden.','economics-12','geopolitics','risk-types','Themenrisiko'),
 G('Exogenous Risk','Im geopolitischen Raster Risiko eines von außen eintretenden, häufig abrupten Schocks. Die Bezeichnung ersetzt keine Prüfung von Vorwarnzeichen, Wahrscheinlichkeit, Geschwindigkeit und Schadenshöhe.','economics-12','geopolitics','risk-types','Exogenes Risiko'),
 G('Resilienz','Fähigkeit, eine Störung zu verkraften, Leistungen aufrechtzuerhalten oder sich anzupassen. Redundanz, Lager und alternative Lieferanten können helfen, verursachen aber Kosten und müssen den tatsächlichen gemeinsamen Engpass reduzieren.','economics-12','geopolitics','mitigation','Resilience'),
 G('Signpost','Vorab definierter beobachtbarer Hinweis, der eine Szenarioeinschätzung stützt, schwächt oder eine Handlung auslöst. Mehrere Meldungen aus derselben ursprünglichen Quelle sind dabei keine unabhängigen Bestätigungen.','economics-12','geopolitics','signposts','Signposts'),
 G('Absoluter Vorteil','Fähigkeit, ein Gut mit weniger Ressourcen als ein anderer Produzent herzustellen. Für die Richtung vorteilhaften Handels sind dagegen relative Opportunitätskosten und damit komparative Vorteile entscheidend.','economics-09','trade','comparative','Absolute Advantage'),
 G('Komparativer Vorteil','Niedrigere Opportunitätskosten eines Gutes gegenüber einem anderen Produzenten. Er kann auch bei absolut geringerer Produktivität bestehen und begründet im einfachen Handelsmodell Spezialisierungsgewinne.','economics-09','trade','comparative','Comparative Advantage'),
 G('Terms of Trade','Verhältnis der Exportpreise zu den Importpreisen bei klar definierten Indizes oder Gütereinheiten. Eine Verbesserung erlaubt für eine gegebene Exportmenge mehr Importe, ist aber allein kein vollständiges Wohlfahrtsmaß.','economics-09','trade','exchange','Reales Austauschverhältnis'),
 G('Spezifischer Zoll','Fester Abgabenbetrag je importierter Mengeneinheit. Bei einem kleinen weiterhin importierenden Land erhöht er im einfachen Modell den Inlandspreis um diesen Betrag; bei prohibitivem Niveau gilt diese Preisgleichheit nicht mehr.','economics-09','trade','tariff','Specific Tariff|Stückzoll'),
 G('Wertzoll','Zoll als Prozentsatz einer definierten Bemessungsgrundlage des Importwerts. Anders als beim Stückzoll ändert sich der Abgabenbetrag je Einheit mit dem zugrunde liegenden Warenwert.','economics-09','trade','tariff','Ad-valorem-Zoll|Ad Valorem Tariff'),
 G('Prohibitiver Zoll','Zoll, dessen Höhe Importe im betrachteten Markt vollständig unterbindet. Bei unveränderten Binnenkurven bestimmt dann das Autarkiegleichgewicht den Preis; ein noch höherer Zoll erhöht diesen nicht mechanisch weiter.','economics-09','trade','tariff','Prohibitive Tariff'),
 G('Quotenrente','Knappheitsgewinn aus einem Importrecht: im einfachen Modell Inlandspreis minus Weltpreis, multipliziert mit der erlaubten Importmenge. Ob Staat, inländische Private oder ausländische Anbieter die Rechte besitzen, beeinflusst nationale Wohlfahrt.','economics-09','trade','quota','Quota Rent'),
 G('Importquote','Hier eine mengenmäßige Obergrenze für Importe, nicht der statistische Anteil von Importen am BIP. Eine bindende Quote kann den Inlandspreis erhöhen und Quotenrenten erzeugen; bei Nachfrageänderungen unterscheidet sie sich von einem festen Zoll.','economics-09','trade','quota','Import Quota'),
 G('Exportsubvention','Staatliche Zahlung für exportierte Einheiten. Im einfachen kleinen Exportland hebt sie den Inlandspreis, erhöht Produktion und Export, senkt inländischen Konsum und belastet den Staatshaushalt.','economics-09','trade','subsidies','Export Subsidy'),
 G('Freihandelszone','Zusammenschluss mit beseitigten oder weitgehend reduzierten internen Handelsbarrieren, während Mitglieder eigene Außenhandelspolitiken behalten. Ursprungsregeln grenzen die begünstigten Waren ab.','economics-09','trade','integration','Free Trade Area'),
 G('Zollunion','Handelsintegration mit intern freiem Handel und gemeinsamer Außenhandelspolitik bzw. gemeinsamem Außenzoll. Freier Kapital- und Arbeitsverkehr ist damit noch nicht automatisch vollständig verwirklicht.','economics-09','trade','integration','Customs Union'),
 G('Gemeinsamer Markt','Integrationsform, die über eine Zollunion hinaus die Mobilität von Produktionsfaktoren wie Arbeit und Kapital erweitert. Sie ist von gemeinsamer Wirtschaftspolitik und einer gemeinsamen Währung zu unterscheiden.','economics-09','trade','integration','Common Market'),
 G('Wirtschaftsunion','Vertiefte Integration mit stärker koordinierter oder gemeinsamer Wirtschaftspolitik zusätzlich zu gemeinsamen Marktregeln. Eine Währungsunion ist eine gesonderte monetäre Dimension und sollte nicht ungeprüft gleichgesetzt werden.','economics-09','trade','integration','Economic Union'),
 G('Handelsschaffung','Ersetzung teurerer inländischer Produktion durch günstigere Produktion eines Handelspartners infolge von Integration. Im einfachen Modell sinkt der Ressourcenbedarf; zusätzliche Nachfrage- und Anpassungseffekte können hinzukommen.','economics-09','trade','creation-diversion','Trade Creation'),
 G('Handelsumlenkung','Verlagerung von Importen von einer günstigeren externen Quelle zu einer teureren begünstigten Partnerquelle infolge unterschiedlicher Handelsbarrieren. Der Käuferpreis kann sinken, obwohl nationale Wohlfahrt durch höhere Ressourcenkosten und entgangene Zolleinnahmen fällt.','economics-09','trade','creation-diversion','Trade Diversion'),
 G('Basiswährung','Währung, deren eine Einheit im betrachteten Wechselkurs bepreist wird. Bei ausdrücklich 1,20 USD je EUR ist EUR die Basiswährung; die Paarbezeichnung einer Plattform muss anhand der tatsächlichen Kurseinheit gelesen werden.','economics-10','fx-markets','quotation','Base Currency'),
 G('FX Swap','Verbundener Tausch zweier Währungen mit gegenläufigem Rücktausch an einem anderen Valutatag, häufig Kassa gegen Termin. Das Instrument verschiebt Währungsliquidität über Zeit und ist von einem Cross-Currency Interest Rate Swap mit laufenden Zinszahlungen zu unterscheiden.','economics-11','fx-markets','instruments','Devisenswap'),
 G('Outright Forward','Einzelnes Devisentermingeschäft: heute bindend vereinbarter Währungstausch zu einem zukünftigen Datum und festem Kurs. Es ist kein einseitig ausübbares Recht und keine sichere Prognose des späteren Kassakurses.','economics-11','fx-markets','instruments','Devisentermingeschäft'),
 G('Valuta','Wertstellungs- bzw. vereinbarter Erfüllungstag einer Zahlung oder Transaktion. Handelstag und Valutatag können auseinanderliegen; die genauen Regeln hängen von Instrument, Währung und Vertrag ab.','economics-10','fx-markets','instruments','Valutatag'),
 G('Preiswährung','Währung, in der der Preis einer Einheit der Basiswährung angegeben wird. Bei 1,20 USD je EUR ist USD die Preiswährung. Diese Einheit bestimmt auch die Richtung einer beobachteten Kursänderung.','economics-10','fx-markets','quotation','Quote Currency'),
 G('Realer Wechselkurs','Nominalkurs bereinigt um geeignete relative Güterpreise oder Kosten. Bei q = S mal Auslands-/Inlandspreis und S in Inland je Ausland bedeutet ein Anstieg eine reale Abwertung des Inlands; inverse Indizes verwenden die umgekehrte Richtung.','economics-10','fx-markets','real-rate','Real Exchange Rate'),
 G('Effektiver Wechselkurs','Aggregiertes Währungsmaß gegenüber mehreren Partnern statt nur einer Gegenwährung. Gewichte, bilaterale Kursrichtung und Aggregationsmethode müssen festgelegt sein; reale Varianten berücksichtigen zusätzlich relative Preise oder Kosten.','economics-10','fx-markets','effective-rate','Effective Exchange Rate'),
 G('Currency Board','Regelgebundenes Währungssystem mit fester Konvertierungszusage und vorgeschriebener Reserveunterlegung der entsprechenden monetären Verbindlichkeiten. Es begrenzt eigenständige Geldpolitik stärker als ein diskretionäres flexibles Regime; Details hängen von der Ausgestaltung ab.','economics-10','fx-markets','regimes'),
 G('Crawling Peg','Wechselkursbindung mit schrittweise veränderter Referenzparität nach einer angekündigten Regel oder einem Anpassungsverfahren. Sie unterscheidet sich von einer unveränderten Parität und von frei schwankenden Kursen.','economics-10','fx-markets','regimes'),
 G('De jure','Nach der formell erklärten oder rechtlich festgelegten Regel. Beim Wechselkursregime kann diese Einordnung von de facto beobachteten Interventionen und Kursbewegungen abweichen.','economics-10','fx-markets','regimes'),
 G('De facto','In der tatsächlichen Praxis beobachtbar, unabhängig von der offiziellen Bezeichnung. Ein angekündigt flexibles Wechselkursregime kann beispielsweise intensiv gesteuert werden.','economics-10','fx-markets','regimes'),
 G('Trilemma','Zielkonflikt, nach dem feste Wechselkurse, freie Kapitalmobilität und volle geldpolitische Autonomie unter den idealisierten Bedingungen nicht gleichzeitig unabhängig aufrechterhalten werden können. Risikoprämien und Beschränkungen verändern die Voraussetzungen.','economics-10','fx-markets','policy-constraint','Impossible Trinity'),
 G('Sterilisierte Intervention','Devisenmarktintervention mit einer gegenläufigen monetären Operation, die ihren unmittelbaren Effekt auf die heimische Geldbasis ausgleicht. Damit verschwinden Reserveverbrauch, Erwartungen und sonstige Marktfolgen nicht automatisch.','economics-10','fx-markets','policy-constraint','Sterilized Intervention'),
 G('J-Kurve','Möglicher zeitlicher Verlauf, bei dem eine Abwertung die Handelsbilanz zunächst über Importpreise verschlechtert und spätere Mengenanpassungen sie verbessern. Dieser Verlauf ist bedingt durch Verträge, Preisweitergabe und Elastizitäten, keine Garantie.','economics-10','fx-markets','trade-effects','J-Curve'),
 G('Marshall-Lerner-Bedingung','Im Standardmodell bei anfangs ausgeglichenem Handel und voller Preisweitergabe verbessert eine kleine Abwertung die Handelsbilanz nach Mengenanpassung, wenn die Summe der absoluten Export- und Importnachfrageelastizitäten größer als eins ist. Andere Ausgangslagen verändern die Bedingung.','economics-10','fx-markets','trade-effects','Marshall–Lerner'),
 G('Kapitalverkehrskontrollen','Regeln, die bestimmte grenzüberschreitende Finanztransaktionen begrenzen oder verteuern. Ziele können Krisenbegrenzung, geringere volatile Verschuldung oder geldpolitischer Spielraum sein; Finanzierungskosten, Umgehung und Vertrauen gehören in die Gegenrechnung.','economics-11','fx-markets','capital-controls','Capital Controls'),
 G('Natürliche Absicherung','Wirtschaftlich gegenläufige Zahlungsströme, beispielsweise Einnahmen und Schuldenzahlungen in derselben Fremdwährung. Eine wirksame Deckung verlangt passende Beträge, Termine und tatsächlich verfügbare Einnahmen.','economics-10','fx-markets','capital-flows','Natural Hedge'),
 G('Kreuzkurs','Aus zwei anderen Währungsrelationen abgeleiteter Wechselkurs. Die Einheiten bestimmen Multiplikation oder Division; bei handelbaren Kursen muss zusätzlich jede passende Geld- und Briefseite berücksichtigt werden.','economics-10','fx-calculation','cross-rates','Cross Rate|Cross Rates'),
 G('Geldkurs','Preis, zu dem ein Händler die betrachtete Basiswährung oder das betrachtete Instrument kauft. Ein Kunde, der diese Basiswährung verkauft, erhält den Geldkurs. Beim Invertieren einer Devisennotierung wird der alte Briefkurs zur Basis des neuen Geldkurses.','economics-10','fx-calculation','bid-ask','Bid'),
 G('Briefkurs','Preis, zu dem ein Händler die betrachtete Basiswährung oder das Instrument verkauft. Wer die Basiswährung kauft, bezahlt den Briefkurs; dieser liegt bei regulärer Notierung nicht unter dem Geldkurs.','economics-10','fx-calculation','bid-ask','Ask'),
 G('Dreiecksarbitrage','Geschlossener Tauschweg über drei Währungen, der zu gleichzeitig ausführbaren Kursen nach relevanten Kosten mehr von der Anfangswährung liefert als eingesetzt wurde. Unterschiedliche Mittelpunkte allein beweisen diese Möglichkeit nicht.','economics-10','fx-calculation','triangular','Triangular Arbitrage'),
 G('Gedeckte Zinsparität','Preisrelation zwischen Kassakurs, Terminkurs und passenden Aufzinsungsfaktoren zweier Währungen. Im reibungslosen Modell erzielen direkte heimische Anlage und auf Termin rückgetauschte Auslandsanlage denselben Endwert. Sie ist keine Kassakursprognose.','economics-11','fx-calculation','covered-parity','Covered Interest Parity|CIP'),
 G('Forward Points','Differenz zwischen Termin- und Kassakurs in einer ausdrücklich angegebenen Punkteinheit. Vorzeichen und Skalierung müssen bekannt sein; Punkte sind weder automatisch Prozentpunkte noch stets gleich große Kurseinheiten für alle Währungspaare.','economics-11','fx-calculation','points'),
 G('Terminaufschlag','Positiver relativer Unterschied zwischen Termin- und Kassakurs in derselben Richtung. Bei D je F bedeutet er einen höheren Terminpreis von F in D; Laufzeitaufschlag und annualisierte Kennzahl müssen unterschieden werden.','economics-11','fx-calculation','points','Forward Premium'),
 G('Terminabschlag','Negativer relativer Unterschied zwischen Termin- und Kassakurs bei unveränderter Notierung. Eine inverse Notierung kehrt die wirtschaftliche Richtung um, aber wegen des anderen Nenners nicht exakt denselben Prozentbetrag.','economics-11','fx-calculation','points','Forward Discount'),
 G('Cross-Currency Basis','Preisabweichung gegenüber einer mit definierten Referenzzinsen formulierten gedeckten Zinsparität, häufig als Zinsaufschlag einer bestimmten Vertragsseite ausgedrückt. Vorzeichen, Referenzkurven, Besicherung und Finanzierungsbedingungen müssen ausdrücklich genannt werden.','economics-11','fx-calculation','funding-bounds'),
 G('Ungedeckte Zinsparität','Erwartungsbeziehung zwischen Zinsen und künftiger Wechselkursänderung ohne vertraglich fixierten Rücktauschkurs. Sie benötigt Annahmen über Erwartungen und Risikoprämien und ist nicht dieselbe risikolose Zahlungsstromgleichheit wie gedeckte Zinsparität.','economics-11','fx-calculation','interpretation','Uncovered Interest Parity|UIP'),
 G('Carry Trade','Finanzierung einer höher verzinsten Währungsanlage durch eine niedriger verzinste Währung, typischerweise mit offener Wechselkursposition. Ein negativer Rücktauscheffekt kann den Zinsvorteil übersteigen; vollständige Termindeckung verändert die Renditerechnung.','economics-11','fx-calculation','interpretation'),
 G('Ökonomischer Gewinn','Erlös abzüglich sämtlicher relevanter wirtschaftlicher Kosten einschließlich der Opportunitätskosten eigener Arbeit und eigenen Kapitals. Ein Wert von null kann eine normale Vergütung dieser Ressourcen enthalten und bedeutet nicht, dass kein bilanzieller Gewinn entsteht.','economics-02','market-structures','economic-profit','Economic Profit'),
 G('Opportunitätskosten','Wert der besten tatsächlich verfügbaren aufgegebenen Alternative. Für ökonomische Entscheidungen zählen vergleichbare Ressourcen, Horizonte und Risiken; eine beliebige maximal denkbare Rendite ist kein geeigneter Vergleich.','economics-02','market-structures','economic-profit','Opportunity Cost'),
 G('Versunkene Kosten','Bereits angefallene und durch die jetzige Entscheidung nicht mehr rückholbare Kosten. Sie verändern die Differenz zwischen künftigen Handlungsalternativen nicht. Fixkosten sind nur dann versunken, wenn sie auch nicht mehr vermieden oder zurückgewonnen werden können.','economics-02','market-structures','economic-profit','Sunk Cost|Sunk Costs'),
 G('Grenzkosten','Zusätzliche Gesamtkosten einer kleinen Outputsteigerung, im glatten Modell die Ableitung der Gesamtkosten nach der Menge. Liegen sie unter den bisherigen Durchschnittskosten, sinkt deren Durchschnitt; darüber steigt er. Grenz- und Durchschnittskosten erfüllen verschiedene Entscheidungsaufgaben.','economics-02','market-structures','costs','Marginal Cost|MC'),
 G('Grenzerlös','Änderung des Gesamterlöses durch eine kleine Mengenerhöhung. Beim Preisnehmer entspricht er dem vorgegebenen Preis. Bei fallender einheitlicher Preis-Mengen-Funktion liegt er darunter, weil der niedrigere Preis auch bereits verkaufte Einheiten betrifft.','economics-02','market-structures','market-power','Marginal Revenue|MR'),
 G('AVC','Average Variable Cost: variable Kosten geteilt durch positive Outputmenge. Bei unvermeidbaren Fixkosten markiert das minimale AVC-Niveau die kurzfristige Betriebsschwelle des Preisnehmers; unterhalb davon deckt keine Menge ihre variablen Kosten.','economics-02','market-structures','shutdown','Variable Durchschnittskosten'),
 G('ATC','Average Total Cost: Gesamtkosten geteilt durch positive Outputmenge. Bei ökonomischer Kostenabgrenzung bedeutet Preis gleich ATC einen ökonomischen Gewinn von null. ATC enthält variable und fixe Stückkosten.','economics-02','market-structures','costs','Gesamte Durchschnittskosten'),
 G('AFC','Average Fixed Cost: Fixkosten geteilt durch positive Produktionsmenge. Bei konstanten Fixkosten sinkt dieser Stückkostenanteil mit der Menge; daraus folgt nicht, dass auch gesamte Stückkosten immer sinken.','economics-02','market-structures','costs'),
 G('Betriebsschwelle','Kurzfristige Preisschwelle, bei der Produktion gerade die vermeidbaren variablen Kosten deckt. Im üblichen Preisnehmermodell ist sie das Minimum der AVC-Kurve. Am Schwellenpreis kann Produktion gegenüber Stilllegung indifferent sein; unvermeidbare Fixkosten bleiben ungedeckt.','economics-02','market-structures','shutdown','Shutdown-Preis|Shutdown Point'),
 G('Gewinnschwelle','Punkt, an dem Erlös und relevante Gesamtkosten übereinstimmen. Im ökonomischen Preisnehmermodell liegt der niedrigste Break-even-Preis am ATC-Minimum; normale Opportunitätskosten sind bereits gedeckt. Sie ist von der niedrigeren kurzfristigen Betriebsschwelle zu unterscheiden.','economics-02','market-structures','shutdown','Break-even-Preis'),
 G('Economies of Scale','Sinkende langfristige Durchschnittskosten bei größerem Output und anpassbaren Produktionsfaktoren. Ursachen können Spezialisierung oder effizientere Anlagengrößen sein. Reine kurzfristige Auslastung einer vorhandenen Anlage ist ein anderer Mechanismus.','economics-02','market-structures','scale','Skaleneffekte'),
 G('Diseconomies of Scale','Steigende langfristige Durchschnittskosten bei wachsendem Output, beispielsweise durch zunehmende Koordinations- und Überwachungskosten. Die Aussage betrifft anpassbare Betriebsgröße, nicht nur Überlastung einer kurzfristig festen Anlage.','economics-02','market-structures','scale'),
 G('Minimum Efficient Scale','Kleinste Produktionsgröße, bei der das minimale langfristige Durchschnittskostenniveau erreicht wird. Ihre Größe relativ zum Gesamtmarkt kann beeinflussen, wie viele effizient produzierende Anbieter Platz haben.','economics-02','market-structures','scale','MES|Mindesteffizienzgröße'),
 G('Monopolistische Konkurrenz','Marktmodell mit vielen Anbietern differenzierter Produkte und relativ freiem Eintritt. Im typischen langfristigen Gleichgewicht ist ökonomischer Gewinn null, obwohl der Preis oberhalb der Grenzkosten liegt; Produktion kann unterhalb der ATC-minimalen Menge liegen.','economics-03','market-structures','monopolistic-competition','Monopolistic Competition'),
 G('Oligopol','Markt mit wenigen strategisch bedeutenden Anbietern, deren Entscheidungen sich gegenseitig beeinflussen. Preis- oder Mengenwahl, Reihenfolge, Kapazitäten und Produktdifferenzierung bestimmen das passende Modell; wenige Anbieter garantieren kein bestimmtes Preisniveau.','economics-03','market-structures','strategic-choices','Oligopoly'),
 G('Cournot-Modell','Oligopolmodell gleichzeitiger Mengenwahl. Jedes Unternehmen optimiert seine Menge bei als gegeben angenommener Konkurrentenmenge. Im Gleichgewicht passen die besten Reaktionen zueinander; Preis entsteht anschließend aus der gesamten Marktmenge.','economics-03','market-structures','cournot','Cournot'),
 G('Stackelberg-Modell','Modell aufeinanderfolgender Mengenwahl: Der Vorreiter legt sich zuerst fest und berücksichtigt die beste Mengenreaktion des nachfolgenden Anbieters. Der mögliche Vorteil hängt von glaubwürdiger Bindung und den konkreten Nachfrage- und Kostenannahmen ab.','economics-03','market-structures','strategic-choices','Stackelberg'),
 G('Bertrand-Modell','Oligopolmodell der Preiswahl. Bei homogenen Produkten, identischen konstanten Grenzkosten und ausreichend Kapazität führt die klassische Variante zum Preis auf Grenzkostenniveau. Differenzierung oder Kapazitätsbeschränkungen können das Ergebnis verändern.','economics-03','market-structures','strategic-choices','Bertrand'),
 G('Nash-Gleichgewicht','Kombination von Entscheidungen, bei der kein Spieler durch alleinige Änderung seiner Entscheidung besser gestellt wird, wenn die Entscheidungen der anderen gleich bleiben. Das Ergebnis muss weder gemeinsam optimal noch gesellschaftlich effizient sein.','economics-03','market-structures','strategic-choices','Nash Equilibrium'),
 G('Dominante Strategie','Entscheidung, die für einen Spieler unabhängig von der betrachteten Entscheidung des Gegners mindestens so gut wie seine Alternativen ist; bei strikter Dominanz jeweils besser. Nicht jedes Spiel und nicht jeder Spieler besitzt eine solche Strategie.','economics-03','market-structures','strategic-choices','Dominant Strategy'),
 G('Lerner-Index','Preis abzüglich Grenzkosten, geteilt durch den Preis. Im inneren Gewinnmaximum eines einfachen einheitlich preissetzenden Unternehmens ist er bei fallender Nachfrage gleich minus dem Kehrwert der Preiselastizität. Ein Anteil am Preis ist nicht derselbe Prozentsatz wie ein Aufschlag auf die Kosten.','economics-03','market-structures','market-power','Lerner Index'),
 G('HHI','Herfindahl-Hirschman-Index: Summe quadrierter Marktanteile im abgegrenzten Markt. Bei Anteilen in Prozent liegt die Skala bis 10.000, bei Dezimalanteilen bis 1. Hohe Konzentration allein beweist noch keine dauerhafte Marktmacht.','economics-03','market-structures','concentration','Herfindahl-Hirschman-Index'),
 G('Konzentrationsrate','Summe der Marktanteile der k größten Anbieter, etwa CR4. Sie zeigt die Bedeutung der größten Unternehmen, aber nicht die Anteilsverteilung innerhalb dieser Gruppe oder alle Eintritts- und Substitutionsmöglichkeiten.','economics-03','market-structures','concentration','CR4|Concentration Ratio'),
 G('Output Gap','Tatsächlicher realer Output abzüglich geschätztem Produktionspotenzial, geteilt durch dieses Potenzial. Eine negative Produktionslücke kann trotz positiven Wachstums bestehen oder größer werden. Potenzial ist modellabhängig und wird revidiert.','economics-05','cycles','output-gap','Produktionslücke'),
 G('Konjunkturzyklus','Wiederkehrende, aber nicht regelmäßig lange Bewegungen breiter realwirtschaftlicher Aktivität zwischen Expansion und Kontraktion. Peak und Trough sind Wendepunkte des Aktivitätsniveaus; langsameres positives Wachstum ist noch kein Niveauabschwung.','economics-05','cycles','phases','Konjunkturzyklen|Business Cycle'),
 G('Kreditzyklus','Wechselspiel von Kreditmenge, Vergabestandards, Risikoneigung und Sicherheitenwerten. Es kann reale Auf- und Abschwünge verstärken, verläuft aber nicht zwingend mit denselben Wendepunkten oder derselben Dauer wie der BIP-Zyklus.','economics-05','cycles','credit-cycle','Credit Cycle'),
 G('Akzeleratoreffekt','Mechanismus, bei dem Änderungen der erwarteten Produktion den gewünschten Kapitalbestand und damit Investitionen verändern. Im einfachen proportionalen Modell hängt Nettoinvestition von der Veränderung des erwarteten Outputs ab; langsameres Wachstum kann Investitionen senken, obwohl Output weiter steigt.','economics-05','cycles','demand-components','Accelerator Effect'),
 G('Lagerinvestition','Veränderung eines zu konsistenter Preisbasis gemessenen Lagerbestands während einer Periode. Ein weiter wachsender Bestand kann das Produktionswachstum bremsen, wenn die Lagerinvestition kleiner als in der Vorperiode wird.','economics-05','cycles','inventories','Lagerveränderung'),
 G('Lager-Umsatz-Relation','Lagerbestand relativ zum Absatz oder Umsatz eines angegebenen Zeitraums bei passender Bewertung. Bei Monatsumsatz kann sie als Anzahl Monatsumsätze gelesen werden. Sie steigt auch, wenn Absatz fällt und der Bestand unverändert bleibt.','economics-05','cycles','inventories','Inventory-to-Sales Ratio|ISR'),
 G('Erwerbsbeteiligungsquote','Arbeitskräfteangebot aus Erwerbstätigen und statistisch Arbeitslosen relativ zur nach der jeweiligen Statistik relevanten Bevölkerung. Sinkende Beteiligung kann eine niedrigere Arbeitslosenquote erklären, ohne dass mehr Arbeitsplätze entstanden sind.','economics-05','cycles','resources','LFPR|Labor Force Participation Rate'),
 G('Diffusionsindex','Maß dafür, wie verbreitet Verbesserungen oder Verschlechterungen über Befragte oder Teilreihen sind. In einer einfachen Konvention zählt Verbesserung voll und unverändert halb. Ein Wert von 55 ist keine Wachstumsrate von 5 %.','economics-05','cycles','indicators','Diffusion Index'),
 G('Deleveraging','Abbau von Verschuldung oder wirtschaftlichem Hebel. Ein Verlust an Vermögenswerten kann bei unveränderten Schulden den Bilanzhebel zunächst erhöhen; die Rückkehr zum Hebelziel kann dann große Verkäufe oder neues Eigenkapital erfordern.','economics-05','cycles','leverage','Bilanzabbau'),
 G('LTV','Loan-to-Value: Kredit- oder Schuldenbetrag geteilt durch den passend bewerteten Sicherheiten- bzw. Vermögenswert. Bei konstanten Schulden steigt die Quote, wenn der Nenner fällt. Sie ist nicht mit dem Hebel Vermögen/Eigenkapital identisch.','economics-05','cycles','leverage','Loan-to-Value|Beleihungsquote'),
 G('Fiskalpolitik','Entscheidungen über öffentliche Einnahmen und Ausgaben einschließlich Käufen, Investitionen und Transfers. Sie beeinflusst Nachfrage, Verteilung und gegebenenfalls langfristige Produktionsmöglichkeiten; ein größerer beobachteter Haushaltssaldo allein trennt automatische Konjunktureffekte noch nicht von neuen Entscheidungen.','economics-08','fiscal','policy-map'),
 G('Fiskalmultiplikator','Änderung des Outputs relativ zu einer definierten Änderung eines fiskalischen Instruments. Der Ausgabenmultiplikator bezieht sich auf Staatskäufe, der Steuermultiplikator auf die spezifizierte Steueränderung. Größe und Vorzeichen hängen von Modell, Zeithorizont, Leckagen und Gegenreaktionen ab.','economics-08','fiscal','multipliers','Ausgabenmultiplikator|Steuermultiplikator|Fiskalmultiplikatoren'),
 G('Marginale Konsumneigung','Anteil einer zusätzlichen Einheit verfügbaren Einkommens, der für Konsum verwendet wird. Sie unterscheidet sich vom durchschnittlichen Konsum-Einkommens-Verhältnis und kann zwischen Haushalten sowie vorübergehenden und dauerhaften Einkommensänderungen variieren.','economics-08','fiscal','multipliers','MPC|Marginal Propensity to Consume'),
 G('Automatische Stabilisatoren','Unter unveränderten Regeln konjunkturabhängig reagierende Einnahmen und Ausgaben, etwa sinkende Nettosteuern bei schwachem Einkommen. Sie puffern private Einkommensänderungen, ohne für jeden Ausschlag einen neuen politischen Beschluss zu benötigen.','economics-08','fiscal','stabilizers','Automatic Stabilizers'),
 G('Diskretionäre Fiskalpolitik','Ausdrückliche Veränderung fiskalischer Regeln, Programme oder Instrumente durch neue Entscheidungen. Sie ist von der automatischen Reaktion eines bestehenden Haushalts auf schwächere oder stärkere Aktivität zu trennen.','economics-08','fiscal','stabilizers'),
 G('Primärsaldo','Staatseinnahmen minus staatliche Ausgaben ohne Zinszahlungen. Positive Werte sind Primärüberschüsse, negative Primärdefizite. Ein Primärüberschuss kann mit einem Gesamtdefizit und einer steigenden Schuldenquote zusammenfallen.','economics-08','fiscal','stance','Primärüberschuss|Primärdefizit|Primary Balance'),
 G('Struktureller Saldo','Geschätzter Haushaltssaldo nach Bereinigung um Konjunktureffekte und nach der verwendeten Methodik bestimmte Einmalfaktoren. Änderungen helfen die Politikrichtung einzuschätzen, hängen aber von Potenzialschätzung, Abgrenzung und Zusammensetzung ab.','economics-08','fiscal','stance','Strukturelles Defizit'),
 G('Schuldenquote','Ein definierter Schuldenbestand geteilt durch einen geeigneten Maßstab; beim Staat meist nominale Staatsschuld relativ zum nominalen BIP. Eine steigende Schuld kann bei noch stärker wachsendem BIP mit einer fallenden Quote einhergehen.','economics-08','fiscal','debt-dynamics','Debt-to-GDP Ratio'),
 G('Stock-Flow Adjustments','Bestandsänderungen, die die Differenz zwischen dem gewählten periodischen Finanzierungssaldo und der Veränderung des Schuldenstands erklären, etwa Bewertungsänderungen oder bestimmte Finanztransaktionen. Vorzeichen und Abgrenzung müssen zur Budgetgleichung passen.','economics-08','fiscal','debt-dynamics','SFA'),
 G('Crowding-out','Verdrängung privater Aktivität durch eine andere Nachfrage- oder Finanzierungsbeanspruchung, etwa höhere Staatsnachfrage bei knappen Ressourcen oder steigenden Finanzierungskosten. Stärke hängt von Auslastung, Geldpolitik, Kapitalmobilität und privaten Reaktionen ab.','economics-08','fiscal','crowding-out','Verdrängungseffekt'),
 G('Ricardianische Äquivalenz','Theoretischer Neutralitätsfall, in dem Haushalte bei unverändertem Staatsausgabenpfad eine kreditfinanzierte Steuersenkung wegen erwarteter späterer Steuern sparen. Voraussetzungen wie geeignete Horizonte und fehlende Kreditbeschränkungen sind entscheidend; die Aussage gilt nicht ohne sie.','economics-08','fiscal','crowding-out','Ricardian Equivalence'),
 G('Erkennungsverzögerung','Zeit bis zur hinreichend verlässlichen Diagnose eines wirtschaftlichen Problems. Veröffentlichungsverzug, Revisionen und widersprüchliche Signale können die Erkennung verzögern. Sie ist von Entscheidung, Umsetzung und späterer Wirkung zu unterscheiden.','economics-08','fiscal','implementation','Recognition Lag'),
 G('Umsetzungsverzögerung','Zeit zwischen einem beschlossenen Eingriff und seiner tatsächlichen Ausführung, beispielsweise durch Vergabe, Verwaltung oder Bauplanung. Eine bewilligte Ausgabe ist noch keine erbrachte Leistung.','economics-08','fiscal','implementation','Implementation Lag'),
 G('Geldpolitik','Zentralbankentscheidungen über monetäre Instrumente und Bedingungen innerhalb eines Mandats. Sie wirkt über Zinsen, Erwartungen, Finanzierung, Vermögenspreise und Wechselkurse; der instrumentelle Schritt ist noch kein garantierter Wachstums- oder Inflationserfolg.','economics-07','monetary','tools'),
 G('Lender of Last Resort','Bereitstellung von Liquidität durch die Zentralbank in Stresssituationen unter bestimmten Zugangs- und Sicherheitenbedingungen. Ein Liquiditätsengpass und fehlendes wirtschaftliches Eigenkapital sind unterschiedliche Probleme; die Funktion ist keine pauschale Verlustgarantie.','economics-07','monetary','roles','Kreditgeber letzter Instanz'),
 G('Disinflation','Rückgang einer weiterhin positiven Inflationsrate. Das allgemeine Preisniveau steigt noch, nur langsamer. Sie ist von Deflation, also einem sinkenden Preisniveau, zu unterscheiden.','economics-07','monetary','objectives'),
 G('Deflation','Rückgang des allgemeinen Preisniveaus über den betrachteten Zeitraum. Einzelne billiger werdende Güter reichen für die Aussage nicht aus. Deflationserwartung kann den Realzins trotz niedrigem Nominalzins erhöhen.','economics-06','monetary','objectives'),
 G('Geldbasis','Im vereinfachten Modell Bargeld beim Publikum plus Reserven der Geschäftsbanken. Sie ist von breiten Geldmengen einschließlich Kundeneinlagen zu unterscheiden; beide Größen müssen nicht proportional wachsen.','economics-07','monetary','reserves','Monetary Base'),
 G('Geldschöpfungsmultiplikator','Verhältnis einer definierten breiten Geldmenge zur Geldbasis im jeweiligen Modell. Bargeldhaltung und Überschussreserven verändern die Relation. Der Kehrwert der Mindestreservequote ist nur ein restriktiver Sonderfall, keine allgemeine Prognoseregel für Bankkredite.','economics-07','monetary','reserves','Money Multiplier'),
 G('Offenmarktgeschäfte','Zentralbanktransaktionen in Finanzinstrumenten, beispielsweise endgültige Käufe/Verkäufe oder befristete besicherte Geschäfte. Sie beeinflussen Reserven und/oder Wertpapierbestände. Ihr geldpolitischer Zweck hängt vom operativen Rahmen und der übrigen Politik ab.','economics-07','monetary','tools','Open Market Operations'),
 G('Neutraler Realzins','Modellabhängiger realer Zins, der bei stabiler Inflation mit normal ausgelasteter Wirtschaft vereinbar wäre. Er ist nicht direkt beobachtbar. Die geldpolitische Restriktion wird häufig relativ zu diesem veränderlichen Vergleichswert beurteilt.','economics-07','monetary','real-rate','Neutral Real Rate'),
 G('Laufzeitprämie','Renditekomponente über den erwarteten Pfad kurzfristiger Zinsen hinaus als Ausgleich für das Halten einer längeren Zinsposition. Sie kann sich mit Risiko, Angebot und Nachfrage verändern; eine langfristige Rendite bildet deshalb nicht nur den aktuellen Leitzins ab.','economics-07','monetary','yield-curve','Term Premium'),
 G('Transmission','Übertragung eines geldpolitischen Eingriffs über Finanzbedingungen und Erwartungen auf Ausgaben, Aktivität und Preise. Geschwindigkeit und Stärke hängen unter anderem von Kreditverträgen, Bankbilanzen, Erwartungen und Schockart ab.','economics-07','monetary','transmission','Monetäre Transmission|Transmission Mechanism'),
 G('Schuldendienst','Zinszahlungen plus fällige Tilgungen über einen angegebenen Zeitraum. Eine Tragfähigkeitskennzahl setzt diesen Betrag beispielsweise zum Einkommen ins Verhältnis; Zinsbindung und Fälligkeiten beeinflussen die zeitliche Belastung.','economics-05','monetary','transmission','Debt Service'),
 G('Umlaufgeschwindigkeit','In der Einkommensversion der Quantitätsgleichung nominales Einkommen geteilt durch die definierte Geldmenge. Sie kann sich durch Geldnachfrage und Zahlungsgewohnheiten verändern; konstante Geschwindigkeit ist eine zusätzliche Modellannahme.','economics-07','monetary','quantity','Velocity'),
 G('Quantitätsgleichung','Identität MV = PY zwischen Geldmenge, Einkommensumlaufgeschwindigkeit und nominalem Einkommen. Für eine kausale Inflationsaussage sind weitere Annahmen über die Geldmenge, reales Wachstum und Umlaufgeschwindigkeit erforderlich.','economics-07','monetary','quantity','Quantity Equation'),
 G('Instrumentenunabhängigkeit','Möglichkeit einer Zentralbank, den Einsatz ihrer Instrumente innerhalb eines vorgegebenen Mandats selbst zu bestimmen. Sie ist von der Freiheit, Ziele selbst festzulegen, und von fehlender Rechenschaftspflicht zu unterscheiden.','economics-07','monetary','credibility','Instrument Independence'),
 G('Forward Guidance','Kommunikation über den erwarteten oder bedingten zukünftigen Politikpfad. Sie kann heutige Finanzierungskonditionen über Erwartungen verändern. Wirkung und spätere Beurteilung hängen von Glaubwürdigkeit und der genauen Bedingtheit der Aussage ab.','economics-07','monetary','unconventional'),
 G('Quantitative Lockerung','Umfangreiche Zentralbankkäufe von Wertpapieren, die etwa Laufzeitprämien, Marktliquidität und Erwartungen beeinflussen sollen. Geschaffene Reserven erzeugen nicht automatisch einen proportionalen Anstieg privater Kredite oder Konsumausgaben.','economics-07','monetary','unconventional','QE|Quantitative Easing'),
 G('Quantitative Straffung','Reduktion von Zentralbankwertpapierbeständen, etwa durch Verkäufe oder ausbleibende Wiederanlage. Wirkung hängt von Tempo, Instrumentenmix und Marktbedingungen ab; ein bestimmter Bilanzabbau entspricht keinem universell festen Zinsschritt.','economics-07','monetary','unconventional','QT|Quantitative Tightening'),
 G('Liquiditätsfalle','Situation, in der zusätzliche liquide Guthaben bzw. konventionelle Lockerung nur schwach in zusätzliche Nachfrage übersetzt werden, häufig bei sehr niedrigen Zinsen. Daraus folgt nicht, dass jede denkbare geld- und fiskalpolitische Maßnahme wirkungslos ist.','economics-07','monetary','limits','Liquidity Trap'),
 G('Effektive Zinsuntergrenze','Praktische Grenze weiterer konventioneller nominaler Zinssenkungen im jeweiligen System. Sie hängt unter anderem von Bargeldalternativen, Bilanzwirkungen und institutionellen Kosten ab und muss nicht exakt null sein.','economics-07','monetary','limits','Effective Lower Bound'),
 G('Fiskalische Dominanz','Situation, in der Anforderungen staatlicher Finanzierung eine eigenständige geldpolitische Verfolgung der Preisstabilität einschränken. Sie ist eine institutionelle Wechselwirkung und nicht identisch mit jedem vorübergehenden Haushaltsdefizit.','economics-07','monetary','limits','Fiscal Dominance'),
 G('Künstliche Intelligenz','Oberbegriff für technische Systeme, die Aufgaben wie Mustererkennung, Sprachverarbeitung, Schlussfolgern oder Entscheidungsunterstützung bearbeiten. Machine Learning ist ein möglicher Ansatz innerhalb der KI; eine plausible Ausgabe ist noch kein Beleg für Wahrheit oder fachlich geeignete Entscheidungen.','quant-14','data-science','map','KI|Artificial Intelligence|AI'),
 G('Deep Learning','Machine Learning mit mehrschichtigen neuronalen Netzen. Die Modelle können komplexe Text-, Bild- oder andere Muster erfassen, benötigen aber geeignete Daten, Validierung und eine Kontrolle von Überanpassung und Einsatzgrenzen.','quant-14','data-science','map'),
 G('Generative KI','Systeme, die aus gelernten Mustern und Eingaben neue Inhalte wie Texte oder Bilder erzeugen. Eine verständliche Zusammenfassung kann unbelegte Aussagen oder Rechenfehler enthalten; Quellenabruf, Generierung und Faktenprüfung sind unterschiedliche Funktionen.','quant-14','data-science','text-ai','Generative AI'),
 G('Clustering','Unüberwachtes Gruppieren von Beobachtungen anhand einer festgelegten Ähnlichkeits- oder Distanzstruktur. Die Gruppen entstehen ohne vorgegebene Zielklasse; ihre Existenz beweist keine gemeinsame zukünftige Rendite oder kausale Beziehung.','quant-14','data-science','learning-types','Clusteranalyse'),
 G('Supervised Learning','Überwachtes Lernen mit zu den Trainingsmerkmalen gehörenden bekannten Zielwerten. Regression behandelt numerische Ziele, Klassifikation Klassen oder Ereignisse. Der Begriff bedeutet nicht, dass ein Mensch jede spätere Einzelprognose überwacht.','quant-14','data-science','learning-types','Überwachtes Lernen|Supervised Regression|Supervised Classification'),
 G('Unsupervised Learning','Unüberwachtes Lernen aus Merkmalen ohne vorgegebene Zielwerte, etwa Clustering oder Dimensionsreduktion. Ein gefundener Datenzusammenhang muss anschließend wirtschaftlich interpretiert werden und ist noch kein Prognosenachweis.','quant-14','data-science','learning-types','Unüberwachtes Lernen'),
 G('Reinforcement Learning','Lernverfahren, das Handlungen in Zuständen anhand von Belohnungen über Entscheidungsfolgen beurteilt. Die Definition der Belohnung, Exploration und Realitätsnähe der Lernumgebung bestimmen wesentlich, ob eine Strategie im tatsächlichen Einsatz sinnvoll ist.','quant-14','data-science','learning-types','Bestärkendes Lernen'),
 G('Fintech','Technologiegestützte Finanzprodukte und Finanzprozesse, beispielsweise digitale Zahlungen, Beratung, Recherche oder Risikoanalyse. Der Begriff bezeichnet ein Anwendungsfeld und ist nicht mit KI, Machine Learning oder Big Data gleichzusetzen.','quant-14','data-science','map'),
 G('Underfitting','Unzureichende Anpassungsfähigkeit eines Modells für die relevante Struktur der Daten. Ein zu einfaches oder zu stark beschränktes Modell kann systematische Muster übersehen und sowohl auf Trainings- als auch auf neuen Daten schlechte Ergebnisse liefern.','quant-14','data-science','overfitting','Unteranpassung'),
 G('Accuracy','Anteil korrekt klassifizierter Fälle an allen ausgewerteten Fällen. Bei seltenen Ereignissen kann eine Regel, die nie das Ereignis meldet, eine hohe Accuracy besitzen und dennoch jeden relevanten Fall verpassen.','quant-14','data-science','classification','Gesamttrefferrate'),
 G('Imputation','Begründetes Ersetzen fehlender Datenwerte, etwa durch eine aus Trainingsdaten geschätzte Regel. Fehlend ist nicht automatisch null. Die Anpassung einer Imputationsregel an zurückgehaltene Testdaten kann ein Informationsleck erzeugen.','quant-14','data-science','pipeline'),
 G('RMSE','Root Mean Squared Error: Quadratwurzel des mittleren quadrierten Prognosefehlers. Er hat die Einheit der numerischen Zielgröße und gewichtet große Fehler stark. Vergleichbar ist er nur bei passender Zielskala und Evaluationsstichprobe.','quant-14','data-science','probability-quality','Root Mean Squared Error'),
 G('Homoskedastizität','Konstante bedingte Varianz des Regressionsfehlers über die betrachteten Beobachtungen. Sie ist eine Voraussetzung der üblichen klassischen Standardfehlerformeln; ihre Verletzung heißt Heteroskedastizität.','quant-09','regression','assumptions','Homoskedasticity'),
 G('Percentile-Intervall','Bootstrap-Intervall, dessen Grenzen direkt aus den passenden Quantilen der Bootstrap-Schätzwerte stammen. Nominales Niveau und tatsächliche Überdeckung können bei Bias, kleinen Stichproben oder ungeeignetem Resampling voneinander abweichen.','quant-12','simulation','bootstrap-uncertainty','Percentile Interval'),
 G('Feature Importance','Kennzahl oder Verfahren zur Beschreibung des Beitrags eines Eingabemerkmals zur Modellprognose nach einer bestimmten Definition. Bei korrelierten Merkmalen kann sich die zugeschriebene Bedeutung verschieben. Ein hoher Wert beweist keine kausale Wirkung.','quant-14','data-science','text-ai','Merkmalsbedeutung'),
 G('HAC-Standardfehler','Schätzungen der Koeffizientenunsicherheit, die unter geeigneten Voraussetzungen Heteroskedastizität und Autokorrelation berücksichtigen. Ihre Eignung hängt von Verfahren und Abhängigkeitsstruktur ab; sie reparieren keine Endogenität oder falsche Mittelwertfunktion.','quant-09','regression','assumptions','HAC'),
 G('Texttokenisierung','Zerlegung von Text in verarbeitbare Einheiten wie Wörter, Wortteile oder Zeichenfolgen nach einer bestimmten Regel. Sie ist ein Vorbereitungsschritt der Sprachverarbeitung und etwas anderes als die digitale Abbildung von Vermögensrechten durch Token.','quant-14','data-science','text-ai','Text Tokenization'),
 G('OLS','Ordinary Least Squares: Schätzverfahren, das die Summe quadrierter vertikaler Abweichungen zwischen beobachteten und angepassten Zielwerten minimiert. In der einfachen Regression mit Intercept verläuft die Gerade durch die Stichprobenmittelwerte. Diese Recheneigenschaften beweisen keine Kausalität oder korrekte Modellspezifikation.','quant-09','regression','least-squares','Kleinste Quadrate|Ordinary Least Squares'),
 G('Intercept','Achsenabschnitt einer Regressionsfunktion: angepasster Wert der Zielgröße bei erklärender Variable null. Er hat die Einheit der Zielgröße. Liegt null außerhalb des beobachteten Bereichs, kann seine direkte wirtschaftliche Interpretation eine riskante Extrapolation sein.','quant-09','regression','model','Achsenabschnitt'),
 G('Residuum','Beobachteter Zielwert minus angepasster Modellwert. Ein positives Residuum liegt oberhalb der geschätzten Funktion. Es ist von dem unbeobachteten Fehler um die wahre Populationsfunktion zu unterscheiden.','quant-09','regression','model','Residual'),
 G('ANOVA','Analysis of Variance: In der Regression Zerlegung der zentrierten Zielvariation in erklärte und Residuenvariation, jeweils mit passenden Freiheitsgraden. Die daraus gebildeten mittleren Quadratsummen dienen unter geeigneten Voraussetzungen zur Modellbeurteilung und zum F-Test.','quant-09','regression','anova','Varianzanalyse'),
 G('Bestimmtheitsmaß','R² misst bei OLS mit Intercept den Anteil der in der Stichprobe erklärten zentrierten Zielvariation. Bei einfacher Regression ist es die quadrierte Stichprobenkorrelation. Ein hohes R² beweist weder Kausalität noch gute Prognosen außerhalb der Schätzstichprobe.','quant-09','regression','anova','R-squared|R²'),
 G('Standard Error of Estimate','Geschätzte Standardabweichung des Regressionsfehlers. In der einfachen Regression mit Intercept wird die Residuenquadratsumme durch n−2 geteilt und daraus die Wurzel gezogen. Die Einheit entspricht der Zielvariable; es ist nicht dasselbe wie der Standardfehler eines einzelnen Koeffizienten.','quant-09','regression','anova','Residual Standard Error'),
 G('Heteroskedastizität','Nicht konstante bedingte Fehlervarianz über Beobachtungen. Bei weiterhin korrekt spezifiziertem exogenem Mittelwertmodell macht sie OLS-Koeffizienten nicht automatisch verzerrt, kann aber die üblichen homoskedastischen Standardfehler und Tests ungültig machen.','quant-09','regression','assumptions','Heteroskedasticity'),
 G('Exogenität','Hier die Annahme eines bedingten Fehlererwartungswerts von null bei gegebenen erklärenden Variablen. Sie schließt einen systematischen, mit den Regressoren zusammenhängenden ausgelassenen Fehlerbeitrag aus. Sie folgt nicht daraus, dass geschätzte OLS-Residuen rechnerisch orthogonal zu den Regressoren sind.','quant-09','regression','assumptions','Exogeneity'),
 G('Endogenität','Verknüpfung erklärender Variablen mit dem nicht erfassten Fehlerbeitrag, beispielsweise durch ausgelassene gemeinsame Einflussgrößen oder umgekehrte Kausalität. Übliche kausale Koeffizienteninterpretationen können dadurch scheitern; robuste Standardfehler lösen dieses Problem nicht.','quant-09','regression','assumptions','Endogeneity'),
 G('Prognoseintervall','Bereich für eine neue einzelne Beobachtung unter einem angegebenen Modell und Niveau. In der klassischen Regression enthält seine Unsicherheit sowohl die Parameterschätzunsicherheit als auch die zusätzliche Fehlerstreuung der neuen Beobachtung. Es ist breiter als das zugehörige Intervall für den bedingten Mittelwert.','quant-09','regression','prediction','Prediction Interval'),
 G('Extrapolation','Verwendung einer angepassten Funktion außerhalb des beobachteten Eingangsbereichs. Der größere Abstand kann die formale Schätzunsicherheit erhöhen; zusätzlich kann die angenommene Beziehung dort nicht mehr gelten.','quant-09','regression','prediction'),
 G('Alpha','Im angegebenen Renditemodell der Intercept bzw. die durchschnittliche Renditekomponente, die durch die verwendeten Risikofaktoren nicht erklärt wird. In der Marktregression ist es mittlere Asset-Überschussrendite minus Beta mal mittlere Markt-Überschussrendite. Ein positives geschätztes Alpha hängt von Zeitraum, Gebühren, Benchmark und Modell ab und beweist ohne Unsicherheitsprüfung kein Können. Deshalb ist ein einzelnes gutes Jahr noch kein Nachweis eines dauerhaft positiven Alpha.','portfolio-04','regression','capm','Jensen-Alpha'),
 G('Beta','Sensitivität einer Asset-Überschussrendite gegenüber der Markt-Überschussrendite im gewählten Marktmodell. Es wird als Kovarianz der beiden Reihen geteilt durch Marktvarianz geschätzt. Beta 1,5 bedeutet eine modellierte Veränderung von 1,5 Prozentpunkten je zusätzlichem Markt-Prozentpunkt, nicht automatisch eine Gesamtvolatilität von 150 %.','portfolio-04','regression','capm'),
 G('Log–log-Modell','Regressionsform, in der sowohl Zielgröße als auch erklärende Größe logarithmiert werden. Die Steigung beschreibt eine lokale Elastizität. Für endliche Änderungen ergibt sich das Verhältnis angepasster Niveaus aus dem X-Verhältnis hoch Steigung.','quant-09','regression','functional-forms','Log-Log'),
 G('Historische Simulation','Anwendung beobachteter gemeinsamer Risikofaktorschocks auf ein heutiges Portfolio. Gleichzeitige Beobachtungen bewahren die empirische Abhängigkeit; nichtlineare Positionen können eine vollständige Neubewertung benötigen. Die Methode bleibt von Repräsentativität und Umfang der Historie abhängig.','quant-12','simulation','historical','Historical Simulation'),
 G('Bootstrap','Resampling-Verfahren zur Approximation der Unsicherheit einer Schätzstatistik anhand vorhandener Daten. Im gewöhnlichen iid-Bootstrap werden gleich große Stichproben mit Zurücklegen gezogen. Paare, Cluster oder Zeitabhängigkeit benötigen gegebenenfalls andere Resampling-Einheiten.','quant-12','simulation','bootstrap','Bootstrapping'),
 G('Monte Carlo','Numerisches Verfahren, das Zufallsszenarien aus einem festgelegten Modell erzeugt und daraus Größen wie Erwartungswerte oder Wahrscheinlichkeiten schätzt. Mehr unabhängige Szenarien verringern Rechenunsicherheit, beseitigen aber keine falschen Modellannahmen.','quant-12','simulation','monte-carlo','Monte-Carlo-Simulation'),
 G('Block-Bootstrap','Resampling zusammenhängender Datenabschnitte statt einzelner Fälle, um relevante zeitliche Abhängigkeit innerhalb der Blöcke zu erhalten. Blocklänge und Prozessstabilität beeinflussen die Eignung; die Methode erhält nicht automatisch jede langfristige Abhängigkeit.','quant-12','simulation','bootstrap-uncertainty','Block Bootstrap'),
 G('Full Revaluation','Vollständige Neubewertung einer Position oder eines Portfolios nach einem Szenarioschock. Sie kann nichtlineare Preisreaktionen erfassen, benötigt aber ein geeignetes Bewertungsmodell, korrekte gemeinsame Risikofaktoren und eine klare Behandlung des Zeitablaufs.','quant-12','simulation','historical-limits'),
 G('Geometrische Brownsche Bewegung','Positives Preisprozess-Modell mit normalverteilten unabhängigen Logschritten bei konstantem Drift und konstanter Volatilität. Der Logdrift ist um die halbe Volatilität zum Quadrat niedriger als der arithmetische Driftparameter. Sprünge und wechselnde Volatilität sind im Grundmodell nicht enthalten.','quant-12','simulation','price-model','GBM|Geometric Brownian Motion'),
 G('Seed','Startwert eines Pseudozufallszahlengenerators. Bei gleichem Generator und identischem Ablauf ermöglicht er die Wiederholung desselben Zahlenstroms. Er ist kein Nachweis für gute Modellannahmen, unabhängige Daten oder korrekte Wahrscheinlichkeiten.','quant-12','simulation','monte-carlo'),
 G('Simulationsfehler','Numerische Unsicherheit eines aus endlich vielen Simulationen berechneten Ergebnisses. Für einen Mittelwert unabhängiger Szenarien mit endlicher Varianz fällt sein Standardfehler mit der Wurzel der Szenariozahl. Er ist von tatsächlichem Marktrisiko und Modellfehler zu unterscheiden.','quant-12','simulation','simulation-error','Monte Carlo Error'),
 G('Risikoneutrales Maß','Bewertungsmaß, unter dem passend diskontierte handelbare Preisprozesse unter geeigneten Arbitrageannahmen Martingale sind. Es dient der konsistenten Bewertung und ist nicht automatisch die Realweltverteilung künftiger Renditen oder eine Behauptung über tatsächliche Anlegerpräferenzen.','quant-12','simulation','pricing','Risk-Neutral Measure'),
 G('Machine Learning','Verfahren, bei denen Regeln oder Modellparameter aus Daten gelernt werden. Je nach Aufgabe werden bekannte Zielwerte, unbeschriftete Strukturen oder Handlungsbelohnungen verwendet. Gute Trainingsanpassung allein belegt keine Leistung auf neuen Daten.','quant-14','data-science','learning-types','Maschinelles Lernen'),
 G('Big Data','Datenumgebungen mit hohem Umfang, hoher Entstehungsgeschwindigkeit und/oder vielfältigen Formaten. Qualität, Herkunft und wirtschaftlicher Nutzen bleiben zusätzliche zentrale Fragen. Viele Datensätze sind nicht automatisch viele unabhängige Informationen.','quant-14','data-science','big-data'),
 G('Feature','Eingabemerkmal eines Modells, etwa eine zum Prognosezeitpunkt bekannte Bilanzkennzahl oder ein Textmerkmal. Seine Konstruktion muss dieselben Informationsgrenzen wie die spätere Entscheidung beachten.','quant-14','data-science','pipeline','Merkmal'),
 G('Label','Vorgegebener Zielwert eines überwachten Lernverfahrens, etwa Ausfall im folgenden Zwölfmonatsfenster. Definition, Messhorizont und zeitliche Verfügbarkeit des Labels bestimmen die tatsächliche Prognoseaufgabe.','quant-14','data-science','pipeline','Zielvariable'),
 G('Data Leakage','Unzulässiger Informationsfluss aus späteren oder zur Bewertung zurückgehaltenen Daten in Modellvorbereitung oder Modellauswahl. Er kann auch durch Skalierung, Imputation, Merkmalsauswahl oder überlappende Zielzeiträume entstehen und führt oft zu zu optimistischer Testleistung.','quant-14','data-science','time-split','Informationsleck'),
 G('Point-in-time-Daten','Daten, die den zum jeweiligen historischen Entscheidungszeitpunkt tatsächlich verfügbaren Informationsstand abbilden. Veröffentlichungslags und spätere Revisionen werden unterschieden; das Bilanzstichtagsdatum allein genügt nicht.','quant-14','data-science','time-split','Point in Time'),
 G('Overfitting','Übermäßige Anpassung an Besonderheiten und Zufall der Trainingsdaten, die außerhalb der Stichprobe nicht fortbestehen. Mehr Komplexität kann den Trainingsfehler senken und die zukünftige Vorhersage dennoch verschlechtern.','quant-14','data-science','overfitting','Überanpassung'),
 G('Regularisierung','Begrenzung der Anpassungsfreiheit eines Modells, häufig durch eine zusätzliche Strafe für Komplexität oder große Koeffizienten. Das Strafgewicht wird mit geeigneter Validierung gewählt; Regularisierung repariert kein Datenleck und keine falsche Zieldefinition.','quant-14','data-science','learning-types','Regularization'),
 G('Hyperparameter','Einstellung des Lernverfahrens, etwa eine Regularisierungsstärke oder Baumtiefe, die nicht einfach als gewöhnlicher Modellkoeffizient in derselben Anpassung geschätzt wird. Ihre Auswahl gehört zur Modellentwicklung und darf den abschließenden Test nicht verbrauchen.','quant-14','data-science','time-split'),
 G('Precision','Anteil tatsächlicher positiver Fälle unter den positiv vorhergesagten Fällen. Bei Ausfallwarnungen ist dies der Anteil tatsächlicher Ausfälle unter allen Warnungen. Die Basisrate beeinflusst die Kennzahl stark; sie ist nicht mit Sensitivität oder Falsch-Positiv-Rate gleichzusetzen.','quant-14','data-science','classification','Positiver Vorhersagewert'),
 G('Recall','Anteil erkannter positiver Fälle unter allen tatsächlich positiven Fällen. Bei Ausfällen beschreibt er, wie viele tatsächliche Ausfälle gewarnt wurden. Er ist auch als Sensitivität bekannt und sagt allein wenig über die Zahl falscher Warnungen aus.','quant-14','data-science','classification','Sensitivität'),
 G('Kalibrierung','Bei Wahrscheinlichkeitsprognosen die Übereinstimmung angegebener Wahrscheinlichkeiten mit empirischen Ereignishäufigkeiten vergleichbarer Fälle. Gute Kalibrierung ist von der Fähigkeit zu unterscheiden, riskante und weniger riskante Fälle zu ordnen.','quant-14','data-science','probability-quality','Calibration'),
 G('Brier Score','Mittlerer quadrierter Abstand zwischen vorhergesagter Ereigniswahrscheinlichkeit und tatsächlichem binärem Ereignisindikator. Er bewertet die Gesamtqualität von Wahrscheinlichkeitsprognosen und ist keine reine isolierte Kalibrierungskennzahl.','quant-14','data-science','probability-quality'),
 G('Concept Drift','Veränderung des Zusammenhangs zwischen Eingabemerkmalen und Zielgröße im Zeitablauf. Ein Modell kann dadurch schlechter werden, obwohl die Verteilung seiner Eingaben ähnlich bleibt.','quant-14','data-science','overfitting'),
 G('Data Drift','Veränderung der Verteilung von Modelleingaben gegenüber der Entwicklungsphase. Sie kann auf einen neuen Einsatzbereich hinweisen, ist aber von einer Veränderung des bedingten Zielzusammenhangs zu unterscheiden.','quant-14','data-science','overfitting'),
 G('Natural Language Processing','Verfahren zur maschinellen Verarbeitung von Sprache, etwa Klassifikation, Informationsextraktion und Textrepräsentation. In Finanztexten sind Kontext, Negation, Zeitbezug, Firmenzuordnung und Veröffentlichungslags besonders wichtig.','quant-14','data-science','text-ai','NLP'),
 G('Embedding','Numerische Repräsentation von Objekten wie Texten, deren geometrische Beziehungen bestimmte gelernte Ähnlichkeiten ausdrücken. Nähe im Merkmalsraum beweist keine wirtschaftliche Gleichwertigkeit oder Wahrheit einer Aussage.','quant-14','data-science','text-ai','Embeddings'),
 G('Standardfehler','Standardabweichung der Stichprobenverteilung eines Schätzers. Beim Mittel unabhängiger gleich verteilter Beobachtungen entspricht er der Populationsstandardabweichung geteilt durch die Wurzel der Fallzahl; bei unbekannter Streuung wird er geschätzt. Er beschreibt Schätzunsicherheit, nicht unmittelbar die Streuung einzelner Renditen.','quant-07','inference','estimators','Standard Error'),
 G('Stichprobenverteilung','Verteilung eines Schätzers über gedachte Wiederholungen desselben Stichprobenverfahrens. Sie ist von der Verteilung einzelner Beobachtungen zu unterscheiden und liefert die Grundlage für Standardfehler, Intervalle und Tests.','quant-07','inference','estimators','Sampling Distribution'),
 G('Geschichtete Stichprobe','Zufallsauswahl innerhalb vorab definierter Teilgruppen einer Population. Alle relevanten Schichten werden berücksichtigt; unterschiedliche Stichprobenanteile können für Aussagen über die Gesamtpopulation eine Gewichtung erfordern.','quant-07','inference','sampling','Stratified Random Sampling'),
 G('Clusterstichprobe','Auswahl ganzer natürlicher Gruppen, gegebenenfalls mit weiterer Auswahl innerhalb dieser Gruppen. Ähnliche Beobachtungen im selben Cluster liefern weniger unabhängige Information als dieselbe Anzahl unabhängig gezogener Fälle.','quant-07','inference','sampling','Cluster Sampling'),
 G('Zentraler Grenzwertsatz','Unter geeigneten Bedingungen nähert sich die Verteilung eines standardisierten Stichprobenmittels bei wachsender Fallzahl der Standardnormalverteilung. Die Verteilung der Einzelbeobachtungen wird dadurch nicht normal. Eine universelle ausreichende Mindestfallzahl gibt es nicht.','quant-07','inference','clt','Central Limit Theorem|CLT'),
 G('Konfidenzintervall','Mit einer festgelegten Überdeckungsregel aus Daten berechneter Bereich für einen Parameter. Ein 95-%-Verfahren enthält unter seinen Voraussetzungen in 95 % wiederholter Stichproben den wahren Parameter. Es ist weder automatisch ein Vorhersageintervall noch eine bayesianische Posterior-Aussage.','quant-07','inference','intervals','Confidence Interval'),
 G('Nullhypothese','Die im Test als Referenz geprüfte Behauptung über einen Parameter oder eine Verteilung. Ihre Nichtverwerfung beweist sie nicht; ihre Verwerfung hängt von Daten, Testregel und Modellannahmen ab.','quant-08','inference','test-logic','Null Hypothesis'),
 G('Alternativhypothese','Die zur Nullhypothese konkurrierende Aussage, etwa ein von null verschiedener oder ausdrücklich größerer Mittelwert. Einseitige oder zweiseitige Richtung muss vor Betrachtung des Testergebnisses sachlich festgelegt werden.','quant-08','inference','test-logic','Alternative Hypothesis'),
 G('p-Wert','Wahrscheinlichkeit unter dem Nullmodell, eine mindestens so extreme Teststatistik wie die beobachtete zu erhalten. Er ist weder die Wahrscheinlichkeit, dass die Nullhypothese wahr ist, noch ein Maß der wirtschaftlichen Effektgröße.','quant-08','inference','p-values','p-value'),
 G('Signifikanzniveau','Vorab festgelegte Grenze für die Wahrscheinlichkeit einer Verwerfung einer wahren Nullhypothese unter den Testvoraussetzungen. Ein Niveau von 5 % beschreibt keine allgemeine Wahrscheinlichkeit, dass die konkrete Entscheidung falsch ist.','quant-08','inference','test-logic','Significance Level'),
 G('Fehler erster Art','Verwerfen einer tatsächlich wahren Nullhypothese. Das Signifikanzniveau kontrolliert seine Wahrscheinlichkeit unter den Modellannahmen. Mehrfaches Testen und nachträgliche Testauswahl können die tatsächliche Gesamtfehlalarmrate erhöhen.','quant-08','inference','errors-power','Type I Error|Fehler I'),
 G('Fehler zweiter Art','Nichtverwerfen der Nullhypothese, obwohl eine bestimmte Alternative wahr ist. Seine Wahrscheinlichkeit hängt unter anderem von Effektgröße, Streuung, Fallzahl und Testregel ab.','quant-08','inference','errors-power','Type II Error|Fehler II'),
 G('Teststärke','Wahrscheinlichkeit, bei einer konkret angegebenen wahren Alternative die Nullhypothese zu verwerfen. Sie entspricht eins minus Fehler-II-Wahrscheinlichkeit und ist ohne Benennung der Alternative keine vollständige Kennzahl.','quant-08','inference','errors-power','Power'),
 G('Gepaarter t-Test','Mittelwerttest auf den innerhalb zusammengehöriger Beobachtungspaare gebildeten Differenzen. Er nutzt deren Standardabweichung und benötigt geeignete Unabhängigkeit zwischen den Paaren. Gleiche Fallzahlen allein begründen noch keine Paarung.','quant-08','inference','paired','Paired t-Test'),
 G('Welch-Test','Test eines Mittelwertunterschieds zwischen unabhängigen Gruppen, der keine gleichen Populationsvarianzen verlangt. Er kombiniert getrennte Varianzschätzungen und verwendet näherungsweise, häufig nicht ganzzahlige Freiheitsgrade.','quant-08','inference','two-samples','Welch t-Test'),
 G('Spearman-Rangkorrelation','Pearson-Korrelation der Ränge zweier Variablen als Maß monotoner Übereinstimmung. Eine Kurzform mit quadrierten Rangdifferenzen gilt ohne Rangbindungen; bei Bindungen werden mittlere Ränge verwendet.','quant-10','inference','correlation-tests','Spearman Rank Correlation'),
 G('Mann-Whitney-Test','Rangbasierter Vergleich zweier unabhängiger Stichproben, auch Wilcoxon Rank Sum genannt. Er ist ohne zusätzliche Voraussetzungen über die Verteilungsformen nicht generell ein reiner Test gleicher Mediane.','quant-10','inference','rank-tests','Mann–Whitney|Wilcoxon Rank Sum'),
 G('Vorzeichentest','Nichtparametrischer Test, der bei geeigneten unabhängigen Differenzen positive und negative Vorzeichen zählt. Unter gleichen Vorzeichenwahrscheinlichkeiten folgt die positive Anzahl einer Binomialverteilung. Er nutzt keine Beträge der Unterschiede.','quant-10','inference','rank-tests','Sign Test'),
 G('Wilcoxon Signed Rank','Test für gepaarte Differenzen, der Vorzeichen und Ränge ihrer absoluten Beträge kombiniert. Die übliche Lageinterpretation setzt eine geeignete symmetrische Differenzverteilung voraus. Er ist vom Rank-Sum-Test unabhängiger Gruppen zu unterscheiden.','quant-10','inference','rank-tests'),
 G('Mehrfachtestproblem','Bei vielen geprüften Hypothesen steigt die Gelegenheit zu zufälligen auffälligen Ergebnissen. Die Gesamtfehlerwahrscheinlichkeit hängt auch von Abhängigkeiten und Auswahlregeln ab; nur das beste Ergebnis zu berichten unterschlägt diese Suche.','quant-08','inference','interpretation','Multiple Testing'),
 G('Bedingte Wahrscheinlichkeit','Wahrscheinlichkeit eines Ereignisses unter der Information, dass ein anderes Ereignis eingetreten ist. Die gemeinsame Wahrscheinlichkeit wird auf die Wahrscheinlichkeit der Bedingung normiert. Die umgekehrte Bedingung ergibt im Allgemeinen eine andere Zahl.','quant-06','distributions','probabilities','Conditional Probability'),
 G('Gemeinsame Verteilung','Wahrscheinlichkeiten zusammengehöriger Kombinationen mehrerer Zufallsgrößen. Einzelne Randverteilungen beschreiben jede Größe für sich, legen aber die Abhängigkeit zwischen ihnen nicht fest.','quant-06','distributions','joint','Joint Distribution'),
 G('Bedingter Erwartungswert','Wahrscheinlichkeitsgewichteter Mittelwert nach Einschränkung auf eine Information oder einen Zustand. Die verbleibenden bedingten Gewichte müssen eins ergeben; ursprüngliche gemeinsame Wahrscheinlichkeiten dürfen nicht unnormiert weiterverwendet werden.','quant-06','distributions','conditioning','Conditional Expectation'),
 G('Totale Varianz','Zerlegung unbedingter Varianz in die durchschnittliche Varianz innerhalb von Zuständen und die Varianz der zustandsabhängigen Mittelwerte. Nur die erste Komponente zu mitteln übersieht das Risiko zwischen den Zuständen.','quant-06','distributions','total-risk','Law of Total Variance'),
 G('Bernoulli-Verteilung','Verteilung eines Indikators mit den Werten eins bei Eintritt eines Ereignisses und null sonst. Der Parameter ist die Eintrittswahrscheinlichkeit. Der Indikator erfasst ohne Erweiterung keine unterschiedlichen Verlustbeträge.','quant-06','distributions','discrete','Bernoulli Distribution'),
 G('Binomialverteilung','Verteilung der Zahl eingetretener Ereignisse in einer festen Anzahl unabhängiger Versuche mit jeweils derselben Eintrittswahrscheinlichkeit. Gemeinsame Risikotreiber oder unterschiedliche Wahrscheinlichkeiten können diese Voraussetzungen verletzen.','quant-06','distributions','discrete','Binomial Distribution'),
 G('Normalverteilung','Symmetrische stetige Verteilungsfamilie mit Mittelwert als Lageparameter und positiver Standardabweichung als Skalenparameter. Ihr Wertebereich ist unbegrenzt. Standardisierung übersetzt Abstände in Einheiten der Standardabweichung, ohne die Verteilungsannahme zu beweisen.','quant-07','distributions','normal','Normal Distribution'),
 G('Lognormalverteilung','Verteilung einer strikt positiven Größe, deren natürlicher Logarithmus normalverteilt ist. Ihr Mittelwert liegt bei positiver Logvarianz über dem Median. Die Parameter des Logarithmus sind nicht unmittelbar Mittelwert und Varianz der ursprünglichen Größe.','quant-07','distributions','lognormal','Lognormal Distribution'),
 G('Prior','Wahrscheinlichkeitsannahme vor Berücksichtigung der gerade untersuchten neuen Evidenz. Sie wird im Bayes-Modell mit der Wahrscheinlichkeit der Evidenz unter den jeweiligen Hypothesen kombiniert.','quant-06','distributions','bayes','Prior Probability'),
 G('Posterior','Aktualisierte Wahrscheinlichkeit nach Berücksichtigung neuer Evidenz. Sie hängt sowohl von den vorherigen Wahrscheinlichkeiten als auch davon ab, wie wahrscheinlich die Evidenz unter den verschiedenen Hypothesen ist.','quant-06','distributions','bayes','Posterior Probability'),
 G('Likelihood Ratio','Verhältnis der Wahrscheinlichkeit beobachteter Evidenz unter einer Hypothese zu ihrer Wahrscheinlichkeit unter einer Alternative. Multipliziert mit den Prior Odds liefert es die Posterior Odds. Abhängige Signale dürfen nicht ohne passendes Modell mehrfach als unabhängige Evidenz gezählt werden.','quant-06','distributions','updating'),
 G('Stichprobenvarianz','Summe der quadrierten Abstände vom Stichprobenmittel, geteilt durch die Beobachtungszahl minus eins. Bei unabhängigen gleich verteilten Beobachtungen mit endlicher Varianz schätzt sie die Populationsvarianz unverzerrt. Die Einheit ist die quadrierte Einheit der Daten.','quant-05','return-statistics','degrees-freedom','Sample Variance'),
 G('Standardabweichung','Quadratwurzel der Varianz. Sie beschreibt die Streuung um den Mittelwert in derselben Einheit wie die Beobachtungen. Ohne zusätzliche Verteilungsannahmen ist sie weder ein Maximalverlust noch eine feste Wahrscheinlichkeitsgrenze.','quant-05','return-statistics','dispersion','Standard Deviation'),
 G('Interquartilsabstand','Differenz zwischen drittem und erstem Quartil. Er beschreibt die Breite der mittleren Datenhälfte und reagiert weniger direkt auf einzelne Extremwerte als die Spannweite. Bei endlichen Stichproben muss die Quartilsregel feststehen.','quant-05','return-statistics','quantiles','Interquartile Range|IQR'),
 G('Getrimmter Mittelwert','Mittelwert nach Entfernung eines festgelegten Anteils der kleinsten und größten Beobachtungen. Er ist weniger ausreißerempfindlich, lässt aber zugleich echte Extremereignisse aus der verdichteten Kennzahl heraus.','quant-05','return-statistics','center','Trimmed Mean'),
 G('Winsorisierter Mittelwert','Mittelwert nach Ersatz extremer Randbeobachtungen durch festgelegte innere Grenzwerte. Anders als beim Trimmen bleibt die Zahl der Positionen gleich. Die Ersetzungsregel muss offengelegt werden.','quant-05','return-statistics','center','Winsorized Mean'),
 G('Semideviation','Streuungsmaß für Abweichungen unterhalb des Mittelwerts. Positive Abweichungen tragen null zum quadrierten Abstand bei. In Anwendung und Aufgaben müssen Nenner und Schätzkonvention ausdrücklich angegeben werden.','quant-05','return-statistics','downside'),
 G('Downside Deviation','Wurzel eines Durchschnitts quadrierter Unterschreitungen eines festgelegten Renditeziels. Beobachtungen am oder über dem Ziel tragen null bei. Das Mitteln über alle Beobachtungen ist von einem bedingten Mittel nur über die schlechten Beobachtungen zu unterscheiden.','quant-05','return-statistics','downside','Target Downside Deviation'),
 G('Variationskoeffizient','Standardabweichung relativ zu einem positiven Mittelwert. Er beschreibt dimensionslose relative Streuung. Bei Mittelwert nahe null wird er instabil; ein negativer Wert ist kein Beleg für eine vorteilhafte Rendite-Risiko-Beziehung.','quant-05','return-statistics','relative-risk','Coefficient of Variation'),
 G('Schiefe','Maß der Asymmetrie einer Verteilung. Negative Momentenschiefe weist auf ausgeprägte negative standardisierte Abweichungen hin, positive auf positive. Eine kleine Stichprobe kann die tatsächliche Form nur unsicher abbilden.','quant-05','return-statistics','shape','Skewness'),
 G('Kurtosis','Viertes standardisiertes zentrales Moment, das extreme Abstände stark gewichtet. Die Normalverteilung hat Kurtosis drei. Der häufig ebenfalls als Kurtosis bezeichnete Exzess zieht drei ab. Hohe Kurtosis ist keine direkte Wahrscheinlichkeit eines bestimmten Verlusts.','quant-05','return-statistics','shape'),
 G('Exzess-Kurtosis','Kurtosis abzüglich drei, sodass die Normalverteilung Referenzwert null besitzt. Vor einem Zahlenvergleich muss geprüft werden, ob ein Programm das ursprüngliche vierte standardisierte Moment oder bereits diesen Exzess ausgibt.','quant-05','return-statistics','shape','Excess Kurtosis'),
 G('Kovarianz','Erwartetes Produkt zweier Abweichungen von ihren jeweiligen Mittelwerten; in Stichproben wird ein entsprechendes Abweichungsproduktmittel geschätzt. Sie misst gemeinsame lineare Bewegung und trägt das Produkt der beiden Maßeinheiten.','quant-05','return-statistics','covariance','Covariance'),
 G('Korrelation','Durch beide Standardabweichungen normierte Kovarianz, bei positiven Varianzen zwischen minus eins und plus eins. Sie beschreibt eine lineare Beziehung. Null Korrelation bedeutet im Allgemeinen weder Unabhängigkeit noch das Fehlen einer nichtlinearen Beziehung.','quant-05','return-statistics','covariance','Correlation'),
 G('Global Minimum Variance Portfolio','Portfolio mit der kleinsten Varianz im betrachteten zulässigen Anlageuniversum. Es hängt von der Kovarianzstruktur und den Gewichtsgrenzen ab, aber bei reiner Varianzminimierung nicht von den erwarteten Renditen.','portfolio-03','portfolio-math','minimum-variance','GMV|Minimumvarianzportfolio'),
 G('Effiziente Grenze','Menge nicht dominierter Portfolios im verwendeten Rendite-Risiko-Modell. Kein anderes zulässiges Portfolio bietet mindestens so viel erwartete Rendite bei höchstens so viel Risiko mit einer strikten Verbesserung. Im Mittelwert-Varianz-Modell ist dies der obere Teil der Minimumvarianzgrenze.','portfolio-03','portfolio-math','efficient-frontier','Efficient Frontier'),
 G('Capital Allocation Line','Gerade der erreichbaren Rendite-Risiko-Kombinationen aus einer sicheren Anlage und einem bestimmten riskanten Portfolio, unter den passenden Finanzierungsannahmen. Ihre Steigung ist die erwartete Überschussrendite je Einheit Standardabweichung des riskanten Portfolios.','portfolio-02','portfolio-math','risk-free','CAL|Kapitalallokationslinie'),
 G('Capital Market Line','Besondere Kapitalallokationslinie mit dem Marktportfolio als riskantem Portfolio im entsprechenden Gleichgewichtsmodell. Sie beschreibt effiziente vollständige Portfolios mit Gesamtstandardabweichung als Risikogröße; einzelne Aktien müssen nicht auf ihr liegen.','portfolio-03','portfolio-math','market','CML|Kapitalmarktlinie'),
 G('Tangentialportfolio','Riskantes Portfolio, dessen Kapitalallokationslinie die effiziente Grenze berührt und unter den Modellbedingungen die höchste erreichbare positive Sharpe Ratio besitzt. Die Identifikation mit dem Marktportfolio benötigt zusätzliche Gleichgewichtsannahmen.','portfolio-03','portfolio-math','market','Tangency Portfolio'),
 G('Risikoaversion','Präferenz, zusätzliches Risiko nur gegen eine angemessene höhere erwartete Rendite zu übernehmen. Im Mittelwert-Varianz-Modell erhöht ein größerer positiver Risikoaversionsparameter den Nutzenabzug für dieselbe Varianz. Er bedeutet nicht zwingend eine vollständige Ablehnung riskanter Anlagen.','portfolio-02','portfolio-math','utility','Risk Aversion'),
 G('Indifferenzkurve','Menge von Risiko-Rendite-Kombinationen mit demselben Nutzen für eine gegebene Präferenz. Im Mittelwert-Varianz-Modell steigt die erforderliche erwartete Rendite mit zusätzlicher Varianz. Die optimale erreichbare Kurve hängt vom Anlageangebot und von Beschränkungen ab.','portfolio-02','portfolio-math','cal-figure','Indifference Curve'),
 G('Realized Return','Tatsächlich erzielte Rendite über einen angegebenen Zeitraum. Sie wird aus beobachteten Preisen und Zahlungen berechnet und ist von einer vorher erwarteten oder geforderten Rendite zu unterscheiden.','quant-03','returns','return-meanings','realisierte Rendite'),
 G('Expected Return','Mit tatsächlichen oder geschätzten Szenariowahrscheinlichkeiten gewichtete mögliche Rendite. Der Erwartungswert muss keinem einzelnen eintretenden Ergebnis entsprechen und ist keine Garantie.','quant-03','returns','return-meanings','erwartete Rendite'),
 G('Required Return','Verlangte Kompensation für Zeit und Risiko einer Anlage. Als Bewertungsmaßstab muss sie zu Währung, Zeithorizont und Risiko der betrachteten Zahlungen passen. Eine Renditeforderung wird durch ihre Höhe noch nicht tatsächlich verdient.','quant-01','returns','rate-roles','geforderte Rendite|Renditeforderung'),
 G('Promised Return','Aus dem heutigen Preis und den vollständig zugesagten Vertragszahlungen abgeleitete Rendite. Wenn Zahlungen ausfallen können, liegt die erwartete Rendite im Allgemeinen unter dieser versprochenen Rendite.','bonds-06','returns','promised-expected','versprochene Rendite'),
 G('Fisher-Beziehung','Verbindung zwischen nominalem Geldwachstum, Inflation und realer Kaufkraftänderung. Für realisierte Größen gilt: nominaler Wachstumsfaktor geteilt durch Preiswachstumsfaktor ergibt den realen Wachstumsfaktor. Das bloße Abziehen der Inflationsrate ist eine Näherung.','quant-03','returns','purchasing-power','Fisher Equation'),
 G('Basispunkt','Ein Hundertstel eines Prozentpunkts, also 0,01 Prozentpunkte bzw. 0,0001 als Dezimalzahl. Ein Anstieg von 3 % auf 3,2 % entspricht 20 Basispunkten, nicht einem relativen Anstieg von 20 %.','bonds-06','returns','comparison','Basis Point|Basispunkte'),
 G('Effektivzins','Effektive Jahresrendite: tatsächlicher Jahreswachstumsfaktor unter der angegebenen Zinskonvention minus eins. Sie berücksichtigt die unterjährige Zinseszinswirkung und ist von einem nominal notierten Jahreszins zu unterscheiden.','quant-03','return-types','compounding','EAR|Effective Annual Rate|effektiver Jahreszins|Effective Annual Yield|Effektive Jahresrendite',[{label:'effektive Jahresrate',units:['fixed-yields']}]),
 G('Nominaler Jahreszins','Annualisierte Zinsnotierung, die zusammen mit ihrer Verzinsungshäufigkeit interpretiert werden muss. Bei zwölf gleich langen Zinsperioden wird die Notierung durch zwölf geteilt, um den Periodenzins zu erhalten. Die effektive Jahresrendite folgt erst aus dessen zwölfmaliger Verzinsung.','quant-03','return-types','compounding','nominal annual rate'),
 G('Logarithmische Rendite','Natürlicher Logarithmus des positiven einfachen Wachstumsfaktors. Logarithmische Renditen lassen sich über aufeinanderfolgende Zeitperioden addieren; für ein Portfolio ergibt eine Gewichtung der einzelnen Logrenditen dagegen im Allgemeinen nicht die exakte Portfoliorendite.','quant-03','return-types','continuous','Log Return|Logrendite|stetige Rendite'),
 G('Geometrisches Mittel','Konstanter durchschnittlicher Wachstumsfaktor, dessen wiederholte Anwendung zum selben Endwert wie die beobachtete Folge führt. Für Renditen wird das geometrische Mittel der positiven Wachstumsfaktoren gebildet und anschließend eins abgezogen.','quant-03','return-types','averages','Geometric Mean'),
 G('Harmonisches Mittel','Kehrwert des arithmetischen Mittels der Kehrwerte positiver Beobachtungen. Bei gleich hohen Geldanlagen zu verschiedenen Preisen beschreibt es den durchschnittlichen Kaufpreis je erworbener Einheit; bei gleich vielen gekauften Einheiten wäre das arithmetische Mittel passend.','quant-03','return-types','harmonic','Harmonic Mean'),
 G('Annualisierung','Umrechnung einer Haltedauerrendite auf eine ausdrücklich angegebene Jahresbasis. Geometrische Annualisierung übersetzt den Wachstumsfaktor auf ein Jahr. Sie ist eine Vergleichskonvention und behauptet keine sichere Wiederholbarkeit einer kurzen Beobachtungsperiode.','quant-03','return-types','annualization','Annualization'),
 G('Nachschüssige Rente','Gleich hohe Zahlungen jeweils am Ende einer Periode; die erste Zahlung liegt eine Periode nach dem Bewertungsbeginn. Ihr Barwert ist die Summe der einzeln abgezinsten Zahlungen.','quant-02','tvm','annuities','Ordinary Annuity'),
 G('Vorschüssige Rente','Gleich hohe Zahlungen jeweils am Anfang einer Periode; die erste Zahlung erfolgt sofort. Gegenüber derselben nachschüssigen Zahlungsfolge liegt jede Zahlung eine Periode früher, weshalb der Barwert mit dem einperiodigen Wachstumsfaktor multipliziert wird.','quant-02','tvm','annuities','Annuity Due'),
 G('Ewige Rente','Unbegrenzte Zahlungsfolge. Bei konstanten positiven Zahlungen und positivem konstantem Diskontsatz ergibt sich der Barwert aus der nächsten Zahlung geteilt durch den Diskontsatz. Bei konstantem Wachstum muss der Diskontsatz das Wachstum übersteigen.','quant-02','tvm','growing-cashflows','Perpetuity'),
 G('Terminal Value','Zusammengefasster Wert der Zahlungen nach dem Ende einer expliziten Prognosephase, bewertet genau an diesem Endzeitpunkt. Er muss anschließend auf heute abgezinst werden; bereits enthaltene Zahlungen dürfen nicht nochmals separat addiert werden.','equity-08','tvm','terminal-value','Fortführungswert'),
 G('Diskontfaktor','Heutiger Wert einer passend abgegrenzten Einheit Zahlung an einem bestimmten zukünftigen Zeitpunkt. Ein separater Faktor pro Fälligkeit ermöglicht die Bewertung bei nicht flacher Zinsstruktur. Währung und Risikoeigenschaften müssen zur Zahlung passen.','bonds-05','tvm','bonds','Discount Factor'),
 G('Spot Rate','Heute geltender Zinssatz für eine Anlage von heute bis zu einer bestimmten Fälligkeit ohne zwischenzeitliche Zahlungen. Mehrere solche laufzeitspezifischen Sätze bilden eine Spotzinskurve. Ihre jeweilige Verzinsungskonvention muss angegeben werden.','bonds-07','tvm','bonds','Spotzins'),
 G('Forward Rate','Heute vereinbarter oder aus heutigen Preisen implizierter Zinssatz für eine zukünftige Zinsperiode. Die Verknüpfung passender Aufzinsungsfaktoren folgt unter geeigneten Bedingungen aus Arbitragefreiheit. Ein Forwardzins ist nicht automatisch eine unverzerrte Prognose des späteren Spotzinses.','bonds-07','tvm','forwards','Forwardzins'),
 G('Replikation','Nachbildung sämtlicher relevanten Zahlungszeitpunkte und zustandsabhängigen Zahlungen eines Anspruchs durch andere Instrumente. Unter den vorausgesetzten Handels- und Finanzierungsbedingungen begründet eine exakte Replikation einen arbitragefreien Preis. Gleiche erwartete Zahlungen allein genügen nicht.','derivatives-01','tvm','additivity','Replication'),
 G('Risikoneutrale Wahrscheinlichkeit','Aus Marktpreisen und risikofreier Finanzierung abgeleitetes Bewertungsgewicht. Es erlaubt im passenden Modell die Bewertung durch Abzinsung gewichteter Auszahlungen. Es ist nicht notwendigerweise die tatsächliche Eintrittswahrscheinlichkeit eines Zustands.','derivatives-08','tvm','option-replication','Risk-neutral Probability'),
 G('Earnings per Share','Ergebnis je Stammaktie. Basic EPS verteilt den den Stammaktionären zurechenbaren Periodengewinn auf die zeitgewichtete durchschnittliche Aktienzahl; Diluted EPS berücksichtigt zusätzlich tatsächlich verwässernde potenzielle Stammaktien. Die reine Aktienzahl am Jahresende ist im Allgemeinen kein geeigneter Nenner.','statements-12','income-statement','basic-eps','EPS|Gewinn je Aktie'),
 G('Treasury Stock Method','Verfahren für die EPS-Verwässerung durch geeignete Optionen und ähnliche Rechte. Es unterstellt Ausübung und einen hypothetischen Rückkauf zum durchschnittlichen Periodenkurs aus den relevanten Erlösen. Nur die verbleibenden zusätzlichen Aktien erhöhen den Nenner; ein tatsächlicher Rückkauf wird nicht behauptet.','statements-12','income-statement','dilution','Treasury-Stock-Methode'),
 G('If-Converted Method','EPS-Verfahren, das die Umwandlung eines wandelbaren Instruments ab dem passenden Zeitpunkt unterstellt. Zusätzliche Aktien erhöhen den Nenner; bei Wandelanleihen wird der dadurch entfallende Nachsteuerzins zum Ergebnis addiert. Einbeziehung erfolgt nur bei verwässernder Wirkung.','statements-12','income-statement','dilution','If-Converted-Methode'),
 G('Antidilution','Wirkung eines potenziellen Eigenkapitalinstruments, das bei unterstellter Umwandlung das Ergebnis je Aktie erhöhen oder den Verlust je Aktie verringern würde. Ein solches Instrument wird bei der maßgeblichen Diluted-EPS-Berechnung ausgeschlossen.','statements-12','income-statement','antidilution','antidilutiv|Antiverwässerung'),
 G('Weighted Average Shares','Zeitgewichtete durchschnittliche Aktienzahl einer Periode. Eine neue Ausgabe zählt ab ihrem maßgeblichen Zeitpunkt; Rückkäufe vermindern den Bestand ab ihrem Zeitpunkt. Splits erfordern dagegen eine rückwirkend konsistente Stückzahlbasis.','statements-12','income-statement','basic-eps','zeitgewichtete Aktienzahl'),
 G('Standalone Selling Price','Preis, zu dem eine versprochene Ware oder Dienstleistung einzeln verkauft würde. Relative Einzelverkaufspreise können den Transaktionspreis eines Pakets auf seine Leistungsverpflichtungen verteilen.','statements-04','income-statement','revenue','Einzelverkaufspreis'),
 G('Current Ratio','Umlaufvermögen geteilt durch kurzfristige Verbindlichkeiten am selben Stichtag. Die Quote misst buchmäßige kurzfristige Deckung; sie sagt ohne Fälligkeiten und Vermögensqualität nicht, ob tatsächlich jederzeit gezahlt werden kann.','statements-12','ratios','liquidity'),
 G('Quick Ratio','Liquide Mittel plus kurzfristige marktgängige Anlagen plus geeignete Nettoforderungen, geteilt durch kurzfristige Verbindlichkeiten. Vorräte und Vorauszahlungen sind ausgeschlossen. Die engere Deckungsmasse reduziert die Abhängigkeit von Warenverkäufen.','statements-12','ratios','liquidity','Acid-Test Ratio'),
 G('Cash Ratio','Liquide Mittel und kurzfristige marktgängige Anlagen geteilt durch kurzfristige Verbindlichkeiten. Anders als die Quick Ratio berücksichtigt diese Deckungskennzahl keine Forderungen.','statements-12','ratios','liquidity'),
 G('Defensive Interval','Liquide Mittel, kurzfristige marktgängige Anlagen und geeignete Forderungen geteilt durch durchschnittliche tägliche betriebliche Barausgaben. Das Ergebnis sind Tage rechnerischer Ausgabendeckung; es ersetzt keine konkrete Fälligkeits- und Liquiditätsplanung.','statements-12','ratios','liquidity','Defensive Interval Ratio|DIR'),
 G('Days Sales Outstanding','Forderungstage: durchschnittliche Forderungen geteilt durch den passenden Jahresumsatz, multipliziert mit der verwendeten Zahl von Tagen pro Jahr. Bei gleicher Datenbasis ist die Kennzahl invers zum Forderungsumschlag.','corporate-08','ratios','activity','DSO|Forderungstage'),
 G('Days Inventory Outstanding','Lagerdauer: durchschnittliche Vorräte geteilt durch jährliche Umsatzkosten, multipliziert mit der Jahres-Tagesbasis. Umsatz statt Umsatzkosten im Nenner würde eine andere Kennzahl erzeugen.','corporate-08','ratios','activity','DIO|Lagertage'),
 G('Days Payables Outstanding','Lieferantenverbindlichkeitstage: durchschnittliche Verbindlichkeiten aus Lieferungen und Leistungen geteilt durch jährliche Krediteinkäufe, multipliziert mit der Tagesbasis. Umsatzkosten sind bei verändertem Vorratsbestand nur ein möglicher Näherungswert für Einkäufe. Höhere DPO verkürzen bei gleichen übrigen Komponenten den Cash Conversion Cycle; Kosten und Vertragsbedingungen sind gesondert zu beurteilen.','corporate-08','ratios','activity','Days Payable Outstanding|DPO|Verbindlichkeitstage'),
 G('Operating Cycle','Zeit vom Einkauf bzw. der Lagerbindung bis zum Einzug der Kundenforderung, im Kennzahlenmodell Lagerdauer plus Forderungstage. Der Cash Conversion Cycle zieht zusätzlich die Lieferantenfinanzierung in Tagen ab.','corporate-08','ratios','activity'),
 G('Cash Conversion Cycle','Rechnerische Dauer der eigenen operativen Mittelbindung: Lagerdauer plus Forderungstage minus Lieferantenverbindlichkeitstage. Ein negativer Wert kann entstehen, wenn Kundenzahlungen vor der Bezahlung der Lieferanten eingehen.','corporate-08','ratios','activity','CCC'),
 G('DuPont-Analyse','Algebraische Zerlegung der Eigenkapitalrendite in zusammenhängende Treiber. Drei Faktoren sind Nettomarge, Vermögensumschlag und Eigenkapitalmultiplikator; die fünfteilige Form trennt zusätzlich Steuer- und Zinsbelastung von der operativen Marge.','statements-12','ratios','dupont','DuPont'),
 G('Tax Burden','In der fünfteiligen DuPont-Analyse der verbleibende Ergebnisanteil nach Steuern: Nettogewinn geteilt durch Vorsteuergewinn. Bei positiven Ergebnissen bedeutet ein kleinerer Faktor eine stärkere Steuerbelastung; der Faktor ist nicht die Steuerquote selbst.','statements-12','ratios','dupont','Steuerbelastungsfaktor'),
 G('Interest Burden','In der fünfteiligen DuPont-Analyse Vorsteuergewinn geteilt durch EBIT. Der Faktor zeigt, welcher Anteil des operativen Ergebnisses nach Zins verbleibt. Bei positiven Ergebnissen bedeutet ein kleinerer Faktor eine stärkere Zinsbelastung.','statements-12','ratios','dupont','Zinsbelastungsfaktor'),
 G('Fixed Charge Coverage','Deckungsmaß für feste Finanzierungslasten. Ein gebräuchlicher Ansatz teilt EBIT zuzüglich darin bereits abgezogener Miet-/Leasingaufwendungen durch Zinsen plus diese Aufwendungen. Nach Leasingaktivierung muss die Abgrenzung angepasst werden, damit nichts doppelt gezählt wird.','statements-12','ratios','solvency'),
 G('Net Interest Margin','Nettozinsertrag einer Bank relativ zu einer passend abgegrenzten durchschnittlichen Basis zinstragender Aktiva. Sie beschreibt einen Geschäftsmodelltreiber, erfasst aber weder sämtliche Kreditverluste noch sämtliche Kosten und Risiken.','statements-12','ratios','industry-cases','Nettozinsmarge'),
 G('Lessee','Leasingnehmer: Vertragspartei, die das Nutzungsrecht an einem Vermögenswert gegen vereinbarte Gegenleistung erhält. Ihr bilanzierter Vermögenswert ist im Nutzungsrechtsmodell das Recht zur Nutzung, nicht zwingend rechtliches Eigentum am Gegenstand.','statements-07','leases-compensation','lease-contract','Leasingnehmer'),
 G('Lessor','Leasinggeber: Vertragspartei, die einem anderen die Nutzung eines Vermögenswerts überlässt. Ihre Bilanzierung hängt unter anderem davon ab, ob der Vertrag wirtschaftlich Vermietung oder Finanzierung darstellt.','statements-07','leases-compensation','lessor','Leasinggeber'),
 G('Right-of-use Asset','Bilanzierter Wert des vertraglichen Rechts, einen Leasinggegenstand zu nutzen. Er beginnt grundsätzlich mit der Leasingverbindlichkeit, angepasst etwa um Vorauszahlungen, direkte Kosten und Anreize. Sein späterer Buchwert muss nicht mit der Schuld übereinstimmen.','statements-07','leases-compensation','lease-measurement','Nutzungsrecht|Nutzungsrechtsvermögenswert'),
 G('Finance Lease','Leasingklassifikation mit einer wirtschaftlich finanzierungsähnlichen Nutzung. Beim US-GAAP-Leasingnehmer werden unter anderem Abschreibung und Zins getrennt erfasst. Die IFRS-Leasingnehmerbilanzierung folgt grundsätzlich einem ähnlichen einheitlichen Nutzungsrechtsmodell mit Ausnahmen.','statements-07','leases-compensation','lease-comparison'),
 G('Operating Lease','Leasingklassifikation, die insbesondere unter US GAAP beim Leasingnehmer einen gewöhnlich gleichmäßigen einheitlichen Aufwand vorsieht. Ein heutiger gewöhnlicher mehrjähriger US Operating Lease steht trotzdem mit Nutzungsrecht und Schuld in der Bilanz. Die Leasinggeberperspektive ist separat zu beurteilen.','statements-07','leases-compensation','lease-comparison'),
 G('Defined Contribution Plan','Pensionsplan mit Beitragszusage. Der Arbeitgeber schuldet die vereinbarten Beiträge, grundsätzlich keine festgelegte spätere Rentenleistung. Noch nicht bezahlte fällige Beiträge können eine Verbindlichkeit erzeugen.','statements-09','leases-compensation','pensions','Beitragszusage'),
 G('Defined Benefit Plan','Pensionsplan mit einer zugesagten Leistung, zum Beispiel abhängig von Dienstzeit und Gehalt. Der Arbeitgeber bewertet die Verpflichtung und vergleicht sie mit vorhandenem Planvermögen; Schätz-, Anlage- und Langlebigkeitsrisiken können die Finanzierung verändern.','statements-09','leases-compensation','pensions','Leistungszusage'),
 G('Planvermögen','Zur Deckung von Pensionsleistungen gehaltene geeignete Vermögenswerte. Ihr Fair Value wird mit der bewerteten Leistungszusage verglichen. Arbeitgeberbeiträge, tatsächliche Anlageerträge und ausgezahlte Leistungen verändern diesen Bestand.','statements-09','leases-compensation','pensions','Plan Assets'),
 G('Service Cost','Dienstzeitaufwand einer Pensionszusage: durch Arbeitsleistung zusätzlich erdienter Leistungsanspruch, bewertet nach den maßgeblichen Regeln. Er ist von Zins, Neubewertung und tatsächlichen Arbeitgeberbeiträgen zu unterscheiden.','statements-09','leases-compensation','pensions','Dienstzeitaufwand'),
 G('Other Comprehensive Income','Sonstiges Ergebnis: nach den einschlägigen Regeln erfasste Ergebnisbestandteile außerhalb des Periodengewinns, die das Eigenkapital beeinflussen. Ob später eine Umgliederung in die GuV erfolgt, hängt vom Posten ab; IAS-19-Neubewertungen werden nicht in die GuV recycelt.','statements-09','leases-compensation','pension-comparison','OCI|sonstiges Ergebnis'),
 G('Vesting','Unverfallbarwerden eines zugesagten Vergütungsanspruchs nach Erfüllung seiner Bedingungen. Bei aktienbasierter Vergütung können Dienstzeit-, Leistungs- oder Marktbedingungen relevant sein; diese werden bilanziell nicht in jeder Hinsicht gleich behandelt.','statements-09','leases-compensation','share-payments','Unverfallbarkeit'),
 G('Grant-Date Fair Value','Maßgeblicher Fair Value einer Vergütungszusage am Gewährungszeitpunkt. Bei gewöhnlichen eigenkapitalerfüllten Mitarbeiterzusagen bildet er grundsätzlich die Bewertungsbasis je Instrument; eine spätere Kursbewegung ersetzt ihn nicht automatisch.','statements-09','leases-compensation','share-payments'),
 G('Time-Weighted Return','Zeitgewichtete Rendite: geometrische Verkettung von Teilrenditen zwischen externen Geldbewegungen. Sie isoliert die Anlageentwicklung vom direkten Einfluss der Beitragshöhen und eignet sich häufig zur Managerbeurteilung. Kumulative und annualisierte TWR sind zu unterscheiden.','quant-04','benchmarks','time-weighted','TWR|zeitgewichtete Rendite'),
 G('Money-Weighted Return','Geldgewichtete Rendite: interner Zinsfuß der Ein- und Auszahlungen aus Anlegersicht einschließlich des Endvermögens. Höhe und Zeitpunkt der Beiträge beeinflussen das Ergebnis. Bei bestimmten Vorzeichenfolgen kann die IRR-Lösung mehrdeutig sein.','quant-04','benchmarks','money-weighted','MWR|geldgewichtete Rendite'),
 G('Indexdivisor','Skalierungsfaktor, durch den die relevante Kurssumme oder Indexkapitalisierung geteilt wird. Anpassungen verhindern, dass technische Änderungen wie bestimmte Kapitalmaßnahmen oder Mitgliederwechsel als Marktgewinn oder -verlust erscheinen.','equity-03','benchmarks','divisor','Divisor'),
 G('Free Float','Investierbarer Streubesitzanteil eines Titels nach der angegebenen Indexmethodik. Ein Float-adjustierter Index gewichtet die Marktkapitalisierung mit diesem Anteil; große nicht frei handelbare Beteiligungen können ausgeschlossen sein.','equity-03','benchmarks','index-weights','Streubesitz'),
 G('Reconstitution','Änderung der Mitgliedschaft eines Index, etwa Aufnahme oder Ausschluss von Titeln nach festgelegten Regeln. Sie ist von Rebalancing zu unterscheiden, das die Gewichte neu ausrichtet; beide Vorgänge können gemeinsam auftreten.','equity-03','benchmarks','index-weights'),
 G('Dissociation','Tatsächliche Distanzierung von einer unzulässigen beruflichen Tätigkeit, beispielsweise durch Verweigerung der Mitwirkung oder Entfernung der eigenen Zuordnung zu einem Bericht. Sie ist nicht mit einer pauschal immer notwendigen Behördenmeldung gleichzusetzen.','ethics-02','standard-i','law','Distanzierung'),
 G('Written Consent','Dokumentierbare Zustimmung. Bei konfliktträchtiger Zusatzvergütung nach Standard IV(B) ist sie vor Annahme von allen betroffenen Parteien erforderlich; abrufbare E-Mail-Zustimmungen können die Form erfüllen. Bloße Mitteilung oder Schweigen sind nicht automatisch Zustimmung.','ethics-05','standard-iv','compensation','schriftliche Zustimmung'),
 G('Reasonable Basis','Tragfähige Grundlage einer Anlageanalyse oder Empfehlung, gestützt auf geeignete Untersuchung und angemessene Sorgfalt. Ihr erforderlicher Umfang hängt von Aufgabe und Risiko ab; weder bloße Überzeugung noch ein zufällig guter späterer Ertrag ersetzt sie.','ethics-06','standard-v','basis'),
 G('Record Retention','Aufbewahrung geeigneter Nachweise zu Analyse, Empfehlung, Entscheidung und relevanter Kommunikation. Gesetzliche und betriebliche Regeln sind zu beachten; nur ohne solche Vorgaben empfiehlt CFA Institute mindestens sieben Jahre. Auch digitale Nachrichten und begründete Halteentscheidungen können erfasst sein.','ethics-06','standard-v','records','Aufbewahrungspflicht'),
 G('Material Nonpublic Information','Information, die für eine vernünftige Anlageentscheidung wesentlich und noch nicht angemessen allgemein verbreitet ist. Beide Merkmale müssen zusammen geprüft werden. Ihr Besitz darf nicht dazu genutzt werden, eine Anlagehandlung vorzunehmen oder andere dazu zu veranlassen.','ethics-03','standard-ii','material-public','MNPI|wesentliche nicht öffentliche Information'),
 G('Mosaic Theory','Analyseansatz, bei dem eine eigenständige bedeutende Schlussfolgerung aus öffentlichen Informationen und für sich nicht wesentlichen nicht öffentlichen Bausteinen entsteht. Ein bereits wesentlicher vertraulicher Hinweis wird durch Beimischung öffentlicher Daten nicht zulässig.','ethics-03','standard-ii','mosaic','Mosaiktheorie'),
 G('Market Manipulation','Irreführende Einwirkung auf Marktpreise oder Handelsaktivität, etwa durch bewusst falsche Meldungen oder künstliches Volumen. Ein echter großer Auftrag ist nicht schon wegen seiner Kurswirkung manipulativ; Zweck und wirtschaftliche Gestaltung sind entscheidend.','ethics-03','standard-ii','manipulation','Marktmanipulation'),
 G('Information Barrier','Organisatorische und technische Vorkehrungen, die unzulässigen Informationsfluss zwischen Tätigkeiten oder Personen begrenzen. Zugriff, Kommunikation, Zuständigkeiten und Überwachung müssen tatsächlich zur vorgesehenen Trennung passen.','ethics-03','standard-ii','controls','Informationsbarriere'),
 G('Watch List','Interne Liste für besonders zu beobachtende Wertpapiere oder Sachverhalte. Die konkrete Wirkung folgt aus dem betrieblichen Verfahren. Sie ist nicht automatisch identisch mit einer Restricted List und erlaubt keine ansonsten unzulässige Handlung.','ethics-03','standard-ii','controls'),
 G('Restricted List','Interne Liste mit ausdrücklich definierten Handels- oder Tätigkeitsbeschränkungen. Umfang, betroffene Personen und Ausnahmen ergeben sich aus den maßgeblichen Regeln; ein bloßer Listeneintrag ersetzt keine materielle Prüfung.','ethics-03','standard-ii','controls'),
 G('Fair Dealing','Faire und objektive Behandlung von Kunden bei Analyse, Empfehlung und Anlagehandlung. Unterschiede können durch Bedürfnisse, Eignung oder zulässige Leistungsstufen begründet sein. Fairness verlangt keine identischen Portfolios, erlaubt aber keine unsachliche Bevorzugung.','ethics-04','standard-iii','fair-dealing','faire Behandlung'),
 G('Suitability','Eignung einer Anlage oder Handlung für die finanzielle Situation, Ziele und Grenzen des Kunden im Kontext seines Gesamtportfolios. Bei einem festen Fondsmandat steht dessen Einhaltung im Mittelpunkt. Hohe erwartete Rendite allein beweist keine Eignung.','ethics-04','standard-iii','suitability','Anlageeignung'),
 G('Investment Policy Statement','Schriftliche Arbeitsgrundlage für die Anlageverwaltung mit Zielen, Risikovorgaben und relevanten Einschränkungen wie Liquidität, Zeithorizont oder rechtlichen Grenzen. Sie muss die tatsächlichen aktuellen Umstände abbilden und bei wesentlichen Änderungen überprüft werden.','portfolio-01','standard-iii','suitability','IPS'),
 G('Best Execution','Sorgfältig angestrebte günstigste erreichbare Gesamtausführung unter den gegebenen Umständen und Kundenbedingungen. Neben Provisionen zählen etwa Ausführungspreis, Wahrscheinlichkeit, Größe und Zeitvorgaben. Niedrigste sichtbare Provision allein beweist keine beste Ausführung.','ethics-04','standard-iii','loyalty'),
 G('Pro-rata-Zuteilung','Verteilung einer verfügbaren Menge im Verhältnis vorab definierter Bezugsgrößen, etwa geeigneter Kundenorders. Bei Teilfüllung erhält jede Order denselben relativen Erfüllungsanteil; Mindestlose und Rundung müssen im Verfahren berücksichtigt werden.','ethics-04','standard-iii','allocation','Pro Rata'),
 G('Beneficial Ownership','Wirtschaftliche Berechtigung an einer Anlage, die über den formalen Kontonamen hinausgehen kann, etwa durch wirtschaftliches Interesse oder maßgebliche Verfügungsmacht. Für Konflikte und persönliche Geschäfte sind auch relevante indirekte Beziehungen zu prüfen.','ethics-07','standard-vi','priority','wirtschaftliches Eigentum'),
 G('Front Running','Persönlicher Handel im Vorfeld eines bekannten bevorstehenden Kundenauftrags, um dessen erwartete Wirkung zum eigenen Vorteil zu nutzen. Die spätere ordnungsgemäße Ausführung des Kundenauftrags oder eine allgemeine Konflikterklärung beseitigt diesen Verstoß nicht.','ethics-07','standard-vi','priority'),
 G('Preclearance','Prüfung und erforderliche Freigabe eines vorgeschlagenen Geschäfts vor seiner Ausführung. Sie braucht vollständige aktuelle Informationen und ergänzt nachträgliche Überwachung. Eine auf falschen Angaben beruhende Freigabe erlaubt keine materiell verbotene Handlung.','ethics-07','standard-vi','personal-controls'),
 G('Referral Fee','Vergütung oder anderer wirtschaftlicher Vorteil für die Empfehlung von Produkten oder Dienstleistungen. Auch Sachleistungen, interne Programme und selbst gezahlte Vermittlungsvorteile können erfasst sein. Art und geschätzter Wert sind den betroffenen Parteien angemessen offenzulegen.','ethics-07','standard-vi','referrals','Vermittlungsvergütung'),
 G('Interessenkonflikt','Beziehung, Verpflichtung oder Anreiz, die das unabhängige Urteil oder die Erfüllung beruflicher Pflichten vernünftigerweise beeinträchtigen könnte. Ein nachgewiesener Schaden ist keine Voraussetzung. Vermeidung, Begrenzung und wirksame Offenlegung sind getrennte mögliche Maßnahmen.','ethics-07','standard-vi','conflicts','Conflict of Interest'),
 G('Professional Conduct Program','System des CFA Institute zur Untersuchung und Durchsetzung beruflicher und programmbezogener Pflichten. Professional-Conduct-Mitarbeitende untersuchen Sachverhalte; zuständige DRC-Panels wirken an Beurteilung und Sanktionen mit. Ein Hinweis ist noch keine festgestellte Verletzung.','ethics-08','code','conduct-program','PCP'),
 G('Disciplinary Review Committee','Ehrenamtliches Gremium von CFA-Charterholdern, das an disziplinarischer Prüfung und Entscheidungen durch zuständige Panels beteiligt ist. Es ist von Untersuchungsmitarbeitenden und von staatlichen Gerichten zu unterscheiden.','ethics-08','code','conduct-program','DRC'),
 G('Informationsasymmetrie','Ungleiche Verteilung entscheidungsrelevanten Wissens zwischen Beteiligten. In der Beratung kann der Kunde die Analysequalität schlechter beurteilen als der Fachmann. Transparenz, Sorgfalt und Verantwortlichkeit begrenzen daraus entstehende Probleme, beseitigen sie aber nicht vollständig.','ethics-01','ethics-foundations','trust','Information Asymmetry'),
 G('Situativer Einfluss','Druck oder Anreiz aus einer konkreten Entscheidungssituation, etwa Gruppennormen, Autorität, Vergütung oder Zeitnot. Solche Faktoren können auch bei Menschen mit gutem Selbstbild das Urteil beeinflussen und sollten ausdrücklich geprüft werden.','ethics-01','ethics-foundations','pressure','Situational Influence'),
 G('Track Record','Dokumentierte Historie einer Anlageleistung über einen angegebenen Zeitraum und eine definierte Konten- oder Strategieauswahl. Herkunft, tatsächliche oder simulierte Ergebnisse, Gebührenbasis und Auswahl dürfen nicht irreführend dargestellt werden.','ethics-04','standard-iii','performance'),
 G('Directed Brokerage','Vom Kunden vorgegebene Nutzung eines bestimmten Brokers. Die Vorgabe kann den verfügbaren Ausführungsraum und die Möglichkeit bester Ausführung begrenzen; diese Folgen sind zu erklären, während angemessene Sorgfalt innerhalb des Auftrags bestehen bleibt.','ethics-04','standard-iii','loyalty')
];
